INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们买了三根芯片。", "corrected_sentence": "他们买了三块芯片。", "error_description": "量词错误：“根”用于细长的东西，芯片应该用“块”来计量。正确说法是“他们买了三块芯片。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人往机器里装了两根芯片。", "corrected_sentence": "工人往机器里装了两块芯片。", "error_description": "量词错误：“根”用于细长的东西，芯片应该用“块”来计量。正确说法是“工人往机器里装了两块芯片。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
