INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98524, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "十分周到，毫无疏漏。", "primary_collocate": null, "pronunciation": "wàn quán", "ipa": "wan˥˩ tɕʰyɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这次旅行，她的安排非常万全。", "target_word": "万全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的教学计划写得很万全。", "target_word": "万全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想得真万全，连雨伞都带了。", "target_word": "万全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，小王把资料准备得万全。", "target_word": "万全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份菜单考虑得很万全，没有漏掉一样。", "target_word": "万全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的接待工作做得很万全，客人都很满意。", "target_word": "万全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场婚礼的每件小事都安排得很万全。", "target_word": "万全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方案不够万全，还漏了一个问题。", "target_word": "万全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了比赛，教练把每个细节都想得万全。", "target_word": "万全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做事认真，计划总是很万全。", "target_word": "万全", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "万全之策", "label": "复合"}, {"form": "萬全", "label": "繁体"}], "register": "书面", "sense_fingerprint": "考虑或安排得很周到、没有遗漏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb662756-0b78-4edf-9c5e-051c04c57dff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98524, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "万全", "is_correct": true, "explanation": "万全 wàn quán，指考虑或安排十分周到、没有遗漏，是本题要听的词。"}, {"text": "完全", "is_correct": false, "explanation": "wán（第二声）与 wàn（第四声）声调不同，意思是全部、彻底。"}, {"text": "万元", "is_correct": false, "explanation": "quán（第二声）与 yuán（第二声）只差声母（q 与零声母），意思是一万块钱。"}, {"text": "万千", "is_correct": false, "explanation": "quán 与 qiān（第一声）的韵母介音和声调都不同，意思是数量极多。"}, {"text": "版权", "is_correct": false, "explanation": "wàn（第四声）与 bǎn（第三声）声母不同，声调也不同，意思是著作权。"}, {"text": "王权", "is_correct": false, "explanation": "wàn（第四声）与 wáng（第二声）韵母不同（-an 与 -ang），意思是君主的权力。"}], "explanations": {"万全": "万全 wàn quán，指考虑或安排十分周到、没有遗漏，是本题要听的词。", "完全": "wán（第二声）与 wàn（第四声）声调不同，意思是全部、彻底。", "万元": "quán（第二声）与 yuán（第二声）只差声母（q 与零声母），意思是一万块钱。", "万千": "quán 与 qiān（第一声）的韵母介音和声调都不同，意思是数量极多。", "版权": "wàn（第四声）与 bǎn（第三声）声母不同，声调也不同，意思是著作权。", "王权": "wàn（第四声）与 wáng（第二声）韵母不同（-an 与 -ang），意思是君主的权力。"}, "sentence_index": null, "correct_answer": "万全"}, "level_3": {"options": [{"text": "万全", "is_correct": true, "explanation": "“万全”形容安排周到、没有遗漏，符合句意。"}, {"text": "深奥", "is_correct": false, "explanation": "搭配：“深奥”形容道理或学问难懂，不说“安排非常深奥”。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容天气或温度，与“安排”无关，句子说不通。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”形容空间，不能用来修饰“安排”。"}], "explanations": {"万全": "“万全”形容安排周到、没有遗漏，符合句意。", "深奥": "搭配：“深奥”形容道理或学问难懂，不说“安排非常深奥”。", "寒冷": "语义：“寒冷”形容天气或温度，与“安排”无关，句子说不通。", "狭窄": "搭配：“狭窄”形容空间，不能用来修饰“安排”。"}, "sentence_index": 0, "correct_answer": "万全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子很万全，地板擦得发亮。", "explanation": "这里应该用〈干净〉。“万全”指计划、安排十分周到，不用来形容屋子的整洁，形容整洁要用〈干净〉。"}, {"text": "听到这个好消息，他的心情很万全。", "explanation": "这里应该用〈高兴〉。“万全”形容计划、安排十分周到，不用来形容心情，描述心情要用〈高兴〉。"}, {"text": "这台仪器的零件加工得很万全。", "explanation": "这里应该用〈精密〉。“万全”不用来形容加工或零件的精度，这里要用〈精密〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "万全", "is_correct": true, "explanation": "“万全”形容每件小事都安排得周到、没有遗漏，符合婚礼的语境。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”形容待人的态度，与婚礼热闹的语境相冲突，安排不能是冷淡的。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”形容山坡、地势，不能说事情“安排得很陡峭”。"}, {"text": "狼狈", "is_correct": false, "explanation": "语义：“狼狈”形容人处境窘迫，不能说事情安排得狼狈。"}], "explanations": {"万全": "“万全”形容每件小事都安排得周到、没有遗漏，符合婚礼的语境。", "冷淡": "语义：“冷淡”形容待人的态度，与婚礼热闹的语境相冲突，安排不能是冷淡的。", "陡峭": "语义：“陡峭”形容山坡、地势，不能说事情“安排得很陡峭”。", "狼狈": "语义：“狼狈”形容人处境窘迫，不能说事情安排得狼狈。"}, "sentence_index": 6, "correct_answer": "万全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个实验室的设备很万全。", "explanation": "这里应该用〈完备〉。“万全”强调计划或办法周到，形容设备齐全要用〈完备〉。"}, {"text": "妹妹的身体很万全，很少生病。", "explanation": "这里应该用〈健康〉。“万全”不用来形容人的身体，这里要用〈健康〉。"}, {"text": "这碗汤很万全，喝了一口就停不下来。", "explanation": "这里应该用〈美味〉。“万全”形容计划、安排周到，不用来形容食物的味道，形容味道好要用〈美味〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把晚会的节目准备地很万全。", "corrected_sentence": "她把晚会的节目准备得很万全。", "error_description": "“准备地很万全”用错了结构助词，应说“准备得很万全”。“万全”作补语，前面要用“得”，“地”用在状语前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们给婚礼的每个环节都想很万全。", "corrected_sentence": "他们给婚礼的每个环节都想得很万全。", "error_description": "“想很万全”缺少结构助词“得”，应说“想得很万全”。动词后带补语要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
