INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98525, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "号手是吹号的人。", "primary_collocate": null, "pronunciation": "hào shǒu", "ipa": "xaʊ̯˥˩ ʂoʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "演出时号声没有响起，因为乐队里的号手今天没有来。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "号手深吸一口气，吹起了号。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个号手吹得非常好听。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想找一名号手参加升旗仪式。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "升旗时，号手吹着号站在旗杆旁。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想当号手。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "号手的嘴唇吹得有点疼。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，号手吹响了号角。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队里新来的号手很年轻。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老号手教他怎么吹号。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "号手们", "label": "复数"}], "register": "中性", "sense_fingerprint": "吹号的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a70e542a-3e78-41c2-b2e4-2d7a51a2477b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98525, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "号手", "is_correct": true, "explanation": "正确：号手 hào shǒu，指吹号的人。"}, {"text": "好手", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是能干的人。"}, {"text": "好受", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）、shòu（第四声）与 shǒu（第三声）声调都不同，意思是舒服。"}, {"text": "后手", "is_correct": false, "explanation": "hòu 与 hào 韵母不同（ou 与 ao），声调相同，意思是后手、后招。"}, {"text": "到手", "is_correct": false, "explanation": "dào 与 hào 声母不同（d 与 h），声调相同，意思是到手、得到。"}], "explanations": {"号手": "正确：号手 hào shǒu，指吹号的人。", "好手": "hǎo（第三声）与 hào（第四声）声调不同，意思是能干的人。", "好受": "hǎo（第三声）与 hào（第四声）、shòu（第四声）与 shǒu（第三声）声调都不同，意思是舒服。", "后手": "hòu 与 hào 韵母不同（ou 与 ao），声调相同，意思是后手、后招。", "到手": "dào 与 hào 声母不同（d 与 h），声调相同，意思是到手、得到。"}, "sentence_index": null, "correct_answer": "号手"}, "level_3": {"options": [{"text": "号手", "is_correct": true, "explanation": "正确：号手指吹号的人，乐队里的号手缺席，符合语境。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：园丁不是乐队的演奏者，与“乐队里的”语境不符。"}, {"text": "渔夫", "is_correct": false, "explanation": "语义：渔夫不是乐队成员，与“乐队里的”语境不符。"}, {"text": "警察", "is_correct": false, "explanation": "搭配：“乐队里的……”要求是乐队成员，警察不搭配乐队。"}], "explanations": {"号手": "正确：号手指吹号的人，乐队里的号手缺席，符合语境。", "园丁": "语义：园丁不是乐队的演奏者，与“乐队里的”语境不符。", "渔夫": "语义：渔夫不是乐队成员，与“乐队里的”语境不符。", "警察": "搭配：“乐队里的……”要求是乐队成员，警察不搭配乐队。"}, "sentence_index": 0, "correct_answer": "号手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校想把号手挂在旗杆上。", "explanation": "这里应该用〈国旗〉。号手是吹号的人，不是挂在旗杆上的东西。"}, {"text": "学校想买一把号手参加升旗仪式。", "explanation": "这里应该用〈号〉。号手是吹号的人，不能“买一把”；能买的是乐器“号”。"}, {"text": "学校想找一名号手去打扫操场。", "explanation": "这里应该用〈清洁工〉。号手指吹号的人，不负责打扫；打扫操场的应说清洁工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content =