INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98525, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "号手", "is_correct": true, "explanation": "正确：号手指吹号的人，嘴唇吹得疼符合吹号的动作。"}, {"text": "钢琴家", "is_correct": false, "explanation": "搭配：“吹”要与吹奏或吹气相搭配，钢琴家弹琴，不用嘴吹。"}, {"text": "舞蹈家", "is_correct": false, "explanation": "语义：舞蹈家用身体跳舞，与“嘴唇吹得有点疼”不符。"}, {"text": "理发师", "is_correct": false, "explanation": "语义：理发师用手工作，与“嘴唇吹得有点疼”的语境不符。"}], "explanations": {"号手": "正确：号手指吹号的人，嘴唇吹得疼符合吹号的动作。", "钢琴家": "搭配：“吹”要与吹奏或吹气相搭配，钢琴家弹琴，不用嘴吹。", "舞蹈家": "语义：舞蹈家用身体跳舞，与“嘴唇吹得有点疼”不符。", "理发师": "语义：理发师用手工作，与“嘴唇吹得有点疼”的语境不符。"}, "sentence_index": 6, "correct_answer": "号手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老号手是用铜做的。", "explanation": "这里应该用〈号〉。号手是人，不是用铜做的乐器。"}, {"text": "他把老号手吹得很响。", "explanation": "这里应该用〈号〉。号手是吹号的人，被吹响的是号，不是人。"}, {"text": "老号手教他怎么把号手吹响。", "explanation": "号手指吹号的人，不能作“吹响”的对象，被吹响的是号角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "乐队里有一只号手。", "corrected_sentence": "乐队里有一名号手。", "error_description": "错误形式：“一只号手”；正确形式：“一名号手”。号手指人，应用人的量词“名”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
