INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "吹军号或号角的人。", "primary_collocate": null, "pronunciation": "hào shǒu", "ipa": "xaʊ̯˥˩ ʂoʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "清晨，号手站在操场上吹起了起床号。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位号手每天早上都吹军号。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队里的号手要练习很长时间。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们连队的号手。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "号手吹响了冲锋号，战士们冲了上去。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的爷爷年轻时是一名号手。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "号手的声音很大，远处也能听见。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的时候，号手先吹了一首曲子。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个号手背着一把铜号走过来。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做号手需要很好的气息。", "target_word": "号手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "号手们", "label": "复数"}], "register": "中性", "sense_fingerprint": "军队中吹军号或号角的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a70e542a-3e78-41c2-b2e4-2d7a51a2477b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid,