INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98526, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "号手", "is_correct": true, "explanation": "正确：号手 hào shǒu，指吹军号或号角的人。"}, {"text": "好手", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是能干的人。"}, {"text": "好受", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）、shòu（第四声）与 shǒu（第三声）声调都不同，意思是舒服。"}, {"text": "后手", "is_correct": false, "explanation": "hòu 与 hào 韵母不同（ou 与 ao），声调相同，意思是后手、后招。"}, {"text": "到手", "is_correct": false, "explanation": "dào 与 hào 声母不同（d 与 h），声调相同，意思是到手、得到。"}], "explanations": {"号手": "正确：号手 hào shǒu，指吹军号或号角的人。", "好手": "hǎo（第三声）与 hào（第四声）声调不同，意思是能干的人。", "好受": "hǎo（第三声）与 hào（第四声）、shòu（第四声）与 shǒu（第三声）声调都不同，意思是舒服。", "后手": "hòu 与 hào 韵母不同（ou 与 ao），声调相同，意思是后手、后招。", "到手": "dào 与 hào 声母不同（d 与 h），声调相同，意思是到手、得到。"}, "sentence_index": null, "correct_answer": "号手"}, "level_3": {"options": [{"text": "号手", "is_correct": true, "explanation": "正确：号手指吹军号的人，符合“清晨吹起床号”的语境。"}, {"text": "鼓手", "is_correct": false, "explanation": "语义：鼓手敲鼓，句中吹的是号，不能吹起号。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手唱歌，不吹号，与“吹起了起床号”不符。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“吹起……号”要求主语是吹号的人，厨师不能与之搭配。"}], "explanations": {"号手": "正确：号手指吹军号的人，符合“清晨吹起床号”的语境。", "鼓手": "语义：鼓手敲鼓，句中吹的是号，不能吹起号。", "歌手": "语义：歌手唱歌，不吹号，与“吹起了起床号”不符。", "厨师": "搭配：“吹起……号”要求主语是吹号的人，厨师不能与之搭配。"}, "sentence_index": 0, "correct_answer": "号手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们连队的号手，每天负责开车。", "explanation": "这里应该用〈司机〉。号手指吹号的人，不负责开车；负责开车的应说司机。"}, {"text": "他吹响了号手。", "explanation": "号手指吹号的人，是人而不是器具，不能作“吹响”的对象，被吹响的是号角。"}, {"text": "他是我们连队的号手，每天负责看病。", "explanation": "这里应该用〈医生〉。号手指吹号的人，不负责看病；给战士看病的应说医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "号手", "is_correct": true, "explanation": "正确：号手指吹号的人，这里说它的声音大，符合语境。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯不发声，句中说它的声音很大，说不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“声音很大”搭配能发声的人或物，窗帘不能与之搭配。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子没有声音，说它的声音大，与语境矛盾。"}], "explanations": {"号手": "正确：号手指吹号的人，这里说它的声音大，符合语境。", "台灯": "语义：台灯不发声，句中说它的声音很大，说不通。", "窗帘": "搭配：“声音很大”搭配能发声的人或物，窗帘不能与之搭配。", "镜子": "语义：镜子没有声音，说它的声音大，与语境矛盾。"}, "sentence_index": 6, "correct_answer": "号手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的号手是十号。", "explanation": "这里应该用〈号码〉。号手指吹号的人，不能用来表示编号；球衣等编号应说号码。"}, {"text": "他号手了一下午。", "explanation": "这里应该用〈吹号〉。号手是名词，指吹号的人，不能作动词；应说“吹了一下午号”。"}, {"text": "他是我们连队的号手，每天负责打扫操场。", "explanation": "这里应该用〈清洁工〉。号手指吹号的人，不负责打扫；打扫操场的应说清洁工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "连队里有一把号手。", "corrected_sentence": "连队里有一名号手。", "error_description": "错误形式：“一把号手”；正确形式：“一名号手”。号手指人，应用人的量词“名”，“把”只用于有柄的器具。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位号手们在操场上练习。", "corrected_sentence": "三位号手在操场上练习。", "error_description": "错误形式：“三位号手们”；正确形式：“三位号手”。名词前已有“数词＋量词”时，不能再加表示复数的“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
