INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98529, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "详情是一件事的每一个小地方都说清楚的情况。", "primary_collocate": null, "pronunciation": "xiáng qíng", "ipa": "ɕjɑŋ˧˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "详情请看下面的通知。", "target_word": "详情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想了解这次活动的详情。", "target_word": "详情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师还没有告诉我们考试的详情。", "target_word": "详情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的详情已经发在网上了。", "target_word": "详情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想知道旅行的详情，可以给我打电话。", "target_word": "详情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的详情，我今天才听说。", "target_word": "详情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把会议的详情发给我。", "target_word": "详情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想听听事故的详情。", "target_word": "详情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活动详情都写在这张纸上。", "target_word": "详情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于买房的详情，我下次再告诉你。", "target_word": "详情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "詳情", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一件事各个细节都说清楚的详细情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1baa88c0-478f-4d07-801d-78f872fad5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98529, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "详情", "is_correct": true, "explanation": "详情：一件事各个细节都说清楚的情况，是本题的目标词。"}, {"text": "乡情", "is_correct": false, "explanation": "乡情（xiāngqíng）与详情（xiángqíng）只有第一个音节声调不同（第一声与第二声），意思是对家乡的感情。"}, {"text": "响晴", "is_correct": false, "explanation": "响晴（xiǎngqíng）与详情只有第一个音节声调不同（第三声与第二声），意思是晴朗无云。"}, {"text": "闲情", "is_correct": false, "explanation": "闲情（xiánqíng）与详情只有第一个音节韵母不同（an 与 ang），意思是闲适的心情。"}], "explanations": {"详情": "详情：一件事各个细节都说清楚的情况，是本题的目标词。", "乡情": "乡情（xiāngqíng）与详情（xiángqíng）只有第一个音节声调不同（第一声与第二声），意思是对家乡的感情。", "响晴": "响晴（xiǎngqíng）与详情只有第一个音节声调不同（第三声与第二声），意思是晴朗无云。", "闲情": "闲情（xiánqíng）与详情只有第一个音节韵母不同（an 与 ang），意思是闲适的心情。"}, "sentence_index": null, "correct_answer": "详情"}, "level_3": {"options": [{"text": "详情", "is_correct": true, "explanation": "正确：“详情”指事情的具体细节，与“请看下面的通知”的语境相符。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“请看”的对象是通知里的具体内容，心情是感受，不能用“请看”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格特点，不是通知里需要查看的内容，句子说不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是地方，不是可以靠通知查看的事项，句子不合理。"}], "explanations": {"详情": "正确：“详情”指事情的具体细节，与“请看下面的通知”的语境相符。", "心情": "搭配：“请看”的对象是通知里的具体内容，心情是感受，不能用“请看”。", "脾气": "语义：脾气是性格特点，不是通知里需要查看的内容，句子说不通。", "花园": "语义：花园是地方，不是可以靠通知查看的事项，句子不合理。"}, "sentence_index": 0, "correct_answer": "详情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的详情很可爱。", "explanation": "这里应该用〈外貌〉。详情指事情的具体内容，形容人的样子可爱要用外貌。"}, {"text": "他的身体详情很好。", "explanation": "这里应该用〈情况〉。详情用于事情、活动的具体内容，说人的身体状况要用情况。"}, {"text": "这首歌的详情很动听。", "explanation": "这里应该用〈旋律〉。详情指事情的具体内容，形容歌曲好听要用旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98529, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "详情", "is_correct": true, "explanation": "详情：一件事各个细节都说清楚的情况，是本题的目标词。"}, {"text": "乡亲", "is_correct": false, "explanation": "乡亲（xiāngqīn）与详情两个音节的声调都不同，意思是同乡的人。"}, {"text": "香芹", "is_correct": false, "explanation": "香芹（xiāngqín）第一音节声调不同（第一声与第二声），第二音节韵母 in 与 ing 不同，意思是一种蔬菜。"}, {"text": "性情", "is_correct": false, "explanation": "性情（xìngqíng）与详情（xiángqíng）的第一个音节韵母不同（ing 与 iang），声调也不同（第四声与第二声），意思是人的性格。"}, {"text": "相亲", "is_correct": false, "explanation": "相亲（xiāngqīn）与详情（xiángqíng）两个音节的声调都不同，第二音节韵母 in 与 ing 也不同，意思是男女见面看是否合适结婚。"}], "explanations": {"详情": "详情：一件事各个细节都说清楚的情况，是本题的目标词。", "乡亲": "乡亲（xiāngqīn）与详情两个音节的声调都不同，意思是同乡的人。", "香芹": "香芹（xiāngqín）第一音节声调不同（第一声与第二声），第二音节韵母 in 与 ing 不同，意思是一种蔬菜。", "性情": "性情（xìngqíng）与详情（xiángqíng）的第一个音节韵母不同（ing 与 iang），声调也不同（第四声与第二声），意思是人的性格。", "相亲": "相亲（xiāngqīn）与详情（xiángqíng）两个音节的声调都不同，第二音节韵母 in 与 ing 也不同，意思是男女见面看是否合适结婚。"}, "sentence_index": null, "correct_answer": "详情"}, "level_3": {"options": [{"text": "详情", "is_correct": true, "explanation": "正确：“详情”指事情的具体细节，作“发”的宾语，指会议的具体内容，语境相符。"}, {"text": "容貌", "is_correct": false, "explanation": "体貌：容貌指人的相貌，不能作为“发给我”的对象。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以发送的资料，句子说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“发”不能与脚步搭配，脚步不是可以发送的东西。"}], "explanations": {"详情": "正确：“详情”指事情的具体细节，作“发”的宾语，指会议的具体内容，语境相符。", "容貌": "体貌：容貌指人的相貌，不能作为“发给我”的对象。", "石头": "语义：石头不是可以发送的资料，句子说不通。", "脚步": "搭配：“发”不能与脚步搭配，脚步不是可以发送的东西。"}, "sentence_index": 6, "correct_answer": "详情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸色详情很差。", "explanation": "这里应该用〈气色〉。详情指事情的具体内容，形容人的气色差要用气色。"}, {"text": "班级的纪律详情很好。", "explanation": "这里应该用〈情况〉。详情用于事情、活动的具体内容，说班级的纪律状况要用情况。"}, {"text": "这位歌手的详情很有名。", "explanation": "这里应该用〈名气〉。详情指事情的具体内容，形容人有名要用名气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98529, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想先了解一下这次培训很详情。", "corrected_sentence": "我想先了解一下这次培训的详情。", "error_description": "错误：名词“详情”前用了副词“很”。“详情”是名词，不能被“很”修饰，应把“很”改为“的”，作“培训”的定语，写成“这次培训的详情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98529, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份合同的详情们我还没看完。", "corrected_sentence": "这份合同的详情我还没看完。", "error_description": "错误：在不可数的名词“详情”后面加了复数词尾“们”。“详情”不能加“们”，应直接说“这份合同的详情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
