INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98533, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "调动是把人或东西换到别的地方去做事。", "primary_collocate": null, "pronunciation": "diào dòng", "ipa": "tjɑʊ˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "公司把他调动到上海分公司工作。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理调动了三个人去做新项目。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把一些机器调动到新车间。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院调动了更多的医生去帮忙。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了赶时间，经理调动了车间的工人。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把几位老师调动到了山区学校。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在调动员工去外地开会。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防队调动了五辆车去救火。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市调动了一批货去新店。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想调动一下人手，早点做完工作。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调动了", "label": "完成体"}, {"form": "调动过", "label": "经历体"}, {"form": "调动调动", "label": "重叠"}], "register": "中性", "sense_fingerprint": "调动|动词|把人或东西换到别的地方去做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90645a6b-93e3-4121-8054-48deb9684cb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98533, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调动", "is_correct": true, "explanation": "正确：调动指把人或东西换到别的地方去做事，与听到的“diào dòng”一致。"}, {"text": "跳动", "is_correct": false, "explanation": "tiào（第四声）与 diào（第四声）声母不同（t/d），意思是跳动，指有节奏地跳跃或振动。"}, {"text": "电动", "is_correct": false, "explanation": "diàn（第四声）与 diào（第四声）韵母不同（an/ao），意思是电动，指靠电力运转。"}, {"text": "带动", "is_correct": false, "explanation": "dài（第四声）与 diào（第四声）韵母不同（ai/iao），意思是带动，指引导、促使别人一起行动。"}], "explanations": {"调动": "正确：调动指把人或东西换到别的地方去做事，与听到的“diào dòng”一致。", "跳动": "tiào（第四声）与 diào（第四声）声母不同（t/d），意思是跳动，指有节奏地跳跃或振动。", "电动": "diàn（第四声）与 diào（第四声）韵母不同（an/ao），意思是电动，指靠电力运转。", "带动": "dài（第四声）与 diào（第四声）韵母不同（ai/iao），意思是带动，指引导、促使别人一起行动。"}, "sentence_index": null, "correct_answer": "调动"}, "level_3": {"options": [{"text": "调动", "is_correct": true, "explanation": "正确：调动指把人调到别处去做事，与“把他……到上海分公司工作”的人事调配相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢弃、抛掷，不能用来指把人调到别处去工作。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：搬多用于搬运物品，不能说“把他搬到分公司工作”来表示人事调配。"}, {"text": "拿", "is_correct": false, "explanation": "语义：拿是握取、拿取，与人员调派的意思不符。"}], "explanations": {"调动": "正确：调动指把人调到别处去做事，与“把他……到上海分公司工作”的人事调配相符。", "扔": "语义：扔是丢弃、抛掷，不能用来指把人调到别处去工作。", "搬": "搭配：搬多用于搬运物品，不能说“把他搬到分公司工作”来表示人事调配。", "拿": "语义：拿是握取、拿取，与人员调派的意思不符。"}, "sentence_index": 0, "correct_answer": "调动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司调动了工作时间，改成了早九点。", "explanation": "这里应该用〈调整〉。调动用于把人或东西转到别处，时间不能被转移，应说调整工作时间。"}, {"text": "大家调动了这个问题，很快就解决了。", "explanation": "这里应该用〈讨论〉。此义的“调动”只用于人或实体物，不能搭配“问题”，应说讨论问题。"}, {"text": "这个旋钮可以调动温度。", "explanation": "这里应该用〈调节〉。调动指转移人或物，温度是可以调节的数值，不能被调动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调动", "is_correct": true, "explanation": "正确：调动指把人调派到别处，与“公司正在……员工去外地开会”的安排相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是进食，不能用来指公司安排员工去外地。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理指修复器物，不能用来指调派员工。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：打扫的对象是场地或房间，不能与“员工”这样的人作宾语。"}], "explanations": {"调动": "正确：调动指把人调派到别处，与“公司正在……员工去外地开会”的安排相符。", "吃": "语义：吃是进食，不能用来指公司安排员工去外地。", "修理": "语义：修理指修复器物，不能用来指调派员工。", "打扫": "搭配：打扫的对象是场地或房间，不能与“员工”这样的人作宾语。"}, "sentence_index": 6, "correct_answer": "调动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次改革调动了三条新规定。", "explanation": "这里应该用〈制定〉。此义的“调动”不能搭配“规定”，应说制定规定。"}, {"text": "她调动了一下眼神，把目光移开了。", "explanation": "这里应该用〈转移〉。此义的“调动”只用于人或实体物，“眼神”不能作其对象，应说转移目光。"}, {"text": "他把这个计划调动了一下。", "explanation": "这里应该用〈修改〉。此义的“调动”不能搭配“计划”，应说修改计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司把小李调动北京分公司工作。", "corrected_sentence": "公司把小李调动到北京分公司工作。", "error_description": "错误：“调动”引出目的地须用介词“到”，此句漏掉了“到”，应说“把小李调动到北京分公司工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教务处正在调动了几位老师去外地培训。", "corrected_sentence": "教务处正在调动几位老师去外地培训。", "error_description": "错误：“正在”表示动作进行中，不能与表示完成的“了”同用。“调动”后应去掉“了”，说“正在调动几位老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
