INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变更位置或职务；也指调集。", "primary_collocate": null, "pronunciation": "diào dòng", "ipa": "tjɑʊ˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的职务调动了，下个月去新部门。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队连夜调动了很多人到边境。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想调动他的职务，让他当经理。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想调动工作，想一直留在这里。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家调动了大批物资去灾区。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校最近调动了几位老师的教学岗位。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚被调动到新单位，还不熟悉新同事。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥官下令调动全部兵力。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂里调动了两位师傅的岗位。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为家里有事，他申请调动到老家的分局。", "target_word": "调动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调动了", "label": "完成体"}, {"form": "调动过", "label": "经历体"}, {"form": "调动调动", "label": "重叠"}], "register": "中性", "sense_fingerprint": "调动|动词|变更位置或职务；调集", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90645a6b-93e3-4121-8054-48deb9684cb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98534, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调动", "is_correct": true, "explanation": "正确：调动指变更位置或职务，与听到的“diào dòng”一致。"}, {"text": "跳动", "is_correct": false, "explanation": "tiào（第四声）与 diào（第四声）声母不同（t/d），意思是跳动，指有节奏地跳跃或振动。"}, {"text": "电动", "is_correct": false, "explanation": "diàn（第四声）与 diào（第四声）韵母不同（an/ao），意思是电动，指靠电力运转。"}, {"text": "带动", "is_correct": false, "explanation": "dài（第四声）与 diào（第四声）韵母不同（ai/iao），意思是带动，指引导、促使别人一起行动。"}], "explanations": {"调动": "正确：调动指变更位置或职务，与听到的“diào dòng”一致。", "跳动": "tiào（第四声）与 diào（第四声）声母不同（t/d），意思是跳动，指有节奏地跳跃或振动。", "电动": "diàn（第四声）与 diào（第四声）韵母不同（an/ao），意思是电动，指靠电力运转。", "带动": "dài（第四声）与 diào（第四声）韵母不同（ai/iao），意思是带动，指引导、促使别人一起行动。"}, "sentence_index": null, "correct_answer": "调动"}, "level_3": {"options": [{"text": "调动", "is_correct": true, "explanation": "正确：调动指变更职务或位置，与“职务……了，下个月去新部门”的意思相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是进食，不能用来指职务发生变化。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”是修理、修补，不能用于职务的变动。"}, {"text": "放", "is_correct": false, "explanation": "搭配：“放”是放置、释放，不能用于职务的变动。"}], "explanations": {"调动": "正确：调动指变更职务或位置，与“职务……了，下个月去新部门”的意思相符。", "吃": "语义：吃是进食，不能用来指职务发生变化。", "修": "搭配：“修”是修理、修补，不能用于职务的变动。", "放": "搭配：“放”是放置、释放，不能用于职务的变动。"}, "sentence_index": 0, "correct_answer": "调动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这条裤子的长度调动了一下。", "explanation": "这里应该用〈改〉。调动用于变更人的职务或位置，裤子长度是可以修改的数值，不能被调动，应说修改长度。"}, {"text": "公司调动了一下上班时间。", "explanation": "这里应该用〈调整〉。调动用于变更人的职务或位置，上班时间是抽象安排，应说调整。"}, {"text": "这次考试他调动了成绩，比上次高了很多。", "explanation": "这里应该用〈提高〉。调动指变更人或物的位置或职务，成绩是数量，不能被调动，应说提高成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调动", "is_correct": true, "explanation": "正确：调动指变更人的职务或工作单位，与“刚被……到新单位”的意思相符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于擦拭表面，不能与“单位”搭配表示变更。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“吵”是争吵，不能表示变更所在的单位。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物品或身体，不能与“单位”这样的组织搭配。"}], "explanations": {"调动": "正确：调动指变更人的职务或工作单位，与“刚被……到新单位”的意思相符。", "擦": "搭配：“擦”用于擦拭表面，不能与“单位”搭配表示变更。", "吵": "语义：“吵”是争吵，不能表示变更所在的单位。", "洗": "搭配：“洗”的对象是物品或身体，不能与“单位”这样的组织搭配。"}, "sentence_index": 6, "correct_answer": "调动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想调动一下菜的咸淡，结果放太多盐了。", "explanation": "这里应该用〈调节〉。调动指变更人或物的位置或职务，咸淡是味道的程度，不能被调动，应说调节咸淡。"}, {"text": "他从小就调动了一个爱好。", "explanation": "这里应该用〈培养〉。爱好是抽象的，不能被转移，应说培养爱好。"}, {"text": "他把自己的生日调动到了明天。", "explanation": "这里应该用〈改〉。调动指变更人的职务或位置，生日是日期，不能被调动，应说把生日改到明天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的职务调动在北京分公司了。", "corrected_sentence": "他的职务调动到北京分公司了。", "error_description": "错误：“调动”后面的介词用了“在”。变更职务到某处应说“调动到”，不能用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "领导说他下个月调动了到分公司。", "corrected_sentence": "领导说他下个月调动到分公司。", "error_description": "错误：“下个月”指将来，“调动”后不能加“了”表示已经完成。应说“下个月调动到分公司”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
