INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98537, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "证件是一张小卡或小本子，上面写着你是谁。", "primary_collocate": null, "pronunciation": "zhèng jiàn", "ipa": "ʈʂəŋ˥˩ tɕiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "进门以前，请给我看一下你的证件。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的证件放在书包里了。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把证件忘在家里了。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张证件上有你的名字和照片。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机要带着证件。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把证件交给前面的老师。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我丢了证件，很着急。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小本子是他的证件。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相馆可以给你照证件用的照片。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天出门都带着证件。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}], "register": "中性", "sense_fingerprint": "写着持有人身份的小卡或小本子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49f408f-adef-4962-af02-3ece88a3a05a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98537, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "证件", "is_correct": true, "explanation": "“证件”是可以拿来给人看的身份卡片或文件，符合句意。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”看不见，不能在门口“看一下”。"}, {"text": "理想", "is_correct": false, "explanation": "语义：“理想”是人的追求，不是可以拿来看的东西。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“看”不跟“脾气”搭配，不说“看一下你的脾气”。"}], "explanations": {"证件": "“证件”是可以拿来给人看的身份卡片或文件，符合句意。", "心情": "语义：“心情”看不见，不能在门口“看一下”。", "理想": "语义：“理想”是人的追求，不是可以拿来看的东西。", "脾气": "搭配：“看”不跟“脾气”搭配，不说“看一下你的脾气”。"}, "sentence_index": 0, "correct_answer": "证件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张照片是他去过那里的重要证件。", "explanation": "这里应该用〈证据〉。证件是证明身份的卡片或文件，证明某件事真实的要用〈证据〉。"}, {"text": "他递给我一张证件，说要用来交换联系方式。", "explanation": "这里应该用〈名片〉。证件是身份卡，交换联系方式要用〈名片〉。"}, {"text": "他拿着一张证件在陌生的城市里找路。", "explanation": "这里应该用〈地图〉。证件是证明身份的卡片，在陌生的城市找路要用〈地图〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98537, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "证件", "is_correct": true, "explanation": "“证件”是可以丢失的卡片或文件，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气候状况，不是可以丢失的东西。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不是可以丢失的物品，与句意不合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是事物的属性，不能像东西一样丢失。"}], "explanations": {"证件": "“证件”是可以丢失的卡片或文件，符合句意。", "天气": "语义：“天气”是气候状况，不是可以丢失的东西。", "月亮": "语义：“月亮”不是可以丢失的物品，与句意不合。", "颜色": "语义：“颜色”是事物的属性，不能像东西一样丢失。"}, "sentence_index": 6, "correct_answer": "证件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿着证件给朋友打电话。", "explanation": "这里应该用〈手机〉。证件是写着身份的小卡片，打电话要用〈手机〉。"}, {"text": "下雨了，他拿着证件遮雨。", "explanation": "这里应该用〈雨伞〉。证件是身份卡，遮雨要用〈雨伞〉。"}, {"text": "他在文件上盖了证件。", "explanation": "这里应该用〈印章〉。在文件上“盖”的是印章，证件是卡片，不能盖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他出门时带了一条证件。", "corrected_sentence": "他出门时带了一张证件。", "error_description": "量词错误：“条”用于长条形的东西，证件是卡片，应用“张”，不能说“一条证件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的包里放着两条证件。", "corrected_sentence": "她的包里放着两张证件。", "error_description": "量词错误：证件是小卡片，量词用“张”，不能说“两条证件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
