INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98538, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "证明身份、资格等的文件。", "primary_collocate": null, "pronunciation": "zhèng jiàn", "ipa": "ʈʂəŋ˥˩ tɕiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "办理银行卡需要有效证件。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国人住酒店，要出示证件。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请工作时，要交相关证件。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些证件可以证明你的资格。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请准备好所有证件再来办事。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的证件过期了，不能用了。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员正在检查大家的证件。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办签证要交哪些证件？", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有证件，你不能参加考试。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着证件去办公室办手续。", "target_word": "证件", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}], "register": "书面", "sense_fingerprint": "办事时用来证明身份、资格的文件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49f408f-adef-4962-af02-3ece88a3a05a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98538, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "证件", "is_correct": true, "explanation": "“证件”是证明身份或资格的文件，“有效”可以修饰它，符合句意。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”是用来喝的东西，办银行卡不需要“有效饮料”。"}, {"text": "零食", "is_correct": false, "explanation": "语义：“零食”是小吃，与办理银行卡无关，不能说“有效零食”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”是给孩子玩的东西，办银行卡不需要“有效玩具”。"}], "explanations": {"证件": "“证件”是证明身份或资格的文件，“有效”可以修饰它，符合句意。", "饮料": "语义：“饮料”是用来喝的东西，办银行卡不需要“有效饮料”。", "零食": "语义：“零食”是小吃，与办理银行卡无关，不能说“有效零食”。", "玩具": "语义：“玩具”是给孩子玩的东西，办银行卡不需要“有效玩具”。"}, "sentence_index": 0, "correct_answer": "证件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张证件在夜里发光，照亮了小路。", "explanation": "这里应该用〈手电筒〉。证件是证明资格的文件，不能发光照明，要用〈手电筒〉。"}, {"text": "他用这份证件付了两斤苹果的钱。", "explanation": "这里应该用〈钱〉。证件是证明资格的文件，不能用来付钱买东西。"}, {"text": "这份证件教我怎么做红烧肉。", "explanation": "这里应该用〈菜谱〉。证件是证明资格的文件，教人做菜的是〈菜谱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "证件", "is_correct": true, "explanation": "“证件”是可以检查的文件，“检查大家的证件”符合句意。"}, {"text": "感情", "is_correct": false, "explanation": "语义：“感情”是内心的情绪，不是可以检查的东西。"}, {"text": "影子", "is_correct": false, "explanation": "语义：“影子”是光线形成的暗影，不能被检查。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“检查”一般用于证件、作业等可核对的东西，不说检查“脾气”。"}], "explanations": {"证件": "“证件”是可以检查的文件，“检查大家的证件”符合句意。", "感情": "语义：“感情”是内心的情绪，不是可以检查的东西。", "影子": "语义：“影子”是光线形成的暗影，不能被检查。", "脾气": "搭配：“检查”一般用于证件、作业等可核对的东西，不说检查“脾气”。"}, "sentence_index": 6, "correct_answer": "证件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把证件送给了朋友当生日礼物。", "explanation": "这里应该用〈礼物〉。证件是证明身份、资格的文件，不能当生日礼物送人。"}, {"text": "他用证件在纸上写字。", "explanation": "这里应该用〈笔〉。证件是证明资格的文件，写字要用〈笔〉。"}, {"text": "他用证件切菜。", "explanation": "这里应该用〈菜刀〉。证件是证明资格的文件，切菜要用〈菜刀〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的证件被过期了，需要重新办理。", "corrected_sentence": "我的证件过期了，需要重新办理。", "error_description": "“被”误用：“过期”不是及物动词，不能用于被动句，应说“证件过期了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经了交证件，可以走了。", "corrected_sentence": "他已经交了证件，可以走了。", "error_description": "“了”的位置错误：完成的“了”要放在动词后面，应说“交了证件”，不能说“了交证件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98541, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "常量", "is_correct": true, "explanation": "反义：“常量”指值固定不变的量，与值可以变化的“变量”相对。"}, {"text": "公式", "is_correct": false, "explanation": "无关：“公式”是表示关系的式子，与变量不构成反义。"}, {"text": "数字", "is_correct": false, "explanation": "无关：“数字”指数码或数值，与变量没有反义关系。"}, {"text": "括号", "is_correct": false, "explanation": "无关：“括号”是符号，与变量没有反义关系。"}], "correct_answer": "常量", "explanations": {"常量": "反义：“常量”指值固定不变的量，与值可以变化的“变量”相对。", "公式": "无关：“公式”是表示关系的式子，与变量不构成反义。", "数字": "无关：“数字”指数码或数值，与变量没有反义关系。", "括号": "无关：“括号”是符号，与变量没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98541, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "常量", "is_correct": true, "explanation": "反义：“常量”指值固定的量，与可以取不同值的“变量”相对。"}, {"text": "黑板", "is_correct": false, "explanation": "无关：“黑板”是写字用的板子，与变量没有反义关系。"}, {"text": "橡皮", "is_correct": false, "explanation": "无关：“橡皮”是擦字用的文具，与变量没有反义关系。"}, {"text": "铅笔", "is_correct": false, "explanation": "无关：“铅笔”是写字用的文具，与变量没有反义关系。"}], "correct_answer": "常量", "explanations": {"常量": "反义：“常量”指值固定的量，与可以取不同值的“变量”相对。", "黑板": "无关：“黑板”是写字用的板子，与变量没有反义关系。", "橡皮": "无关：“橡皮”是擦字用的文具，与变量没有反义关系。", "铅笔": "无关：“铅笔”是写字用的文具，与变量没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98541, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "变量是算式里可以换成不同数的那个字母。", "primary_collocate": null, "pronunciation": "biàn liàng", "ipa": "pjɛn˥˩ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "算式里的字母是变量。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了一个变量。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个算式里有两个变量。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变量可以换成不同的数。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把变量换成三再算一遍。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算式中的变量用字母来表示。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不知道这个字母是不是变量。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变量换了，答案也会不同。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题里的变量一共有三个。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你找出算式里的变量。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "自变量", "label": "复合词"}, {"form": "因变量", "label": "复合词"}], "register": "书面", "sense_fingerprint": "算式中可以换成不同数的字母", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3810a26-ecf2-428b-beee-e994530c768a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98541, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变量", "is_correct": true, "explanation": "正确：“变量”指算式里可以换成不同数的字母，与“算式里的字母是……”相符。"}, {"text": "数字", "is_correct": false, "explanation": "语义：“数字”指0到9等数码，字母不是数字，句子说不通。"}, {"text": "括号", "is_correct": false, "explanation": "语义：“括号”是符号，字母不能被称为括号。"}, {"text": "加号", "is_correct": false, "explanation": "搭配：“加号”是运算符号，不与“字母”构成判断关系，“字母是加号”不成立。"}], "explanations": {"变量": "正确：“变量”指算式里可以换成不同数的字母，与“算式里的字母是……”相符。", "数字": "语义：“数字”指0到9等数码，字母不是数字，句子说不通。", "括号": "语义：“括号”是符号，字母不能被称为括号。", "加号": "搭配：“加号”是运算符号，不与“字母”构成判断关系，“字母是加号”不成立。"}, "sentence_index": 0, "correct_answer": "变量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "圆周率π是一个变量，它的值一直是3.14。", "explanation": "这里应该用〈常数〉。圆周率的值固定不变，变量的值可以变化，所以要用常数。"}, {"text": "在3x中，3是变量。", "explanation": "这里应该用〈系数〉。3与x相乘，表示固定的倍数，叫系数；变量指x这样的字母。"}, {"text": "长方形的面积等于长乘宽，这是一个变量。", "explanation": "这里应该用〈公式〉。“面积等于长乘宽”是表示关系的式子，叫公式；变量指式子里可以换成不同数的字母。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98541, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变量", "is_correct": true, "explanation": "正确：“变量”是算式中可换成不同数的字母，句子说的是这个字母是否属于此类。"}, {"text": "小数", "is_correct": false, "explanation": "语义：“小数”是带小数点的数，字母不能说是小数，句子说不通。"}, {"text": "减号", "is_correct": false, "explanation": "语义：“减号”是运算符号，不能用来指代字母。"}, {"text": "加法", "is_correct": false, "explanation": "搭配：“加法”指运算，不与“这个字母是不是”构成同类判断。"}], "explanations": {"变量": "正确：“变量”是算式中可换成不同数的字母，句子说的是这个字母是否属于此类。", "小数": "语义：“小数”是带小数点的数，字母不能说是小数，句子说不通。", "减号": "语义：“减号”是运算符号，不能用来指代字母。", "加法": "搭配：“加法”指运算，不与“这个字母是不是”构成同类判断。"}, "sentence_index": 6, "correct_answer": "变量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气预报说明天会变量很大。", "explanation": "这里应该用〈变化〉。变量是名词，不能作谓语动词；说天气起伏要用〈变化〉。"}, {"text": "y=2x是一个变量。", "explanation": "这里应该用〈函数〉。y=2x表示y随x变化的对应关系，整个式子是函数，x和y才是变量。"}, {"text": "他的性格很变量，今天高兴，明天就不理人了。", "explanation": "这里误用了〈变量〉：变量是名词，指数学里可取不同数值的量；形容性格反复无常应该用〈多变〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个式子里只有一只变量。", "corrected_sentence": "这个式子里只有一个变量。", "error_description": "错误：“一只变量”。“变量”是抽象名词，量词应用“个”，不用“只”，正确为“一个变量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经找到了算式里的两个变量们。", "corrected_sentence": "他已经找到了算式里的两个变量。", "error_description": "错误：“变量们”。“们”只用于指人的名词，“变量”后不能加“们”，正确为“两个变量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98542, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "常量", "is_correct": true, "explanation": "反义：“常量”指值固定不变的量，与值可变的“变量”相对。"}, {"text": "方程", "is_correct": false, "explanation": "无关：“方程”是含未知数的等式，与变量没有反义关系。"}, {"text": "图形", "is_correct": false, "explanation": "无关：“图形”指形状，与变量没有反义关系。"}, {"text": "答案", "is_correct": false, "explanation": "无关：“答案”是解题的结果，与变量没有反义关系。"}], "correct_answer": "常量", "explanations": {"常量": "反义：“常量”指值固定不变的量，与值可变的“变量”相对。", "方程": "无关：“方程”是含未知数的等式，与变量没有反义关系。", "图形": "无关：“图形”指形状，与变量没有反义关系。", "答案": "无关：“答案”是解题的结果，与变量没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98542, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "常量", "is_correct": true, "explanation": "反义：“常量”指值固定的量，与可以取不同值的“变量”相对。"}, {"text": "公式", "is_correct": false, "explanation": "无关：“公式”是表示关系的式子，与变量没有反义关系。"}, {"text": "数字", "is_correct": false, "explanation": "无关：“数字”指数码或数值，与变量没有反义关系。"}, {"text": "括号", "is_correct": false, "explanation": "无关：“括号”是符号，与变量没有反义关系。"}], "correct_answer": "常量", "explanations": {"常量": "反义：“常量”指值固定的量，与可以取不同值的“变量”相对。", "公式": "无关：“公式”是表示关系的式子，与变量没有反义关系。", "数字": "无关：“数字”指数码或数值，与变量没有反义关系。", "括号": "无关：“括号”是符号，与变量没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数学中可以取不同数值的量。", "primary_collocate": null, "pronunciation": "biàn liàng", "ipa": "pjɛn˥˩ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "数学里的变量可以取很多值。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度和时间都可以看成变量。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个函数有两个变量。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变量的值不是固定的。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们画出变量的变化。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路程是一个随时间变化的变量。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "速度是一个会变的变量。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图上的两个变量有关系。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生要学会看变量的变化。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格是这个题目里的变量。", "target_word": "变量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "自变量", "label": "复合词"}, {"form": "因变量", "label": "复合词"}], "register": "书面", "sense_fingerprint": "数学中可取不同数值的量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3810a26-ecf2-428b-beee-e994530c768a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变量", "is_correct": true, "explanation": "正确：数学中可以取不同数值的量，与“可以取很多值”相符。"}, {"text": "常数", "is_correct": false, "explanation": "语义：“常数”的值固定不变，不能取很多值。"}, {"text": "三角形", "is_correct": false, "explanation": "语义：“三角形”是图形，没有可以取很多值的数值。"}, {"text": "图形", "is_correct": false, "explanation": "搭配：“取值”只用于数或量，“图形”不能取值。"}], "explanations": {"变量": "正确：数学中可以取不同数值的量，与“可以取很多值”相符。", "常数": "语义：“常数”的值固定不变，不能取很多值。", "三角形": "语义：“三角形”是图形，没有可以取很多值的数值。", "图形": "搭配：“取值”只用于数或量，“图形”不能取值。"}, "sentence_index": 0, "correct_answer": "变量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "自然常数e是一个变量，它的值一直是2.718。", "explanation": "这里应该用〈常数〉。e的值固定不变，变量的值可以变化，所以要用常数。"}, {"text": "在3x中，3是变量。", "explanation": "这里应该用〈系数〉。3与x相乘，表示固定的倍数，叫系数；变量指x这样的字母。"}, {"text": "他的脾气很变量，一会儿笑一会儿哭。", "explanation": "这里误用了〈变量〉：变量是名词，指数学里可取不同数值的量；形容脾气反复无常应该用〈多变〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变量", "is_correct": true, "explanation": "正确：“变量”指数学中取值会变化的量，与“会变的……”相符。"}, {"text": "动物", "is_correct": false, "explanation": "语义：“动物”不是数值，“速度是一个会变的动物”与句意不符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是物体，不是可以取不同数值的量。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不是量，不能说“会变的颜色”来指速度。"}], "explanations": {"变量": "正确：“变量”指数学中取值会变化的量，与“会变的……”相符。", "动物": "语义：“动物”不是数值，“速度是一个会变的动物”与句意不符。", "石头": "语义：“石头”是物体，不是可以取不同数值的量。", "颜色": "搭配：“颜色”不是量，不能说“会变的颜色”来指速度。"}, "sentence_index": 6, "correct_answer": "变量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路程等于速度乘时间，这是一个变量。", "explanation": "这里应该用〈公式〉。“路程等于速度乘时间”是表示数量关系的式子，叫公式；路程、速度、时间才是变量。"}, {"text": "天气预报说明天会变量很大，大家出门要带伞。", "explanation": "这里应该用〈变化〉。变量是名词，不能作谓语动词；说天气起伏要用〈变化〉。"}, {"text": "y=2x是一个变量。", "explanation": "这里应该用〈函数〉。y=2x表示y随x变化的对应关系，整个式子是函数，x和y才是变量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个函数里有三只变量。", "corrected_sentence": "这个函数里有三个变量。", "error_description": "错误：“三只变量”。“变量”的量词是“个”，“只”多用于动物，正确为“三个变量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找出了函数里的两个变量们。", "corrected_sentence": "他找出了函数里的两个变量。", "error_description": "错误：“变量们”。“们”只用于指人的名词，“变量”后不能加“们”，正确为“两个变量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
