INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98545, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "贿赂是偷偷送钱或东西给别人，想让他帮自己做事。", "primary_collocate": null, "pronunciation": "huì lù", "ipa": "xweɪ˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "他偷偷贿赂门口的保安，想进去看比赛。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人想贿赂老师，让孩子的成绩好一点。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用红包贿赂了服务员，换到了好位子。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她贿赂过考官，想让朋友顺利通过考试。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会贿赂别人，也不接受别人的钱。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想贿赂警察，结果警察没有收。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个商人常常贿赂官员，后来出了大事。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贿赂裁判是不对的，比赛应该公平。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱放在信封里，想贿赂校长。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能用礼物贿赂我，我不会帮你的。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "贿赂了", "label": "完成体"}, {"form": "贿赂过", "label": "经历体"}, {"form": "賄賂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "偷偷送钱或东西给人，请他办事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00032f7-208c-448d-9c5f-b377604ba846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98545, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "贿赂", "is_correct": true, "explanation": "正确答案。贿赂指偷偷送财物给人，想让对方帮自己办事。"}, {"text": "汇率", "is_correct": false, "explanation": "lǜ 与 lù 只差韵母（ü 与 u），声调都是第四声，意思是汇率。"}, {"text": "会晤", "is_correct": false, "explanation": "wù 为零声母，lù 的声母是 l，声调都是第四声，意思是会晤、会面。"}, {"text": "回路", "is_correct": false, "explanation": "huí（第二声）与 huì（第四声）声调不同，意思是电路。"}], "explanations": {"贿赂": "正确答案。贿赂指偷偷送财物给人，想让对方帮自己办事。", "汇率": "lǜ 与 lù 只差韵母（ü 与 u），声调都是第四声，意思是汇率。", "会晤": "wù 为零声母，lù 的声母是 l，声调都是第四声，意思是会晤、会面。", "回路": "huí（第二声）与 huì（第四声）声调不同，意思是电路。"}, "sentence_index": null, "correct_answer": "贿赂"}, "level_3": {"options": [{"text": "贿赂", "is_correct": true, "explanation": "正确答案。贿赂指暗中送财物给保安，换取他放行。"}, {"text": "逮捕", "is_correct": false, "explanation": "配价：「逮捕」要求执法人员作主语，普通人不能逮捕保安，句子不通。"}, {"text": "送别", "is_correct": false, "explanation": "语义：「送别」指离开时道别，与「偷偷」以及「想进去看比赛」的目的都不合。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：「祝贺」需要有喜事作由头，不能用来形容偷偷对保安做的事。"}], "explanations": {"贿赂": "正确答案。贿赂指暗中送财物给保安，换取他放行。", "逮捕": "配价：「逮捕」要求执法人员作主语，普通人不能逮捕保安，句子不通。", "送别": "语义：「送别」指离开时道别，与「偷偷」以及「想进去看比赛」的目的都不合。", "祝贺": "搭配：「祝贺」需要有喜事作由头，不能用来形容偷偷对保安做的事。"}, "sentence_index": 0, "correct_answer": "贿赂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每年都用一束花贿赂朋友，祝她生日快乐。", "explanation": "这里是送花表达心意的意思，没有想让对方办事的目的。贿赂指以财物换取办事，不能用来形容生日礼物。"}, {"text": "他想用钱贿赂那台旧电脑，希望它快点运行。", "explanation": "这里应该用〈升级〉。升级指提升设备的性能，电脑可以升级；贿赂指用财物换取人替自己办事，不能用于机器。"}, {"text": "他贿赂朋友吃饭，希望大家都很高兴。", "explanation": "这里应该用〈招待〉。招待指请客吃饭、款待客人，贿赂强调以财物换取办事，不能用来形容请朋友吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98545, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贿赂", "is_correct": true, "explanation": "正确答案。贿赂指暗中送财物给官员，以换取对方办事。"}, {"text": "赦免", "is_correct": false, "explanation": "配价：「赦免」要求掌握权力的人作主语，商人不能赦免官员。"}, {"text": "脱离", "is_correct": false, "explanation": "搭配：「脱离」指离开组织或某种状态，不能直接以官员作宾语。"}, {"text": "检阅", "is_correct": false, "explanation": "语义：「检阅」指检查部队或队伍，与商人和官员的关系不符。"}], "explanations": {"贿赂": "正确答案。贿赂指暗中送财物给官员，以换取对方办事。", "赦免": "配价：「赦免」要求掌握权力的人作主语，商人不能赦免官员。", "脱离": "搭配：「脱离」指离开组织或某种状态，不能直接以官员作宾语。", "检阅": "语义：「检阅」指检查部队或队伍，与商人和官员的关系不符。"}, "sentence_index": 6, "correct_answer": "贿赂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用钱贿赂人心，希望大家都喜欢他。", "explanation": "这里应该用〈收买〉。收买可以用于人心，贿赂只指以财物换取对方办事，不能用于人心。"}, {"text": "这个故事贿赂了很多人，让大家都哭了。", "explanation": "这里应该用〈打动〉。打动指使人感动，故事不能用财物换取办事，所以不能说贿赂人。"}, {"text": "公司贿赂了员工的损失，希望大家不再抱怨。", "explanation": "这里应该用〈补偿〉。补偿是弥补损失，贿赂不能用于损失这类结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98545, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他前年贿赂了过一位税务官，后来被调查了。", "corrected_sentence": "他前年贿赂过一位税务官，后来被调查了。", "error_description": "错误：「贿赂了过」。「了」与「过」不能同时用在同一个动词后面，表示经历时只用「贿赂过」。正确说法是「他前年贿赂过一位税务官」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98545, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司被贿赂过工作人员，后来被查出来了。", "corrected_sentence": "这家公司贿赂过工作人员，后来被查出来了。", "error_description": "错误：在「贿赂过」前加了「被」。「被」使「这家公司」变成受事，与「贿赂」所要求的施事相反，句子意思不通。应去掉「被」，写作「这家公司贿赂过工作人员」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
