INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98546, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用财物收买别人，使其为自己谋利。", "primary_collocate": null, "pronunciation": "huì lù", "ipa": "xweɪ˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "老板用名牌包贿赂经理，想拿到这个项目。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送一辆车贿赂那位官员，想得到工程。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司贿赂客户，拿到了很多合同。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿意贿赂别人，只想靠自己努力。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想用钱贿赂评委，让自己的作品得奖。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她贿赂了几个同事，让他们帮她说好话。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官说，贿赂证人是违法的行为。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人为了当上经理，到处贿赂领导。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾贿赂过税务人员，少交了很多税。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个商人一起贿赂市长，想买下那块地。", "target_word": "贿赂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "贿赂了", "label": "完成体"}, {"form": "贿赂过", "label": "经历体"}, {"form": "賄賂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用财物收买他人，使其为自己谋利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00032f7-208c-448d-9c5f-b377604ba846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98546, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "贿赂", "is_correct": true, "explanation": "正确答案。贿赂指以财物收买别人，使其为自己谋利。"}, {"text": "汇率", "is_correct": false, "explanation": "lǜ 与 lù 只差韵母（ü 与 u），声调都是第四声，意思是汇率。"}, {"text": "回炉", "is_correct": false, "explanation": "回炉（huí lú）与贿赂（huì lù）声母韵母相同，两个音节的声调不同，意思是重新熔炼。"}, {"text": "回路", "is_correct": false, "explanation": "huí（第二声）与 huì（第四声）声调不同，意思是电路。"}], "explanations": {"贿赂": "正确答案。贿赂指以财物收买别人，使其为自己谋利。", "汇率": "lǜ 与 lù 只差韵母（ü 与 u），声调都是第四声，意思是汇率。", "回炉": "回炉（huí lú）与贿赂（huì lù）声母韵母相同，两个音节的声调不同，意思是重新熔炼。", "回路": "huí（第二声）与 huì（第四声）声调不同，意思是电路。"}, "sentence_index": null, "correct_answer": "贿赂"}, "level_3": {"options": [{"text": "贿赂", "is_correct": true, "explanation": "正确答案。贿赂指用财物收买经理，让他为自己办事。"}, {"text": "检测", "is_correct": false, "explanation": "搭配：「检测」的对象是产品或指标，不能用来检测经理。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：「装饰」用于美化物品或场所，不能用名牌包装饰经理。"}, {"text": "拍卖", "is_correct": false, "explanation": "配价：「拍卖」要求拍卖品作宾语，经理不能被拍卖。"}], "explanations": {"贿赂": "正确答案。贿赂指用财物收买经理，让他为自己办事。", "检测": "搭配：「检测」的对象是产品或指标，不能用来检测经理。", "装饰": "搭配：「装饰」用于美化物品或场所，不能用名牌包装饰经理。", "拍卖": "配价：「拍卖」要求拍卖品作宾语，经理不能被拍卖。"}, "sentence_index": 0, "correct_answer": "贿赂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板贿赂了员工的损失，希望大家别再抱怨。", "explanation": "这里应该用〈补偿〉。补偿是弥补损失，贿赂不能用于损失这类结果。"}, {"text": "他贿赂朋友吃饭，希望大家都很高兴。", "explanation": "这里应该用〈招待〉。招待指请客吃饭、款待客人，贿赂强调以财物换取办事，不能用来形容请朋友吃饭。"}, {"text": "他每年都用一束花贿赂朋友，祝她生日快乐。", "explanation": "这里是送花表达心意的意思，没有想让对方办事的目的。贿赂指以财物换取办事，不能用来形容生日礼物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贿赂", "is_correct": true, "explanation": "正确答案。贿赂是违法的行为，指以财物换取对方办事。"}, {"text": "批准", "is_correct": false, "explanation": "配价：「批准」要求有权的机构作主语，证人不能作批准的对象。"}, {"text": "叫醒", "is_correct": false, "explanation": "语义：「叫醒」指让睡着的人醒来，与证人、违法的判断无关。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：「赞美」是称赞，不是违法行为，与句子的判断矛盾。"}], "explanations": {"贿赂": "正确答案。贿赂是违法的行为，指以财物换取对方办事。", "批准": "配价：「批准」要求有权的机构作主语，证人不能作批准的对象。", "叫醒": "语义：「叫醒」指让睡着的人醒来，与证人、违法的判断无关。", "赞美": "语义：「赞美」是称赞，不是违法行为，与句子的判断矛盾。"}, "sentence_index": 6, "correct_answer": "贿赂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "几个商人一起用钱贿赂人心，想买下那块地。", "explanation": "这里应该用〈收买〉。收买可用于人心，贿赂只指用财物换取对方办事，不能用于人心。"}, {"text": "那部电影贿赂了很多观众，让大家都哭了。", "explanation": "这里应该用〈打动〉。打动指使人感动，电影没有用财物换取办事的行为，不能说贿赂观众。"}, {"text": "几个商人一起贿赂了那块地，想让它变得更好。", "explanation": "这里应该用〈改造〉。改造指使事物变得更好，土地可以改造；贿赂指用财物换取人替自己办事，不能用于土地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司去年被贿赂过审计人员，后来被罚了款。", "corrected_sentence": "这家公司去年贿赂过审计人员，后来被罚了款。", "error_description": "错误：在「贿赂过」前加了「被」。「被」使「这家公司」成了受事，与后面的宾语「审计人员」矛盾，应去掉「被」，写作「这家公司去年贿赂过审计人员」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个商人曾经贿赂了过一位工作人员，所以很快被查出来了。", "corrected_sentence": "这个商人曾经贿赂过一位工作人员，所以很快被查出来了。", "error_description": "错误：「了」与「过」同时出现在「贿赂」后。表示经历时只用「过」，应写作「贿赂过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
