INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98565, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赔是弄坏了别人的东西，要拿钱或者一样的东西还给他。", "primary_collocate": null, "pronunciation": "péi", "ipa": "pʰei̯˧˥", "syllable_count": 1, "sentences": [{"text": "我打破了他的杯子，要赔他一个。", "target_word": "赔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明弄坏了同学的书，只好赔他一本新的。", "target_word": "赔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把他的手机摔坏了，我来赔。", "target_word": "赔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你弄坏了我的车，要赔我。", "target_word": "赔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子打碎了邻居的玻璃，爸爸赔了五十块。", "target_word": "赔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把我的伞弄丢了，赔了我一把新的。", "target_word": "赔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁弄坏的，谁就赔。", "target_word": "赔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "狗咬坏了他的鞋，主人赔了新鞋。", "target_word": "赔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我打碎了商店的花瓶，只好赔了三百块。", "target_word": "赔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不小心弄坏了朋友的笔，我想赔他。", "target_word": "赔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "赔了", "label": "体标"}, {"form": "赔过", "label": "体标"}, {"form": "賠", "label": "繁体"}], "register": "中性", "sense_fingerprint": "赔：弄坏别人的东西后，用钱或同样的东西还给对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61055a68-0e57-44de-a57b-c0b45d7280bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98565, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赔", "is_correct": true, "explanation": "péi（第二声）指弄坏别人的东西后，用钱或同样的东西还给对方。"}, {"text": "配", "is_correct": false, "explanation": "pèi（第四声）与 péi（第二声）声调不同，意思是配合、配备。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 péi 声母 b、p 不同，声调也不同，意思是杯子。"}, {"text": "排", "is_correct": false, "explanation": "pái（第二声）与 péi 韵母 ai、ei 不同，意思是排列。"}, {"text": "派", "is_correct": false, "explanation": "pài（第四声）与 péi 韵母不同，声调也不同，意思是派别或派遣。"}, {"text": "被", "is_correct": false, "explanation": "bèi（第四声）与 péi 声母 b、p 不同，声调也不同，意思是被（表被动）。"}], "explanations": {"赔": "péi（第二声）指弄坏别人的东西后，用钱或同样的东西还给对方。", "配": "pèi（第四声）与 péi（第二声）声调不同，意思是配合、配备。", "杯": "bēi（第一声）与 péi 声母 b、p 不同，声调也不同，意思是杯子。", "排": "pái（第二声）与 péi 韵母 ai、ei 不同，意思是排列。", "派": "pài（第四声）与 péi 韵母不同，声调也不同，意思是派别或派遣。", "被": "bèi（第四声）与 péi 声母 b、p 不同，声调也不同，意思是被（表被动）。"}, "sentence_index": null, "correct_answer": "赔"}, "level_3": {"options": [{"text": "赔", "is_correct": true, "explanation": "赔是弄坏别人的东西后，还钱或同样的东西给对方，与句意相符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洁，与打破杯子后的补偿无关。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”指描绘，与弄坏东西后的补偿无关。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”不能与“一个”这样指实物的数量词搭配表示补偿。"}], "explanations": {"赔": "赔是弄坏别人的东西后，还钱或同样的东西给对方，与句意相符。", "洗": "语义：“洗”指清洁，与打破杯子后的补偿无关。", "画": "语义：“画”指描绘，与弄坏东西后的补偿无关。", "讲": "搭配：“讲”不能与“一个”这样指实物的数量词搭配表示补偿。"}, "sentence_index": 0, "correct_answer": "赔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用布把裤子赔好了。", "explanation": "这里应该用〈补〉。补是修补，能让破损的东西恢复；赔是拿钱或东西还给对方，不能用来修好衣服。"}, {"text": "我赔你去医院。", "explanation": "这里应该用〈陪〉。陪是陪同、陪伴；“赔”与“陪”同音，但赔是弄坏东西后的补偿，不能表示陪同。"}, {"text": "老师赔了我一支笔，因为我考得很好。", "explanation": "这里应该用〈奖〉。赔是补偿损失，不能用来奖励；考得好的奖励要用“奖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98565, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赔", "is_correct": true, "explanation": "péi（第二声）指弄坏别人的东西后，用钱或同样的东西还给对方。"}, {"text": "佩", "is_correct": false, "explanation": "pèi（第四声）与 péi（第二声）声调不同，意思是佩戴、佩服。"}, {"text": "悲", "is_correct": false, "explanation": "bēi（第一声）与 péi 声母 b、p 不同，声调也不同，意思是悲伤。"}, {"text": "背", "is_correct": false, "explanation": "bèi（第四声）与 péi 声母 b、p 不同，声调也不同，意思是背面。"}, {"text": "牌", "is_correct": false, "explanation": "pái（第二声）与 péi 声调相同，但韵母 ai 与 ei 不同，意思是牌子。"}, {"text": "妹", "is_correct": false, "explanation": "mèi（第四声）与 péi 声母 m、p 不同，声调也不同，意思是妹妹。"}], "explanations": {"赔": "péi（第二声）指弄坏别人的东西后，用钱或同样的东西还给对方。", "佩": "pèi（第四声）与 péi（第二声）声调不同，意思是佩戴、佩服。", "悲": "bēi（第一声）与 péi 声母 b、p 不同，声调也不同，意思是悲伤。", "背": "bèi（第四声）与 péi 声母 b、p 不同，声调也不同，意思是背面。", "牌": "pái（第二声）与 péi 声调相同，但韵母 ai 与 ei 不同，意思是牌子。", "妹": "mèi（第四声）与 péi 声母 m、p 不同，声调也不同，意思是妹妹。"}, "sentence_index": null, "correct_answer": "赔"}, "level_3": {"options": [{"text": "赔", "is_correct": true, "explanation": "赔是弄坏东西的人要承担补偿，与句意相符。"}, {"text": "笑", "is_correct": false, "explanation": "语义：谁弄坏的谁就笑，与承担补偿的意思毫无关系。"}, {"text": "玩", "is_correct": false, "explanation": "语义：“玩”指游戏或消遣，不能表示承担责任。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”表示承受时须带“亏”“苦”等宾语，单用“谁就吃”不成立。"}], "explanations": {"赔": "赔是弄坏东西的人要承担补偿，与句意相符。", "笑": "语义：谁弄坏的谁就笑，与承担补偿的意思毫无关系。", "玩": "语义：“玩”指游戏或消遣，不能表示承担责任。", "吃": "搭配：“吃”表示承受时须带“亏”“苦”等宾语，单用“谁就吃”不成立。"}, "sentence_index": 6, "correct_answer": "赔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把桌子赔好了。", "explanation": "这里应该用〈修〉。修是修理，能让坏的东西恢复；赔是还钱或还东西，不能用来修理桌子。"}, {"text": "妈妈把地板赔干净了。", "explanation": "这里应该用〈擦〉。擦是擦拭脏东西，赔是补偿损失，不能用来擦地板。"}, {"text": "我帮他搬家，他赔了我一顿饭。", "explanation": "这里应该用〈请〉。赔是补偿损失，不能用于答谢；请人吃饭要说“请”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把他的书弄丢了，所以赔他了一本新的。", "corrected_sentence": "我把他的书弄丢了，所以赔了他一本新的。", "error_description": "错误形式：“赔他了一本新的”；正确形式：“赔了他一本新的”。动态助词“了”须紧跟动词“赔”，不能放在宾语“他”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不小心弄坏了朋友的笔，已经赔他给一支新笔了。", "corrected_sentence": "我不小心弄坏了朋友的笔，已经赔给他一支新笔了。", "error_description": "错误形式：“赔他给一支新笔”；正确形式：“赔给他一支新笔”。“赔给”是一个整体，“给”须紧跟“赔”，不能拆开。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
