INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98570, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "产生某种作用或效果。", "primary_collocate": null, "pronunciation": "qǐ dào", "ipa": "tɕʰi˨˩˦ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这种药起到了很好的作用。", "target_word": "起到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话对他起到了鼓励的作用。", "target_word": "起到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动对身体健康能起到很大作用。", "target_word": "起到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法没有起到作用。", "target_word": "起到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的环境可以起到放松心情的作用。", "target_word": "起到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯起到提醒司机的作用。", "target_word": "起到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告起到过很大的作用。", "target_word": "起到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把伞太小，很难起到挡雨的作用。", "target_word": "起到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书对我学汉语起到了帮助的作用。", "target_word": "起到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树木在城市里起到保护环境的作用。", "target_word": "起到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起到了", "label": "体标"}, {"form": "起到过", "label": "体标"}, {"form": "起不到", "label": "可能补语否定"}], "register": "中性", "sense_fingerprint": "产生某种作用或效果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a70e542a-3e78-41c2-b2e4-2d7a51a2477b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98570, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "起到", "is_correct": true, "explanation": "正确：起到，产生某种作用或效果。"}, {"text": "气到", "is_correct": false, "explanation": "qì（第四声）与 qǐ（第三声）声调不同，意思是“被气得很厉害”。"}, {"text": "气道", "is_correct": false, "explanation": "qì（第四声）与 qǐ（第三声）声调不同，dào 相同，意思是“呼吸的通道”。"}, {"text": "骑到", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是“骑到车或马上”。"}], "explanations": {"起到": "正确：起到，产生某种作用或效果。", "气到": "qì（第四声）与 qǐ（第三声）声调不同，意思是“被气得很厉害”。", "气道": "qì（第四声）与 qǐ（第三声）声调不同，dào 相同，意思是“呼吸的通道”。", "骑到": "qí（第二声）与 qǐ（第三声）声调不同，意思是“骑到车或马上”。"}, "sentence_index": null, "correct_answer": "起到"}, "level_3": {"options": [{"text": "起到", "is_correct": true, "explanation": "正确：“起到了”表示这种药产生了效果，符合句意。"}, {"text": "撞", "is_correct": false, "explanation": "语义：“撞”指碰击，与“产生作用”无关，“撞了很好的作用”不成立。"}, {"text": "挡", "is_correct": false, "explanation": "语义：“挡”指阻拦，与“产生作用”无关，“挡了很好的作用”不成立。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：“拿”不能以“作用”为宾语，“拿了很好的作用”不成立。"}], "explanations": {"起到": "正确：“起到了”表示这种药产生了效果，符合句意。", "撞": "语义：“撞”指碰击，与“产生作用”无关，“撞了很好的作用”不成立。", "挡": "语义：“挡”指阻拦，与“产生作用”无关，“挡了很好的作用”不成立。", "拿": "搭配：“拿”不能以“作用”为宾语，“拿了很好的作用”不成立。"}, "sentence_index": 0, "correct_answer": "起到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在比赛中起到了自己的特长。", "explanation": "这里应该用〈发挥〉。起到的宾语是“作用、效果”一类，说“特长”要用“发挥”。"}, {"text": "他的成绩起到了九十分。", "explanation": "这里应该用〈达到〉。起到表示产生作用，不能与分数连用；“成绩达到九十分”要用“达到”。"}, {"text": "这个故事起到了孩子们的兴趣。", "explanation": "这里应该用〈引起〉。起到的宾语是“作用、效果”一类，“兴趣”要用“引起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98570, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "起到", "is_correct": true, "explanation": "正确：起到，产生某种作用或效果。"}, {"text": "挤到", "is_correct": false, "explanation": "jǐ 与 qǐ 的声母不同（j 与 q），声调相同，意思是“挤进去、挤到某处”。"}, {"text": "骑到", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是“骑到车或马上”。"}, {"text": "齐到", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是“全部到齐”。"}], "explanations": {"起到": "正确：起到，产生某种作用或效果。", "挤到": "jǐ 与 qǐ 的声母不同（j 与 q），声调相同，意思是“挤进去、挤到某处”。", "骑到": "qí（第二声）与 qǐ（第三声）声调不同，意思是“骑到车或马上”。", "齐到": "qí（第二声）与 qǐ（第三声）声调不同，意思是“全部到齐”。"}, "sentence_index": null, "correct_answer": "起到"}, "level_3": {"options": [{"text": "起到", "is_correct": true, "explanation": "正确：“起到过”表示广告产生过很大的作用，符合句意。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”指去掉，不能表示产生作用，“删除过很大的作用”不成立。"}, {"text": "碰", "is_correct": false, "explanation": "搭配：“碰”指接触，不能以“作用”为宾语。"}, {"text": "吞", "is_correct": false, "explanation": "搭配：“吞”不能与“作用”搭配，“吞过很大的作用”不成立。"}], "explanations": {"起到": "正确：“起到过”表示广告产生过很大的作用，符合句意。", "删除": "语义：“删除”指去掉，不能表示产生作用，“删除过很大的作用”不成立。", "碰": "搭配：“碰”指接触，不能以“作用”为宾语。", "吞": "搭配：“吞”不能与“作用”搭配，“吞过很大的作用”不成立。"}, "sentence_index": 6, "correct_answer": "起到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事起到了大家的注意。", "explanation": "这里应该用〈引起〉。起到的宾语是“作用、效果”一类，“注意”要用“引起”。"}, {"text": "这次活动起到了很多快乐。", "explanation": "这里应该用〈带来〉。起到的宾语是“作用、效果”一类，“快乐”要用“带来”。"}, {"text": "这场大雨起到了很大的损失。", "explanation": "这里应该用〈造成〉。起到的宾语是“作用、效果”一类，“损失”要用“造成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方法起到着明显的作用。", "corrected_sentence": "这个方法起到了明显的作用。", "error_description": "“起到”后面应接“了”或“过”，不能接“着”。错误形式：起到着；正确形式：起到了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动起到地很大的作用。", "corrected_sentence": "这次活动起到了很大的作用。", "error_description": "“起到”后面应接体标“了”或“过”，不能接结构助词“地”。错误形式：起到地；正确形式：起到了。“地”是用在动词前的状语标记，不能放在“起到”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
