INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98573, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "路边是马路的旁边。", "primary_collocate": null, "pronunciation": "lù biān", "ipa": "lu˥˩ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "他把车停在路边。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边有一家小饭店。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的花开了。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在路边等朋友。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在路边玩球。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边站着一个老人。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的树很高，夏天很凉快。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在路边买了一杯水。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在路边停车。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边坐着几个人，在聊天。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "马路旁边的位置，常说在路边、停在路边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88de35c8-0eb8-4233-8872-c58f86c79787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98573, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河里", "is_correct": false, "explanation": "语义：汽车不能停在河里，与常理不合。"}, {"text": "路边", "is_correct": true, "explanation": "“路边”是马路的旁边，汽车可以停在这里，与“停在”搭配。"}, {"text": "天空中", "is_correct": false, "explanation": "搭配：“停”一般用于地面上的车，不能与“天空中”搭配。"}, {"text": "厨房里", "is_correct": false, "explanation": "语义：汽车不能停在厨房里，与常理不合。"}], "explanations": {"河里": "语义：汽车不能停在河里，与常理不合。", "路边": "“路边”是马路的旁边，汽车可以停在这里，与“停在”搭配。", "天空中": "搭配：“停”一般用于地面上的车，不能与“天空中”搭配。", "厨房里": "语义：汽车不能停在厨房里，与常理不合。"}, "sentence_index": 0, "correct_answer": "路边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他坐在我的路边，我们一起吃饭。", "explanation": "这里应该用〈旁边〉。“路边”指马路的旁边，人与人之间的位置要说“旁边”。"}, {"text": "我们在教室的路边上课。", "explanation": "这里应该用〈里〉。“路边”只指道路两侧，教室里没有马路，不能说“教室的路边”。"}, {"text": "她坐在床的路边。", "explanation": "这里应该用〈一边〉。“路边”只指马路的旁边，床上没有马路，床的一侧要说“一边”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98573, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海底", "is_correct": false, "explanation": "语义：海底不会长出陆地上的树，与句意不合。"}, {"text": "书桌", "is_correct": false, "explanation": "搭配：书桌上不会长出很高的树，“书桌的树”不搭配。"}, {"text": "路边", "is_correct": true, "explanation": "“路边”指道路两侧，可以说“路边的树”，与句意相合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房里不会长出很高的树，“厨房的树”与句意不合。"}], "explanations": {"海底": "语义：海底不会长出陆地上的树，与句意不合。", "书桌": "搭配：书桌上不会长出很高的树，“书桌的树”不搭配。", "路边": "“路边”指道路两侧，可以说“路边的树”，与句意相合。", "厨房": "语义：厨房里不会长出很高的树，“厨房的树”与句意不合。"}, "sentence_index": 6, "correct_answer": "路边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的路边写满了批注。", "explanation": "这里应该用〈页边〉。“路边”只指道路两侧，书页的边缘要说“页边”。"}, {"text": "这张桌子的路边坏了一个角。", "explanation": "这里应该用〈边缘〉。“路边”只指道路两侧，桌子的边缘不能说“路边”。"}, {"text": "他的裤子的路边破了一个洞。", "explanation": "这里应该用〈裤腿〉。“路边”只指道路两侧，衣物的部位不能说“路边”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹在路边的等公交车。", "corrected_sentence": "妹妹在路边等公交车。", "error_description": "错误形式：“在路边的等”；正确形式：“在路边等”。“在路边”作状语，后面直接接动词，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把路边卖水果。", "corrected_sentence": "他在路边卖水果。", "error_description": "错误形式：“把路边卖水果”；正确形式：“在路边卖水果”。“把”字句要求处置某物，“路边”是处所，不能用“把”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
