INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98574, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "道路的两侧。", "primary_collocate": null, "pronunciation": "lù biān", "ipa": "lu˥˩ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "路边种着很多树。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的路边都是白色的花。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边长满了草。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小路的路边有一条小河。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的灯亮了。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边停满了车。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条大路的路边都种着梧桐树。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的房子都很旧。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪以后，路边都是白的。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边摆着很多卖水果的小摊。", "target_word": "路边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "道路两侧的一带，常有树、店、房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88de35c8-0eb8-4233-8872-c58f86c79787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱里", "is_correct": false, "explanation": "语义：树不能种在冰箱里，与常理不合。"}, {"text": "路边", "is_correct": true, "explanation": "“路边”指道路两侧，可以作主语，句意是路边种着很多树。"}, {"text": "书包里", "is_correct": false, "explanation": "语义：书包里不能种树，与常理不合。"}, {"text": "屏幕上", "is_correct": false, "explanation": "搭配：“种”不能用于屏幕，“屏幕上种着树”不搭配。"}], "explanations": {"冰箱里": "语义：树不能种在冰箱里，与常理不合。", "路边": "“路边”指道路两侧，可以作主语，句意是路边种着很多树。", "书包里": "语义：书包里不能种树，与常理不合。", "屏幕上": "搭配：“种”不能用于屏幕，“屏幕上种着树”不搭配。"}, "sentence_index": 0, "correct_answer": "路边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的路边有很多朋友。", "explanation": "这里应该用〈身边〉。“路边”指道路两侧，人的周围不能说“路边”。"}, {"text": "这间教室的路边有一个黑板。", "explanation": "这里应该用〈前面〉。“路边”指道路两侧，教室里没有马路，黑板应说“前面”。"}, {"text": "这张床的路边放着一个枕头。", "explanation": "这里应该用〈旁边〉。“路边”只指道路两侧，床上没有路，床边要说“旁边”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房间", "is_correct": false, "explanation": "语义：大路上没有房间，“大路的房间种着梧桐树”与句意不合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：大路上没有厨房，“大路的厨房种着梧桐树”与句意矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气里不能种树，“大路的空气种着梧桐树”说不通。"}, {"text": "路边", "is_correct": true, "explanation": "“路边”指道路两侧，“大路的路边种着梧桐树”符合句意。"}], "explanations": {"房间": "语义：大路上没有房间，“大路的房间种着梧桐树”与句意不合。", "厨房": "语义：大路上没有厨房，“大路的厨房种着梧桐树”与句意矛盾。", "空气": "语义：空气里不能种树，“大路的空气种着梧桐树”说不通。", "路边": "“路边”指道路两侧，“大路的路边种着梧桐树”符合句意。"}, "sentence_index": 6, "correct_answer": "路边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的路边印着一朵花。", "explanation": "这里应该用〈页边〉。“路边”只指道路两侧，书页的边缘要说“页边”。"}, {"text": "这张照片的路边有一道划痕。", "explanation": "这里应该用〈边缘〉。“路边”只指道路两侧，照片的边缘不能说“路边”。"}, {"text": "这件衣服的路边破了一个洞。", "explanation": "这里应该用〈下摆〉。“路边”只指道路两侧，衣服的下摆不能说“路边”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条街的路边的停满了汽车。", "corrected_sentence": "这条街的路边停满了汽车。", "error_description": "错误形式：“这条街的路边的停满了汽车”；正确形式：“这条街的路边停满了汽车”。“路边”后多加了结构助词“的”，“的”后面不能直接接动词短语作谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个孩子把路边踢球。", "corrected_sentence": "几个孩子在路边踢球。", "error_description": "错误形式：“把路边踢球”；正确形式：“在路边踢球”。“把”字句要求处置某物，“路边”是处所，不能用“把”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
