INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98577, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "车号是车子身上的号码，每辆车都不一样。", "primary_collocate": null, "pronunciation": "chē hào", "ipa": "tʂʰɤ˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "每辆车的车号都不一样。", "target_word": "车号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆公共汽车的车号是八三六。", "target_word": "车号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太黑了，我看不清那辆车的车号。", "target_word": "车号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车的车号写在车门上。", "target_word": "车号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他记下了那辆红色汽车的车号。", "target_word": "车号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们记住校车的车号。", "target_word": "车号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车号太小，我在远处看不见。", "target_word": "车号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大货车的车号涂在车头的右边。", "target_word": "车号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道你家那辆车的车号吗？", "target_word": "车号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里有二十辆车，每辆都有自己的车号。", "target_word": "车号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "車號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "车子身上的号码，每辆车各不相同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caeccb10-6a79-4d7a-87ac-7a371c930c18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98577, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "车号", "is_correct": true, "explanation": "正确答案：车号指车子身上的号码。"}, {"text": "查号", "is_correct": false, "explanation": "chá（第二声）与 chē（第一声）韵母和声调都不同，查号指查询电话号码，与车号意思不同。"}, {"text": "叉号", "is_correct": false, "explanation": "chā（第一声）与 chē（第一声）韵母不同（a 与 e），叉号指打叉的记号，与车号意思不同。"}, {"text": "车道", "is_correct": false, "explanation": "dào 与 hào 声母不同（d 与 h），车道指车辆行驶的路线，与车号意思不同。"}], "explanations": {"车号": "正确答案：车号指车子身上的号码。", "查号": "chá（第二声）与 chē（第一声）韵母和声调都不同，查号指查询电话号码，与车号意思不同。", "叉号": "chā（第一声）与 chē（第一声）韵母不同（a 与 e），叉号指打叉的记号，与车号意思不同。", "车道": "dào 与 hào 声母不同（d 与 h），车道指车辆行驶的路线，与车号意思不同。"}, "sentence_index": null, "correct_answer": "车号"}, "level_3": {"options": [{"text": "车祸", "is_correct": false, "explanation": "语义：车祸是交通事故，不是车辆的编号，“每辆车的车祸”说不通。"}, {"text": "车号", "is_correct": true, "explanation": "车号是每辆车自己的编号，符合“每辆车的……都不一样”。"}, {"text": "车站", "is_correct": false, "explanation": "语义：车站是乘车或停车的场所，不是车辆自身的标识，句子说不通。"}, {"text": "车间", "is_correct": false, "explanation": "语义：车间是工厂里的生产场所，不是车辆自身的属性，“每辆车的车间”说不通。"}], "explanations": {"车祸": "语义：车祸是交通事故，不是车辆的编号，“每辆车的车祸”说不通。", "车号": "车号是每辆车自己的编号，符合“每辆车的……都不一样”。", "车站": "语义：车站是乘车或停车的场所，不是车辆自身的标识，句子说不通。", "车间": "语义：车间是工厂里的生产场所，不是车辆自身的属性，“每辆车的车间”说不通。"}, "sentence_index": 0, "correct_answer": "车号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手机车号是13812345678。", "explanation": "这里应该用〈号码〉。手机号码是通信用的号码；车号只指车辆的编号，不能用来说手机。"}, {"text": "我在门口看到一只车号。", "explanation": "这里应该用〈个〉，不能用〈只〉。〈只〉多用于动物或成对的东西，车号是编号，应说“一个车号”。"}, {"text": "这辆车的车号是SUV。", "explanation": "这里应该用〈车型〉。SUV说的是车的款式；车号是车辆的编号，不能用来说车的种类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98577, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "车夫", "is_correct": false, "explanation": "搭配：“太小”一般不用来形容人，车夫是人，不能说“车夫太小”。"}, {"text": "车速", "is_correct": false, "explanation": "语义：车速是速度，不是有形的号码，不能用“太小、看不见”来描述。"}, {"text": "车号", "is_correct": true, "explanation": "车号是车子身上的号码，远处看不清的字可以说“车号太小”。"}, {"text": "车主", "is_correct": false, "explanation": "语义：车主是车的主人，是人，不能说“车主太小”。"}], "explanations": {"车夫": "搭配：“太小”一般不用来形容人，车夫是人，不能说“车夫太小”。", "车速": "语义：车速是速度，不是有形的号码，不能用“太小、看不见”来描述。", "车号": "车号是车子身上的号码，远处看不清的字可以说“车号太小”。", "车主": "语义：车主是车的主人，是人，不能说“车主太小”。"}, "sentence_index": 6, "correct_answer": "车号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试的时候，每个学生都要在卷子上写自己的车号。", "explanation": "这里应该用〈学号〉。学号是学生的编号；车号只指车辆的编号，不用于学生。"}, {"text": "我的车号是八号桌。", "explanation": "这里应该用〈桌号〉。桌号是餐桌的编号；车号只指车辆的编号，不能用来指餐桌。"}, {"text": "他在本子上记下了一把车号。", "explanation": "这里应该用〈个〉，不能用〈把〉。〈把〉用于有柄的东西，车号应用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我记下了一辆车号。", "corrected_sentence": "我记下了一个车号。", "error_description": "量词错误：车号是编号，不是车辆，不能用“辆”，应说“一个车号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块车号我记不住。", "corrected_sentence": "这个车号我记不住。", "error_description": "量词错误：“块”用于块状的东西，车号是编号，应说“这个车号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98581, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "去年", "is_correct": true, "explanation": "反义：去年指今年之前的一年，转年指今年之后的一年，二者方向相反，是一对反义词。"}, {"text": "课本", "is_correct": false, "explanation": "无关：课本是学习用品，与表示年份的“转年”没有反义关系。"}, {"text": "冰箱", "is_correct": false, "explanation": "无关：冰箱是家用电器，与时间概念没有反义关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "无关：雨伞是遮雨的物品，与“转年”不构成反义。"}], "correct_answer": "去年", "explanations": {"去年": "反义：去年指今年之前的一年，转年指今年之后的一年，二者方向相反，是一对反义词。", "课本": "无关：课本是学习用品，与表示年份的“转年”没有反义关系。", "冰箱": "无关：冰箱是家用电器，与时间概念没有反义关系。", "雨伞": "无关：雨伞是遮雨的物品，与“转年”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98581, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "去年", "is_correct": true, "explanation": "反义：去年指今年之前的一年，转年指今年之后的一年，二者方向相反，是一对反义词。"}, {"text": "书包", "is_correct": false, "explanation": "无关：书包是装书的用具，与“转年”没有反义关系。"}, {"text": "手套", "is_correct": false, "explanation": "无关：手套是保暖的穿戴物，与时间概念没有反义关系。"}, {"text": "牛奶", "is_correct": false, "explanation": "无关：牛奶是饮品，与“转年”不构成反义。"}], "correct_answer": "去年", "explanations": {"去年": "反义：去年指今年之前的一年，转年指今年之后的一年，二者方向相反，是一对反义词。", "书包": "无关：书包是装书的用具，与“转年”没有反义关系。", "手套": "无关：手套是保暖的穿戴物，与时间概念没有反义关系。", "牛奶": "无关：牛奶是饮品，与“转年”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98581, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "转年是过了这一年以后的下一年。", "primary_collocate": null, "pronunciation": "zhuǎn nián", "ipa": "tʂwan˨˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "今年我们先租房，转年再买房子。", "target_word": "转年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他转年夏天就要大学毕业了。", "target_word": "转年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树今年开花，转年结了很多果子。", "target_word": "转年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们转年春天打算去北京旅游。", "target_word": "转年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年太忙，转年一定好好休息。", "target_word": "转年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐去年结婚，转年生了个儿子。", "target_word": "转年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十二月到了上海，转年一月就找到了工作。", "target_word": "转年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说转年这里要修一条新地铁。", "target_word": "转年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年赚了钱，转年想开新店。", "target_word": "转年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "转年的这个时候，我们就是大学生了。", "target_word": "转年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "转年|名词|过了这一年以后的下一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90645a6b-93e3-4121-8054-48deb9684cb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98581, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转年", "is_correct": true, "explanation": "正确：转年指今年之后的下一年，与“今年先租房”构成先后顺序，后句用“再”引出之后的事。"}, {"text": "去年", "is_correct": false, "explanation": "语义：去年在今年之前，与“今年先租房，……再买房子”的时间顺序矛盾。"}, {"text": "上周", "is_correct": false, "explanation": "语义：上周已经过去，不能作为“再买房子”这一将来动作的时间点。"}, {"text": "清晨", "is_correct": false, "explanation": "搭配：“清晨”是一天之中的时段，不能与“今年”这种年度时间词放在同一句中构成先后的时间框架。"}], "explanations": {"转年": "正确：转年指今年之后的下一年，与“今年先租房”构成先后顺序，后句用“再”引出之后的事。", "去年": "语义：去年在今年之前，与“今年先租房，……再买房子”的时间顺序矛盾。", "上周": "语义：上周已经过去，不能作为“再买房子”这一将来动作的时间点。", "清晨": "搭配：“清晨”是一天之中的时段，不能与“今年”这种年度时间词放在同一句中构成先后的时间框架。"}, "sentence_index": 0, "correct_answer": "转年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上个月我转年去了北京，那次旅行很开心。", "explanation": "这里应该用〈去年〉。转年指某年之后的下一年，和“上个月”这样的近期时间相矛盾，说去年的经历要用去年。"}, {"text": "他中午到的公司，转年就签了合同。", "explanation": "这里应该用〈当天〉。转年指下一年，不能用来指同一天之内发生的事，同一天签合同要用当天。"}, {"text": "我们这周末转年再见面吧。", "explanation": "这里应该用〈下周末〉。转年指明年，与“这周末”这样的近期时间相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转年", "is_correct": true, "explanation": "正确：转年指下一年，与“十二月到了上海”之后的“一月”前后相接，符合时间顺序。"}, {"text": "当天", "is_correct": false, "explanation": "语义：当天指同一天，无法与后面的具体月份“一月”搭配。"}, {"text": "上午", "is_correct": false, "explanation": "搭配：“上午”是一天中的时段，不能与“一月”这样的月份直接搭配。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：昨天已经过去，不能作为“一月就找到了工作”的时间点。"}], "explanations": {"转年": "正确：转年指下一年，与“十二月到了上海”之后的“一月”前后相接，符合时间顺序。", "当天": "语义：当天指同一天，无法与后面的具体月份“一月”搭配。", "上午": "搭配：“上午”是一天中的时段，不能与“一月”这样的月份直接搭配。", "昨天": "语义：昨天已经过去，不能作为“一月就找到了工作”的时间点。"}, "sentence_index": 6, "correct_answer": "转年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我刚才在超市，转年又回家了。", "explanation": "这里应该用〈后来〉。转年指下一年，不能表示几分钟之内的先后顺序，同一段时间内的先后要用后来。"}, {"text": "他转年刚刚毕业，现在正在找工作。", "explanation": "这里应该用〈去年〉。转年指某年之后的下一年，与“现在正在找工作”这样的当前状态对不上，说过去的时间要用去年。"}, {"text": "我们连续工作了两个小时，转年才休息。", "explanation": "这里应该用〈过一会儿〉。转年指下一年，不能表示工作两个小时这样的短时间间隔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年我们买了车，一个转年就换了房子。", "corrected_sentence": "去年我们买了车，转年就换了房子。", "error_description": "错误：“转年”前面加了数量词“一个”。“转年”是时间名词，不能用数量词修饰，应直接说“转年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他转年的就找到了新工作。", "corrected_sentence": "他转年就找到了新工作。", "error_description": "错误：“转年”作时间状语时，与后面的“就”之间不能加“的”，应说“转年就……”。（“转年的这个时候”中的“的”是定语标记，与此不同。）", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98585, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98585, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98585, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "转发是把收到的话或图片再发给别的人。", "primary_collocate": null, "pronunciation": "zhuǎn fā", "ipa": "tʂwan˨˩˦ fa˥", "syllable_count": 2, "sentences": [{"text": "请把这张照片转发给我妈妈。", "target_word": "转发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把朋友的消息转发到了群里。", "target_word": "转发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条通知太重要了，请大家转发一下。", "target_word": "转发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天转发过这个视频。", "target_word": "转发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看到好笑的图片就转发给我吧。", "target_word": "转发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都转发很多新闻。", "target_word": "转发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们转发这份作业要求。", "target_word": "转发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别随便转发你不认识的人发的链接。", "target_word": "转发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚收到一张图片，马上转发给了哥哥。", "target_word": "转发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他转发了朋友的求助信息。", "target_word": "转发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转发了", "label": "体标"}, {"form": "转发过", "label": "体标"}, {"form": "转发量", "label": "复合"}], "register": "中性", "sense_fingerprint": "把收到的话或图片再发给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e7f192b-be0b-4077-9581-3be7d265068c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98585, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转发", "is_correct": true, "explanation": "正确：“转发”表示把收到的照片再发给别人，与“给我妈妈”的接收对象相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是演唱，照片不能被唱给别人，句子说不通。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”的对象是话语或故事，不能与“照片”搭配表示传送。"}, {"text": "说", "is_correct": false, "explanation": "语义：“说”是口头表达，照片无法用口说给妈妈，与把照片发过去的意思不符。"}], "explanations": {"转发": "正确：“转发”表示把收到的照片再发给别人，与“给我妈妈”的接收对象相符。", "唱": "语义：“唱”是演唱，照片不能被唱给别人，句子说不通。", "讲": "搭配：“讲”的对象是话语或故事，不能与“照片”搭配表示传送。", "说": "语义：“说”是口头表达，照片无法用口说给妈妈，与把照片发过去的意思不符。"}, "sentence_index": 0, "correct_answer": "转发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把新买的自行车转发给了弟弟。", "explanation": "这里应该用〈送〉。转发只用于消息和信息，自行车是实物，要用送。"}, {"text": "这位作家把新作转发到了杂志上。", "explanation": "这里应该用〈发表〉。转发是把已收到的内容再传给别人，作品首次公开刊登要用发表。"}, {"text": "我把生日礼物转发给了妈妈。", "explanation": "这里应该用〈寄〉。转发只用于消息和信息，生日礼物是实物，要用寄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98585, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转发", "is_correct": true, "explanation": "正确：“转发”表示把收到的作业要求再发给同学或家长，与“老师让我们”的指令语境相符。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是把纸张弄破，与老师让大家传达要求的意思相反，句子说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，“作业要求”不能被吃。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指弄碎易碎的物体，“作业要求”是文字内容，无法打碎。"}], "explanations": {"转发": "正确：“转发”表示把收到的作业要求再发给同学或家长，与“老师让我们”的指令语境相符。", "撕": "语义：“撕”是把纸张弄破，与老师让大家传达要求的意思相反，句子说不通。", "吃": "搭配：“吃”的宾语应是食物，“作业要求”不能被吃。", "打碎": "语义：“打碎”指弄碎易碎的物体，“作业要求”是文字内容，无法打碎。"}, "sentence_index": 6, "correct_answer": "转发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "麻烦你转发一下小李，就说我晚点到。", "explanation": "这里应该用〈转告〉。转发的对象是消息，不能直接以人作宾语，要说“转告小李”。"}, {"text": "下课以后，我把作业本转发到了老师的桌子上。", "explanation": "这里应该用〈交〉。转发只用于消息、图片等信息，作业本是实物，要放到老师桌上应该说“交”。"}, {"text": "我把心里的话转发给了朋友。", "explanation": "这里应该用〈倾诉〉。转发的内容必须是别人已经发来的信息，心里的话是自己的感受，要直接说出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98585, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天把这个新闻转发了给同事。", "corrected_sentence": "我昨天把这个新闻转发给了同事。", "error_description": "错误形式“转发了给同事”，“了”放在了补语“给”之前；正确形式“转发给了同事”，“了”应放在“给”之后，表示动作已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98585, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把这个链接转发了我。", "corrected_sentence": "妈妈把这个链接转发给了我。", "error_description": "错误形式“转发了我”，缺少引出接收者的“给”；正确形式“转发给了我”，转发的接收者要用“给”来引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
