INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98589, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98589, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "进路是往里面去的路。", "primary_collocate": null, "pronunciation": "jìn lù", "ipa": "tɕin˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这个山洞的进路很窄，只能一个人走。", "target_word": "进路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪盖住了前面的进路。", "target_word": "进路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子的进路在那棵大树旁边。", "target_word": "进路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找不到进路，我们只好在门口等着。", "target_word": "进路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城的进路有两条，都很长。", "target_word": "进路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把进路封住了，车不能进去。", "target_word": "进路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园的进路旁种满了玫瑰。", "target_word": "进路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，我们看不清进路。", "target_word": "进路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条进路通向山里的小村子。", "target_word": "进路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你告诉我，仓库的进路在哪儿？", "target_word": "进路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "书面", "sense_fingerprint": "通往里面的具体道路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3810a26-ecf2-428b-beee-e994530c768a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98589, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进路", "is_correct": true, "explanation": "进路指通往里面的道路，山洞的通道窄、只能一个人通过，与语境相符。"}, {"text": "天花板", "is_correct": false, "explanation": "搭配：天花板只说高低，不说宽窄，不能与“很窄”搭配。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口指一个地方的人数，与山洞通道的宽窄无关。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气可以说多少、好坏，不说“很窄”。"}], "explanations": {"进路": "进路指通往里面的道路，山洞的通道窄、只能一个人通过，与语境相符。", "天花板": "搭配：天花板只说高低，不说宽窄，不能与“很窄”搭配。", "人口": "语义：人口指一个地方的人数，与山洞通道的宽窄无关。", "空气": "搭配：空气可以说多少、好坏，不说“很窄”。"}, "sentence_index": 0, "correct_answer": "进路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力推开进路，走进了院子。", "explanation": "这里应该用〈大门〉。进路是道路，不能推开，要推开的是门。"}, {"text": "我把钥匙插进进路，打开了门。", "explanation": "这里应该用〈锁孔〉。进路是往里去的道路，不能插钥匙；插钥匙的是锁孔。"}, {"text": "这扇门就是进路，我们推开它走了进去。", "explanation": "这里应该用〈进口〉。进路指往里去的道路，门不是道路，不能说门就是进路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98589, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进路", "is_correct": true, "explanation": "进路指通往花园内部的道路，道路旁种满玫瑰，符合语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以种花的处所，也不能位于花园的旁边。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音没有空间位置，不能作为种满玫瑰的地方。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“旁”前应接处所名词，“颜色”不能这样使用。"}], "explanations": {"进路": "进路指通往花园内部的道路，道路旁种满玫瑰，符合语境。", "天空": "语义：天空不是可以种花的处所，也不能位于花园的旁边。", "声音": "语义：声音没有空间位置，不能作为种满玫瑰的地方。", "颜色": "搭配：“旁”前应接处所名词，“颜色”不能这样使用。"}, "sentence_index": 6, "correct_answer": "进路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把进路装进口袋，带回了家。", "explanation": "这里应该用〈地图〉。进路是一条路，不能装进口袋；能带走的是画着路的地图。"}, {"text": "这座楼的进路有二十层，楼层很高。", "explanation": "这里应该用〈楼梯〉。进路指道路，不能用来形容楼层数。"}, {"text": "他从进路爬上了屋顶，又从屋顶跳下来。", "explanation": "这里应该用〈梯子〉。进路是道路，不能用来爬屋顶；爬屋顶要用〈梯子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雪封住了那座进路，我们只好绕路。", "corrected_sentence": "大雪封住了那条进路，我们只好绕路。", "error_description": "量词用错：“进路”是道路，应用量词“条”，不能用“座”（座多用于山、桥、楼房）。正确说法是“那条进路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前面那把进路很窄，只能一个人走。", "corrected_sentence": "前面那条进路很窄，只能一个人走。", "error_description": "量词用错：“进路”是道路，应用“条”，不能用“把”（把多用于有柄的物件或椅子）。正确说法是“前面那条进路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98593, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98593, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98593, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "过门是新娘到新家里去，成为那家的人。", "primary_collocate": null, "pronunciation": "guò mén", "ipa": "kuo˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "新娘过门以后，要先给长辈敬茶。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，奶奶过门时坐的是花轿。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她还没过门，就先学了婆家的规矩。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大女儿去年过门，现在住在城里。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过门那天，新娘穿着红衣服。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居家的女儿下个月过门。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她过门以后，家里多了很多笑声。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新媳妇过门第一天，起得特别早。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都来看新娘过门。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她过门半年，就和婆婆像母女一样。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过了门", "label": "体标（了）"}], "register": "口语", "sense_fingerprint": "新娘出嫁后到夫家去，成为那家的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61055a68-0e57-44de-a57b-c0b45d7280bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98593, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "过门", "is_correct": true, "explanation": "正确答案。过门（guò mén）指新娘到新家里去，成为那家的人。"}, {"text": "过敏", "is_correct": false, "explanation": "声调和韵母都不同：mǐn（第三声）与 mén（第二声）的韵母是 in 与 en，意思是对某物过敏。"}, {"text": "过猛", "is_correct": false, "explanation": "第二音节不同：měng（第三声）与 mén（第二声）的韵母是 eng 与 en，意思是猛烈。"}, {"text": "国门", "is_correct": false, "explanation": "第一音节声调不同：guó（第二声）与 guò（第四声）不同，其余相同，意思是国家的大门。"}, {"text": "过问", "is_correct": false, "explanation": "第二音节声母和声调都不同：wèn（第四声）与 mén（第二声），意思是询问、干预。"}], "explanations": {"过门": "正确答案。过门（guò mén）指新娘到新家里去，成为那家的人。", "过敏": "声调和韵母都不同：mǐn（第三声）与 mén（第二声）的韵母是 in 与 en，意思是对某物过敏。", "过猛": "第二音节不同：měng（第三声）与 mén（第二声）的韵母是 eng 与 en，意思是猛烈。", "国门": "第一音节声调不同：guó（第二声）与 guò（第四声）不同，其余相同，意思是国家的大门。", "过问": "第二音节声母和声调都不同：wèn（第四声）与 mén（第二声），意思是询问、干预。"}, "sentence_index": null, "correct_answer": "过门"}, "level_3": {"options": [{"text": "过门", "is_correct": true, "explanation": "正确答案。“过门”指新娘到新家，符合“新娘……以后，要先给长辈敬茶”的句意。"}, {"text": "离婚", "is_correct": false, "explanation": "语义：新娘刚进门，不会离婚，与“新娘”的身份矛盾。"}, {"text": "投票", "is_correct": false, "explanation": "语义：“投票”与新娘的身份以及后文“先给长辈敬茶”的礼节不搭。"}, {"text": "驾崩", "is_correct": false, "explanation": "语域：“驾崩”专指帝王去世，只用于帝王，不能用于新娘，语域不符。"}], "explanations": {"过门": "正确答案。“过门”指新娘到新家，符合“新娘……以后，要先给长辈敬茶”的句意。", "离婚": "语义：新娘刚进门，不会离婚，与“新娘”的身份矛盾。", "投票": "语义：“投票”与新娘的身份以及后文“先给长辈敬茶”的礼节不搭。", "驾崩": "语域：“驾崩”专指帝王去世，只用于帝王，不能用于新娘，语域不符。"}, "sentence_index": 0, "correct_answer": "过门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们俩去年过门，现在住在城里。", "explanation": "这里应该用〈结婚〉。过门指新娘到新家，不能用于两人一起结婚。"}, {"text": "吃完饭，奶奶去邻居家过门聊天。", "explanation": "这里应该用〈串门〉。串门是到别人家里闲坐聊天；过门指新娘到夫家，不能表示去邻居家聊天。"}, {"text": "社区干部过门给老人送了药。", "explanation": "这里应该用〈上门〉。过门指新娘到夫家，不能表示到别人家里送东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98593, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过门", "is_correct": true, "explanation": "正确答案。“过门”指新娘到新家，符合“她……以后，家里多了很多笑声”的句意。"}, {"text": "下葬", "is_correct": false, "explanation": "语义：“下葬”指人去世后埋葬，与“家里多了很多笑声”矛盾。"}, {"text": "去世", "is_correct": false, "explanation": "语义：人去世后，家里不会多出笑声，句意矛盾。"}, {"text": "谢世", "is_correct": false, "explanation": "语域：“谢世”是书面、委婉的说法，与口语语境不符，句意也与笑声矛盾。"}], "explanations": {"过门": "正确答案。“过门”指新娘到新家，符合“她……以后，家里多了很多笑声”的句意。", "下葬": "语义：“下葬”指人去世后埋葬，与“家里多了很多笑声”矛盾。", "去世": "语义：人去世后，家里不会多出笑声，句意矛盾。", "谢世": "语域：“谢世”是书面、委婉的说法，与口语语境不符，句意也与笑声矛盾。"}, "sentence_index": 6, "correct_answer": "过门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "叔叔每天早上过门上班，很辛苦。", "explanation": "这里应该用〈出门〉。过门指新娘到夫家，不能表示外出工作。"}, {"text": "婚后第二天，她过门回娘家住了三天。", "explanation": "这里应该用〈回门〉。过门指新娘进入夫家，与“回娘家住”的意思矛盾。"}, {"text": "护士过门给老人打针，很耐心。", "explanation": "这里应该用〈上门〉。过门指新娘到夫家，不能表示到别人家里去服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98593, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐过过门以后，就很少回娘家了。", "corrected_sentence": "姐姐过了门以后，就很少回娘家了。", "error_description": "体标错误：“过过门”应为“过了门”。“过门”表示动作已完成，体标应用“了”，不能用“过”重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98593, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "堂姐前年过门着，现在和婆婆一起做饭。", "corrected_sentence": "堂姐前年过门了，现在和婆婆一起做饭。", "error_description": "体标错误：“过门着”应为“过门了”。“着”表示持续状态，不能与“过门”这一完成性动作搭配，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
