INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98594, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98594, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "旧时指女子嫁到夫家。", "primary_collocate": null, "pronunciation": "guò mén", "ipa": "kuo˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "奶奶过门那年，只有十八岁。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新娘过门的时候，家里放了鞭炮。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她过门三天，就学会了做饭。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过门以前，她们两家没有见过面。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说她过门时，什么也没带。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐明年春天过门，全家都在准备。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧时女子过门后，要听婆婆的话。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过门的那天，天下着大雪。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她刚过门，就要照顾一大家人。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二婶过门多年，对大家都很好。", "target_word": "过门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过了门", "label": "体标（了）"}], "register": "口语", "sense_fingerprint": "旧时女子出嫁后进入夫家生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61055a68-0e57-44de-a57b-c0b45d7280bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98594, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "过门", "is_correct": true, "explanation": "正确答案。过门（guò mén）指旧时女子嫁到夫家。"}, {"text": "过敏", "is_correct": false, "explanation": "声调和韵母都不同：mǐn（第三声）与 mén（第二声）的韵母是 in 与 en，意思是对某物过敏。"}, {"text": "过猛", "is_correct": false, "explanation": "第二音节不同：měng（第三声）与 mén（第二声）的韵母是 eng 与 en，意思是猛烈。"}, {"text": "国门", "is_correct": false, "explanation": "第一音节声调不同：guó（第二声）与 guò（第四声）不同，其余相同，意思是国家的大门。"}, {"text": "柜门", "is_correct": false, "explanation": "第一音节韵母不同：guì（第四声）与 guò（第四声）的韵母是 ui 与 uo，意思是柜子的门。"}], "explanations": {"过门": "正确答案。过门（guò mén）指旧时女子嫁到夫家。", "过敏": "声调和韵母都不同：mǐn（第三声）与 mén（第二声）的韵母是 in 与 en，意思是对某物过敏。", "过猛": "第二音节不同：měng（第三声）与 mén（第二声）的韵母是 eng 与 en，意思是猛烈。", "国门": "第一音节声调不同：guó（第二声）与 guò（第四声）不同，其余相同，意思是国家的大门。", "柜门": "第一音节韵母不同：guì（第四声）与 guò（第四声）的韵母是 ui 与 uo，意思是柜子的门。"}, "sentence_index": null, "correct_answer": "过门"}, "level_3": {"options": [{"text": "过门", "is_correct": true, "explanation": "正确答案。“过门”指旧时女子嫁到夫家，符合“奶奶……那年只有十八岁”的句意。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休通常指工作到一定年纪后离职，与“只有十八岁”矛盾。"}, {"text": "驾崩", "is_correct": false, "explanation": "语域：“驾崩”专指帝王去世，只用于帝王，不能用于奶奶，语域不符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”那年不可能已经十八岁，与句意矛盾。"}], "explanations": {"过门": "正确答案。“过门”指旧时女子嫁到夫家，符合“奶奶……那年只有十八岁”的句意。", "退休": "语义：退休通常指工作到一定年纪后离职，与“只有十八岁”矛盾。", "驾崩": "语域：“驾崩”专指帝王去世，只用于帝王，不能用于奶奶，语域不符。", "出生": "语义：“出生”那年不可能已经十八岁，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "过门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年过门，现在在城里工作。", "explanation": "这里应该用〈结婚〉。过门只指女子嫁到夫家，不能用于男子。"}, {"text": "下午没事，她去邻居家过门聊天。", "explanation": "这里应该用〈串门〉。串门是到别人家闲坐聊天；过门指女子嫁到夫家，不能表示去邻居家聊天。"}, {"text": "新婚第三天，她过门，住在娘家。", "explanation": "这里应该用〈回门〉。过门指女子进入夫家，与“住在娘家”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过门", "is_correct": true, "explanation": "正确答案。“过门”指旧时女子嫁到夫家，符合“旧时女子……后，要听婆婆的话”的句意。"}, {"text": "投票", "is_correct": false, "explanation": "语义：旧时女子没有投票权，“投票”与句中的时代背景不符。"}, {"text": "离婚", "is_correct": false, "explanation": "语义：离婚后便不再受婆家约束，与“要听婆婆的话”矛盾。"}, {"text": "去世", "is_correct": false, "explanation": "语义：人去世后就不存在“要听婆婆的话”，句意矛盾。"}], "explanations": {"过门": "正确答案。“过门”指旧时女子嫁到夫家，符合“旧时女子……后，要听婆婆的话”的句意。", "投票": "语义：旧时女子没有投票权，“投票”与句中的时代背景不符。", "离婚": "语义：离婚后便不再受婆家约束，与“要听婆婆的话”矛盾。", "去世": "语义：人去世后就不存在“要听婆婆的话”，句意矛盾。"}, "sentence_index": 6, "correct_answer": "过门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐姐每天早上过门上班，很辛苦。", "explanation": "这里应该用〈出门〉。过门指女子嫁入夫家，不能表示外出工作。"}, {"text": "医生过门给奶奶看病，很耐心。", "explanation": "这里应该用〈上门〉。过门指女子嫁入夫家，不能表示到别人家里去服务。"}, {"text": "吃完晚饭，她常去邻居家过门聊天。", "explanation": "这里应该用〈串门〉。串门是到别人家闲坐聊天；过门指女子嫁入夫家，不能表示去邻居家聊天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈正在过门以后，就很少回娘家。", "corrected_sentence": "妈妈过门以后，就很少回娘家。", "error_description": "体标错误：“正在”表示动作正在进行，而“过门以后”指已经完成的事件，二者矛盾，应去掉“正在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我表姐去年过过门，现在住在婆家。", "corrected_sentence": "我表姐去年过了门，现在住在婆家。", "error_description": "体标错误：“过过门”应为“过了门”。“过门”表示动作已完成，体标应用“了”，不能用“过”重复。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
