INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98597, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "道学是很久以前讲做人道理的学问。", "primary_collocate": null, "pronunciation": "dào xué", "ipa": "tau̯˥˩ ɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "道学是讲做人道理的学问。", "target_word": "道学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷年轻时学过道学。", "target_word": "道学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的人很重视道学。", "target_word": "道学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书讲的是道学，不是历史。", "target_word": "道学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老先生每天教孩子读道学的书。", "target_word": "道学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对道学很有兴趣，常去图书馆看书。", "target_word": "道学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "道学告诉人们要怎样做人。", "target_word": "道学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人觉得道学太老了，不好懂。", "target_word": "道学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们今天还能从道学里学到做人的道理。", "target_word": "道学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天讲的是道学的基本道理。", "target_word": "道学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道學", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "道学：古时讲做人道理的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61055a68-0e57-44de-a57b-c0b45d7280bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98597, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道学", "is_correct": true, "explanation": "道学指古时讲做人道理的学问，与句中的定义相符。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学研究数量和图形，不讲做人的道理。"}, {"text": "地理", "is_correct": false, "explanation": "语义：地理研究地表和各地的自然与人文情况，与做人的道理无关。"}, {"text": "门道", "is_correct": false, "explanation": "语域：“门道”是口语，指窍门或门路，不指讲做人道理的学问，与书面语的定义句不协调。"}], "explanations": {"道学": "道学指古时讲做人道理的学问，与句中的定义相符。", "数学": "语义：数学研究数量和图形，不讲做人的道理。", "地理": "语义：地理研究地表和各地的自然与人文情况，与做人的道理无关。", "门道": "语域：“门道”是口语，指窍门或门路，不指讲做人道理的学问，与书面语的定义句不协调。"}, "sentence_index": 0, "correct_answer": "道学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从小就学了一本道学。", "explanation": "这里应该用〈门〉。道学是一门学问，量词用“门”；“本”用于书籍，不能修饰“道学”。"}, {"text": "他的道学很甜，大家都爱吃。", "explanation": "这里应该用〈糖〉。道学是一门学问，不能吃，也谈不上甜；“甜”形容的是食物。"}, {"text": "他用道学修好了自行车。", "explanation": "这里应该用〈工具〉。道学是讲做人道理的学问，不是修理用的工具；修好自行车要用扳手或零件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98597, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道学", "is_correct": true, "explanation": "道学指讲做人道理的学问，正是句中“告诉人们要怎样做人”的内容。"}, {"text": "化学", "is_correct": false, "explanation": "语义：化学研究物质的组成和变化，不讲怎样做人。"}, {"text": "物理", "is_correct": false, "explanation": "语义：物理研究物质运动和能量的规律，与做人无关。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法研究语言的组织规则，不讲怎样做人。"}], "explanations": {"道学": "道学指讲做人道理的学问，正是句中“告诉人们要怎样做人”的内容。", "化学": "语义：化学研究物质的组成和变化，不讲怎样做人。", "物理": "语义：物理研究物质运动和能量的规律，与做人无关。", "语法": "语义：语法研究语言的组织规则，不讲怎样做人。"}, "sentence_index": 6, "correct_answer": "道学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条道学太长了，我们走了两个小时。", "explanation": "这里应该用〈道路〉。道学是讲做人道理的学问，不是可以走的路；指路要说“道路”。"}, {"text": "他用道学看完了整部电影。", "explanation": "这里应该用〈电视〉。道学是讲做人道理的学问，不是可以观看的东西；看电影要用电视或其他放映设备。"}, {"text": "这碗道学很香，快趁热吃吧。", "explanation": "这里应该用〈汤〉。道学是讲做人道理的学问，不能吃，也谈不上香。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "叔叔年轻时研究过一把道学。", "corrected_sentence": "叔叔年轻时研究过道学。", "error_description": "量词错误：“一把道学”不成立。“把”用于有柄的器具，“道学”是一种学问，不能用“把”计量，此处直接说“研究过道学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们也能从一条道学里明白做人的道理。", "corrected_sentence": "孩子们也能从道学里明白做人的道理。", "error_description": "量词错误：“一条道学”不成立。“条”用于长条形的东西，“道学”是一种学问，不能用“条”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
