INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98598, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "宋代以讲求义理、修身为主的儒家学说。", "primary_collocate": null, "pronunciation": "dào xué", "ipa": "tau̯˥˩ ɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "道学是宋代的儒家学说。", "target_word": "道学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "宋代的道学很重视修身。", "target_word": "道学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朱熹是宋代道学的重要人物。", "target_word": "道学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写了一本书，讲宋代道学。", "target_word": "道学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宋代的读书人常常学习道学。", "target_word": "道学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "道学讲义理，也讲怎样修身。", "target_word": "道学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史课上，老师讲了宋代的道学。", "target_word": "道学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "道学对后来的儒家影响很大。", "target_word": "道学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宋代以后，道学成了很重要的学问。", "target_word": "道学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想了解宋代的道学。", "target_word": "道学", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "道學", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "道学：宋代讲义理、修身的儒家学说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61055a68-0e57-44de-a57b-c0b45d7280bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道学", "is_correct": true, "explanation": "道学指宋代以讲求义理、修身为主的儒家学说，与句中的说法相符。"}, {"text": "佛教", "is_correct": false, "explanation": "语义：佛教是外来宗教，不是宋代的儒家学说。"}, {"text": "绘画", "is_correct": false, "explanation": "语义：绘画是艺术门类，与儒家学说无关。"}, {"text": "门路", "is_correct": false, "explanation": "语义：“门路”指门径、途径，不是学说，不能说“门路是宋代的儒家学说”。"}], "explanations": {"道学": "道学指宋代以讲求义理、修身为主的儒家学说，与句中的说法相符。", "佛教": "语义：佛教是外来宗教，不是宋代的儒家学说。", "绘画": "语义：绘画是艺术门类，与儒家学说无关。", "门路": "语义：“门路”指门径、途径，不是学说，不能说“门路是宋代的儒家学说”。"}, "sentence_index": 0, "correct_answer": "道学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写了一本书，讲西方道学。", "explanation": "这里应该用〈哲学〉。此义的道学指宋代形成的儒家学说，不能用来指西方的思想体系；讲西方的思想，应该说哲学。"}, {"text": "他很喜欢穿宋代的道学。", "explanation": "这里应该用〈读〉。道学是一门学问，要读、学、研究；“穿”一般只用于衣服、鞋袜等。"}, {"text": "他研究了一把道学。", "explanation": "这里应该用〈门〉。道学是一门学问，量词用“门”；“把”用于有柄的器具，不能修饰“道学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道学", "is_correct": true, "explanation": "道学是宋代的儒家学说，历史课上讲它正合适，与句意相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：宋代没有汽车，历史课上不会讲它。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是现代电器，宋代没有，历史课上不会讲“宋代的冰箱”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是现代器物，宋代没有，历史课上不会讲它。"}], "explanations": {"道学": "道学是宋代的儒家学说，历史课上讲它正合适，与句意相符。", "汽车": "语义：宋代没有汽车，历史课上不会讲它。", "冰箱": "语义：冰箱是现代电器，宋代没有，历史课上不会讲“宋代的冰箱”。", "电脑": "语义：电脑是现代器物，宋代没有，历史课上不会讲它。"}, "sentence_index": 6, "correct_answer": "道学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想了解宋代的一座道学。", "explanation": "这里应该用〈门〉。道学是一门学问，量词用“门”；“座”多用于山、桥、建筑，不能修饰“道学”。"}, {"text": "宋代的道学很长，我们走了半天才到。", "explanation": "这里应该用〈道路〉。道学指宋代的儒家学说，不是可以走的路；“走了半天才到”说的应是道路。"}, {"text": "这个园子的道学很香，走近就闻得到。", "explanation": "这里应该用〈花〉。道学是一门学问，不能散发香气；“香”形容的是花草等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朱熹研究过一把道学。", "corrected_sentence": "朱熹研究过一门道学。", "error_description": "量词错误：“一把道学”；正确形式：“一门道学”。“道学”是一门学问，量词应用“门”，“把”用于有柄的器具。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把宋代道学讲清楚着。", "corrected_sentence": "老师把宋代道学讲清楚了。", "error_description": "体标错误：结果补语“清楚”后应用“了”，说“讲清楚了”，不能用“着”。“着”表示持续的状态，不能与这种已完成的结果搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
