INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98601, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "还原是把东西变回原来的样子。", "primary_collocate": null, "pronunciation": "huán yuán", "ipa": "xwan˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他把打乱的魔方还原了。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅正在还原那幅旧画的颜色。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把桌子还原成刚才的样子。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房结束前，要把房子还原成原来的样子。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人想把旧房子还原成一百年前的样子。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服洗坏了，颜色还原不了了。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把拆开的玩具又还原了。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个被压扁的礼盒，他慢慢还原成了原来的形状。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧收音机拆开后，他又把它还原了。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把旧家具还原得和新的一样。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "还原了", "label": "完成体"}, {"form": "还原过", "label": "经历体"}, {"form": "還原", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把具体的东西变回原来的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00032f7-208c-448d-9c5f-b377604ba846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98601, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还原", "is_correct": true, "explanation": "正确答案。还原指把打乱的魔方恢复成原来的样子。"}, {"text": "咨询", "is_correct": false, "explanation": "语义：「咨询」指向人请教意见，不能用于魔方。"}, {"text": "批准", "is_correct": false, "explanation": "配价：「批准」要求有权的机构作主语，且宾语是事项，不能批准魔方。"}, {"text": "尊敬", "is_correct": false, "explanation": "搭配：「尊敬」的对象是人，不能用于魔方。"}], "explanations": {"还原": "正确答案。还原指把打乱的魔方恢复成原来的样子。", "咨询": "语义：「咨询」指向人请教意见，不能用于魔方。", "批准": "配价：「批准」要求有权的机构作主语，且宾语是事项，不能批准魔方。", "尊敬": "搭配：「尊敬」的对象是人，不能用于魔方。"}, "sentence_index": 0, "correct_answer": "还原"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人还原了一台新电脑。", "explanation": "这里应该用〈组装〉。还原是恢复到原样，新电脑没有原来的样子，不能说还原。"}, {"text": "我们还原了一套新房子。", "explanation": "这里应该用〈装修〉。还原指恢复到原来的样子，新房子还没有原样，不能说还原。"}, {"text": "妈妈还原了一锅粥。", "explanation": "这里应该用〈煮〉。还原要求对象已有原来的状态，一锅新煮的粥没有原状，不能说还原。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98601, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还原", "is_correct": true, "explanation": "正确答案。还原指把拆开的玩具恢复成原来的样子。"}, {"text": "祝福", "is_correct": false, "explanation": "搭配：「祝福」的对象是人，不能用来祝福玩具。"}, {"text": "吵醒", "is_correct": false, "explanation": "搭配：「吵醒」的对象须是能睡的人或动物，玩具不能被吵醒。"}, {"text": "亲近", "is_correct": false, "explanation": "搭配：「亲近」的对象是人，玩具不能被亲近。"}], "explanations": {"还原": "正确答案。还原指把拆开的玩具恢复成原来的样子。", "祝福": "搭配：「祝福」的对象是人，不能用来祝福玩具。", "吵醒": "搭配：「吵醒」的对象须是能睡的人或动物，玩具不能被吵醒。", "亲近": "搭配：「亲近」的对象是人，玩具不能被亲近。"}, "sentence_index": 6, "correct_answer": "还原"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专家还原了明年的天气，让大家早做准备。", "explanation": "这里应该用〈预测〉。还原指恢复到已经存在过的状态，明年的天气还没有发生，无法还原。"}, {"text": "这棵小树还原了很多，已经快有我高了。", "explanation": "这里应该用〈生长〉。还原指恢复原状，小树向上长高是生长，不能说还原。"}, {"text": "地震还原了那座老房子，墙壁都塌了。", "explanation": "这里应该用〈破坏〉。地震造成的是毁坏，不是恢复原样，不能说还原。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把散乱的积木还原成了。", "corrected_sentence": "他把散乱的积木还原好了。", "error_description": "错误：「还原成了」后面缺少「成」所引出的内容，句子不完整。应写作「还原好了」，用结果补语「好」表示还原完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他又把它还原了成原样。", "corrected_sentence": "他又把它还原成了原样。", "error_description": "错误：「了」放在了「成」之前。应写作「还原成了原样」，「了」要放在结果部分之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
