INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98602, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "恢复到原来的状态。", "primary_collocate": null, "pronunciation": "huán yuán", "ipa": "xwan˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "警察想还原事情的经过。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家还原这个故事的真相。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑坏了，我想把系统还原。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家用旧资料还原了那次事故的经过。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机可以还原到刚买时的状态。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察用监控录像还原了当时的情况。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要还原当时的情况，才能找到原因。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台游戏机出了问题，可以还原成出厂时的状态。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想还原那天晚上发生的事。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "录音太差了，声音没法还原。", "target_word": "还原", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "还原了", "label": "完成体"}, {"form": "还原过", "label": "经历体"}, {"form": "還原", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使事情、情况、系统等恢复到原来的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00032f7-208c-448d-9c5f-b377604ba846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还原", "is_correct": true, "explanation": "正确答案。还原指使事情恢复到原来的样子，这里指还原经过。"}, {"text": "感受", "is_correct": false, "explanation": "搭配：「感受」的对象是情感或感觉，不能用于事情的经过。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：「庆祝」是为喜事欢庆，与警察调查经过的意图不合。"}, {"text": "原谅", "is_correct": false, "explanation": "搭配：「原谅」的对象是人或过错，不能原谅事情的经过。"}], "explanations": {"还原": "正确答案。还原指使事情恢复到原来的样子，这里指还原经过。", "感受": "搭配：「感受」的对象是情感或感觉，不能用于事情的经过。", "庆祝": "语义：「庆祝」是为喜事欢庆，与警察调查经过的意图不合。", "原谅": "搭配：「原谅」的对象是人或过错，不能原谅事情的经过。"}, "sentence_index": 0, "correct_answer": "还原"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "艺术家还原了一幅新画。", "explanation": "这里应该用〈创作〉。还原指恢复到原来的样子，新作品没有原样，不能说还原。"}, {"text": "这种做法还原了浪费。", "explanation": "这里应该用〈减少〉。还原指恢复原状，浪费是已经发生的消耗，不能说还原。"}, {"text": "农民还原了很多粮食。", "explanation": "这里应该用〈收获〉。还原指恢复到原来的状态，粮食是劳动的产出，不能说还原。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还原", "is_correct": true, "explanation": "正确答案。还原指恢复当时的情况，才能分析出原因。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：「忘记」与「才能找到原因」的目标矛盾，忘了情况就无法找到原因。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：「欣赏」的对象多是作品或景色，不能用于当时的情况。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：「放弃」指不再坚持，与「才能找到原因」的目的相反。"}], "explanations": {"还原": "正确答案。还原指恢复当时的情况，才能分析出原因。", "忘记": "语义：「忘记」与「才能找到原因」的目标矛盾，忘了情况就无法找到原因。", "欣赏": "搭配：「欣赏」的对象多是作品或景色，不能用于当时的情况。", "放弃": "语义：「放弃」指不再坚持，与「才能找到原因」的目的相反。"}, "sentence_index": 6, "correct_answer": "还原"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专家还原了明年的天气，让大家早做准备。", "explanation": "这里应该用〈预测〉。还原指恢复到已经存在过的状态，明年的天气还没有发生，无法还原。"}, {"text": "地震还原了那座老房子，墙壁都塌了。", "explanation": "这里应该用〈破坏〉。地震造成的是毁坏，不是恢复原样，不能说还原。"}, {"text": "这棵小树还原了很多，已经快有我高了。", "explanation": "这里应该用〈生长〉。还原指恢复原状，小树向上长高是生长，不能说还原。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察已经把那起事故的情况还原原来的状态了。", "corrected_sentence": "警察已经把那起事故的情况还原到原来的状态了。", "error_description": "错误：动词「还原」后缺少介词「到」。「把……还原到原来的状态」中「到」不能省略，应写作「还原到原来的状态」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台游戏机已经还原了成出厂时的状态。", "corrected_sentence": "这台游戏机已经还原成了出厂时的状态。", "error_description": "错误：「了」放在了「成」之前。「还原成」后面应接「了」，应写作「还原成了出厂时的状态」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
