INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98605, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "钩是弯弯的小铁条，可以用来挂东西。", "primary_collocate": null, "pronunciation": "gōu", "ipa": "kou̯˥", "syllable_count": 1, "sentences": [{"text": "他把钥匙挂在钩上。", "target_word": "钩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门上的钩很小，只能挂一件外衣。", "target_word": "钩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把锅铲挂到了钩上。", "target_word": "钩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个钩弯弯的，用来挂毛巾。", "target_word": "钩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗边有个钩，雨伞挂在那里。", "target_word": "钩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在桌子下面装了一个钩，用来挂包。", "target_word": "钩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浴室的墙上有四个钩。", "target_word": "钩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个钩是铁的，不会坏。", "target_word": "钩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书包太重，钩都弯了。", "target_word": "钩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把灯挂在那个钩上。", "target_word": "钩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个钩", "label": "量词"}, {"form": "钩子", "label": "复合词"}, {"form": "鉤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "钩：弯弯的小铁条，用来挂东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61055a68-0e57-44de-a57b-c0b45d7280bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98605, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "钩", "is_correct": true, "explanation": "正确答案。钩（gōu）是弯弯的小铁条，可以用来挂东西。"}, {"text": "够", "is_correct": false, "explanation": "声调不同：gòu（第四声）与 gōu（第一声）声调不同，意思是足够。"}, {"text": "抠", "is_correct": false, "explanation": "声母不同：kōu 的声母是 k，与 gōu 的 g 不同，意思是用指甲或工具挖。"}, {"text": "狗", "is_correct": false, "explanation": "声调不同：gǒu（第三声）与 gōu（第一声）声调不同，意思是狗。"}], "explanations": {"钩": "正确答案。钩（gōu）是弯弯的小铁条，可以用来挂东西。", "够": "声调不同：gòu（第四声）与 gōu（第一声）声调不同，意思是足够。", "抠": "声母不同：kōu 的声母是 k，与 gōu 的 g 不同，意思是用指甲或工具挖。", "狗": "声调不同：gǒu（第三声）与 gōu（第一声）声调不同，意思是狗。"}, "sentence_index": null, "correct_answer": "钩"}, "level_3": {"options": [{"text": "钩", "is_correct": true, "explanation": "正确答案。“钩”是弯弯的小铁条，可以用来挂东西，符合“他把钥匙挂在……上”的句意。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不能用来挂钥匙，句意不通。"}, {"text": "抽屉", "is_correct": false, "explanation": "语义：抽屉是用来放东西的，不能用来挂钥匙。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“挂”不能与“空气”搭配，空气无法挂东西。"}], "explanations": {"钩": "正确答案。“钩”是弯弯的小铁条，可以用来挂东西，符合“他把钥匙挂在……上”的句意。", "水": "语义：水不能用来挂钥匙，句意不通。", "抽屉": "语义：抽屉是用来放东西的，不能用来挂钥匙。", "空气": "搭配：“挂”不能与“空气”搭配，空气无法挂东西。"}, "sentence_index": 0, "correct_answer": "钩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在店里买了一朵钩，挂在门后。", "explanation": "这里应该用〈个〉。“朵”用于花、云等，不用于这种小铁条。"}, {"text": "我在墙上钉了一棵钩，挂着毛巾。", "explanation": "这里应该用〈个〉。“棵”用于树、草等植物，钩是器具，不能用“棵”。"}, {"text": "奶奶用钩写了一张卡片。", "explanation": "这里应该用〈笔〉。钩是弯弯的小铁条，不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98605, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钩", "is_correct": true, "explanation": "正确答案。“钩”是挂东西的小铁条，符合“浴室的墙上有四个……”的句意。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋不会出现在墙上当作装置，句意荒谬。"}, {"text": "桥", "is_correct": false, "explanation": "语义：墙上不会有四座桥，句意荒谬。"}, {"text": "云朵", "is_correct": false, "explanation": "搭配：“墙上有”一般用来说物件，“云朵”不能附着在墙上。"}], "explanations": {"钩": "正确答案。“钩”是挂东西的小铁条，符合“浴室的墙上有四个……”的句意。", "鸡蛋": "语义：鸡蛋不会出现在墙上当作装置，句意荒谬。", "桥": "语义：墙上不会有四座桥，句意荒谬。", "云朵": "搭配：“墙上有”一般用来说物件，“云朵”不能附着在墙上。"}, "sentence_index": 6, "correct_answer": "钩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用钩洗了碗。", "explanation": "这里应该用〈刷子〉。钩是弯弯的小铁条，不能用来洗碗。"}, {"text": "我吃了一颗钩，味道很甜。", "explanation": "这里应该用〈糖〉。钩是挂东西的小铁条，不能吃。"}, {"text": "我喝了一杯钩，觉得很解渴。", "explanation": "这里应该用〈水〉。钩是挂东西的小铁条，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了三张钩，挂在厨房里。", "corrected_sentence": "我买了三个钩，挂在厨房里。", "error_description": "量词“张”用错：“张”用于纸、桌子等平面的东西，钩是小铁条，应用“个”，应说“三个钩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家的墙上有三个钩们，挂着毛巾。", "corrected_sentence": "我家的墙上有三个钩，挂着毛巾。", "error_description": "“钩”后加了复数词尾“们”，错误。“们”一般只用于指人的名词，“钩”是器具，应说“三个钩”，不说“三个钩们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
