INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98606, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "弯曲、用来悬挂或钩取东西的器具。", "primary_collocate": null, "pronunciation": "gōu", "ipa": "kou̯˥", "syllable_count": 1, "sentences": [{"text": "我把帽子挂在门后的钩上。", "target_word": "钩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上有一个钩，包就挂在上面。", "target_word": "钩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用一个长钩把树上的风筝拿下来。", "target_word": "钩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个钩太小，挂不住重的包。", "target_word": "钩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔夫在钩上放了一条小虫。", "target_word": "钩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房里有三个钩，上面挂着勺子。", "target_word": "钩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把外衣挂到那个钩上。", "target_word": "钩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个钩是铁做的，很结实。", "target_word": "钩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "衣柜里的钩坏了，我换了一个新的。", "target_word": "钩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在墙上装了两个钩。", "target_word": "钩", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个钩", "label": "量词"}, {"form": "钩子", "label": "复合词"}, {"form": "鉤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "钩：弯曲的器具，用来挂东西或钩取东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61055a68-0e57-44de-a57b-c0b45d7280bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98606, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "钩", "is_correct": true, "explanation": "正确答案。钩（gōu）指弯曲、用来挂东西或钩取东西的器具。"}, {"text": "狗", "is_correct": false, "explanation": "声调不同：gǒu（第三声）与 gōu（第一声）声调不同，意思是狗。"}, {"text": "抠", "is_correct": false, "explanation": "声母不同：kōu 的声母是 k，与 gōu 的 g 只差一个音位，意思是用指甲或工具挖。"}, {"text": "购", "is_correct": false, "explanation": "声调不同：gòu（第四声）与 gōu（第一声）声调不同，意思是购买。"}], "explanations": {"钩": "正确答案。钩（gōu）指弯曲、用来挂东西或钩取东西的器具。", "狗": "声调不同：gǒu（第三声）与 gōu（第一声）声调不同，意思是狗。", "抠": "声母不同：kōu 的声母是 k，与 gōu 的 g 只差一个音位，意思是用指甲或工具挖。", "购": "声调不同：gòu（第四声）与 gōu（第一声）声调不同，意思是购买。"}, "sentence_index": null, "correct_answer": "钩"}, "level_3": {"options": [{"text": "钩", "is_correct": true, "explanation": "正确答案。“钩”指挂东西的器具，符合“挂在门后的……上”的句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能用来挂帽子，句意不通。"}, {"text": "抽屉", "is_correct": false, "explanation": "语义：抽屉是用来放东西、拉开使用的，不能用来挂帽子。"}, {"text": "洞", "is_correct": false, "explanation": "搭配：“挂在……上”需要有突出的挂件，“洞”不能说挂在上面。"}], "explanations": {"钩": "正确答案。“钩”指挂东西的器具，符合“挂在门后的……上”的句意。", "桌子": "语义：桌子不能用来挂帽子，句意不通。", "抽屉": "语义：抽屉是用来放东西、拉开使用的，不能用来挂帽子。", "洞": "搭配：“挂在……上”需要有突出的挂件，“洞”不能说挂在上面。"}, "sentence_index": 0, "correct_answer": "钩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶去店里买了一朵钩，挂在厨房门后。", "explanation": "这里应该用〈个〉。“朵”用于花、云等，钩是器具，不能用“朵”。"}, {"text": "爷爷用钩写了一封信。", "explanation": "这里应该用〈笔〉。钩是挂取东西的器具，不能用来写字。"}, {"text": "妈妈用钩切了一块肉。", "explanation": "这里应该用〈刀〉。钩是挂取东西的器具，不能用来切肉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_e