INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钩", "is_correct": true, "explanation": "正确答案。“钩”指挂东西的器具，符合“请把外衣挂到那个……上”的句意。"}, {"text": "饭碗", "is_correct": false, "explanation": "语义：饭碗是盛饭的器具，不能用来挂外衣。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能用来挂外衣，句意荒谬。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“挂到……上”一般指挂在物件上，“河流”不能用来挂东西。"}], "explanations": {"钩": "正确答案。“钩”指挂东西的器具，符合“请把外衣挂到那个……上”的句意。", "饭碗": "语义：饭碗是盛饭的器具，不能用来挂外衣。", "月亮": "语义：月亮不能用来挂外衣，句意荒谬。", "河流": "搭配：“挂到……上”一般指挂在物件上，“河流”不能用来挂东西。"}, "sentence_index": 6, "correct_answer": "钩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用钩刷了地板。", "explanation": "这里应该用〈拖把〉。钩是挂取器具，不能用来刷地板。"}, {"text": "弟弟用钩吃掉了一碗饭。", "explanation": "这里应该用〈勺子〉。钩是挂取器具，不能用来盛饭送进嘴里；吃饭要用勺子或筷子。"}, {"text": "我喝了一杯钩，觉得很解渴。", "explanation": "这里应该用〈水〉。钩是挂取东西的器具，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口有两个钩们，衣服就挂在上面。", "corrected_sentence": "门口有两个钩，衣服就挂在上面。", "error_description": "“钩”后加了复数词尾“们”，错误。“们”一般只用于指人的名词，“钩”是器具，应说“两个钩”，不说“两个钩们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸买了三张钩，装在墙上。", "corrected_sentence": "爸爸买了三个钩，装在墙上。", "error_description": "量词“张”用错：“张”用于纸、桌子等平面的东西，钩是小器具，应用“个”，应说“三个钩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98609, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98609, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98609, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "门把是门上让你用手握住的地方，拉一拉门就开了。", "primary_collocate": null, "pronunciation": "mén bǎ", "ipa": "mən˧˥ pa˨˩˦", "syllable_count": 2, "sentences": [{"text": "他伸手拉住门把，慢慢打开了门。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门把很凉，我的手一碰就缩回来了。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个门把太高，小孩够不着。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我握着门把，听见屋里有声音。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门把坏了，我们打不开房门。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用布擦了擦门把。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要用力拉门把。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门把上有一点水，摸起来湿湿的。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他转了转门把，可是门锁着。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白色的门配上黑色的门把，很好看。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "門把", "label": "繁体"}], "register": "中性", "sense_fingerprint": "门上用手握住来拉开门的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec4c1b08-8b6c-49e8-8306-b34cf5a1cd34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98609, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "门把", "is_correct": true, "explanation": "门把是门上供手握持的部件，拉住它才能把门打开，符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：句中开的是门，窗户不是门，拉住窗户也不能打开这扇门。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“拉住”用于门把、把手一类的东西，钥匙要插进锁孔转动，不说“拉住钥匙开门”。"}, {"text": "门铃", "is_correct": false, "explanation": "语义：门铃是按的，不是拉的，而且门铃本身不能打开门。"}], "explanations": {"门把": "门把是门上供手握持的部件，拉住它才能把门打开，符合句意。", "窗户": "语义：句中开的是门，窗户不是门，拉住窗户也不能打开这扇门。", "钥匙": "搭配：“拉住”用于门把、把手一类的东西，钥匙要插进锁孔转动，不说“拉住钥匙开门”。", "门铃": "语义：门铃是按的，不是拉的，而且门铃本身不能打开门。"}, "sentence_index": 0, "correct_answer": "门把"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用钥匙打开了门把，走进屋子。", "explanation": "这里应该用〈门锁〉。钥匙要插进门锁才能开锁，门把是用手转动或拉动的部件，不能用钥匙打开。"}, {"text": "夜里他推上门把，把门闩好，谁也进不来。", "explanation": "这里应该用〈门闩〉。门闩是用来闩门的，推上才能把门插住；门把主要用来拉或转开门，不是闩门的部件。"}, {"text": "我买了一张门把，装在房门上。", "explanation": "这里应该用〈个〉。门把是小件，量词用“个”；“张”用于纸、桌子这类平面的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98609, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "门把", "is_correct": true, "explanation": "门把是门上用手握的部件，拉它才能开门，符合句意。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙是固定的建筑构件，没有可以用手拉的部分，“请不要用力拉墙”不通。"}, {"text": "水龙头", "is_correct": false, "explanation": "搭配：水龙头要拧，不说“用力拉水龙头”。"}, {"text": "按钮", "is_correct": false, "explanation": "搭配：按钮要按，不说“用力拉按钮”。"}], "explanations": {"门把": "门把是门上用手握的部件，拉它才能开门，符合句意。", "墙": "语义：墙是固定的建筑构件，没有可以用手拉的部分，“请不要用力拉墙”不通。", "水龙头": "搭配：水龙头要拧，不说“用力拉水龙头”。", "按钮": "搭配：按钮要按，不说“用力拉按钮”。"}, "sentence_index": 6, "correct_answer": "门把"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按下门把，灯就亮了。", "explanation": "这里应该用〈开关〉。按的是开关，门把是拉或转的，不是按的，也不控制灯。"}, {"text": "他拧开门把，水就流出来了。", "explanation": "这里应该用〈水龙头〉。拧开的是水龙头，门把不通水。"}, {"text": "我修好了一辆门把。", "explanation": "这里应该用〈个〉。门把是小件，“辆”用于车，不能用于门把。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他又买了一张门把，装在卧室门上。", "corrected_sentence": "他又买了一个门把，装在卧室门上。", "error_description": "量词错误：“张”用于纸、桌子这类平面的东西，门把应该用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆门把的颜色和墙很配。", "corrected_sentence": "这个门把的颜色和墙很配。", "error_description": "量词错误：“辆”用于车，门把应该用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
