INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98610, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98610, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装在门上供手握持以开关门的部件。", "primary_collocate": null, "pronunciation": "mén bǎ", "ipa": "mən˧˥ pa˨˩˦", "syllable_count": 2, "sentences": [{"text": "工人在新门上装了一个金属门把。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种门把用铜做成，很结实。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里卖各种样子的门把。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅换了旧门把，门又好用了。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门把松了，师傅用工具拧紧了它。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个圆形门把。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个门把的颜色和房间很配。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的门把上挂着一块牌子。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门把上的漆掉了一块，看起来很旧。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把门把拧下来，检查里面的零件。", "target_word": "门把", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "門把", "label": "繁体"}], "register": "中性", "sense_fingerprint": "装在门上供手握持以开关门的部件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec4c1b08-8b6c-49e8-8306-b34cf5a1cd34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98610, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "门把", "is_correct": true, "explanation": "门把是门上供手握持的部件，装在门上，符合句意。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘挂在窗户上遮光，不是门上供手握持的部件，句子不通。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯铺在地上，不装在门上，也不是金属部件。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“装”说装在门上的部件，钥匙随身携带，不说“装在门上”。"}], "explanations": {"门把": "门把是门上供手握持的部件，装在门上，符合句意。", "窗帘": "语义：窗帘挂在窗户上遮光，不是门上供手握持的部件，句子不通。", "地毯": "语义：地毯铺在地上，不装在门上，也不是金属部件。", "钥匙": "搭配：“装”说装在门上的部件，钥匙随身携带，不说“装在门上”。"}, "sentence_index": 0, "correct_answer": "门把"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "师傅换了新门把，窗户又能关严了。", "explanation": "这里应该用〈窗把手〉。关窗户要靠窗把手，门把只装在门上，不能用来关窗。"}, {"text": "师傅换了一台门把，门又好用了。", "explanation": "这里应该用〈个〉。门把是小件，“台”用于机器、电器，不能用于门把。"}, {"text": "他拧开门把，屋里响起了歌。", "explanation": "这里应该用〈收音机〉。拧开的是收音机的旋钮，门把不能发出声音，也不能用来放歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98610, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "门把", "is_correct": true, "explanation": "门把有颜色，可以和房间的颜色相配，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音没有颜色，不能说“声音的颜色和房间很配”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道没有颜色，不能说它的颜色和房间相配。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“颜色”搭配有颜色的物体，空气没有颜色。"}], "explanations": {"门把": "门把有颜色，可以和房间的颜色相配，符合句意。", "声音": "语义：声音没有颜色，不能说“声音的颜色和房间很配”。", "味道": "语义：味道没有颜色，不能说它的颜色和房间相配。", "空气": "搭配：“颜色”搭配有颜色的物体，空气没有颜色。"}, "sentence_index": 6, "correct_answer": "门把"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他关掉门把，屋里安静下来。", "explanation": "这里应该用〈电视〉。关掉的是电视，门把是开关门的部件，不能用来关电器。"}, {"text": "行李箱的门把断了，他换了一个新的。", "explanation": "这里应该用〈把手〉。行李箱上供提拿的部件叫“把手”，“门把”只装在门上，不能用于行李箱。"}, {"text": "他买了一辆门把，装在卧室门上。", "explanation": "这里应该用〈个〉。门把是小件，“辆”用于车，不能用于门把。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他又装了一座门把，门比以前好开了。", "corrected_sentence": "他又装了一个门把，门比以前好开了。", "error_description": "量词错误：“座”用于山、楼这类大型或固定的东西，门把应该用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人换了一条门把，很快就装好了。", "corrected_sentence": "工人换了一个门把，很快就装好了。", "error_description": "量词错误：“条”用于细长的东西，如河、鱼、绳子，门把应该用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
