INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98611, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "开支是花出去的钱。", "primary_collocate": null, "pronunciation": "kāi zhī", "ipa": "kʰaɪ̯˥ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "这个月我家的开支很大。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每个月都记下自己的开支。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房以后，他的开支多了很多。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想少花钱，所以先看看每笔开支。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把不必要的开支减下来。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个月的开支只有两千块。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子上学以后，家里的开支变大了。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租是我最大的一笔开支。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把每天的开支写在本子上。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生的日常开支一般不太多。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "日常开支", "label": "复合词"}], "register": "中性", "sense_fingerprint": "日常生活中花出去的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3810a26-ecf2-428b-beee-e994530c768a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98611, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”指取得的结果，与“我家的……很大”所说的花费不符。"}, {"text": "开支", "is_correct": true, "explanation": "正确：“开支”指花出去的钱，与“很大”搭配，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”说高或矮，不说“很大”。"}, {"text": "财政", "is_correct": false, "explanation": "语域与搭配：“财政”多指国家或政府的收支，用于家庭较书面，“家的……很大”不自然。"}], "explanations": {"成绩": "语义：“成绩”指取得的结果，与“我家的……很大”所说的花费不符。", "开支": "正确：“开支”指花出去的钱，与“很大”搭配，符合句意。", "身高": "搭配：“身高”说高或矮，不说“很大”。", "财政": "语域与搭配：“财政”多指国家或政府的收支，用于家庭较书面，“家的……很大”不自然。"}, "sentence_index": 0, "correct_answer": "开支"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每个月都向公司交开支，用来换工作机会。", "explanation": "这里应该用〈费用〉。开支是自己花出去的钱的总称，不说“交开支”给别人。"}, {"text": "他每个月拿到的开支是八千元。", "explanation": "这里应该用〈收入〉。拿到的是收进来的钱，开支是花出去的钱。"}, {"text": "他每个月都把开支存进银行。", "explanation": "这里应该用〈储蓄〉。存进银行的是存下来的钱，开支是花出去的钱，不能存。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98611, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气氛", "is_correct": false, "explanation": "搭配：“气氛”说浓或热烈，不说“变大”。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：“年纪”指人的岁数，不属于“家里”。"}, {"text": "开支", "is_correct": true, "explanation": "正确：“开支”指花出去的钱，上学后支出增加，与“变大”搭配。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”说升高或降低，不说“变大”。"}], "explanations": {"气氛": "搭配：“气氛”说浓或热烈，不说“变大”。", "年纪": "语义：“年纪”指人的岁数，不属于“家里”。", "开支": "正确：“开支”指花出去的钱，上学后支出增加，与“变大”搭配。", "体温": "搭配：“体温”说升高或降低，不说“变大”。"}, "sentence_index": 6, "correct_answer": "开支"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月领到的开支是八千元。", "explanation": "这里应该用〈工资〉。领到的是收入，开支是花出去的钱。"}, {"text": "他做兼职，每个月能挣不少开支。", "explanation": "这里应该用〈收入〉。挣到的是收入，开支是花出去的钱。"}, {"text": "这笔开支由政府每年收取。", "explanation": "这里应该用〈税收〉。政府收取的是税收，开支是花出去的钱，不能由政府收取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98611, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月我家有三只开支比较大。", "corrected_sentence": "这个月我家有三笔开支比较大。", "error_description": "量词错误：“开支”应用量词“笔”，说“三笔开支”，不说“三只开支”（只多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98611, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上个月他有两张开支忘了记下来。", "corrected_sentence": "上个月他有两笔开支忘了记下来。", "error_description": "量词错误：“开支”应用量词“笔”，说“两笔开支”，不说“两张开支”（“张”多用于纸、桌子等平面的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
