INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98612, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "支出的费用。", "primary_collocate": null, "pronunciation": "kāi zhī", "ipa": "kʰaɪ̯˥ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "公司的开支要经过经理同意。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的开支由公司来付。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想减少办公开支。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目的总开支是十万元。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会计正在算今年的开支。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府每年都公布教育开支。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的开支比去年高了一些。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔开支需要先写报告。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把多余的开支都取消了。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把出差的开支交给财务。", "target_word": "开支", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "办公开支", "label": "复合词"}], "register": "中性", "sense_fingerprint": "公司、机构等支出的费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3810a26-ecf2-428b-beee-e994530c768a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体型", "is_correct": false, "explanation": "体貌：“体型”指人或动物的身体形状，不用于公司。"}, {"text": "学历", "is_correct": false, "explanation": "语义：“学历”是个人受教育的经历，公司没有学历。"}, {"text": "开支", "is_correct": true, "explanation": "正确：“开支”指公司花出去的费用，需要经理同意，与句意一致。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”属于人的性格，公司没有脾气。"}], "explanations": {"体型": "体貌：“体型”指人或动物的身体形状，不用于公司。", "学历": "语义：“学历”是个人受教育的经历，公司没有学历。", "开支": "正确：“开支”指公司花出去的费用，需要经理同意，与句意一致。", "脾气": "语义：“脾气”属于人的性格，公司没有脾气。"}, "sentence_index": 0, "correct_answer": "开支"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司卖产品，今年赚了很多开支。", "explanation": "这里应该用〈利润〉。赚到的是利润，开支是花出去的费用。"}, {"text": "公司每个月都发开支给员工。", "explanation": "这里应该用〈工资〉。发给员工的是工资，开支是花出去的钱，不能发给员工。"}, {"text": "公司把开支存进银行。", "explanation": "这里应该用〈利润〉。存进银行的是利润，开支是花出去的钱，不能存。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”说深或浅，不说“比去年高”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”是称呼，没有高低，句子说的是支出的变化。"}, {"text": "开支", "is_correct": true, "explanation": "正确：“开支”可以增高，“工厂的开支比去年高了一些”符合句意。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：“眼睛”说大小或亮暗，不说“高”。"}], "explanations": {"颜色": "搭配：“颜色”说深或浅，不说“比去年高”。", "名字": "语义：“名字”是称呼，没有高低，句子说的是支出的变化。", "开支": "正确：“开支”可以增高，“工厂的开支比去年高了一些”符合句意。", "眼睛": "体貌：“眼睛”说大小或亮暗，不说“高”。"}, "sentence_index": 6, "correct_answer": "开支"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司今年的开支来自卖产品赚的钱。", "explanation": "这里应该用〈收入〉。卖产品得到的是收入，开支是支出的费用。"}, {"text": "政府向企业收取开支。", "explanation": "这里应该用〈税收〉。政府向企业收取的是税收，开支是花出去的钱，不能收取。"}, {"text": "银行每年支付给存户开支。", "explanation": "这里应该用〈利息〉。银行支付给存户的是利息，开支是花出去的钱，不能支付给存户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校这学期有几张办公开支要审核。", "corrected_sentence": "学校这学期有几笔办公开支要审核。", "error_description": "量词错误：“办公开支”应用量词“笔”，不用“张”（张多用于纸、桌子等平面物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会计已经把这只开支记好了。", "corrected_sentence": "会计已经把这笔开支记好了。", "error_description": "量词错误：“开支”应用量词“笔”，说“这笔开支”，不说“这只开支”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
