INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98613, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "防护是做好准备，不让东西受到伤害。", "primary_collocate": null, "pronunciation": "fáng hù", "ipa": "fɑŋ˧˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "这家工厂的防护做得很好。", "target_word": "防护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭时的防护也不能马虎。", "target_word": "防护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "防护不够，孩子容易受伤。", "target_word": "防护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们给自行车加了防护，不怕下雨。", "target_word": "防护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "滑雪时要做好头部防护。", "target_word": "防护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人上班前先检查防护。", "target_word": "防护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "防护很重要，千万别忘了。", "target_word": "防护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥有很好的防护。", "target_word": "防护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎样做防护。", "target_word": "防护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天出门，防护要做足。", "target_word": "防护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防護", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做好准备，不让东西受到伤害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1baa88c0-478f-4d07-801d-78f872fad5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98613, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "防护", "is_correct": true, "explanation": "正确：防护（fáng hù）指做好准备，不让东西受到伤害。"}, {"text": "防火", "is_correct": false, "explanation": "huǒ（第三声）与 hù（第四声）韵母和声调都不同，意思是防止火灾。"}, {"text": "防寒", "is_correct": false, "explanation": "hán（第二声）与 hù（第四声）韵母与声调不同，意思是防备寒冷。"}, {"text": "防蛀", "is_correct": false, "explanation": "zhù（第四声）与 hù（第四声）声母不同（zh 与 h），意思是防止虫蛀。"}], "explanations": {"防护": "正确：防护（fáng hù）指做好准备，不让东西受到伤害。", "防火": "huǒ（第三声）与 hù（第四声）韵母和声调都不同，意思是防止火灾。", "防寒": "hán（第二声）与 hù（第四声）韵母与声调不同，意思是防备寒冷。", "防蛀": "zhù（第四声）与 hù（第四声）声母不同（zh 与 h），意思是防止虫蛀。"}, "sentence_index": null, "correct_answer": "防护"}, "level_3": {"options": [{"text": "防护", "is_correct": true, "explanation": "正确：防护指为不受伤害做的准备，符合“这家工厂的……做得很好”的语境。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：“歌唱”是唱歌，与工厂的安全准备无关。"}, {"text": "教学", "is_correct": false, "explanation": "语义：“教学”是授课，与工厂的安全准备语境不符。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：“做得很好”一般不说“收入做得很好”，应说收入很高。"}], "explanations": {"防护": "正确：防护指为不受伤害做的准备，符合“这家工厂的……做得很好”的语境。", "歌唱": "语义：“歌唱”是唱歌，与工厂的安全准备无关。", "教学": "语义：“教学”是授课，与工厂的安全准备语境不符。", "收入": "搭配：“做得很好”一般不说“收入做得很好”，应说收入很高。"}, "sentence_index": 0, "correct_answer": "防护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人要防护骗子，不要随便给钱。", "explanation": "这里应该用〈防备〉。防护是为了让东西不受伤害，骗子是要防备的对象，不能说防护骗子。"}, {"text": "消防员赶到现场，防护了大火。", "explanation": "这里应该用〈扑灭〉。防护针对需要保护的对象，大火是要扑灭的对象。"}, {"text": "猫在厨房里防护老鼠。", "explanation": "这里应该用〈驱赶〉。防护是让东西免受伤害，老鼠是要驱赶的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98613, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "防护", "is_correct": true, "explanation": "正确：防护（fáng hù）指做好准备，不让东西受到伤害。"}, {"text": "防腐", "is_correct": false, "explanation": "fǔ（第三声）与 hù（第四声）声母不同（f 与 h），意思是防止腐烂。"}, {"text": "防务", "is_correct": false, "explanation": "wù 与 hù 声母不同（w 与 h），意思是国防事务，不是防护。"}, {"text": "防暑", "is_correct": false, "explanation": "shǔ（第三声）与 hù（第四声）声母和声调都不同，意思是防备暑热。"}], "explanations": {"防护": "正确：防护（fáng hù）指做好准备，不让东西受到伤害。", "防腐": "fǔ（第三声）与 hù（第四声）声母不同（f 与 h），意思是防止腐烂。", "防务": "wù 与 hù 声母不同（w 与 h），意思是国防事务，不是防护。", "防暑": "shǔ（第三声）与 hù（第四声）声母和声调都不同，意思是防备暑热。"}, "sentence_index": null, "correct_answer": "防护"}, "level_3": {"options": [{"text": "防护", "is_correct": true, "explanation": "正确：防护指做好准备、防止受伤，符合“防护很重要，千万别忘了”的语境。"}, {"text": "玩笑", "is_correct": false, "explanation": "语义：“玩笑”不是需要牢记的要点，句中“很重要，千万别忘了”讲不通。"}, {"text": "谎言", "is_correct": false, "explanation": "语义：谎言不宜被说成“很重要，千万别忘了”，与句子的语境相反。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“很重要，千万别忘了”通常用于事情或要点，不用来评价饮料。"}], "explanations": {"防护": "正确：防护指做好准备、防止受伤，符合“防护很重要，千万别忘了”的语境。", "玩笑": "语义：“玩笑”不是需要牢记的要点，句中“很重要，千万别忘了”讲不通。", "谎言": "语义：谎言不宜被说成“很重要，千万别忘了”，与句子的语境相反。", "饮料": "搭配：“很重要，千万别忘了”通常用于事情或要点，不用来评价饮料。"}, "sentence_index": 6, "correct_answer": "防护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天，我们用蚊香防护蚊子。", "explanation": "这里应该用〈驱赶〉。防护的对象是需要保护的人或物，蚊子是要驱赶的对象；蚊香是把蚊子赶走，不能说防护蚊子。"}, {"text": "警察及时防护了暴乱。", "explanation": "这里应该用〈镇压〉。防护用于保护人或物，暴乱是要镇压的对象。"}, {"text": "警察很快防护了逃犯。", "explanation": "这里应该用〈围捕〉。防护的对象是需要保护的人或物，逃犯是要围捕的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人的防护们都做得很好。", "corrected_sentence": "工人的防护都做得很好。", "error_description": "错误：在名词“防护”后面加了复数词尾“们”。“防护”是不可数的抽象名词，不能加“们”，应直接说“工人的防护”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们在高处作业，先做得防护再上去。", "corrected_sentence": "工人们在高处作业，先做好防护再上去。", "error_description": "错误形式：“做得防护”；正确形式：“做好防护”。“做”后的结果补语应为形容词“好”，“得”不能直接接名词“防护”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
