INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98614, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "防备并保护，使免受损害。", "primary_collocate": null, "pronunciation": "fáng hù", "ipa": "fɑŋ˧˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "下雨前，农民先用布盖住树木，防护它们。", "target_word": "防护", "complexity_tier": "T3", "furigana": "fánghù", "sentence_source": "generated"}, {"text": "出门要戴口罩，防护自己的呼吸道。", "target_word": "防护", "complexity_tier": "T3", "furigana": "fánghù", "sentence_source": "generated"}, {"text": "医生工作时必须防护好自己。", "target_word": "防护", "complexity_tier": "T3", "furigana": "fánghù", "sentence_source": "generated"}, {"text": "夏天晒太阳，要用防晒霜防护皮肤。", "target_word": "防护", "complexity_tier": "T3", "furigana": "fánghù", "sentence_source": "generated"}, {"text": "我们要防护这座老房子，别让雨水伤到它。", "target_word": "防护", "complexity_tier": "T3", "furigana": "fánghù", "sentence_source": "generated"}, {"text": "他给手机贴了膜，防护屏幕。", "target_word": "防护", "complexity_tier": "T3", "furigana": "fánghù", "sentence_source": "generated"}, {"text": "骑车时要戴好头盔，防护头部。", "target_word": "防护", "complexity_tier": "T3", "furigana": "fánghù", "sentence_source": "generated"}, {"text": "海边的村子用高墙防护房屋，抵挡海浪。", "target_word": "防护", "complexity_tier": "T3", "furigana": "fánghù", "sentence_source": "generated"}, {"text": "做实验时，学生要先防护眼睛。", "target_word": "防护", "complexity_tier": "T3", "furigana": "fánghù", "sentence_source": "generated"}, {"text": "这种霜可以防护皮肤不受阳光伤害。", "target_word": "防护", "complexity_tier": "T3", "furigana": "fánghù", "sentence_source": "generated"}], "morphological_forms": [{"form": "防護", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事先防备并加以保护，使不受损害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1baa88c0-478f-4d07-801d-78f872fad5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98614, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "防护", "is_correct": true, "explanation": "正确：防护（fáng hù）指防备并保护，使免受损害。"}, {"text": "防火", "is_correct": false, "explanation": "huǒ（第三声）与 hù（第四声）韵母和声调都不同，意思是防止火灾。"}, {"text": "防腐", "is_correct": false, "explanation": "fǔ（第三声）与 hù（第四声）声母不同（f 与 h），意思是防止腐烂。"}, {"text": "防务", "is_correct": false, "explanation": "wù 与 hù 声母不同（w 与 h），意思是国防事务，不是防护。"}], "explanations": {"防护": "正确：防护（fáng hù）指防备并保护，使免受损害。", "防火": "huǒ（第三声）与 hù（第四声）韵母和声调都不同，意思是防止火灾。", "防腐": "fǔ（第三声）与 hù（第四声）声母不同（f 与 h），意思是防止腐烂。", "防务": "wù 与 hù 声母不同（w 与 h），意思是国防事务，不是防护。"}, "sentence_index": null, "correct_answer": "防护"}, "level_3": {"options": [{"text": "防护", "is_correct": true, "explanation": "正确：防护指事先防备并保护，使树木免受雨水伤害，符合“下雨前用布盖住树木”的语境。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：修剪是剪去枝叶，与“用布盖住树木”的保护动作不符。"}, {"text": "浇灌", "is_correct": false, "explanation": "语义：浇灌是给植物浇水，与“下雨前用布盖住树木”的目的相反。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”多用于房屋、设施，不说拆除树木，与前句的遮盖动作也不相容。"}], "explanations": {"防护": "正确：防护指事先防备并保护，使树木免受雨水伤害，符合“下雨前用布盖住树木”的语境。", "修剪": "语义：修剪是剪去枝叶，与“用布盖住树木”的保护动作不符。", "浇灌": "语义：浇灌是给植物浇水，与“下雨前用布盖住树木”的目的相反。", "拆除": "搭配：“拆除”多用于房屋、设施，不说拆除树木，与前句的遮盖动作也不相容。"}, "sentence_index": 0, "correct_answer": "防护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提前防护小偷，把门窗都锁好了。", "explanation": "这里应该用〈防备〉。防护是保护人或物免受伤害，小偷是要防备的对象，不能说防护小偷。"}, {"text": "严格执行规定，可以防护事故的发生。", "explanation": "这里应该用〈防止〉。防护的对象是人或物，要保护它们免受伤害；“事故的发生”是要避免的事，应说防止。"}, {"text": "他很快防护了这道数学题。", "explanation": "这里应该用〈解答〉。防护的对象是需要免受伤害的人或物，数学题只能解答，不能说防护。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98614, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "防护", "is_correct": true, "explanation": "正确：防护（fáng hù）指防备并保护，使免受损害。"}, {"text": "防暑", "is_correct": false, "explanation": "shǔ（第三声）与 hù（第四声）声母与声调都不同（sh 与 h），意思是防备暑热。"}, {"text": "防寒", "is_correct": false, "explanation": "hán（第二声）与 hù（第四声）韵母与声调不同，意思是防备寒冷。"}, {"text": "防蛀", "is_correct": false, "explanation": "zhù（第四声）与 hù（第四声）声母不同（zh 与 h），意思是防止虫蛀。"}], "explanations": {"防护": "正确：防护（fáng hù）指防备并保护，使免受损害。", "防暑": "shǔ（第三声）与 hù（第四声）声母与声调都不同（sh 与 h），意思是防备暑热。", "防寒": "hán（第二声）与 hù（第四声）韵母与声调不同，意思是防备寒冷。", "防蛀": "zhù（第四声）与 hù（第四声）声母不同（zh 与 h），意思是防止虫蛀。"}, "sentence_index": null, "correct_answer": "防护"}, "level_3": {"options": [{"text": "防护", "is_correct": true, "explanation": "正确：防护指做好保护，使头部免受伤害，符合“骑车时戴好头盔”的语境。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：“打扮”指修饰外表，与戴头盔保护头部的意图不符。"}, {"text": "切割", "is_correct": false, "explanation": "语义：“切割”是割开物体，与“戴好头盔”的保护语境冲突。"}, {"text": "训练", "is_correct": false, "explanation": "搭配：“训练”多搭配体能、技能，不直接以“头部”作为保护对象。"}], "explanations": {"防护": "正确：防护指做好保护，使头部免受伤害，符合“骑车时戴好头盔”的语境。", "打扮": "语义：“打扮”指修饰外表，与戴头盔保护头部的意图不符。", "切割": "语义：“切割”是割开物体，与“戴好头盔”的保护语境冲突。", "训练": "搭配：“训练”多搭配体能、技能，不直接以“头部”作为保护对象。"}, "sentence_index": 6, "correct_answer": "防护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警方加大力度防护犯罪，维护治安。", "explanation": "这里应该用〈打击〉。防护是保护人或物免受伤害，犯罪是要打击的对象，不能说防护犯罪。"}, {"text": "农民用竹竿防护野猪，不让它进入庄稼地。", "explanation": "这里应该用〈驱赶〉。防护的对象是需要保护的人或物，野猪是要驱赶的对象。"}, {"text": "消防员赶到现场，防护大火，很快控制了火势。", "explanation": "这里应该用〈扑灭〉。防护是保护免受伤害，大火是要扑灭的对象，不能说防护大火。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台风要来了，他把窗户防护了好。", "corrected_sentence": "台风要来了，他把窗户防护好了。", "error_description": "错误形式：“防护了好”；正确形式：“防护好了”。结果补语“好”必须紧跟动词，放在“了”之后不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下雪前，园丁用草帘花枝防护好。", "corrected_sentence": "下雪前，园丁用草帘把花枝防护好。", "error_description": "错误：受事“花枝”放在动词“防护”前，却缺少“把”。应写成“把花枝防护好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
