INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98615, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "限于是只能在一个范围里，不能超出去。", "primary_collocate": null, "pronunciation": "xiàn yú", "ipa": "ɕjɛn˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "小王的任务限于联系客人，别的不用管。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本店折扣限于今天，明天就没有了。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题的讨论限于班里，不要说出去。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车位限于住在这里的人使用。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名限于三月一日以前，晚了不行。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行限于国内，不能出国。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的帮助不限于钱，还有很多时间。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间限于工作人员进入。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每人买的东西限于两件，不能再多了。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的生意限于本市。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不限于", "label": "否定"}, {"form": "仅限于", "label": "复合"}], "register": "书面", "sense_fingerprint": "只能在一个范围里，不能超出这个范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158031be-7c16-4e76-bc41-c9e0a5326719') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98615, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "超出", "is_correct": false, "explanation": "搭配：“超出”接的是范围或数量，不能接“联系客人”这种动作。"}, {"text": "解决", "is_correct": false, "explanation": "语义：“解决”的对象是问题，“联系客人”不是需要解决的问题。"}, {"text": "限于", "is_correct": true, "explanation": "正确：“限于”表示任务只在联系客人这一范围内，与“别的不用管”相合。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“任务”不能“拒绝”，“拒绝联系客人”说不通。"}], "explanations": {"超出": "搭配：“超出”接的是范围或数量，不能接“联系客人”这种动作。", "解决": "语义：“解决”的对象是问题，“联系客人”不是需要解决的问题。", "限于": "正确：“限于”表示任务只在联系客人这一范围内，与“别的不用管”相合。", "拒绝": "语义：“任务”不能“拒绝”，“拒绝联系客人”说不通。"}, "sentence_index": 0, "correct_answer": "限于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "物业限于全部车辆。", "explanation": "这里应该用〈禁止〉。限于表示把范围圈在某处，“限于全部车辆”说不通；要表示不许外来车辆进入，应该用禁止。"}, {"text": "这个停车位的价格限于每天的天气。", "explanation": "这里应该用〈取决于〉。限于表示把范围圈在某处，停车价格不能说限于天气，应说取决于某些因素。"}, {"text": "这个停车位限于很快就满了。", "explanation": "这里应该用〈马上〉。限于表示把范围圈在某处，不能接“很快就满了”这样的结果；要说车位很快满了，应说马上就满。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98615, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讨厌", "is_correct": false, "explanation": "语义：“帮助”没有情感，不会讨厌钱，这句话说不通。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”是消耗的意思，“帮助”不会吃掉钱，句子说不通。"}, {"text": "限于", "is_correct": true, "explanation": "正确：“不限于”表示不只局限在钱上，与“还有很多时间”相合。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“帮助”没有喜好，“不喜欢钱”与后文的意思不搭。"}], "explanations": {"讨厌": "语义：“帮助”没有情感，不会讨厌钱，这句话说不通。", "吃掉": "语义：“吃掉”是消耗的意思，“帮助”不会吃掉钱，句子说不通。", "限于": "正确：“不限于”表示不只局限在钱上，与“还有很多时间”相合。", "喜欢": "语义：“帮助”没有喜好，“不喜欢钱”与后文的意思不搭。"}, "sentence_index": 6, "correct_answer": "限于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他限于公司的利润。", "explanation": "这里应该用〈分享〉。限于表示把范围圈在某处，人不能被圈在利润里，说不通；要说他分享利润，应该用分享。"}, {"text": "这家公司的生意限于越来越好。", "explanation": "这里应该用〈变得〉。限于表示把范围圈在某处，后面要接范围，不能接“越来越好”这样的变化；要说生意变好，应说变得越来越好。"}, {"text": "这家公司的生意限于很多地方。", "explanation": "这里应该用〈遍布〉。“限于”表示范围被圈小，“限于很多地方”自相矛盾；要说生意分布广，应该用遍布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98615, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小组的工作限于了财务核对。", "corrected_sentence": "这个小组的工作限于财务核对。", "error_description": "“了”放错了位置：“限于”后面不能加“了”。正确说法是“这个小组的工作限于财务核对。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98615, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张票限于了学生购买。", "corrected_sentence": "这张票限于学生购买。", "error_description": "“了”放错了位置：“限于”后面不能加“了”。正确说法是“这张票限于学生购买。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
