INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98616, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "局限在某个范围之内。", "primary_collocate": null, "pronunciation": "xiàn yú", "ipa": "ɕjɛn˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "这次活动限于本校学生参加。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议名额限于五十人，请早点报名。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛限于十八岁以下的孩子。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天的讨论限于这一个问题。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种票限于周末使用，平时不能用。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些图书限于馆内阅读，不能外借。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作限于整理文件，不管别的事。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个规定不限于学生，老师也要遵守。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的优惠限于会员，别人没有。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的内容限于前五课。", "target_word": "限于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不限于", "label": "否定"}, {"form": "仅限于", "label": "复合"}], "register": "书面", "sense_fingerprint": "把人、事、时间等局限在某个范围之内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158031be-7c16-4e76-bc41-c9e0a5326719') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98616, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "破坏", "is_correct": false, "explanation": "配价：“破坏”后面要接具体事物做宾语，不能接“本校学生参加”这样的动作。"}, {"text": "替代", "is_correct": false, "explanation": "语义：“替代”要说明替代了什么，这句话里没有可替代的对象，说不通。"}, {"text": "限于", "is_correct": true, "explanation": "正确：“限于”表示范围只在本校学生之内，与“只能本校学生参加”相合。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：“扩大”表示扩展范围，与“只限本校学生”的意思正好相反，且不能接“参加”做宾语。"}], "explanations": {"破坏": "配价：“破坏”后面要接具体事物做宾语，不能接“本校学生参加”这样的动作。", "替代": "语义：“替代”要说明替代了什么，这句话里没有可替代的对象，说不通。", "限于": "正确：“限于”表示范围只在本校学生之内，与“只能本校学生参加”相合。", "扩大": "语义：“扩大”表示扩展范围，与“只限本校学生”的意思正好相反，且不能接“参加”做宾语。"}, "sentence_index": 0, "correct_answer": "限于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校限于学生的手机。", "explanation": "这里应该用〈限制〉。限于表示把范围圈在某处，不能拿“学生的手机”作管控对象；限制可以接对象。"}, {"text": "班主任限于我的作业。", "explanation": "这里应该用〈检查〉。限于表示把范围圈在某处，不能表示班主任对作业进行检查。"}, {"text": "他的成绩限于进步。", "explanation": "这里应该用〈提高〉。限于表示把范围圈在某处，“成绩限于进步”说不通；要说成绩变好，应说提高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饲养", "is_correct": false, "explanation": "语义：饲养的对象是动物，不能饲养“整理文件”。"}, {"text": "呼吸", "is_correct": false, "explanation": "配价：“呼吸”是不及物动词，后面不能直接带“整理文件”做宾语。"}, {"text": "限于", "is_correct": true, "explanation": "正确：“限于”表示工作范围只在整理文件之内，与“不管别的事”相合。"}, {"text": "放牧", "is_correct": false, "explanation": "语义：放牧是带着牲畜吃草，与“整理文件”毫无关系。"}], "explanations": {"饲养": "语义：饲养的对象是动物，不能饲养“整理文件”。", "呼吸": "配价：“呼吸”是不及物动词，后面不能直接带“整理文件”做宾语。", "限于": "正确：“限于”表示工作范围只在整理文件之内，与“不管别的事”相合。", "放牧": "语义：放牧是带着牲畜吃草，与“整理文件”毫无关系。"}, "sentence_index": 6, "correct_answer": "限于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈限于我每天玩游戏的时间。", "explanation": "这里应该用〈约束〉。限于表示把范围圈在某处，不能用来指父母对孩子施加管束。"}, {"text": "老师限于同学们的座位。", "explanation": "这里应该用〈安排〉。限于表示把范围圈在某处，不能表示老师对同学们的座位进行安排。"}, {"text": "这家店的分店限于全国各地。", "explanation": "这里应该用〈遍布〉。“限于”表示范围被圈小，说“限于全国各地”自相矛盾；要说分店分布很广，应该用遍布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项活动限于了老队员参加。", "corrected_sentence": "这项活动限于老队员参加。", "error_description": "“了”放错了位置：“限于”后面不能加“了”。正确说法是“这项活动限于老队员参加。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔补助限于了贫困学生申请。", "corrected_sentence": "这笔补助限于贫困学生申请。", "error_description": "“了”放错了位置：“限于”后面不能加“了”。正确说法是“这笔补助限于贫困学生申请。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
