INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98618, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "科学院或工程院中学术上有杰出成就的最高称号的获得者。", "primary_collocate": null, "pronunciation": "yuàn shì", "ipa": "yɥɛn˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "他在五十岁时当选为院士。", "target_word": "院士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国只有很少的科学家能成为院士。", "target_word": "院士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位院士获得过很多国际奖。", "target_word": "院士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程院今年选出了二十位新院士。", "target_word": "院士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是中国最年轻的女院士之一。", "target_word": "院士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院士是获得最高学术称号的科学家。", "target_word": "院士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究了三十年，终于成了院士。", "target_word": "院士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老院士的论文改变过这个领域。", "target_word": "院士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成为院士以后，他仍然天天做研究。", "target_word": "院士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位院士在大会上发表了讲话。", "target_word": "院士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "工程院院士", "label": "复合"}], "register": "书面", "sense_fingerprint": "科学院或工程院最高学术称号的获得者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3810a26-ecf2-428b-beee-e994530c768a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98618, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "院士", "is_correct": true, "explanation": "院士（yuàn shì）指科学院或工程院中学术上有杰出成就的最高称号获得者，是本题的目标词。"}, {"text": "原始", "is_correct": false, "explanation": "原始（yuán shǐ）与院士（yuàn shì）两个音节的声调都不同（第二声、第三声对第四声），意思是最初的、早期的。"}, {"text": "远视", "is_correct": false, "explanation": "远视（yuǎn shì）只有第一音节声调不同（第三声对第四声），意思是看远处清楚、看近处模糊。"}, {"text": "院史", "is_correct": false, "explanation": "院史（yuàn shǐ）只有第二音节声调不同（第三声对第四声），意思是学院的历史。"}], "explanations": {"院士": "院士（yuàn shì）指科学院或工程院中学术上有杰出成就的最高称号获得者，是本题的目标词。", "原始": "原始（yuán shǐ）与院士（yuàn shì）两个音节的声调都不同（第二声、第三声对第四声），意思是最初的、早期的。", "远视": "远视（yuǎn shì）只有第一音节声调不同（第三声对第四声），意思是看远处清楚、看近处模糊。", "院史": "院史（yuàn shǐ）只有第二音节声调不同（第三声对第四声），意思是学院的历史。"}, "sentence_index": null, "correct_answer": "院士"}, "level_3": {"options": [{"text": "院士", "is_correct": true, "explanation": "院士是通过选举产生的学术最高称号，与“当选为”相符。"}, {"text": "冠军", "is_correct": false, "explanation": "搭配：“当选”搭配选举产生的职务或称号，不说“当选为冠军”。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不是选举产生的称号，“当选”不能用于此。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：“五十岁时”不可能是小学生，与语境矛盾。"}], "explanations": {"院士": "院士是通过选举产生的学术最高称号，与“当选为”相符。", "冠军": "搭配：“当选”搭配选举产生的职务或称号，不说“当选为冠军”。", "厨师": "语义：厨师不是选举产生的称号，“当选”不能用于此。", "小学生": "语义：“五十岁时”不可能是小学生，与语境矛盾。"}, "sentence_index": 0, "correct_answer": "院士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在国外拿到了院士学位，回国后当了老师。", "explanation": "这里应该用〈博士〉。院士是荣誉称号，不是学位。"}, {"text": "他担任学校的院士，管理了五年。", "explanation": "这里应该用〈院长〉。院士是学术荣誉称号，不是管理职务。"}, {"text": "医院里来了一位院士，照顾病人。", "explanation": "这里应该用〈护士〉。院士是科学界的荣誉称号，不是护理工作者的称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "院士", "is_correct": true, "explanation": "院士是学术上的最高荣誉称号，经过多年研究可以获得，与语境相符。"}, {"text": "歌星", "is_correct": false, "explanation": "语义：研究三十年不会使人成为歌星，与语境矛盾。"}, {"text": "演员", "is_correct": false, "explanation": "语义：研究与表演是两种完全不同的职业，不能说“成了演员”。"}, {"text": "运动员", "is_correct": false, "explanation": "搭配：“运动员”靠训练和比赛成长，不能与“研究了三十年”搭配。"}], "explanations": {"院士": "院士是学术上的最高荣誉称号，经过多年研究可以获得，与语境相符。", "歌星": "语义：研究三十年不会使人成为歌星，与语境矛盾。", "演员": "语义：研究与表演是两种完全不同的职业，不能说“成了演员”。", "运动员": "搭配：“运动员”靠训练和比赛成长，不能与“研究了三十年”搭配。"}, "sentence_index": 6, "correct_answer": "院士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐姐是一名院士，负责修桥。", "explanation": "这里应该用〈工程师〉。院士是学术荣誉称号，不指修桥的职业。"}, {"text": "超市的院士很热情，帮我找到了东西。", "explanation": "这里应该用〈售货员〉。院士是荣誉称号，不指在超市工作的人。"}, {"text": "他在这次比赛里成了院士，拿到了金牌。", "explanation": "这里应该用〈冠军〉。院士是学术上的荣誉称号，不是体育比赛的名次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年当选为工程院的一把院士。", "corrected_sentence": "她去年当选为工程院的一名院士。", "error_description": "量词用错：“院士”指人，应用“名”或“位”，不能用“把”（把用于有柄的物件或椅子）。正确说法是“一名院士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年考上了工程院院士。", "corrected_sentence": "他去年当选为工程院院士。", "error_description": "搭配错误：院士是选举产生的荣誉称号，不是考试考取的，不能说“考上院士”，应说“当选为院士”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
