INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98619, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "除此之外是说已经说过的这些以外，还有别的。", "primary_collocate": null, "pronunciation": "chú cǐ zhī wài", "ipa": "tʂʰu˧˥ tsʰɨ˨˩ tʂɨ˥ wai˥˩", "syllable_count": 4, "sentences": [{"text": "他买了一台电脑，除此之外还买了手机。", "target_word": "除此之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会做饭，除此之外还会洗衣服。", "target_word": "除此之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天要开会，除此之外还要写报告。", "target_word": "除此之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市很大，除此之外人也很多。", "target_word": "除此之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做了鱼，除此之外还做了汤。", "target_word": "除此之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我养了一只猫，除此之外还养了两条鱼。", "target_word": "除此之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很聪明，除此之外也非常努力。", "target_word": "除此之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天天气热，除此之外雨也特别多。", "target_word": "除此之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学汉语，除此之外还学写汉字。", "target_word": "除此之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王喜欢踢球，除此之外也爱打篮球。", "target_word": "除此之外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说过的这些以外，还有别的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1baa88c0-478f-4d07-801d-78f872fad5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98619, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "除此之外", "is_correct": true, "explanation": "正确：“除此之外”表示在前面所说的之外还有别的，这里引出电脑之外的手机，语境相符。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，买电脑和买手机之间并没有对立关系，转折说不通。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示因果，买电脑与买手机之间没有因果关系，“因为”说不通。"}, {"text": "只要", "is_correct": false, "explanation": "语义：“只要”引出充分条件，买电脑与买手机之间不构成条件关系，句子说不通。"}], "explanations": {"除此之外": "正确：“除此之外”表示在前面所说的之外还有别的，这里引出电脑之外的手机，语境相符。", "然而": "语义：“然而”表示转折，买电脑和买手机之间并没有对立关系，转折说不通。", "因为": "语义：“因为”表示因果，买电脑与买手机之间没有因果关系，“因为”说不通。", "只要": "语义：“只要”引出充分条件，买电脑与买手机之间不构成条件关系，句子说不通。"}, "sentence_index": 0, "correct_answer": "除此之外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们多练习，除此之外提高了水平。", "explanation": "这里应该用〈从而〉。“除此之外”表示补充，不表示由前面的动作导致的结果，表示结果要用“从而”。"}, {"text": "他很努力，除此之外没有成功。", "explanation": "这里应该用〈但是〉。“除此之外”表示补充，不表示转折，表示与前文相反要用“但是”。"}, {"text": "我们努力了，除此之外成功了。", "explanation": "这里应该用〈结果〉。“除此之外”表示补充，不表示前面行为带来的结果，表示结果要用“结果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98619, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "除此之外", "is_correct": true, "explanation": "正确：“除此之外”表示在前面所说的之外还有别的，这里补充他聪明之外还很努力，语境相符。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表示让步，“聪明”与“努力”之间不存在需要让步的对立关系，句子说不通。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示不这样就会怎样，聪明与努力之间没有这种关系，句子说不通。"}, {"text": "不然", "is_correct": false, "explanation": "语义：“不然”表示假设不这样的后果，这里说他聪明不然也很努力，意思不通。"}], "explanations": {"除此之外": "正确：“除此之外”表示在前面所说的之外还有别的，这里补充他聪明之外还很努力，语境相符。", "尽管": "语义：“尽管”表示让步，“聪明”与“努力”之间不存在需要让步的对立关系，句子说不通。", "否则": "语义：“否则”表示不这样就会怎样，聪明与努力之间没有这种关系，句子说不通。", "不然": "语义：“不然”表示假设不这样的后果，这里说他聪明不然也很努力，意思不通。"}, "sentence_index": 6, "correct_answer": "除此之外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "因为下大雨，除此之外比赛取消了。", "explanation": "这里应该用〈所以〉。“除此之外”表示补充，不表示因果，“因为”后面要用“所以”引出结果。"}, {"text": "他看见了我，除此之外走过来。", "explanation": "这里应该用〈于是〉。“除此之外”表示补充，不表示接续的动作，前后动作衔接要用“于是”。"}, {"text": "我们准备了很久，除此之外下雨了。", "explanation": "这里应该用〈却〉。“除此之外”表示补充，不表示与前文相反的情况，表示出乎意料要用“却”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98619, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他会弹钢琴，除此之外以外还会拉小提琴。", "corrected_sentence": "他会弹钢琴，除此之外还会拉小提琴。", "error_description": "错误：在“除此之外”后面又加了“以外”，形式重复。“除此之外”本身已表示“在……之外”，应去掉“以外”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98619, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在北京住了一周，除了此之外还去了上海。", "corrected_sentence": "我们在北京住了一周，除此之外还去了上海。", "error_description": "错误：在固定说法“除此之外”中间多加了“了”，写成“除了此之外”。“除此之外”是固定结构，不能拆开，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
