INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98622, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "党政军机关中职位较高的领导人。", "primary_collocate": null, "pronunciation": "shǒu zhǎng", "ipa": "ʂoʊ̯˨˩˦ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "首长们正在会议室里开会。", "target_word": "首长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机关里的首长每天都很忙。", "target_word": "首长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位首长曾经在北京工作过。", "target_word": "首长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首长要求大家按时完成工作。", "target_word": "首长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有首长来检查，办公室打扫得很干净。", "target_word": "首长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位受人尊敬的首长。", "target_word": "首长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首长的秘书把文件放在桌子上。", "target_word": "首长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，首长还在看材料。", "target_word": "首长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老首长退休以后住在小城里。", "target_word": "首长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首长在大会上讲了话。", "target_word": "首长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "首长们", "label": "复数"}], "register": "中性", "sense_fingerprint": "党政军机关中职位较高的领导人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a70e542a-3e78-41c2-b2e4-2d7a51a2477b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98622, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "首长", "is_correct": true, "explanation": "正确：首长，党政军机关中职位较高的领导人。"}, {"text": "首场", "is_correct": false, "explanation": "zh 与 ch 的声母不同，意思是“第一场（比赛或演出）”。"}, {"text": "手杖", "is_correct": false, "explanation": "zhàng（第四声）与 zhǎng（第三声）声调不同，意思是“拐杖”。"}, {"text": "首张", "is_correct": false, "explanation": "zhāng（第一声）与 zhǎng（第三声）声调不同，意思是“第一张（如专辑）”。"}], "explanations": {"首长": "正确：首长，党政军机关中职位较高的领导人。", "首场": "zh 与 ch 的声母不同，意思是“第一场（比赛或演出）”。", "手杖": "zhàng（第四声）与 zhǎng（第三声）声调不同，意思是“拐杖”。", "首张": "zhāng（第一声）与 zhǎng（第三声）声调不同，意思是“第一张（如专辑）”。"}, "sentence_index": null, "correct_answer": "首长"}, "level_3": {"options": [{"text": "首长", "is_correct": true, "explanation": "正确：“首长们正在会议室里开会”，指党政机关的领导人开会。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不会在会议室里开会，与句中的“开会”不合。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不会开会，与“开会”的主语不合。"}, {"text": "小鸟", "is_correct": false, "explanation": "语义：小鸟不会在会议室里开会。"}], "explanations": {"首长": "正确：“首长们正在会议室里开会”，指党政机关的领导人开会。", "猫": "语义：猫不会在会议室里开会，与句中的“开会”不合。", "窗帘": "语义：窗帘不会开会，与“开会”的主语不合。", "小鸟": "语义：小鸟不会在会议室里开会。"}, "sentence_index": 0, "correct_answer": "首长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "首长在树上唱歌。", "explanation": "这里应该用〈小鸟〉。首长指党政军机关中职位较高的领导人，树上唱歌的是小鸟，不能用“首长”。"}, {"text": "首长在路边要饭。", "explanation": "这里应该用〈乞丐〉。首长指党政军机关中职位较高的领导人，路边要饭的人要说“乞丐”。"}, {"text": "首长在菜地里种白菜。", "explanation": "这里应该用〈农民〉。首长指党政军机关中职位较高的领导人，种白菜的人要说“农民”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首长", "is_correct": true, "explanation": "正确：“首长的秘书把文件放在桌子上”，指领导的秘书。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子没有秘书，“椅子的秘书”不成立。"}, {"text": "花", "is_correct": false, "explanation": "语义：花没有秘书，“花的秘书”不成立。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有秘书，“窗户的秘书”不成立。"}], "explanations": {"首长": "正确：“首长的秘书把文件放在桌子上”，指领导的秘书。", "椅子": "语义：椅子没有秘书，“椅子的秘书”不成立。", "花": "语义：花没有秘书，“花的秘书”不成立。", "窗户": "语义：窗户没有秘书，“窗户的秘书”不成立。"}, "sentence_index": 6, "correct_answer": "首长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "首长在院子里叫。", "explanation": "这里应该用〈小狗〉。首长指职位较高的领导人，院子里叫的是小狗，不能用“首长”。"}, {"text": "首长在河边滚来滚去。", "explanation": "这里应该用〈石头〉。首长指党政军机关中职位较高的领导人，河边滚来滚去的是石头，不能用“首长”。"}, {"text": "首长在锅里煮着。", "explanation": "这里应该用〈饺子〉。首长指党政军机关中职位较高的领导人，锅里煮着的是饺子，不能用“首长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议室里坐着两首长。", "corrected_sentence": "会议室里坐着两位首长。", "error_description": "缺少量词：数词后面的“首长”需要量词“位”。错误形式：两首长；正确形式：两位首长。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一首长在大会上发了言。", "corrected_sentence": "一位首长在大会上发了言。", "error_description": "缺少量词：数词“一”后面要加量词“位”。错误形式：一首长；正确形式：一位首长。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
