INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98623, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "香蕉是弯弯的黄色水果，剥开皮就可以吃。", "primary_collocate": null, "pronunciation": "xiāng jiāo", "ipa": "ɕiɑŋ˥ tɕjɑʊ˥", "syllable_count": 2, "sentences": [{"text": "香蕉的皮是黄色的。", "target_word": "香蕉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先剥开皮，再吃香蕉。", "target_word": "香蕉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子最爱吃香蕉。", "target_word": "香蕉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早饭吃了一根香蕉。", "target_word": "香蕉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这串香蕉弯弯的，很好看。", "target_word": "香蕉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香蕉熟透了，又软又甜。", "target_word": "香蕉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢香蕉，不喜欢苹果。", "target_word": "香蕉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在超市买了三斤香蕉。", "target_word": "香蕉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一把香蕉。", "target_word": "香蕉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根香蕉已经黄了，可以吃了。", "target_word": "香蕉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一根香蕉", "label": "量词"}, {"form": "一串香蕉", "label": "量词"}, {"form": "一把香蕉", "label": "量词"}], "register": "中性", "sense_fingerprint": "弯弯的黄色水果，剥皮即食", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caeccb10-6a79-4d7a-87ac-7a371c930c18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98623, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "香蕉", "is_correct": true, "explanation": "正确答案：香蕉是弯弯的黄色水果。"}, {"text": "橡胶", "is_correct": false, "explanation": "xiàng（第四声）与 xiāng（第一声）声调不同，橡胶是一种有弹性的材料，与香蕉意思不同。"}, {"text": "香煎", "is_correct": false, "explanation": "jiān 与 jiāo 韵母不同，香煎指煎至焦香的烹饪方式，与香蕉意思不同。"}, {"text": "香肩", "is_correct": false, "explanation": "jiān 与 jiāo 韵母不同，香肩指女性的肩部，与香蕉意思不同。"}], "explanations": {"香蕉": "正确答案：香蕉是弯弯的黄色水果。", "橡胶": "xiàng（第四声）与 xiāng（第一声）声调不同，橡胶是一种有弹性的材料，与香蕉意思不同。", "香煎": "jiān 与 jiāo 韵母不同，香煎指煎至焦香的烹饪方式，与香蕉意思不同。", "香肩": "jiān 与 jiāo 韵母不同，香肩指女性的肩部，与香蕉意思不同。"}, "sentence_index": null, "correct_answer": "香蕉"}, "level_3": {"options": [{"text": "大海", "is_correct": false, "explanation": "搭配：“皮”是物体的外层，大海没有可以剥开的皮，不与“皮”搭配。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是水果，没有可以剥开的皮。"}, {"text": "香蕉", "is_correct": true, "explanation": "香蕉是弯弯的黄色水果，有可以剥开的皮。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的，不能说它的皮是黄色的。"}], "explanations": {"大海": "搭配：“皮”是物体的外层，大海没有可以剥开的皮，不与“皮”搭配。", "月亮": "语义：月亮不是水果，没有可以剥开的皮。", "香蕉": "香蕉是弯弯的黄色水果，有可以剥开的皮。", "空气": "语义：空气是无形的，不能说它的皮是黄色的。"}, "sentence_index": 0, "correct_answer": "香蕉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早饭吃了一件香蕉。", "explanation": "这里应该用〈根〉，不能用〈件〉。〈件〉用于衣服、事情等，香蕉是长条形水果，应说“一根”。"}, {"text": "我早饭吃了一头香蕉。", "explanation": "这里应该用〈根〉，不能用〈头〉。〈头〉用于牛、羊等牲畜，香蕉不能这样计数。"}, {"text": "我早饭吃了一张香蕉。", "explanation": "这里应该用〈根〉，不能用〈张〉。〈张〉用于平面的东西，香蕉是长条形水果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考试", "is_correct": false, "explanation": "语义：“不喜欢苹果”说的是食物，考试不是可以吃的东西。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水不能吃，与苹果不构成食物之间的对比。"}, {"text": "香蕉", "is_correct": true, "explanation": "香蕉是孩子能吃的水果，与“不喜欢苹果”构成对比。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：后半句拿“苹果”作比较，前面应是食物；黑板不能吃，不构成对比。"}], "explanations": {"考试": "语义：“不喜欢苹果”说的是食物，考试不是可以吃的东西。", "墨水": "语义：墨水不能吃，与苹果不构成食物之间的对比。", "香蕉": "香蕉是孩子能吃的水果，与“不喜欢苹果”构成对比。", "黑板": "语义：后半句拿“苹果”作比较，前面应是食物；黑板不能吃，不构成对比。"}, "sentence_index": 6, "correct_answer": "香蕉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆香蕉已经黄了，可以吃了。", "explanation": "这里应该用〈根〉，不能用〈辆〉。〈辆〉用于车，香蕉不是车。"}, {"text": "这本香蕉已经黄了，可以吃了。", "explanation": "这里应该用〈根〉，不能用〈本〉。〈本〉用于书册，香蕉不能用本计数。"}, {"text": "这座香蕉已经黄了，可以吃了。", "explanation": "这里应该用〈根〉，不能用〈座〉。〈座〉用于山、桥、楼等大型固定物，不能用来计数香蕉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我早上吃了一件香蕉。", "corrected_sentence": "我早上吃了一根香蕉。", "error_description": "量词错误：“件”用于衣服、事情等，香蕉应用“根”，应说“一根香蕉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了三张香蕉。", "corrected_sentence": "我买了三根香蕉。", "error_description": "量词错误：“张”用于平面的东西，香蕉应用“根”，应说“三根香蕉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
