INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98625, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "点水是东西轻轻碰一下水面就起来。", "primary_collocate": null, "pronunciation": "diǎn shuǐ", "ipa": "tjɛn˨˩ ʂweɪ˨˩", "syllable_count": 2, "sentences": [{"text": "蜻蜓在水面上点水。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞过河面，点水后又飞走了。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "燕子低低地飞着，在湖上点水。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只水鸟点水一下，就飞起来了。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟从水面掠过，点水后又飞起来了。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他扔出的小石片在湖面上点水，一连跳了五下。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白鸟飞得很低，翅膀好像要点水。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜻蜓飞来，点水时水面起了小圈。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟点水，水面就起了圈。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，燕子飞过小河，轻轻点水。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "點水", "label": "繁体"}, {"form": "点过水", "label": "体标"}, {"form": "点了水", "label": "体标"}], "register": "中性", "sense_fingerprint": "鸟、虫等轻碰一下水面就飞起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caeccb10-6a79-4d7a-87ac-7a371c930c18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98625, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "点水", "is_correct": true, "explanation": "点水：东西轻轻碰一下水面就起来。"}, {"text": "点缀", "is_correct": false, "explanation": "点缀（diǎnzhuì）与点水第二个音节声母不同（zh 与 sh），声调也不同（第四声与第三声），意思是装饰。"}, {"text": "点数", "is_correct": false, "explanation": "点数（diǎnshù）与点水第二个音节韵母不同（u 与 uei），声调也不同，意思是逐个计算数目。"}, {"text": "甜水", "is_correct": false, "explanation": "甜水（tiánshuǐ）与点水第一个音节声母不同（t 与 d），声调也不同（第二声与第三声），意思是甜的水。"}], "explanations": {"点水": "点水：东西轻轻碰一下水面就起来。", "点缀": "点缀（diǎnzhuì）与点水第二个音节声母不同（zh 与 sh），声调也不同（第四声与第三声），意思是装饰。", "点数": "点数（diǎnshù）与点水第二个音节韵母不同（u 与 uei），声调也不同，意思是逐个计算数目。", "甜水": "甜水（tiánshuǐ）与点水第一个音节声母不同（t 与 d），声调也不同（第二声与第三声），意思是甜的水。"}, "sentence_index": null, "correct_answer": "点水"}, "level_3": {"options": [{"text": "点水", "is_correct": true, "explanation": "点水指轻轻碰一下水面，与蜻蜓在水面上的动作相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：蜻蜓是飞行的昆虫，不会游泳，与“在水面上”的飞行动作相矛盾。"}, {"text": "划船", "is_correct": false, "explanation": "语义：划船需要人操作船桨，蜻蜓无法划船，句意不成立。"}, {"text": "打鱼", "is_correct": false, "explanation": "搭配：“打鱼”的主语须是人，不能说蜻蜓打鱼。"}], "explanations": {"点水": "点水指轻轻碰一下水面，与蜻蜓在水面上的动作相符。", "游泳": "语义：蜻蜓是飞行的昆虫，不会游泳，与“在水面上”的飞行动作相矛盾。", "划船": "语义：划船需要人操作船桨，蜻蜓无法划船，句意不成立。", "打鱼": "搭配：“打鱼”的主语须是人，不能说蜻蜓打鱼。"}, "sentence_index": 0, "correct_answer": "点水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力点水，水花溅得满身都是。", "explanation": "这个词不这么用：这里的意思是“用力拍打”，应是〈拍〉；点水只是轻轻碰一下水面，不能用“用力”修饰。"}, {"text": "老师拿起粉笔，在黑板上点水，写出一行字。", "explanation": "这个词不这么用：这里应是〈写〉的意思，点水只能用于水面，不能用于黑板。"}, {"text": "燕子点水后，整个身子钻进水底，很久才浮上来。", "explanation": "这个词不这么用：这里描述的是“潜入水中”，应是〈潜〉；点水是轻碰水面后立即离开，不会钻进水底。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98625, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点水", "is_correct": true, "explanation": "“点水”指轻碰水面，符合翅膀几乎要触到水面的意思。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：翅膀不能唱歌，与“飞得很低”的动作不相关。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：翅膀不能吃饭，与句中描述的飞行动作冲突。"}, {"text": "洗澡", "is_correct": false, "explanation": "配价：“洗澡”的动作主体一般是人或动物整体，不能只让“翅膀”去洗澡。"}], "explanations": {"点水": "“点水”指轻碰水面，符合翅膀几乎要触到水面的意思。", "唱歌": "语义：翅膀不能唱歌，与“飞得很低”的动作不相关。", "吃饭": "语义：翅膀不能吃饭，与句中描述的飞行动作冲突。", "洗澡": "配价：“洗澡”的动作主体一般是人或动物整体，不能只让“翅膀”去洗澡。"}, "sentence_index": 6, "correct_answer": "点水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春天，燕子飞过小河，用嘴点水，在河面上留下了一个洞。", "explanation": "这个词不这么用：这里应是〈戳〉的意思，把水面戳出洞；点水只是轻碰水面，不会留下洞。"}, {"text": "春天，燕子飞过小河，在河底点水。", "explanation": "这个词不这么用：这里的意思是“潜入河底”，应是〈潜〉；点水只能发生在水面，不能在河底点水。"}, {"text": "春天，燕子飞过小河，在水面上点水，把河水搅得又浑又浊。", "explanation": "这个词不这么用：这里应是〈搅〉的意思，点水只是轻碰水面，不会把河水搅浑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98625, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蜻蜓点水一个，就飞走了。", "corrected_sentence": "蜻蜓点水一下，就飞走了。", "error_description": "量词错误：“点水”的动量词应用“下”，表示轻碰的次数，不能说“点水一个”，应说“点水一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98625, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸭子在水面上点水一个，就飞走了。", "corrected_sentence": "小鸭子在水面上点水一下，就飞走了。", "error_description": "量词错误：“点水”的动量词应用“下”，表示轻碰的次数，不能说“点水一个”，应说“点水一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
