INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98626, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "轻轻地接触水面。", "primary_collocate": null, "pronunciation": "diǎn shuǐ", "ipa": "tjɛn˨˩ ʂweɪ˨˩", "syllable_count": 2, "sentences": [{"text": "他用脚尖点水，试一试水冷不冷。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在河边，用手指点水玩。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻轻点水，水面起了一圈圈小波纹。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水鸟飞得很低，翅膀偶尔点水。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在池边，脚尖轻轻点水。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员的脚点水一下，就跳了起来。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸭子在水面上点水，一下就飞走了。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，海鸥低飞，不时点水。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会游泳，只敢在浅水边点水。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩伸出脚，在河边点水玩。", "target_word": "点水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "點水", "label": "繁体"}, {"form": "点过水", "label": "体标"}, {"form": "点了水", "label": "体标"}], "register": "中性", "sense_fingerprint": "轻轻地接触水面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caeccb10-6a79-4d7a-87ac-7a371c930c18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98626, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "点水", "is_correct": true, "explanation": "点水：轻轻地接触水面。"}, {"text": "点缀", "is_correct": false, "explanation": "点缀（diǎnzhuì）与点水第二个音节声母不同（zh 与 sh），声调也不同（第四声与第三声），意思是装饰。"}, {"text": "点数", "is_correct": false, "explanation": "点数（diǎnshù）与点水第二个音节韵母不同（u 与 uei），声调也不同，意思是逐个计算数目。"}, {"text": "甜水", "is_correct": false, "explanation": "甜水（tiánshuǐ）与点水第一个音节声母不同（t 与 d），声调也不同（第二声与第三声），意思是甜的水。"}], "explanations": {"点水": "点水：轻轻地接触水面。", "点缀": "点缀（diǎnzhuì）与点水第二个音节声母不同（zh 与 sh），声调也不同（第四声与第三声），意思是装饰。", "点数": "点数（diǎnshù）与点水第二个音节韵母不同（u 与 uei），声调也不同，意思是逐个计算数目。", "甜水": "甜水（tiánshuǐ）与点水第一个音节声母不同（t 与 d），声调也不同（第二声与第三声），意思是甜的水。"}, "sentence_index": null, "correct_answer": "点水"}, "level_3": {"options": [{"text": "点水", "is_correct": true, "explanation": "“点水”指用脚尖轻轻接触水面，符合句意。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：用脚尖不能唱歌，与“试一试水冷不冷”的动作不相符。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：用脚尖吃饭不合常理，与“试水”的语境不符。"}, {"text": "洗澡", "is_correct": false, "explanation": "配价：“洗澡”的动作主体是整个人，不能用“脚尖”作工具。"}], "explanations": {"点水": "“点水”指用脚尖轻轻接触水面，符合句意。", "唱歌": "语义：用脚尖不能唱歌，与“试一试水冷不冷”的动作不相符。", "吃饭": "语义：用脚尖吃饭不合常理，与“试水”的语境不符。", "洗澡": "配价：“洗澡”的动作主体是整个人，不能用“脚尖”作工具。"}, "sentence_index": 0, "correct_answer": "点水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力点水，水花溅得满身都是。", "explanation": "这个词不这么用：这里的意思是“用力拍打”，应是〈拍〉；点水是轻轻接触水面，不能用“用力”修饰。"}, {"text": "孩子们站在河边，用棍子点水，在湖面上弄出了很多洞。", "explanation": "这个词不这么用：这里应是〈戳〉的意思，把湖面戳出洞；点水是轻轻接触水面，不会在湖面上弄出洞。"}, {"text": "他点水后，整个身子钻进水底，很久才浮上来。", "explanation": "这个词不这么用：这里描述的是“潜入水中”，应是〈潜〉；点水是轻碰水面后立即离开，不会钻进水底。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点水", "is_correct": true, "explanation": "“点水”指轻碰水面，与“一下就飞走”相符。"}, {"text": "打鱼", "is_correct": false, "explanation": "搭配：“打鱼”的主语须是人，不能说小鸭子打鱼。"}, {"text": "洗衣服", "is_correct": false, "explanation": "搭配：“洗衣服”的主语和对象都与小鸭子不搭，不能这样说。"}, {"text": "划船", "is_correct": false, "explanation": "语义：小鸭子不会划船，与“在水面上”的动作矛盾。"}], "explanations": {"点水": "“点水”指轻碰水面，与“一下就飞走”相符。", "打鱼": "搭配：“打鱼”的主语须是人，不能说小鸭子打鱼。", "洗衣服": "搭配：“洗衣服”的主语和对象都与小鸭子不搭，不能这样说。", "划船": "语义：小鸭子不会划船，与“在水面上”的动作矛盾。"}, "sentence_index": 6, "correct_answer": "点水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小女孩伸出脚，在河底点水玩。", "explanation": "这个词不这么用：这里的意思是“潜入河底”，应是〈潜〉；点水只能发生在水面，不能在河底点水玩。"}, {"text": "小女孩伸出脚，连续狠狠地点水，把水溅到了岸上。", "explanation": "这个词不这么用：这里应是〈拍〉的意思，点水是轻轻接触水面，不能狠狠地拍打。"}, {"text": "小女孩伸出脚，用它点水，很快把水桶装满了。", "explanation": "这个词不这么用：这里应是〈舀〉的意思，点水只是轻碰水面，不能把水桶装满。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
