INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98629, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一律是全都一样，没有例外。", "primary_collocate": null, "pronunciation": "yí lǜ", "ipa": "i˧˥ ly˥˩", "syllable_count": 2, "sentences": [{"text": "这里的房间一律朝南。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班的同学一律住校。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买的衣服一律是红色的。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的玩具一律放在柜子里。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的菜一律不放辣椒。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，作业一律明天交。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的小狗一律要拴着绳子。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的饮料一律十元一瓶。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家注意，客人的鞋一律放在门口。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天去的人一律没有带伞。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：说明一类人或事物全都是同一种情况，没有例外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc1bb5e-b14c-41de-8ff0-76ccf8bb8da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98629, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一律", "is_correct": true, "explanation": "“一律”表示全部都是同一种情况，与“这里的房间”的整体性呼应。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”说明事件的频率，不能用来描述房间的朝向这种固定状态。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”表示任意、不固定，与“一律朝南”的统一状态相反。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与房间朝向这种固定状态不合。"}], "explanations": {"一律": "“一律”表示全部都是同一种情况，与“这里的房间”的整体性呼应。", "偶尔": "搭配：“偶尔”说明事件的频率，不能用来描述房间的朝向这种固定状态。", "随便": "语义：“随便”表示任意、不固定，与“一律朝南”的统一状态相反。", "忽然": "语义：“忽然”表示突然发生，与房间朝向这种固定状态不合。"}, "sentence_index": 0, "correct_answer": "一律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套房子一律有三个卧室。", "explanation": "这里应该用〈一共〉。一律强调全部情况一致，不用来统计数量，统计数量要用“一共”。"}, {"text": "我妹妹一律在画画。", "explanation": "这里应该用〈一直〉。一律需要多个对象或情况相同，不能描述单个人持续做某事。"}, {"text": "妈妈一律睡了。", "explanation": "这里应该用〈已经〉。一律指多个对象或情况统一，不能描述某一个人已经完成的状态，表示已经发生要用“已经”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98629, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一律", "is_correct": true, "explanation": "“一律”表示没有例外，与“公园里的小狗”的统一要求呼应。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来不，与“要拴着绳子”的统一要求相反。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，与“一律要拴着绳子”所表达的长期统一规定不合。"}, {"text": "悄悄", "is_correct": false, "explanation": "语义：“悄悄”表示暗中进行，与公园里要拴绳的公开规定不合。"}], "explanations": {"一律": "“一律”表示没有例外，与“公园里的小狗”的统一要求呼应。", "从不": "语义：“从不”表示从来不，与“要拴着绳子”的统一要求相反。", "突然": "语义：“突然”表示事情忽然发生，与“一律要拴着绳子”所表达的长期统一规定不合。", "悄悄": "语义：“悄悄”表示暗中进行，与公园里要拴绳的公开规定不合。"}, "sentence_index": 6, "correct_answer": "一律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书一律很有意思。", "explanation": "这里应该用〈真〉。一律要求多个对象全都一样、没有例外，只说一本书时不能用“一律”。"}, {"text": "我一律忘带伞。", "explanation": "这里应该用〈经常〉。一律强调全部情况统一、没有例外，不能用来描述某一个人反复发生的事，表示经常要用“经常”。"}, {"text": "一律有三个人带了伞。", "explanation": "这里应该用〈只〉。一律强调全部一致，不能限定只有几个人的情况，限定范围要用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间教室里的座位很一律朝前。", "corrected_sentence": "这间教室里的座位一律朝前。", "error_description": "“一律”是副词，表示没有例外，不能被程度副词“很”修饰。应删去“很”，写作“一律朝前”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一律要寄存包裹。", "corrected_sentence": "我要寄存包裹。", "error_description": "“一律”指多个对象全都相同、没有例外，不能用于单独一人“我”；应删去“一律”，写作“我要寄存包裹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
