INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98630, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "全部一样，没有例外。", "primary_collocate": null, "pronunciation": "yí lǜ", "ipa": "i˧˥ ly˥˩", "syllable_count": 2, "sentences": [{"text": "学校规定，所有学生一律穿校服。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的东西一律五块钱。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天早上八点上课，迟到的人一律不能进教室。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议期间，手机一律关机。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的水果一律半价。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里一律不许大声说话。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管是谁，进门前一律要洗手。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，作文一律用黑笔写。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的新员工一律先学一个月。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了十点，客人一律不能再进来。", "target_word": "一律", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：表示范围内全部一样，没有例外，常用在规定、通知里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc1bb5e-b14c-41de-8ff0-76ccf8bb8da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一律", "is_correct": true, "explanation": "“一律”表示全部一样、没有例外，与“所有学生”和“学校规定”相合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时候，与“所有学生”的全员要求相反。"}, {"text": "最好", "is_correct": false, "explanation": "语义：“最好”表示建议，与“学校规定”的强制语气冲突。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”表示任意、不加限制，与“学校规定”的统一要求相矛盾。"}], "explanations": {"一律": "“一律”表示全部一样、没有例外，与“所有学生”和“学校规定”相合。", "偶尔": "语义：“偶尔”表示有时候，与“所有学生”的全员要求相反。", "最好": "语义：“最好”表示建议，与“学校规定”的强制语气冲突。", "随便": "语义：“随便”表示任意、不加限制，与“学校规定”的统一要求相矛盾。"}, "sentence_index": 0, "correct_answer": "一律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班一律有四十个学生。", "explanation": "这里应该用〈一共〉。一律强调全部情况相同、没有例外，不用来统计总数，统计人数要用“一共”。"}, {"text": "我爸爸一律爱喝茶。", "explanation": "这里应该用〈一向〉。一律指多个对象或情况一致，不用来说明单个人的习惯，表示习惯要用“一向”。"}, {"text": "他一律跑出了教室。", "explanation": "这里应该用〈一下子〉。一律指多个对象或情况统一，不能描述某一个人瞬间完成的动作，应说“一下子跑出了教室”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一律", "is_correct": true, "explanation": "“一律”表示没有例外，与“不管是谁”的全员要求呼应。"}, {"text": "从不", "is_correct": false, "explanation": "搭配：“从不”表示从来没有，不能与表示要求的“要”搭配使用。"}, {"text": "有时", "is_correct": false, "explanation": "语义：“有时”表示偶尔，与“不管是谁”的全员要求相反。"}, {"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷”表示暗中进行，与“进门前要洗手”这种公开要求不合。"}], "explanations": {"一律": "“一律”表示没有例外，与“不管是谁”的全员要求呼应。", "从不": "搭配：“从不”表示从来没有，不能与表示要求的“要”搭配使用。", "有时": "语义：“有时”表示偶尔，与“不管是谁”的全员要求相反。", "偷偷": "语义：“偷偷”表示暗中进行，与“进门前要洗手”这种公开要求不合。"}, "sentence_index": 6, "correct_answer": "一律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的天气一律很好。", "explanation": "这里应该用〈非常〉。一律要求多个对象或情况全都一样，“今天的天气”只是一个情况，不能用“一律”。"}, {"text": "我一律去了医院。", "explanation": "这里应该用〈刚〉。一律指多个对象或情况统一，不能描述某一个人刚刚完成的动作，表示“刚刚”要用“刚”。"}, {"text": "一律有三个人没交作业。", "explanation": "这里应该用〈只〉。一律强调全部一致，不能用来限定只有几个人的情况，限定范围要用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "凡是参加比赛的队员，很一律要戴头盔。", "corrected_sentence": "凡是参加比赛的队员，一律要戴头盔。", "error_description": "修饰错误：副词“一律”不能被程度副词“很”修饰，应删去“很”，写作“凡是参加比赛的队员，一律要戴头盔。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来参观的客人很一律要登记。", "corrected_sentence": "来参观的客人一律要登记。", "error_description": "“一律”是副词，表示没有例外，不能被程度副词“很”修饰。应删去“很”，写作“一律要登记”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98635, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上班", "is_correct": true, "explanation": "“上班”与“下班”是反义词，指一天工作开始、到工作地点去。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”与“下班”没有反义关系，不是相对的动作。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”与“下班”没有反义关系，二者不构成相对的概念。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”与“下班”没有反义关系，不属于工作的对立行为。"}], "correct_answer": "上班", "explanations": {"上班": "“上班”与“下班”是反义词，指一天工作开始、到工作地点去。", "唱歌": "“唱歌”与“下班”没有反义关系，不是相对的动作。", "读书": "“读书”与“下班”没有反义关系，二者不构成相对的概念。", "游泳": "“游泳”与“下班”没有反义关系，不属于工作的对立行为。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98635, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上班", "is_correct": true, "explanation": "“上班”与“下班”是反义词，指一天工作开始、到工作地点去。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”与“下班”没有反义关系，不是相对的动作。"}, {"text": "做饭", "is_correct": false, "explanation": "“做饭”与“下班”没有反义关系，二者不构成相对的概念。"}, {"text": "打球", "is_correct": false, "explanation": "“打球”与“下班”没有反义关系，不属于工作的对立行为。"}], "correct_answer": "上班", "explanations": {"上班": "“上班”与“下班”是反义词，指一天工作开始、到工作地点去。", "写字": "“写字”与“下班”没有反义关系，不是相对的动作。", "做饭": "“做饭”与“下班”没有反义关系，二者不构成相对的概念。", "打球": "“打球”与“下班”没有反义关系，不属于工作的对立行为。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98635, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "下班是一天的工作做完了，离开上班的地方。", "primary_collocate": null, "pronunciation": "xià bān", "ipa": "ɕja˥˩ pan˥", "syllable_count": 2, "sentences": [{"text": "下班的时间到了，大家都走了。", "target_word": "下班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天不用加班，可以早点下班。", "target_word": "下班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸下班回来，手里拿着一些水果。", "target_word": "下班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她下班后常常去公园走路。", "target_word": "下班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司五点半下班。", "target_word": "下班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班路上我遇到了老同学。", "target_word": "下班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你下班了吗？", "target_word": "下班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下班以后还在学英语。", "target_word": "下班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说今天大家可以提前下班。", "target_word": "下班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我下班回家，孩子已经睡着了。", "target_word": "下班", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下了班", "label": "体标"}, {"form": "下过班", "label": "体标"}, {"form": "上下班", "label": "复合"}], "register": "通用", "sense_fingerprint": "做完当天工作后离开上班地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '389b43bd-a0c5-4cce-afd4-0cb183a97713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98635, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下班", "is_correct": true, "explanation": "“下班”指一天工作做完离开，与“时间到了，大家都走了”相符。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”指水变成冰，与“大家都走了”无关。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”指植物长出芽，与人离开无关。"}, {"text": "加班", "is_correct": false, "explanation": "语义：“加班”是继续工作，与“大家都走了”的离开义矛盾。"}], "explanations": {"下班": "“下班”指一天工作做完离开，与“时间到了，大家都走了”相符。", "结冰": "语义：“结冰”指水变成冰，与“大家都走了”无关。", "发芽": "语义：“发芽”指植物长出芽，与人离开无关。", "加班": "语义：“加班”是继续工作，与“大家都走了”的离开义矛盾。"}, "sentence_index": 0, "correct_answer": "下班"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的数学课提前十分钟下班。", "explanation": "这里应该用〈下课〉。“下班”指工作结束，课程结束应用“下课”。"}, {"text": "我女儿每天四点下班。", "explanation": "这里应该用〈放学〉。“下班”用于上班的人，学生学习结束应用“放学”。"}, {"text": "电影结束后观众陆续下班。", "explanation": "这里应该用〈散场〉。“下班”指工作结束，观众离场应用“散场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98635, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下班", "is_correct": true, "explanation": "“下班”用于询问对方工作是否结束，与“你……了吗”搭配自然。"}, {"text": "椅子", "is_correct": false, "explanation": "词性：“椅子”是名词，不能放在“你……了吗”里当动作。"}, {"text": "铅笔", "is_correct": false, "explanation": "词性：“铅笔”是名词，不能说“你铅笔了吗”。"}, {"text": "去世", "is_correct": false, "explanation": "语义：“去世”指人死亡，问活着的对方是否去世不合逻辑。"}], "explanations": {"下班": "“下班”用于询问对方工作是否结束，与“你……了吗”搭配自然。", "椅子": "词性：“椅子”是名词，不能放在“你……了吗”里当动作。", "铅笔": "词性：“铅笔”是名词，不能说“你铅笔了吗”。", "去世": "语义：“去世”指人死亡，问活着的对方是否去世不合逻辑。"}, "sentence_index": 6, "correct_answer": "下班"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的小狗每天傍晚六点下班，然后去散步。", "explanation": "这里应该用〈回窝〉。“下班”指人结束工作离开单位，小狗没有工作单位，应说“回窝”。"}, {"text": "这台洗衣机每天晚上十点下班。", "explanation": "这里应该用〈停机〉。“下班”指人结束工作离开单位，洗衣机不上班，这里应说“停机”。"}, {"text": "这朵花每天下午五点下班。", "explanation": "这里应该用〈闭合〉。“下班”指人结束工作离开单位，花没有工作，傍晚花朵闭合，应说“闭合”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98635, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下班着回家吃饭。", "corrected_sentence": "他下班以后回家吃饭。", "error_description": "“着”不能直接放在“下班”后面表示这里的动作，应说“他下班以后回家吃饭”，把“着”换成“以后”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98635, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我下班过，知道很累。", "corrected_sentence": "我下过班，知道很累。", "error_description": "“过”要放在离合词“下班”的中间，应说“下过班”，不能说“下班过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
