INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98639, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不时是隔一会儿就有一次。", "primary_collocate": null, "pronunciation": "bù shí", "ipa": "pu˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "他一边开车，一边不时看地图。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里不时传来孩子们的笑声。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不时抬头看看窗外的雨。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲课时，同学们不时点头。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在房间里写作业，妈妈不时过去看看。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路上不时有汽车开过。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电话里不时咳嗽几声。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边不时有人走过来钓鱼。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋外不时传来狗叫声。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在等车，不时看一下时间。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不时|副词|隔一会儿就有一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90645a6b-93e3-4121-8054-48deb9684cb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98639, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不时", "is_correct": true, "explanation": "正确答案“不时”，读作 bù shí，意思是隔一会儿就有一次。"}, {"text": "不是", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是“不是”，表示否定判断。"}, {"text": "不迟", "is_correct": false, "explanation": "chí 与 shí 声母不同（ch 与 sh），意思是“不迟”，指不迟到。"}, {"text": "不施", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是不施加、不使用，多见于书面。"}], "explanations": {"不时": "正确答案“不时”，读作 bù shí，意思是隔一会儿就有一次。", "不是": "shì（第四声）与 shí（第二声）声调不同，意思是“不是”，表示否定判断。", "不迟": "chí 与 shí 声母不同（ch 与 sh），意思是“不迟”，指不迟到。", "不施": "shī（第一声）与 shí（第二声）声调不同，意思是不施加、不使用，多见于书面。"}, "sentence_index": null, "correct_answer": "不时"}, "level_3": {"options": [{"text": "不时", "is_correct": true, "explanation": "正确：“不时”表示隔一会儿就看一次，与开车时反复看地图的情境相合。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，与“一边……一边”所说的正在持续进行的动作不符。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”指突然发生的一次动作，与“一边开车，一边”的持续状态矛盾。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示动作刚刚发生，与“一边……一边”的同时进行不合。"}], "explanations": {"不时": "正确：“不时”表示隔一会儿就看一次，与开车时反复看地图的情境相合。", "已经": "体貌：“已经”表示动作已经完成，与“一边……一边”所说的正在持续进行的动作不符。", "忽然": "语义：“忽然”指突然发生的一次动作，与“一边开车，一边”的持续状态矛盾。", "刚刚": "语义：“刚刚”表示动作刚刚发生，与“一边……一边”的同时进行不合。"}, "sentence_index": 0, "correct_answer": "不时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个周末不时去爬山。", "explanation": "这里应该用〈常常〉。“不时”指隔一段时间才出现一次，间隔不固定，不能用来描述“每个周末”这种固定周期。"}, {"text": "他不时去了一趟北京。", "explanation": "这里应该用〈专程〉。“不时”指隔一段时间反复出现，“去了一趟北京”是一次性的行动，应说专程。"}, {"text": "我每天早上不时跑步。", "explanation": "这里应该用〈总是〉。“不时”表示间隔不定地出现，与“每天早上”这种每日固定的安排矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98639, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不时", "is_correct": true, "explanation": "正确答案“不时”，读作 bù shí，意思是隔一会儿就有一次。"}, {"text": "不适", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是身体或感觉不舒服。"}, {"text": "不使", "is_correct": false, "explanation": "shǐ（第三声）与 shí（第二声）声调不同，意思是不让、不致使，多用于书面。"}, {"text": "不失", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是不丢失、不失去。"}], "explanations": {"不时": "正确答案“不时”，读作 bù shí，意思是隔一会儿就有一次。", "不适": "shì（第四声）与 shí（第二声）声调不同，意思是身体或感觉不舒服。", "不使": "shǐ（第三声）与 shí（第二声）声调不同，意思是不让、不致使，多用于书面。", "不失": "shī（第一声）与 shí（第二声）声调不同，意思是不丢失、不失去。"}, "sentence_index": null, "correct_answer": "不时"}, "level_3": {"options": [{"text": "不时", "is_correct": true, "explanation": "正确：“不时”表示隔一会儿就咳嗽一次，与打电话时断续咳嗽的情境相合。"}, {"text": "业已", "is_correct": false, "explanation": "语域：“业已”是书面语，放在这样的口语叙述中显得不协调。"}, {"text": "顿时", "is_correct": false, "explanation": "语义：“顿时”表示情况立刻发生突变，与“咳嗽几声”的断续动作不符。"}, {"text": "从来", "is_correct": false, "explanation": "语法：“从来”多与否定词连用，如“从来不”，不能直接修饰“咳嗽几声”这样的肯定动作。"}], "explanations": {"不时": "正确：“不时”表示隔一会儿就咳嗽一次，与打电话时断续咳嗽的情境相合。", "业已": "语域：“业已”是书面语，放在这样的口语叙述中显得不协调。", "顿时": "语义：“顿时”表示情况立刻发生突变，与“咳嗽几声”的断续动作不符。", "从来": "语法：“从来”多与否定词连用，如“从来不”，不能直接修饰“咳嗽几声”这样的肯定动作。"}, "sentence_index": 6, "correct_answer": "不时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "太阳不时东升西落。", "explanation": "这里应该用〈每天〉。东升西落是固定的规律，“不时”表示间隔不定地出现，不能用来说明它。"}, {"text": "这个孩子不时长大了。", "explanation": "这里应该用〈渐渐〉。“不时”指隔一会儿反复出现一次，长大是持续渐进的变化，不能用“不时”。"}, {"text": "我不时考过了一次驾照。", "explanation": "这里应该用〈终于〉。“不时”指反复出现，“考过了一次驾照”是一次性的结果，不能用“不时”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一边看书，一边的不时抬头。", "corrected_sentence": "她一边看书，一边不时抬头。", "error_description": "错误：“一边”后不能加“的”。“不时”作状语直接修饰“抬头”，应说“一边不时抬头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "表演期间，观众不时了鼓掌。", "corrected_sentence": "表演期间，观众不时鼓掌。", "error_description": "错误：“了”插在“不时”和动词之间。“不时”是副词，后面直接接动词，应说“不时鼓掌”，不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
