INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98640, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "时常；每隔一段时间就发生一次。", "primary_collocate": null, "pronunciation": "bù shí", "ipa": "pu˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "我和老朋友不时见面，一起吃饭。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然搬走了，但还不时给我打电话。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷不时讲起年轻时的故事。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司不时开会，讨论新的计划。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她住在国外，不时寄一些照片回来。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市不时下雨，出门要带伞。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不时去图书馆借几本书。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不时给我们发一些学习材料。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大后，还不时回来看看爸妈。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气好的时候，我不时去公园跑步。", "target_word": "不时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不时|副词|时常；每隔一段时间就发生一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90645a6b-93e3-4121-8054-48deb9684cb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98640, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不时", "is_correct": true, "explanation": "正确答案“不时”，读作 bù shí，意思是时常，或每隔一段时间就发生一次。"}, {"text": "不是", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是“不是”，表示否定判断。"}, {"text": "不迟", "is_correct": false, "explanation": "chí 与 shí 声母不同（ch 与 sh），意思是“不迟”，指不迟到。"}, {"text": "补时", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是比赛中补足损失的时间。"}], "explanations": {"不时": "正确答案“不时”，读作 bù shí，意思是时常，或每隔一段时间就发生一次。", "不是": "shì（第四声）与 shí（第二声）声调不同，意思是“不是”，表示否定判断。", "不迟": "chí 与 shí 声母不同（ch 与 sh），意思是“不迟”，指不迟到。", "补时": "bǔ（第三声）与 bù（第四声）声调不同，意思是比赛中补足损失的时间。"}, "sentence_index": null, "correct_answer": "不时"}, "level_3": {"options": [{"text": "不时", "is_correct": true, "explanation": "正确：“不时”表示时常见面，与“老朋友时常聚会、一起吃饭”的情境相合。"}, {"text": "分别", "is_correct": false, "explanation": "语义：“分别”表示各自、分开，与句中“一起吃饭”的一起相反。"}, {"text": "独自", "is_correct": false, "explanation": "搭配：“独自”只能用于单一施事，不能与“我和老朋友”这样的复数主语搭配。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“一起吃饭”所暗示的经常聚会相矛盾。"}], "explanations": {"不时": "正确：“不时”表示时常见面，与“老朋友时常聚会、一起吃饭”的情境相合。", "分别": "语义：“分别”表示各自、分开，与句中“一起吃饭”的一起相反。", "独自": "搭配：“独自”只能用于单一施事，不能与“我和老朋友”这样的复数主语搭配。", "从不": "语义：“从不”表示从来没有，与“一起吃饭”所暗示的经常聚会相矛盾。"}, "sentence_index": 0, "correct_answer": "不时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我上周不时去了一趟游泳馆。", "explanation": "这里应该用〈专程〉。“不时”指隔一段时间反复发生，“去了一趟游泳馆”是一次性的行动，应说专程。"}, {"text": "他上个月不时搬了家。", "explanation": "这里应该用〈突然〉。“不时”指隔一段时间反复发生，“上个月搬了家”是一次性的事件，不能用“不时”。"}, {"text": "他不时考过了驾照。", "explanation": "这里应该用〈终于〉。考过驾照是一次性的结果，“不时”指反复出现，不能修饰它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98640, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不时", "is_correct": true, "explanation": "正确答案“不时”，读作 bù shí，意思是时常，或每隔一段时间就发生一次。"}, {"text": "不适", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是身体或感觉不舒服。"}, {"text": "不使", "is_correct": false, "explanation": "shǐ（第三声）与 shí（第二声）声调不同，意思是不让、不致使，多用于书面。"}, {"text": "不失", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是不丢失、不失去。"}], "explanations": {"不时": "正确答案“不时”，读作 bù shí，意思是时常，或每隔一段时间就发生一次。", "不适": "shì（第四声）与 shí（第二声）声调不同，意思是身体或感觉不舒服。", "不使": "shǐ（第三声）与 shí（第二声）声调不同，意思是不让、不致使，多用于书面。", "不失": "shī（第一声）与 shí（第二声）声调不同，意思是不丢失、不失去。"}, "sentence_index": null, "correct_answer": "不时"}, "level_3": {"options": [{"text": "不时", "is_correct": true, "explanation": "正确：“不时”表示隔一段时间就去一次，与“去图书馆借书”的反复行为相合。"}, {"text": "业已", "is_correct": false, "explanation": "语域：“业已”是书面语，放在这样的口语叙述中显得生硬，不合语域。"}, {"text": "顿时", "is_correct": false, "explanation": "语义：“顿时”表示情况立刻发生突变，与平常去借书的叙述不符。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，修饰形容词或心理动词，不能直接修饰“去”。"}], "explanations": {"不时": "正确：“不时”表示隔一段时间就去一次，与“去图书馆借书”的反复行为相合。", "业已": "语域：“业已”是书面语，放在这样的口语叙述中显得生硬，不合语域。", "顿时": "语义：“顿时”表示情况立刻发生突变，与平常去借书的叙述不符。", "非常": "语法：“非常”是程度副词，修饰形容词或心理动词，不能直接修饰“去”。"}, "sentence_index": 6, "correct_answer": "不时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春天不时到来。", "explanation": "这里应该用〈每年〉。春天按季节固定到来，“不时”表示间隔不定地出现，不能用来说明固定的规律。"}, {"text": "他去年不时参加了一次比赛。", "explanation": "这里应该用〈特意〉。“不时”表示反复出现，“参加了一次比赛”是一次性的行为，应说特意去参加。"}, {"text": "他不时结束了那次长途旅行。", "explanation": "这里应该用〈最终〉。“不时”指反复出现，“结束了那次长途旅行”是一次性的结局，应说最终。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶不时了给我打电话问候。", "corrected_sentence": "奶奶不时给我打电话问候。", "error_description": "错误：“不时”后面不能加“了”。“不时”是副词，直接放在动词前，应说“奶奶不时给我打电话”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每到周末，我们从不时聚会。", "corrected_sentence": "每到周末，我们不时聚会。", "error_description": "错误：“不时”前不能加“从”。“从不”是另一个副词，表示从来没有，与“不时”不同。应说“我们不时聚会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98647, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清楚", "is_correct": true, "explanation": "正确：“清楚”是“不清楚”在“不明白”这一义项上的反义词，表示明白、了解。"}, {"text": "温和", "is_correct": false, "explanation": "与“不清楚”没有反义关系，“温和”形容性格或态度。"}, {"text": "聪明", "is_correct": false, "explanation": "与“不清楚”没有反义关系，“聪明”形容才智，不是这个义项的反义词。"}, {"text": "结实", "is_correct": false, "explanation": "与“不清楚”没有反义关系，“结实”形容物体坚固。"}], "correct_answer": "清楚", "explanations": {"清楚": "正确：“清楚”是“不清楚”在“不明白”这一义项上的反义词，表示明白、了解。", "温和": "与“不清楚”没有反义关系，“温和”形容性格或态度。", "聪明": "与“不清楚”没有反义关系，“聪明”形容才智，不是这个义项的反义词。", "结实": "与“不清楚”没有反义关系，“结实”形容物体坚固。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98647, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清楚", "is_correct": true, "explanation": "正确：“清楚”是“不清楚”在“不明白”这一义项上的反义词，表示明白、了解。"}, {"text": "明亮", "is_correct": false, "explanation": "与“不清楚”没有反义关系，“明亮”形容光线或颜色。"}, {"text": "干净", "is_correct": false, "explanation": "与“不清楚”没有反义关系，“干净”形容卫生状况。"}, {"text": "紧张", "is_correct": false, "explanation": "与“不清楚”没有反义关系，“紧张”形容心理状态。"}], "correct_answer": "清楚", "explanations": {"清楚": "正确：“清楚”是“不清楚”在“不明白”这一义项上的反义词，表示明白、了解。", "明亮": "与“不清楚”没有反义关系，“明亮”形容光线或颜色。", "干净": "与“不清楚”没有反义关系，“干净”形容卫生状况。", "紧张": "与“不清楚”没有反义关系，“紧张”形容心理状态。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98647, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对某事的情况、原因或做法不了解，想不明白。", "primary_collocate": null, "pronunciation": "bù qīngchu", "ipa": "pu˥˩ tɕʰɪŋ˥ tʂʰu", "syllable_count": 3, "sentences": [{"text": "这道题我不清楚怎么做。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为什么生气，我不清楚。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的意思我还是不清楚。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不清楚明天几点开会。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的原因，我们都不清楚。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不清楚的地方可以问我。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不清楚这个词怎么用。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到底想要什么，大家都不清楚。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站在哪儿，我不清楚。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不清楚他住在哪个城市。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "对事情的原因或做法不了解、不明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7155aefb-858f-446a-814e-20518e39b4af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98647, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不清楚", "is_correct": true, "explanation": "正确：“不清楚”表示看不明白、想不明白，“这道题我不清楚怎么做”符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌或事物好看，不能说“我漂亮怎么做”。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容身材，与“怎么做”搭配不通。"}, {"text": "明显", "is_correct": false, "explanation": "搭配：“明显”描述可见的情况，不能作“我”的状态谓语。"}], "explanations": {"不清楚": "正确：“不清楚”表示看不明白、想不明白，“这道题我不清楚怎么做”符合句意。", "漂亮": "语义：“漂亮”形容外貌或事物好看，不能说“我漂亮怎么做”。", "苗条": "体貌：“苗条”形容身材，与“怎么做”搭配不通。", "明显": "搭配：“明显”描述可见的情况，不能作“我”的状态谓语。"}, "sentence_index": 0, "correct_answer": "不清楚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你不清楚这个问题。", "explanation": "误用：“不清楚”是形容词，不能带宾语，不能说“不清楚这个问题”；这里应说“弄清楚这个问题”。"}, {"text": "这个杯子不清楚，你洗一下吧。", "explanation": "误用：“不清楚”指看不明白或不分明，不用来说东西脏；这里应说“这个杯子不干净，你洗一下吧”。"}, {"text": "这个房间很不清楚。", "explanation": "误用：“不清楚”不用来描述房间的整洁程度；这里应说“这个房间很脏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98647, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不清楚", "is_correct": true, "explanation": "正确：“不清楚”表示对事情不了解，“我不清楚这个词怎么用”符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或体积，不能说“我高大这个词怎么用”。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”形容年龄，与“这个词怎么用”不搭。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音，与“这个词怎么用”不搭。"}], "explanations": {"不清楚": "正确：“不清楚”表示对事情不了解，“我不清楚这个词怎么用”符合句意。", "高大": "体貌：“高大”形容身材或体积，不能说“我高大这个词怎么用”。", "年轻": "语义：“年轻”形容年龄，与“这个词怎么用”不搭。", "响亮": "语义：“响亮”形容声音，与“这个词怎么用”不搭。"}, "sentence_index": 6, "correct_answer": "不清楚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服很不清楚，快去洗吧。", "explanation": "误用：“不清楚”指看不明白或不分明，不用来说衣服脏；这里应说“这件衣服很脏，快去洗吧”。"}, {"text": "请你不清楚这件事。", "explanation": "误用：“不清楚”是形容词，不能当动词用，不能说“不清楚这件事”；这里应说“弄清楚这件事”。"}, {"text": "这个苹果很不清楚，别吃了。", "explanation": "误用：“不清楚”指不了解或不分明，不能用来说食物坏了；这里应说“这个苹果坏了，别吃了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98647, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他为什么没来上课，我不清楚过。", "corrected_sentence": "他为什么没来上课，我不清楚。", "error_description": "体标错误：“不清楚”是形容词性否定状态，后面不能加表示经历的“过”。应说“他为什么没来上课，我不清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98647, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不不清楚这个字怎么写。", "corrected_sentence": "我不清楚这个字怎么写。", "error_description": "否定词重复：“不清楚”本身已含否定，前面不能再加“不”，应说“我不清楚这个字怎么写”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98648, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清楚", "is_correct": true, "explanation": "正确：“清楚”是“不清楚”在“模糊不分明”这一义项上的反义词。"}, {"text": "高大", "is_correct": false, "explanation": "与“不清楚”没有反义关系，“高大”形容身材或体积。"}, {"text": "甜美", "is_correct": false, "explanation": "与“不清楚”没有反义关系，“甜美”形容声音或容貌。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“不清楚”没有反义关系，“漂亮”形容外貌或事物好看。"}], "correct_answer": "清楚", "explanations": {"清楚": "正确：“清楚”是“不清楚”在“模糊不分明”这一义项上的反义词。", "高大": "与“不清楚”没有反义关系，“高大”形容身材或体积。", "甜美": "与“不清楚”没有反义关系，“甜美”形容声音或容貌。", "漂亮": "与“不清楚”没有反义关系，“漂亮”形容外貌或事物好看。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98648, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清楚", "is_correct": true, "explanation": "正确：“清楚”是“不清楚”在“模糊不分明”这一义项上的反义词。"}, {"text": "温和", "is_correct": false, "explanation": "与“不清楚”没有反义关系，“温和”形容性格或态度。"}, {"text": "聪明", "is_correct": false, "explanation": "与“不清楚”没有反义关系，“聪明”形容才智。"}, {"text": "热情", "is_correct": false, "explanation": "与“不清楚”没有反义关系，“热情”形容待人的态度。"}], "correct_answer": "清楚", "explanations": {"清楚": "正确：“清楚”是“不清楚”在“模糊不分明”这一义项上的反义词。", "温和": "与“不清楚”没有反义关系，“温和”形容性格或态度。", "聪明": "与“不清楚”没有反义关系，“聪明”形容才智。", "热情": "与“不清楚”没有反义关系，“热情”形容待人的态度。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98648, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（看或听上）模糊，不分明。", "primary_collocate": null, "pronunciation": "bù qīngchu", "ipa": "pu˥˩ tɕʰɪŋ˥ tʂʰu", "syllable_count": 3, "sentences": [{"text": "这张照片拍得不清楚。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里他的声音不清楚。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑板上的字太小，看得不清楚。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雾很大，远处的山影不清楚。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字写得不清楚，我看不懂。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话不清楚，我没听明白。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路灯太暗，门牌号不清楚。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上的图片不清楚了。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里很黑，人脸不清楚。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张老照片的颜色已经不清楚了。", "target_word": "不清楚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物看起来或听起来模糊、不分明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7155aefb-858f-446a-814e-20518e39b4af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不清楚", "is_correct": true, "explanation": "正确：“不清楚”表示事物模糊不分明，“这张照片拍得不清楚”符合句意。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”形容心情，不能描述照片的效果。"}, {"text": "结实", "is_correct": false, "explanation": "体貌：“结实”形容身体或物体坚固，不用于描述照片。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”形容声音或环境，不能用于“拍得”。"}], "explanations": {"不清楚": "正确：“不清楚”表示事物模糊不分明，“这张照片拍得不清楚”符合句意。", "高兴": "语义：“高兴”形容心情，不能描述照片的效果。", "结实": "体貌：“结实”形容身体或物体坚固，不用于描述照片。", "安静": "搭配：“安静”形容声音或环境，不能用于“拍得”。"}, "sentence_index": 0, "correct_answer": "不清楚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件外套不清楚，要洗一下。", "explanation": "误用：“不清楚”指模糊、不分明，不用来说东西脏；这里应说“这件外套不干净，要洗一下”。"}, {"text": "这个书包很不清楚，快拿去洗洗。", "explanation": "误用：“不清楚”指模糊、不分明，不用来说书包脏；这里应说“这个书包很脏，快拿去洗洗”。"}, {"text": "这个碗很不清楚，快洗一下。", "explanation": "误用：“不清楚”指模糊、不分明，不用来说碗脏；这里应说“这个碗不干净，快洗一下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不清楚", "is_correct": true, "explanation": "正确：“不清楚”表示看不清，“路灯太暗，门牌号不清楚”符合句意。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”与前句“路灯太暗”矛盾，不能描述门牌号。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”形容卫生状况，不用于门牌号是否看得清。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能描述门牌号。"}], "explanations": {"不清楚": "正确：“不清楚”表示看不清，“路灯太暗，门牌号不清楚”符合句意。", "明亮": "语义：“明亮”与前句“路灯太暗”矛盾，不能描述门牌号。", "干净": "搭配：“干净”形容卫生状况，不用于门牌号是否看得清。", "响亮": "搭配：“响亮”形容声音，不能描述门牌号。"}, "sentence_index": 6, "correct_answer": "不清楚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双鞋很不清楚，你擦一下。", "explanation": "误用：“不清楚”指模糊、不分明，不用来说鞋脏；这里应说“这双鞋很脏，你擦一下”。"}, {"text": "这条裤子很不清楚，快去洗洗吧。", "explanation": "误用：“不清楚”指模糊、不分明，不用来说裤子脏；这里应说“这条裤子很脏，快去洗洗吧”。"}, {"text": "这张桌子不清楚，去洗一下。", "explanation": "误用：“不清楚”指模糊、不分明，不用来说桌子脏；这里应说“这张桌子不干净，去洗一下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个镜头拍地不清楚。", "corrected_sentence": "这个镜头拍得不清楚。", "error_description": "助词错误：“拍”后面的补语要用“得”，不能用“地”。应说“这个镜头拍得不清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路灯太暗，门牌号不清楚过。", "corrected_sentence": "路灯太暗，门牌号不清楚了。", "error_description": "时态助词错误：表示“变得模糊”的变化要用“了”，“过”表示经历过，不能接在形容词“不清楚”后面。应说“路灯太暗，门牌号不清楚了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
