INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98651, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "二便是身体排出的尿和大便。", "primary_collocate": null, "pronunciation": "èr biàn", "ipa": "ɚ˥˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "医生问病人二便是否正常。", "target_word": "二便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人生病后，二便都不太好。", "target_word": "二便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士每天记录病人的二便。", "target_word": "二便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子发烧了，二便也有变化。", "target_word": "二便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近二便正常，吃得也好。", "target_word": "二便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，要注意观察二便的颜色。", "target_word": "二便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人刚做完手术，二便不能自己控制。", "target_word": "二便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈帮奶奶清理二便。", "target_word": "二便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查二便可以知道身体有没有问题。", "target_word": "二便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝的二便正常，说明身体很健康。", "target_word": "二便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "身体排出的尿和大便（医疗护理语境）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1baa88c0-478f-4d07-801d-78f872fad5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98651, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "二便", "is_correct": true, "explanation": "正确：二便（èr biàn）指身体排出的尿和大便。"}, {"text": "耳边", "is_correct": false, "explanation": "ěr（第三声）与 èr（第四声）声调不同，biān（第一声）与 biàn（第四声）声调也不同，意思是耳朵旁边。"}, {"text": "二片", "is_correct": false, "explanation": "piàn 与 biàn 声母不同（p 与 b），意思是两片。"}, {"text": "二篇", "is_correct": false, "explanation": "piān 与 biàn 声母与声调都不同，意思是两篇（文章）。"}], "explanations": {"二便": "正确：二便（èr biàn）指身体排出的尿和大便。", "耳边": "ěr（第三声）与 èr（第四声）声调不同，biān（第一声）与 biàn（第四声）声调也不同，意思是耳朵旁边。", "二片": "piàn 与 biàn 声母不同（p 与 b），意思是两片。", "二篇": "piān 与 biàn 声母与声调都不同，意思是两篇（文章）。"}, "sentence_index": null, "correct_answer": "二便"}, "level_3": {"options": [{"text": "二便", "is_correct": true, "explanation": "正确：二便指尿和大便，医生询问病人的排泄情况是否正常，符合语境。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：发型属于外在形象，不是医生询问是否正常的身体功能。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不属于病人的身体状况，“病人的天气是否正常”讲不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是病人的身体状况，医生不会询问作业是否正常。"}], "explanations": {"二便": "正确：二便指尿和大便，医生询问病人的排泄情况是否正常，符合语境。", "发型": "体貌：发型属于外在形象，不是医生询问是否正常的身体功能。", "天气": "语义：天气不属于病人的身体状况，“病人的天气是否正常”讲不通。", "作业": "语义：作业不是病人的身体状况，医生不会询问作业是否正常。"}, "sentence_index": 0, "correct_answer": "二便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士每天给病人记录一支二便。", "explanation": "这里应该用〈次〉。二便按排便次数计量，“支”只用于笔、杆等细长物。"}, {"text": "护士每天记录病人的一条二便。", "explanation": "二便是尿和大便的统称，不用“条”这类个体量词计量，直接说“记录病人的二便”即可。"}, {"text": "护士每天给病人记录一只二便。", "explanation": "这里应该用〈次〉。“只”多用于动物或成对的物品，不用于计量二便。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二便", "is_correct": true, "explanation": "正确：二便指尿和大便，“病人刚做完手术，二便不能自己控制”符合语境。"}, {"text": "论文", "is_correct": false, "explanation": "语义：论文不是身体的排泄功能，“论文不能自己控制”与“做完手术”的语境不相容。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业与手术后的身体状况无关，句子语义不通。"}, {"text": "体检", "is_correct": false, "explanation": "搭配：“控制”一般搭配身体机能、情绪、局面，不搭配“体检”。"}], "explanations": {"二便": "正确：二便指尿和大便，“病人刚做完手术，二便不能自己控制”符合语境。", "论文": "语义：论文不是身体的排泄功能，“论文不能自己控制”与“做完手术”的语境不相容。", "作业": "语义：作业与手术后的身体状况无关，句子语义不通。", "体检": "搭配：“控制”一般搭配身体机能、情绪、局面，不搭配“体检”。"}, "sentence_index": 6, "correct_answer": "二便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士取了一朵二便去化验。", "explanation": "这里应该用〈份〉。化验样本计量用“份”，“朵”是花的量词，不能用于二便。"}, {"text": "宝宝每次拉出一张二便，很有趣。", "explanation": "这里应该用〈次〉。“张”用于纸张、桌子等平面的东西，不用于计量二便。"}, {"text": "护士给病人称了一根二便的重量。", "explanation": "“根”用于细长物。二便是尿和大便的统称，不用“根”计量，应说“称了病人二便的重量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生说，要注意观察二便们的颜色。", "corrected_sentence": "医生说，要注意观察二便的颜色。", "error_description": "错误形式：“二便们”；正确形式：“二便”。“们”只用于指人的名词，“二便”不能加“们”，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "护理员昨天帮病人清理着二便，还换了床单。", "corrected_sentence": "护理员昨天帮病人清理了二便，还换了床单。", "error_description": "错误形式：“清理着”；正确形式：“清理了”。“昨天”指已完成的动作，应用“了”表示完成，不用“着”（表示动作正在进行或状态持续）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
