INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98656, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98656, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人的相貌、面相。", "primary_collocate": null, "pronunciation": "rén xiàng", "ipa": "ʐən˧˥ ɕjaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这位老先生会看人相。", "target_word": "人相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说我的人相不错，以后会有好运。", "target_word": "人相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看了看他的人相，笑着说他有福气。", "target_word": "人相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人都觉得人相能看出一个人的命运。", "target_word": "人相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算命先生说他的人相很好。", "target_word": "人相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶常说，看人相就能知道他是不是好人。", "target_word": "人相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对人相很有兴趣，还看过很多书。", "target_word": "人相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的人相看起来很有福气。", "target_word": "人相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说这个孩子人相好，将来有福。", "target_word": "人相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友学过看人相，常给大家看看。", "target_word": "人相", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "人的面相，可用来判断运气和性格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00032f7-208c-448d-9c5f-b377604ba846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人相", "is_correct": true, "explanation": "正确：“看人相”指看相貌和面相，符合句子语境。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“看”不能与脚步搭配，要说“听脚步”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看”不用于味道，要说“闻味道”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音靠听觉感知，与“看”的对象不符。"}], "explanations": {"人相": "正确：“看人相”指看相貌和面相，符合句子语境。", "脚步": "搭配：“看”不能与脚步搭配，要说“听脚步”。", "味道": "搭配：“看”不用于味道，要说“闻味道”。", "声音": "语义：声音靠听觉感知，与“看”的对象不符。"}, "sentence_index": 0, "correct_answer": "人相"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的人相在村里很有名，大家都认识他。", "explanation": "这里应该用〈名气〉。人相指人的相貌或面相，不能用来说一个人在村里的名声，说“有名”要用名气。"}, {"text": "他看见我，人相很生气。", "explanation": "这里应该用〈表情〉。人相指相貌或面相，不表示一时的情绪，描述生气要用表情。"}, {"text": "他的人相很固执，大家都不愿意和他商量。", "explanation": "这里应该用〈性格〉。人相是外貌，不能形容固执这类性情，形容性格要用性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人相", "is_correct": true, "explanation": "正确：“对人相有兴趣”指对相貌和面相的研究感兴趣，与“看过很多书”相符。"}, {"text": "地板", "is_correct": false, "explanation": "搭配：“对地板有兴趣”不自然，与“看过很多书”的语境也不合。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是值得钻研的对象，与“看过很多书”的语境相矛盾。"}, {"text": "厕所", "is_correct": false, "explanation": "搭配：“对厕所有兴趣”不自然，厕所不是常见的学习对象。"}], "explanations": {"人相": "正确：“对人相有兴趣”指对相貌和面相的研究感兴趣，与“看过很多书”相符。", "地板": "搭配：“对地板有兴趣”不自然，与“看过很多书”的语境也不合。", "垃圾": "语义：垃圾不是值得钻研的对象，与“看过很多书”的语境相矛盾。", "厕所": "搭配：“对厕所有兴趣”不自然，厕所不是常见的学习对象。"}, "sentence_index": 6, "correct_answer": "人相"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试他的人相很好。", "explanation": "这里应该用〈成绩〉。人相指相貌或面相，考试的好坏要用成绩。"}, {"text": "这件衣服的人相很便宜。", "explanation": "这里应该用〈价格〉。人相指人的相貌，衣服没有相貌，说便宜要用价格。"}, {"text": "这个月我的人相增加了三公斤。", "explanation": "这里应该用〈体重〉。人相是面貌，不能用公斤计量增加，体重才说增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一条好人相，很受老人喜欢。", "corrected_sentence": "他有一副好人相，很受老人喜欢。", "error_description": "错误在〈人相〉前的量词。“条”用于细长之物，不能用于相貌；应说“一副好人相”，“副”用于相貌、面相。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我朋友的人相的很有福气，大家都羡慕他。", "corrected_sentence": "我朋友的人相很有福气，大家都羡慕他。", "error_description": "错误：“我朋友的人相”已作主语，其后接谓语“很有福气”时，不能在中心语“人相”后再加“的”，应去掉多余的“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
