INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98659, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以南是在某个地方的南边。", "primary_collocate": null, "pronunciation": "yǐ nán", "ipa": "i˨˩ nan˧˥", "syllable_count": 2, "sentences": [{"text": "长江以南的冬天不太冷。", "target_word": "以南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市以南有一条大河。", "target_word": "以南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京以南的天气更暖和。", "target_word": "以南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校以南五百米有个地铁站。", "target_word": "以南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家在这条路以南。", "target_word": "以南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海南在广东以南，那里一年都很热。", "target_word": "以南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河以南的人喜欢吃米饭。", "target_word": "以南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山以南有很多茶园。", "target_word": "以南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了桥，桥以南就是我的老家。", "target_word": "以南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "淮河以南很多地方冬天也很绿。", "target_word": "以南", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "以南地区", "label": "复合"}], "register": "通用", "sense_fingerprint": "以某地为界，在它南边的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '389b43bd-a0c5-4cce-afd4-0cb183a97713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98659, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以南", "is_correct": true, "explanation": "“以南”指以长江为界、在它南边，与“长江以南的冬天”相符。"}, {"text": "之前", "is_correct": false, "explanation": "搭配：“之前”多指时间，“长江之前”不能表示地理位置。"}, {"text": "之间", "is_correct": false, "explanation": "搭配：“之间”需要两个或以上的参照物，“长江之间”不能作地点。"}, {"text": "之后", "is_correct": false, "explanation": "语义：“之后”表示时间先后，不表示方位，与句中的地理位置冲突。"}], "explanations": {"以南": "“以南”指以长江为界、在它南边，与“长江以南的冬天”相符。", "之前": "搭配：“之前”多指时间，“长江之前”不能表示地理位置。", "之间": "搭配：“之间”需要两个或以上的参照物，“长江之间”不能作地点。", "之后": "语义：“之后”表示时间先后，不表示方位，与句中的地理位置冲突。"}, "sentence_index": 0, "correct_answer": "以南"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的小猫以南有一棵大树。", "explanation": "这里应该用〈南边〉。“以南”的参照必须是地点，“小猫”不是地点，应说“小猫的南边”。"}, {"text": "这个书包以南有一棵大树。", "explanation": "这里应该用〈南面〉。“以南”的参照必须是地点，“书包”不是地点，应说“书包的南面”。"}, {"text": "这次会议以南有一家饭馆。", "explanation": "这里应该用〈南边〉。“以南”的参照必须是地点，“会议”是活动，不能作参照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98659, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以南", "is_correct": true, "explanation": "“以南”指以河为界、在它南边，与“河以南的人”相符。"}, {"text": "之上", "is_correct": false, "explanation": "搭配：“河之上”指河面上，不用来指人的居住地点，与句意不协调。"}, {"text": "之下", "is_correct": false, "explanation": "搭配：“河之下”指河底，不能作人喜欢吃饭的地方。"}, {"text": "之初", "is_correct": false, "explanation": "语义：“之初”表示时间的开端，不表示方位，与“河”不能对应。"}], "explanations": {"以南": "“以南”指以河为界、在它南边，与“河以南的人”相符。", "之上": "搭配：“河之上”指河面上，不用来指人的居住地点，与句意不协调。", "之下": "搭配：“河之下”指河底，不能作人喜欢吃饭的地方。", "之初": "语义：“之初”表示时间的开端，不表示方位，与“河”不能对应。"}, "sentence_index": 6, "correct_answer": "以南"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈以南坐着我的弟弟。", "explanation": "这里应该用〈南边〉。“以南”指以某地为界的一大片区域，人身边的位置要说“妈妈的南边”。"}, {"text": "桌子以南放着一个杯子。", "explanation": "这里应该用〈旁边〉。“以南”用于地理区域，不用于桌子这样的小物件。"}, {"text": "我的书包以南是一支笔。", "explanation": "这里应该用〈旁边〉。“以南”用于地理区域，书包不能作参照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98659, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "黄河以南了的村子很多。", "corrected_sentence": "黄河以南的村子很多。", "error_description": "方位短语“黄河以南”后不能直接带“了”，这里多出一个“了”；去掉后为“黄河以南的村子很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98659, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座山南以有很多茶园。", "corrected_sentence": "这座山以南有很多茶园。", "error_description": "语序错误：应说“以南”，不能说“南以”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
