INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98663, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "伙是一起做事的一群人。", "primary_collocate": null, "pronunciation": "huǒ", "ipa": "xuɔ˨˩˦", "syllable_count": 1, "sentences": [{"text": "路边有一伙人在下棋。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那伙人天天一起打球。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一伙年轻人正在河边玩儿。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这伙人是来帮我们搬家的。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有一伙同学常常一起复习。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口站着一伙人，不知道在等谁。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一伙孩子在院子里踢足球。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天来了一伙客人，都是我爸的朋友。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是一伙人，总是一起上班。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那伙工人今天在修路。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "团伙", "label": "复合词"}, {"form": "同伙", "label": "复合词"}, {"form": "入伙", "label": "复合词"}], "register": "口语", "sense_fingerprint": "量词，用于一起做事的一群人，如一伙人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caeccb10-6a79-4d7a-87ac-7a371c930c18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98663, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伙", "is_correct": true, "explanation": "伙（huǒ，第三声）：结成一帮的人。"}, {"text": "货", "is_correct": false, "explanation": "货（huò）与伙声调不同（第四声与第三声），意思是货物。"}, {"text": "活", "is_correct": false, "explanation": "活（huó）与伙声调不同（第二声与第三声），意思是活着或灵活。"}, {"text": "或", "is_correct": false, "explanation": "或（huò）与伙声调不同（第四声与第三声），意思是或者。"}], "explanations": {"伙": "伙（huǒ，第三声）：结成一帮的人。", "货": "货（huò）与伙声调不同（第四声与第三声），意思是货物。", "活": "活（huó）与伙声调不同（第二声与第三声），意思是活着或灵活。", "或": "或（huò）与伙声调不同（第四声与第三声），意思是或者。"}, "sentence_index": null, "correct_answer": "伙"}, "level_3": {"options": [{"text": "伙", "is_correct": true, "explanation": "“伙”用于结成一帮的人，与“一___人在下棋”相符。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物，不能用来数人。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”指山、楼等大型固定物，不能数一群人。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，如桌子、纸，不能数人。"}], "explanations": {"伙": "“伙”用于结成一帮的人，与“一___人在下棋”相符。", "只": "搭配：“只”多用于动物，不能用来数人。", "座": "语义：“座”指山、楼等大型固定物，不能数一群人。", "张": "搭配：“张”用于平面的东西，如桌子、纸，不能数人。"}, "sentence_index": 0, "correct_answer": "伙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一伙面包，准备带去野餐。", "explanation": "这里应该用〈个〉。“伙”只用于结成一帮的人，面包不能用“伙”来数。"}, {"text": "一伙货物昨天运到了学校，我们都很高兴。", "explanation": "这个词不这么用：这里应该用〈批〉。“伙”指结伙的人，不能用来数货物，货物应用“批”。"}, {"text": "门口停着一伙车，等着出发。", "explanation": "这个词不这么用：这里应该用〈辆〉。“伙”指结成一帮的人，车辆应用“辆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98663, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "伙", "is_correct": true, "explanation": "伙（huǒ，第三声）：结成一帮的人。"}, {"text": "祸", "is_correct": false, "explanation": "祸（huò）与伙声调不同（第四声与第三声），意思是灾祸。"}, {"text": "获", "is_correct": false, "explanation": "获（huò）与伙声调不同（第四声与第三声），意思是获得。"}, {"text": "果", "is_correct": false, "explanation": "果（guǒ）与伙声母不同（g 与 h），意思是水果。"}], "explanations": {"伙": "伙（huǒ，第三声）：结成一帮的人。", "祸": "祸（huò）与伙声调不同（第四声与第三声），意思是灾祸。", "获": "获（huò）与伙声调不同（第四声与第三声），意思是获得。", "果": "果（guǒ）与伙声母不同（g 与 h），意思是水果。"}, "sentence_index": null, "correct_answer": "伙"}, "level_3": {"options": [{"text": "伙", "is_correct": true, "explanation": "“伙”用于结成一帮的人，与“一___孩子在院子里踢足球”相符。"}, {"text": "棵", "is_correct": false, "explanation": "搭配：“棵”用于植物，不能用来数孩子。"}, {"text": "扇", "is_correct": false, "explanation": "语义：“扇”用于门窗等，与孩子无关。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书册，不能用来数人。"}], "explanations": {"伙": "“伙”用于结成一帮的人，与“一___孩子在院子里踢足球”相符。", "棵": "搭配：“棵”用于植物，不能用来数孩子。", "扇": "语义：“扇”用于门窗等，与孩子无关。", "本": "搭配：“本”用于书册，不能用来数人。"}, "sentence_index": 6, "correct_answer": "伙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一伙鸽子飞过天空。", "explanation": "这里应该用〈群〉。“伙”指结成一帮的人，鸽子这类动物用“群”。"}, {"text": "他借了一伙书。", "explanation": "这里应该用〈本〉。“伙”只用于结成一帮的人，书应用“本”来数。"}, {"text": "他买了一伙桌子。", "explanation": "这里应该用〈张〉。“伙”不能用来数桌子，桌子应用“张”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口站着一伙个人，正在等车。", "corrected_sentence": "门口站着一伙人，正在等车。", "error_description": "错误形式：“一伙个人”。正确形式：“一伙人”。“伙”本身就是量词，后面不能再加量词“个”，应直接说“一伙人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一伙们客人昨天来到我家。", "corrected_sentence": "一伙客人昨天来到我家。", "error_description": "错误形式：“一伙们客人”。正确形式：“一伙客人”。“们”只能加在指人的名词后面，不能加在量词“伙”后面，应直接说“一伙客人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
