INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98664, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "由共同活动的人组成的集体。", "primary_collocate": null, "pronunciation": "huǒ", "ipa": "xuɔ˨˩˦", "syllable_count": 1, "sentences": [{"text": "警察抓住了一伙小偷。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这伙骗子专门骗老人。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那伙人在城里做了很多坏事。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一伙强盗躲在山里。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们这伙人专门在车站偷东西。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说有一伙坏人在附近。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这伙小偷昨晚被警察抓到了。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他加入了一伙走私的人。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里来了一伙卖假药的人。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现了一伙偷车的人。", "target_word": "伙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "团伙", "label": "复合词"}, {"form": "同伙", "label": "复合词"}, {"form": "入伙", "label": "复合词"}], "register": "口语", "sense_fingerprint": "量词，用于结成一帮的人，常指坏人，如一伙小偷", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caeccb10-6a79-4d7a-87ac-7a371c930c18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伙", "is_correct": true, "explanation": "伙（huǒ，第三声）：结成一帮的人，常指坏人。"}, {"text": "货", "is_correct": false, "explanation": "货（huò）与伙声调不同（第四声与第三声），意思是货物。"}, {"text": "活", "is_correct": false, "explanation": "活（huó）与伙声调不同（第二声与第三声），意思是活着或灵活。"}, {"text": "或", "is_correct": false, "explanation": "或（huò）与伙声调不同（第四声与第三声），意思是或者。"}], "explanations": {"伙": "伙（huǒ，第三声）：结成一帮的人，常指坏人。", "货": "货（huò）与伙声调不同（第四声与第三声），意思是货物。", "活": "活（huó）与伙声调不同（第二声与第三声），意思是活着或灵活。", "或": "或（huò）与伙声调不同（第四声与第三声），意思是或者。"}, "sentence_index": null, "correct_answer": "伙"}, "level_3": {"options": [{"text": "伙", "is_correct": true, "explanation": "“伙”用于结成一帮的人，与“警察抓住了一___小偷”相符。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车辆，不能用来数小偷。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”指山、楼等大型固定物，与小偷无关。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，不能用来数小偷。"}], "explanations": {"伙": "“伙”用于结成一帮的人，与“警察抓住了一___小偷”相符。", "辆": "搭配：“辆”用于车辆，不能用来数小偷。", "座": "语义：“座”指山、楼等大型固定物，与小偷无关。", "张": "搭配：“张”用于平面的东西，不能用来数小偷。"}, "sentence_index": 0, "correct_answer": "伙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一伙面包，准备带去野餐。", "explanation": "这里应该用〈个〉。“伙”只用于结成一帮的人，面包不能用“伙”来数。"}, {"text": "仓库里刚运来一伙货物。", "explanation": "这里应该用〈批〉。“伙”指结成一帮的人，不能用来数货物，货物应用“批”。"}, {"text": "他买了一伙桌子。", "explanation": "这里应该用〈张〉。“伙”不能用来数桌子，桌子应用“张”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
