INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一国派驻他国的外交代表机关。", "primary_collocate": null, "pronunciation": "shǐ guǎn", "ipa": "ʂɻ̩˨˩ kuan˨˩˦", "syllable_count": 2, "sentences": [{"text": "中国在很多国家都有使馆。", "target_word": "使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的护照丢了，要去使馆办新的。", "target_word": "使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使馆的工作人员帮助在外国的本国人。", "target_word": "使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家的使馆在城市东边。", "target_word": "使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大使是使馆里最重要的人。", "target_word": "使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使馆发了一个通知，请大家注意安全。", "target_word": "使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在使馆门口等了很久。", "target_word": "使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国关系变好后，他们开了新的使馆。", "target_word": "使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使馆里的人都是从自己国家派来的。", "target_word": "使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在使馆工作了五年。", "target_word": "使馆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "大使馆", "label": "复合"}, {"form": "使館", "label": "繁体"}], "register": "正式", "sense_fingerprint": "派驻外国的外交代表机关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb662756-0b78-4edf-9c5e-051c04c57dff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使馆", "is_correct": true, "explanation": "“使馆”指一国派驻他国的外交机关，“在很多国家都有”正合适。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”是天体，不是机构，国家不能在别国“有”它。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“都有”后接“年龄”不成立，国家不说“有年龄”。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“感冒”指疾病，国家不说“有感冒”。"}], "explanations": {"使馆": "“使馆”指一国派驻他国的外交机关，“在很多国家都有”正合适。", "月亮": "语义：“月亮”是天体，不是机构，国家不能在别国“有”它。", "年龄": "搭配：“都有”后接“年龄”不成立，国家不说“有年龄”。", "感冒": "搭配：“感冒”指疾病，国家不说“有感冒”。"}, "sentence_index": 0, "correct_answer": "使馆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看见路边有一只使馆。", "explanation": "这里应该用〈座〉。“只”用于动物，使馆是建筑，要用〈座〉。"}, {"text": "他是中国驻法国的使馆，工作很努力。", "explanation": "这里应该用〈大使〉。使馆是机构，不能指人，指人的外交代表要用〈大使〉。"}, {"text": "我昨天去使馆取了一千块钱。", "explanation": "这里应该用〈银行〉。使馆是国家派驻外国的外交机构，不办理取款业务，取钱要去〈银行〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使馆", "is_correct": true, "explanation": "“使馆”是地点名词，“记者在……门口等”正合适。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”不是地点，记者不会在雨伞门口等。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”指日子，不能用来指称“门口”的所在地。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“门口”要接场所名词，“钢笔”不是场所，不搭配。"}], "explanations": {"使馆": "“使馆”是地点名词，“记者在……门口等”正合适。", "雨伞": "语义：“雨伞”不是地点，记者不会在雨伞门口等。", "生日": "语义：“生日”指日子，不能用来指称“门口”的所在地。", "钢笔": "搭配：“门口”要接场所名词，“钢笔”不是场所，不搭配。"}, "sentence_index": 6, "correct_answer": "使馆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一位优秀的使馆。", "explanation": "这里应该用〈使节〉。使馆是机构，不能指人，指人的外交代表要用〈使节〉。"}, {"text": "这位使馆很友善，经常帮助留学生。", "explanation": "这里应该用〈领事〉。使馆是机构，不能用来形容待人友善的人，这里要用〈领事〉。"}, {"text": "我经过时看到一本使馆。", "explanation": "这里应该用〈座〉。“本”多用于书、本子等，使馆是建筑，要用〈座〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家旁边有一只使馆。", "corrected_sentence": "我家旁边有一个使馆。", "error_description": "“一只使馆”用错了量词：“只”用于动物，使馆是机构、建筑，应说“一个使馆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹使馆做翻译。", "corrected_sentence": "我妹妹在使馆做翻译。", "error_description": "“使馆做翻译”漏了介词“在”，应说“在使馆做翻译”。表示地点的名词前要加“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
