INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98671, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98671, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做完是把事情做到最后，已经结束了。", "primary_collocate": null, "pronunciation": "zuò wán", "ipa": "tsuɔ˥˩ wan˧˥", "syllable_count": 2, "sentences": [{"text": "我做完作业就去玩。", "target_word": "做完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做完饭，大家一起吃。", "target_word": "做完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做完了今天的工作。", "target_word": "做完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做完这些题再休息吧。", "target_word": "做完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完运动，我喝了一杯水。", "target_word": "做完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做完手术，还在医院里休息。", "target_word": "做完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们做完实验就回家。", "target_word": "做完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟做完了所有的练习。", "target_word": "做完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完了这件事，我心里很轻松。", "target_word": "做完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说做完卷子才能出去。", "target_word": "做完", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做完了", "label": "完成体"}, {"form": "做不完", "label": "可能补语否定式"}, {"form": "做得完", "label": "可能补语肯定式"}], "register": "中性", "sense_fingerprint": "把一件事情做到最后并结束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8ddae9-ae0a-4af4-8122-16a67952f138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98671, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：「吃」指吃东西，不能说吃作业。"}, {"text": "做完", "is_correct": true, "explanation": "正确：「做完」表示把作业做到结束，与「就去玩」搭配。"}, {"text": "摔", "is_correct": false, "explanation": "语义：「摔」指使劲往地上扔，与作业的完成无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」用于洗东西或身体，不能洗作业。"}], "explanations": {"吃": "搭配：「吃」指吃东西，不能说吃作业。", "做完": "正确：「做完」表示把作业做到结束，与「就去玩」搭配。", "摔": "语义：「摔」指使劲往地上扔，与作业的完成无关。", "洗": "搭配：「洗」用于洗东西或身体，不能洗作业。"}, "sentence_index": 0, "correct_answer": "做完"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我做完了新同学。", "explanation": "这里应该用〈认识〉。做完指把事情做到结束，不能用于结识的人。"}, {"text": "雨做完了。", "explanation": "这里应该用〈下完〉。做完的主语要能动手做事，雨不能做完。"}, {"text": "我做完了一个机会。", "explanation": "这里应该用〈得到〉。做完强调把事情做到结束，不能用于机会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98671, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：「喝」指饮用液体，不能用于实验。"}, {"text": "做完", "is_correct": true, "explanation": "正确：「做完」表示把实验做到结束，与「就回家」搭配。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」用于歌曲、戏曲等，不能唱实验。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」用于衣服鞋袜，不能穿实验。"}], "explanations": {"喝": "语义：「喝」指饮用液体，不能用于实验。", "做完": "正确：「做完」表示把实验做到结束，与「就回家」搭配。", "唱": "搭配：「唱」用于歌曲、戏曲等，不能唱实验。", "穿": "搭配：「穿」用于衣服鞋袜，不能穿实验。"}, "sentence_index": 6, "correct_answer": "做完"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做完了真相。", "explanation": "这里应该用〈说出〉。做完指动手完成事务，不能用于真相。"}, {"text": "这次比赛做完了纪录。", "explanation": "这里应该用〈打破〉。做完指把事情做到结束，不能用于纪录。"}, {"text": "他做完了很大的打击。", "explanation": "这里应该用〈遭受〉。做完不能用于打击，打击不是可以做完的事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做完得作业，就去玩了。", "corrected_sentence": "他做完了作业，就去玩了。", "error_description": "错误：「做完得作业」中「得」应为「了」。「做完了」表示把作业做完，「了」紧跟结果补语「完」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们做完过卷子就走。", "corrected_sentence": "我们做完卷子就走。", "error_description": "错误：「做完过卷子」中多出「过」。「做完」已表示动作结束，后接宾语时不加「过」，正确为「做完卷子」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
