INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98676, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向主管机关报告并登记，以备查考。", "primary_collocate": null, "pronunciation": "bèi àn", "ipa": "pei˥˩ an˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的合同已经向政府备案。", "target_word": "备案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些材料要向有关部门备案。", "target_word": "备案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把规定交给教育局备案。", "target_word": "备案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新产品要备案以后才能卖。", "target_word": "备案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家境外企业必须先向主管部门备案。", "target_word": "备案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份计划请你向上级备案。", "target_word": "备案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办比赛要到体育局备案。", "target_word": "备案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药品广告也要备案。", "target_word": "备案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国人来办活动，需要到公安局备案。", "target_word": "备案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所有文件均需备案，以便日后查考。", "target_word": "备案", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "备了案", "label": "完成体（离合）"}, {"form": "备过案", "label": "经历体（离合）"}, {"form": "备案了", "label": "完成体"}], "register": "书面", "sense_fingerprint": "向主管机关报告并登记以备查考", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8ddae9-ae0a-4af4-8122-16a67952f138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "备案", "is_correct": true, "explanation": "正确：备案指向主管机关报告并登记以备查考，合同报给政府符合句意。"}, {"text": "宣誓", "is_correct": false, "explanation": "语义：合同不能向政府宣誓，句意不通。"}, {"text": "致谢", "is_correct": false, "explanation": "语义：合同没有感情，不会向政府致谢。"}, {"text": "吐槽", "is_correct": false, "explanation": "语域：吐槽是口语说法，与书面的合同报送语域不合，而且合同不会抱怨。"}], "explanations": {"备案": "正确：备案指向主管机关报告并登记以备查考，合同报给政府符合句意。", "宣誓": "语义：合同不能向政府宣誓，句意不通。", "致谢": "语义：合同没有感情，不会向政府致谢。", "吐槽": "语域：吐槽是口语说法，与书面的合同报送语域不合，而且合同不会抱怨。"}, "sentence_index": 0, "correct_answer": "备案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在朋友圈里备案了。", "explanation": "这里应该用〈发布〉。在朋友圈发消息要说发布，备案是向主管机关报告并登记，不能这样用。"}, {"text": "他已经向律师备案了。", "explanation": "这里应该用〈咨询〉。向律师请教问题要说咨询，备案的对象是主管机关。"}, {"text": "他每天早上去浴室备案。", "explanation": "这里应该用〈洗澡〉。去浴室是为了洗澡，备案是向主管机关报告并登记，两者不相干。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "备案", "is_correct": true, "explanation": "正确：办比赛需要到主管机关登记，备案指报给主管机关登记留档，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：体育局是办事机关，不是睡觉的地方，句意荒谬。"}, {"text": "美容", "is_correct": false, "explanation": "语义：美容指护理人的容貌，与办比赛的手续无关。"}, {"text": "买菜", "is_correct": false, "explanation": "语义：体育局不是菜市场，买菜与办比赛的语境不合。"}], "explanations": {"备案": "正确：办比赛需要到主管机关登记，备案指报给主管机关登记留档，符合句意。", "睡觉": "语义：体育局是办事机关，不是睡觉的地方，句意荒谬。", "美容": "语义：美容指护理人的容貌，与办比赛的手续无关。", "买菜": "语义：体育局不是菜市场，买菜与办比赛的语境不合。"}, "sentence_index": 6, "correct_answer": "备案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了考试已经备案好几天了。", "explanation": "这里应该用〈复习〉。为考试做准备要说复习，备案是向主管机关报告并登记，不能用于个人学习。"}, {"text": "他每天晚上在家备案吃饭。", "explanation": "这里应该用〈准备〉。在家准备饭菜要说准备，备案是向主管机关报告并登记，不能用于做饭。"}, {"text": "水费要按时备案。", "explanation": "这里应该用〈缴纳〉。水费要按时交给供水部门，备案是报给主管机关留档。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司要去工商局备案个。", "corrected_sentence": "这家公司要去工商局备个案。", "error_description": "量词“个”放错位置：应为“备个案”，“个”要放在离合词中间，不能放在“案”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些表格都要备案表格，方便以后查。", "corrected_sentence": "这些表格都要备案，方便以后查。", "error_description": "“备案”是离合词，不能直接带宾语，后面不能再加“表格”，应为“这些表格都要备案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98679, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "传入", "is_correct": true, "explanation": "正确：传入指从外面传到里面，与传出方向相反，是反义词。"}, {"text": "种植", "is_correct": false, "explanation": "种植指栽培植物，与传出的方向和意义都无关，不构成反义。"}, {"text": "修理", "is_correct": false, "explanation": "修理指把坏了的东西弄好，与传出的意义无关，不构成反义。"}, {"text": "购买", "is_correct": false, "explanation": "购买指用钱换取物品，与传出的方向和意义都无关，不构成反义。"}], "correct_answer": "传入", "explanations": {"传入": "正确：传入指从外面传到里面，与传出方向相反，是反义词。", "种植": "种植指栽培植物，与传出的方向和意义都无关，不构成反义。", "修理": "修理指把坏了的东西弄好，与传出的意义无关，不构成反义。", "购买": "购买指用钱换取物品，与传出的方向和意义都无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
