INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98679, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "传出是从里面传到外面来。", "primary_collocate": null, "pronunciation": "chuán chū", "ipa": "tʂʰwan˧˥ tʂʰu˥", "syllable_count": 2, "sentences": [{"text": "屋子里传出一阵好听的音乐。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里传出一股香味。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔壁传出孩子的哭声。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里传出大家读书的声音。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里传出妈妈的声音。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞里传出奇怪的响声。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上传出了跳舞的声音，我睡不着。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听见房间里传出笑声。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店里传出热闹的歌声。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门里传出一声大叫，我吓了一跳。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传出了", "label": "完成体"}, {"form": "传出过", "label": "经历体"}, {"form": "传不出", "label": "可能补语否定式"}], "register": "中性", "sense_fingerprint": "声音、气味等从里面传到外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8ddae9-ae0a-4af4-8122-16a67952f138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98679, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "传出", "is_correct": true, "explanation": "正确：传出，表示声音、气味等从里面传到外面。"}, {"text": "穿出", "is_correct": false, "explanation": "穿出：chuān（第一声）与 chuán（第二声）声调不同，意思是穿过、露出。"}, {"text": "喘出", "is_correct": false, "explanation": "喘出：chuǎn（第三声）与 chuán（第二声）声调不同，意思是喘息时吐出。"}, {"text": "传书", "is_correct": false, "explanation": "传书：chuán shū 与 chuán chū 只有声母不同（sh 与 ch），意思是传递书信。"}], "explanations": {"传出": "正确：传出，表示声音、气味等从里面传到外面。", "穿出": "穿出：chuān（第一声）与 chuán（第二声）声调不同，意思是穿过、露出。", "喘出": "喘出：chuǎn（第三声）与 chuán（第二声）声调不同，意思是喘息时吐出。", "传书": "传书：chuán shū 与 chuán chū 只有声母不同（sh 与 ch），意思是传递书信。"}, "sentence_index": null, "correct_answer": "传出"}, "level_3": {"options": [{"text": "剪出", "is_correct": false, "explanation": "搭配：「剪出」指用剪刀剪出形状，不能剪出声音。"}, {"text": "传出", "is_correct": true, "explanation": "正确：「传出」指声音从屋子里传到外面，可以搭配「一阵音乐」。"}, {"text": "搬出", "is_correct": false, "explanation": "搭配：「搬出」要搬具体的物体，不能搬声音。"}, {"text": "倒出", "is_correct": false, "explanation": "搭配：「倒出」指把液体或颗粒倒出来，不能说倒出音乐。"}], "explanations": {"剪出": "搭配：「剪出」指用剪刀剪出形状，不能剪出声音。", "传出": "正确：「传出」指声音从屋子里传到外面，可以搭配「一阵音乐」。", "搬出": "搭配：「搬出」要搬具体的物体，不能搬声音。", "倒出": "搭配：「倒出」指把液体或颗粒倒出来，不能说倒出音乐。"}, "sentence_index": 0, "correct_answer": "传出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从书包里传出一本书。", "explanation": "这里应该用〈拿出〉。传出指声音、气味从里面传到外面，不能用来表示取出物品。"}, {"text": "血从伤口传出来了。", "explanation": "这里应该用〈流出〉。传出只用于声音、消息等，不能用于血液这类液体的流动。"}, {"text": "他在牌局上传出一张王牌。", "explanation": "这里应该用〈打出〉。传出用于声音、消息，不用于出牌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98679, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "传出", "is_correct": true, "explanation": "正确：传出，表示声音、气味等从里面传到外面。"}, {"text": "转出", "is_correct": false, "explanation": "转出：zhuǎn chū 与 chuán chū 声母（zh 与 ch）和声调不同，意思是转移出去。"}, {"text": "传输", "is_correct": false, "explanation": "传输：chuán shū 与 chuán chū 第二字声母不同（sh 与 ch），意思是输送信号或能量。"}, {"text": "串出", "is_correct": false, "explanation": "串出：chuàn（第四声）与 chuán（第二声）声调不同，意思是串联而出，较少用。"}], "explanations": {"传出": "正确：传出，表示声音、气味等从里面传到外面。", "转出": "转出：zhuǎn chū 与 chuán chū 声母（zh 与 ch）和声调不同，意思是转移出去。", "传输": "传输：chuán shū 与 chuán chū 第二字声母不同（sh 与 ch），意思是输送信号或能量。", "串出": "串出：chuàn（第四声）与 chuán（第二声）声调不同，意思是串联而出，较少用。"}, "sentence_index": null, "correct_answer": "传出"}, "level_3": {"options": [{"text": "拿出", "is_correct": false, "explanation": "搭配：「拿出」要拿具体的东西，不能拿声音。"}, {"text": "传出", "is_correct": true, "explanation": "正确：「传出」指声音从楼上传到我这里，与「跳舞的声音」搭配。"}, {"text": "掏出", "is_correct": false, "explanation": "搭配：「掏出」指从口袋等处取出东西，不能掏声音。"}, {"text": "射出", "is_correct": false, "explanation": "语义：「射出」指光、箭等急速射出，不用于声音。"}], "explanations": {"拿出": "搭配：「拿出」要拿具体的东西，不能拿声音。", "传出": "正确：「传出」指声音从楼上传到我这里，与「跳舞的声音」搭配。", "掏出": "搭配：「掏出」指从口袋等处取出东西，不能掏声音。", "射出": "语义：「射出」指光、箭等急速射出，不用于声音。"}, "sentence_index": 6, "correct_answer": "传出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他心里传出一阵高兴。", "explanation": "这里应该用〈感到〉。传出指声音、消息从里向外传，不能用于心里的感觉。"}, {"text": "他传出了一个假期。", "explanation": "这里应该用〈度过〉。传出指从里向外传播，不能用于时间的度过。"}, {"text": "他传出了一位朋友。", "explanation": "这里应该用〈失去〉。传出只用于声音、消息等，不能用来指人或关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "香味厨房里传出来了。", "corrected_sentence": "香味从厨房里传出来了。", "error_description": "错误：「香味厨房里传出来了」漏掉了引出起点的介词「从」。正确应为「香味从厨房里传出来了」，传出的起点要用「从……」引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "歌声在窗户传出来了。", "corrected_sentence": "歌声从窗户传出来了。", "error_description": "错误：「在窗户」用「在」引出起点，应改为「从」。正确为「歌声从窗户传出来了」，声音的起点要用「从」引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98680, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "传入", "is_correct": true, "explanation": "正确：传入指消息从外面传到里面，与传出方向相反，是反义词。"}, {"text": "种植", "is_correct": false, "explanation": "种植指栽培植物，与消息传播的方向和意义都无关，不构成反义。"}, {"text": "修理", "is_correct": false, "explanation": "修理指把坏了的东西弄好，与消息传播的意义无关，不构成反义。"}, {"text": "购买", "is_correct": false, "explanation": "购买指用钱换取物品，与消息传播的方向和意义都无关，不构成反义。"}], "correct_answer": "传入", "explanations": {"传入": "正确：传入指消息从外面传到里面，与传出方向相反，是反义词。", "种植": "种植指栽培植物，与消息传播的方向和意义都无关，不构成反义。", "修理": "修理指把坏了的东西弄好，与消息传播的意义无关，不构成反义。", "购买": "购买指用钱换取物品，与消息传播的方向和意义都无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
