INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98680, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "由内向外传播出来。", "primary_collocate": null, "pronunciation": "chuán chū", "ipa": "tʂʰwan˧˥ tʂʰu˥", "syllable_count": 2, "sentences": [{"text": "公司里传出一个好消息。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校传出老师要换人的消息。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里传出病人好起来的消息。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事是从公司传出的。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议刚结束，消息就传出了。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要结婚的事，是从朋友那里传出的。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队传出换教练的消息，大家都很吃惊。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂传出要关门的消息。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好消息从北京传出，大家都高兴。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事最早是从小村子里传出的。", "target_word": "传出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传出了", "label": "完成体"}, {"form": "传出过", "label": "经历体"}, {"form": "传不出", "label": "可能补语否定式"}], "register": "中性", "sense_fingerprint": "消息、事情从内部向外传播", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8ddae9-ae0a-4af4-8122-16a67952f138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98680, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "传出", "is_correct": true, "explanation": "正确：传出，表示消息、事情从内部向外传播。"}, {"text": "穿出", "is_correct": false, "explanation": "穿出：chuān（第一声）与 chuán（第二声）声调不同，意思是穿过、露出。"}, {"text": "喘出", "is_correct": false, "explanation": "喘出：chuǎn（第三声）与 chuán（第二声）声调不同，意思是喘息时吐出。"}, {"text": "传书", "is_correct": false, "explanation": "传书：chuán shū 与 chuán chū 只有声母不同（sh 与 ch），意思是传递书信。"}], "explanations": {"传出": "正确：传出，表示消息、事情从内部向外传播。", "穿出": "穿出：chuān（第一声）与 chuán（第二声）声调不同，意思是穿过、露出。", "喘出": "喘出：chuǎn（第三声）与 chuán（第二声）声调不同，意思是喘息时吐出。", "传书": "传书：chuán shū 与 chuán chū 只有声母不同（sh 与 ch），意思是传递书信。"}, "sentence_index": null, "correct_answer": "传出"}, "level_3": {"options": [{"text": "切出", "is_correct": false, "explanation": "搭配：「切出」指用刀把东西切开，不能切出消息。"}, {"text": "传出", "is_correct": true, "explanation": "正确：「传出」指消息从公司向外传播，可以搭配「一个好消息」。"}, {"text": "剪出", "is_correct": false, "explanation": "搭配：「剪出」指用剪刀剪出形状，不用于消息。"}, {"text": "吃出", "is_correct": false, "explanation": "搭配：「吃出」指通过吃来辨别味道，不能吃出消息。"}], "explanations": {"切出": "搭配：「切出」指用刀把东西切开，不能切出消息。", "传出": "正确：「传出」指消息从公司向外传播，可以搭配「一个好消息」。", "剪出": "搭配：「剪出」指用剪刀剪出形状，不用于消息。", "吃出": "搭配：「吃出」指通过吃来辨别味道，不能吃出消息。"}, "sentence_index": 0, "correct_answer": "传出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在地上传出了一个脚印。", "explanation": "这里应该用〈留下〉。传出用于消息、事情向外传播，不能用于脚印这样的痕迹。"}, {"text": "这个梦想终于传出了。", "explanation": "这里应该用〈实现〉。传出指消息向外传开，不用于梦想的实现。"}, {"text": "他传出了全部责任。", "explanation": "这里应该用〈承担〉。传出不能用于责任，责任不会从里面传到外面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98680, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "传出", "is_correct": true, "explanation": "正确：传出，表示消息、事情从内部向外传播。"}, {"text": "转出", "is_correct": false, "explanation": "转出：zhuǎn chū 与 chuán chū 声母（zh 与 ch）和声调不同，意思是转移出去。"}, {"text": "传输", "is_correct": false, "explanation": "传输：chuán shū 与 chuán chū 第二字声母不同（sh 与 ch），意思是输送信号或能量。"}, {"text": "串出", "is_correct": false, "explanation": "串出：chuàn（第四声）与 chuán（第二声）声调不同，意思是串联而出，较少用。"}], "explanations": {"传出": "正确：传出，表示消息、事情从内部向外传播。", "转出": "转出：zhuǎn chū 与 chuán chū 声母（zh 与 ch）和声调不同，意思是转移出去。", "传输": "传输：chuán shū 与 chuán chū 第二字声母不同（sh 与 ch），意思是输送信号或能量。", "串出": "串出：chuàn（第四声）与 chuán（第二声）声调不同，意思是串联而出，较少用。"}, "sentence_index": null, "correct_answer": "传出"}, "level_3": {"options": [{"text": "抬出", "is_correct": false, "explanation": "搭配：「抬出」要抬起有重量的东西，不能抬消息。"}, {"text": "射出", "is_correct": false, "explanation": "语义：「射出」指光、箭等急速射出，不用于消息。"}, {"text": "传出", "is_correct": true, "explanation": "正确：「传出」指消息从球队向外传开，与「换教练的消息」搭配。"}, {"text": "掏出", "is_correct": false, "explanation": "搭配：「掏出」指从口袋等处取出东西，不能掏消息。"}], "explanations": {"抬出": "搭配：「抬出」要抬起有重量的东西，不能抬消息。", "射出": "语义：「射出」指光、箭等急速射出，不用于消息。", "传出": "正确：「传出」指消息从球队向外传开，与「换教练的消息」搭配。", "掏出": "搭配：「掏出」指从口袋等处取出东西，不能掏消息。"}, "sentence_index": 6, "correct_answer": "传出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我常常传出小时候的事。", "explanation": "这里应该用〈回忆〉。传出指消息、事情从内部向外传播，不能表示回想过去。"}, {"text": "为了这件事，他传出了很多时间。", "explanation": "这里应该用〈花费〉。传出指消息向外传开，不能用于时间的投入。"}, {"text": "请你传出一下这个菜的味道。", "explanation": "这里应该用〈品尝〉。传出指消息向外传播，尝味道要说品尝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个消息传出不去。", "corrected_sentence": "这个消息传不出去。", "error_description": "错误：「传出不去」的可能补语语序错误。正确为「传不出去」，可能补语否定式的格式是「动词＋不＋补语」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个消息小村子传出来了。", "corrected_sentence": "这个消息从小村子传出来了。", "error_description": "错误：「小村子」前漏掉了介词「从」。正确为「这个消息从小村子传出来了」，消息的起点要用「从」引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98683, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "笨拙", "is_correct": true, "explanation": "反义：“优雅”指动作从容好看，“笨拙”指动作不灵活，二者相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "近义而非反义：“漂亮”和“优雅”都可以形容样子好看。"}, {"text": "高大", "is_correct": false, "explanation": "无反义关系：“高大”只说身材高，不涉及动作美不美。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”多用于光线、颜色、眼神，与“优雅”不相对。"}], "correct_answer": "笨拙", "explanations": {"笨拙": "反义：“优雅”指动作从容好看，“笨拙”指动作不灵活，二者相反。", "漂亮": "近义而非反义：“漂亮”和“优雅”都可以形容样子好看。", "高大": "无反义关系：“高大”只说身材高，不涉及动作美不美。", "明亮": "无反义关系：“明亮”多用于光线、颜色、眼神，与“优雅”不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98683, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻快", "is_correct": false, "explanation": "无反义关系：“轻快”形容动作灵活敏捷，与“优雅”不相对。"}, {"text": "温柔", "is_correct": false, "explanation": "无反义关系：“温柔”形容性情或态度，不是“优雅”的反面。"}, {"text": "笨拙", "is_correct": true, "explanation": "反义：“优雅”指动作从容好看，“笨拙”指动作不灵活，二者相反。"}, {"text": "灵巧", "is_correct": false, "explanation": "无反义关系：“灵巧”形容手脚灵活，与“优雅”不构成反义。"}], "correct_answer": "笨拙", "explanations": {"轻快": "无反义关系：“轻快”形容动作灵活敏捷，与“优雅”不相对。", "温柔": "无反义关系：“温柔”形容性情或态度，不是“优雅”的反面。", "笨拙": "反义：“优雅”指动作从容好看，“笨拙”指动作不灵活，二者相反。", "灵巧": "无反义关系：“灵巧”形容手脚灵活，与“优雅”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98683, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "优雅是样子和动作好看，安静，让人喜欢。", "primary_collocate": null, "pronunciation": "yōu yǎ", "ipa": "joʊ̯⁵⁵ ja²¹⁴", "syllable_count": 2, "sentences": [{"text": "她走路的样子很优雅，大家都喜欢看她。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位女老师说话轻轻的，动作也很优雅。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天鹅在水上慢慢游着，样子真优雅。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她安静地坐着，样子很优雅。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈喝茶的动作很优雅，也很安静。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她优雅地走进教室，同学们都看着她。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只猫优雅地走过桌子，没有一点声音。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳舞的时候，她的动作轻轻的，十分优雅。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把茶杯轻轻放下，动作优雅又安静。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看她跳舞，我觉得她像一只优雅的白鹤。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "优雅地", "label": "状语形式"}, {"form": "優雅", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或动物的样子、动作好看而安静，让人喜欢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64d38e22-74eb-4da9-84a8-607619094d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98683, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粗鲁", "is_correct": false, "explanation": "语义：“粗鲁”形容言行粗野，与后半句“大家都喜欢看她”矛盾。"}, {"text": "优雅", "is_correct": true, "explanation": "“优雅”形容人走路的样子好看而从容，与“大家都喜欢看她”相符。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”多形容声音或场所，不用来形容走路的样子。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容声音或环境乱，不说“样子很嘈杂”。"}], "explanations": {"粗鲁": "语义：“粗鲁”形容言行粗野，与后半句“大家都喜欢看她”矛盾。", "优雅": "“优雅”形容人走路的样子好看而从容，与“大家都喜欢看她”相符。", "吵闹": "搭配：“吵闹”多形容声音或场所，不用来形容走路的样子。", "嘈杂": "搭配：“嘈杂”形容声音或环境乱，不说“样子很嘈杂”。"}, "sentence_index": 0, "correct_answer": "优雅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只小狗很优雅，一直在草地上乱跑乱叫。", "explanation": "这里应该用〈调皮〉。“优雅”形容动作从容、安静、好看，不用于形容乱跑乱叫的小狗。"}, {"text": "这家餐厅的价格很优雅，一顿饭要花一千多块。", "explanation": "这里应该用〈昂贵〉。“优雅”形容样子、动作或风格好看、从容，不用于形容价格，价格高要用〈昂贵〉。"}, {"text": "他干活很优雅，一会儿就把屋子收拾好了。", "explanation": "这里应该用〈麻利〉。“优雅”侧重动作的美和从容，干活求快、利索要用〈麻利〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98683, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笨重", "is_correct": false, "explanation": "语义：笨重的脚步容易发出声响，与“没有一点声音”矛盾。"}, {"text": "喧闹", "is_correct": false, "explanation": "搭配：“喧闹”形容场所或场面热闹，不用来形容猫走路的样子。"}, {"text": "优雅", "is_correct": true, "explanation": "“优雅”形容猫走路轻盈从容，与“没有一点声音”相符。"}, {"text": "冒失", "is_correct": false, "explanation": "语义：冒失的动作容易碰响东西，与“没有一点声音”矛盾。"}], "explanations": {"笨重": "语义：笨重的脚步容易发出声响，与“没有一点声音”矛盾。", "喧闹": "搭配：“喧闹”形容场所或场面热闹，不用来形容猫走路的样子。", "优雅": "“优雅”形容猫走路轻盈从容，与“没有一点声音”相符。", "冒失": "语义：冒失的动作容易碰响东西，与“没有一点声音”矛盾。"}, "sentence_index": 6, "correct_answer": "优雅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她优雅地跑进房间，差点摔倒。", "explanation": "这里应该用〈慌张〉。“优雅”指动作从容好看，慌乱跑进房间、差点摔倒的情形要用〈慌张〉。"}, {"text": "这家饭店的厨房很优雅，地上满是油污，苍蝇到处飞。", "explanation": "这里应该用〈脏乱〉。“优雅”形容样子好看、安静、让人喜欢，地上满是油污、苍蝇乱飞的厨房要用〈脏乱〉。"}, {"text": "这头狮子很优雅，一声吼叫就吓跑了野狼。", "explanation": "这里应该用〈勇猛〉。“优雅”形容动作安静从容，吼叫吓跑野狼的猛兽要用〈勇猛〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她优雅的转过身，轻轻地笑了。", "corrected_sentence": "她优雅地转过身，轻轻地笑了。", "error_description": "错误：「优雅的转过身」，修饰动词的“优雅”误用了定语标记“的”。正确：「优雅地转过身」，“优雅”作状语修饰动词时要用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她弹钢琴弹很优雅，大家都在听。", "corrected_sentence": "她弹钢琴弹得很优雅，大家都在听。", "error_description": "错误：「弹很优雅」，漏掉补语标记“得”。正确：「弹得很优雅」，描述动作做得怎么样要用“动词＋得＋形容词”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98684, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "嘈杂", "is_correct": false, "explanation": "无反义关系：“嘈杂”形容声音或环境吵乱，与“优雅”不相对。"}, {"text": "朴素", "is_correct": false, "explanation": "无反义关系：“朴素”指简单不华丽，不是“优雅”的反面。"}, {"text": "粗俗", "is_correct": true, "explanation": "反义：“优雅”指言谈、风格高雅、不粗俗，“粗俗”与之相反。"}, {"text": "雄壮", "is_correct": false, "explanation": "无反义关系：“雄壮”形容声势雄浑有力，与“优雅”没有反义关系。"}], "correct_answer": "粗俗", "explanations": {"嘈杂": "无反义关系：“嘈杂”形容声音或环境吵乱，与“优雅”不相对。", "朴素": "无反义关系：“朴素”指简单不华丽，不是“优雅”的反面。", "粗俗": "反义：“优雅”指言谈、风格高雅、不粗俗，“粗俗”与之相反。", "雄壮": "无反义关系：“雄壮”形容声势雄浑有力，与“优雅”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98684, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻快", "is_correct": false, "explanation": "无反义关系：“轻快”形容动作灵活敏捷，与“优雅”不相对。"}, {"text": "温柔", "is_correct": false, "explanation": "无反义关系：“温柔”形容性情或态度，不是“优雅”的反面。"}, {"text": "粗俗", "is_correct": true, "explanation": "反义：“优雅”指言谈、风格高雅、不粗俗，“粗俗”与之相反。"}, {"text": "灵巧", "is_correct": false, "explanation": "无反义关系：“灵巧”形容手脚灵活，与“优雅”不构成反义。"}], "correct_answer": "粗俗", "explanations": {"轻快": "无反义关系：“轻快”形容动作灵活敏捷，与“优雅”不相对。", "温柔": "无反义关系：“温柔”形容性情或态度，不是“优雅”的反面。", "粗俗": "反义：“优雅”指言谈、风格高雅、不粗俗，“粗俗”与之相反。", "灵巧": "无反义关系：“灵巧”形容手脚灵活，与“优雅”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98684, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "优美高雅，不粗俗。", "primary_collocate": null, "pronunciation": "yōu yǎ", "ipa": "joʊ̯⁵⁵ ja²¹⁴", "syllable_count": 2, "sentences": [{"text": "他说话很优雅，从来不说粗俗的话。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老先生举止优雅，谈吐也不粗俗。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着一件优雅的旗袍，走进了会场。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首钢琴曲很优雅，听了让人心里很平静。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的家具不多，但是布置得很优雅。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的文字优雅，读起来像诗一样。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的谈吐优雅，不管在哪儿都受人欢迎。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有优雅的老房子和安静的小路。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话粗俗，她说话却很优雅。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会上，她穿得优雅，也唱得很动听。", "target_word": "优雅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "优雅地", "label": "状语形式"}, {"form": "優雅", "label": "繁体"}], "register": "中性", "sense_fingerprint": "言谈、风格、环境等优美高雅，不粗俗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64d38e22-74eb-4da9-84a8-607619094d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98684, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喧闹", "is_correct": false, "explanation": "搭配：“喧闹”形容场所或场面热闹，不用来评价说话的风格。"}, {"text": "优雅", "is_correct": true, "explanation": "“优雅”形容言谈高雅，与后半句“从来不说粗俗的话”相符。"}, {"text": "粗俗", "is_correct": false, "explanation": "语义：“粗俗”与后半句“从来不说粗俗的话”矛盾。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容声音或环境吵乱，不用来形容说话的格调。"}], "explanations": {"喧闹": "搭配：“喧闹”形容场所或场面热闹，不用来评价说话的风格。", "优雅": "“优雅”形容言谈高雅，与后半句“从来不说粗俗的话”相符。", "粗俗": "语义：“粗俗”与后半句“从来不说粗俗的话”矛盾。", "嘈杂": "搭配：“嘈杂”形容声音或环境吵乱，不用来形容说话的格调。"}, "sentence_index": 0, "correct_answer": "优雅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台老机器的噪音很优雅，吵得人睡不着觉。", "explanation": "这里应该用〈刺耳〉。“优雅”只形容言谈、风格、环境的高雅，不用来形容噪音。"}, {"text": "这首进行曲很优雅，听得人热血沸腾。", "explanation": "这里应该用〈激昂〉。“优雅”形容风格柔和、高雅，热血沸腾的进行曲要用〈激昂〉。"}, {"text": "这首歌的唱法很优雅，嗓子吼得沙哑，像在喊叫。", "explanation": "这里应该用〈粗犷〉。“优雅”形容风格柔和高雅，嗓子吼得沙哑、大声喊叫的唱法要用〈粗犷〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”与后半句“不管在哪儿都受人欢迎”矛盾。"}, {"text": "生硬", "is_correct": false, "explanation": "语义：“生硬”与后半句“不管在哪儿都受人欢迎”矛盾。"}, {"text": "优雅", "is_correct": true, "explanation": "“优雅”形容谈吐高雅，与“受人欢迎”相符。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”多形容声音或场所，不用来评价谈吐。"}], "explanations": {"冷淡": "语义：“冷淡”与后半句“不管在哪儿都受人欢迎”矛盾。", "生硬": "语义：“生硬”与后半句“不管在哪儿都受人欢迎”矛盾。", "优雅": "“优雅”形容谈吐高雅，与“受人欢迎”相符。", "吵闹": "搭配：“吵闹”多形容声音或场所，不用来评价谈吐。"}, "sentence_index": 6, "correct_answer": "优雅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只天鹅的叫声很优雅，吵得人头疼。", "explanation": "此处“优雅”只形容言谈、风格、环境的高雅、不粗俗，不能用来形容吵得人头疼的叫声。"}, {"text": "这头野牛很优雅，猛地冲过来撞翻了篱笆。", "explanation": "这里应该用〈凶猛〉。“优雅”形容柔和、高雅，不用于形容冲撞篱笆的野牛。"}, {"text": "他脾气很优雅，一进门就大声骂人。", "explanation": "这里应该用〈暴躁〉。“优雅”形容言行柔和从容，脾气暴躁、大声骂人的人要用〈暴躁〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她说话说很优雅，从不说粗话。", "corrected_sentence": "她说话说得很优雅，从不说粗话。", "error_description": "错误：「说话说很优雅」，动词后接“很优雅”作补语时漏掉“得”。正确：「说话说得很优雅」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他优雅的说了几句话，大家都安静下来。", "corrected_sentence": "他优雅地说了几句话，大家都安静下来。", "error_description": "错误：「优雅的说」，“优雅”修饰动词“说”作状语时误用了“的”。正确：「优雅地说」，应用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
