INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98687, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "元数据是用来说明另一份资料是什么的资料。", "primary_collocate": null, "pronunciation": "yuán shù jù", "ipa": "ɥɛn˧˥ ʂu˥˩ tɕy˥˩", "syllable_count": 3, "sentences": [{"text": "元数据是用来说明另一份资料的资料。", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片的元数据里有拍摄的时间。", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆用元数据说明每本书的作者和出版社。", "target_word": "元数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先看一下这个文件的元数据。", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "元数据能告诉我们文件是谁做的。", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们怎么查看视频的元数据。", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有元数据，我们很难找到想要的资料。", "target_word": "元数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把文件的元数据改了一下。", "target_word": "元数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个音乐文件都有自己的元数据，比如歌手名。", "target_word": "元数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站用元数据告诉搜索引擎这一页讲什么。", "target_word": "元数据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "说明另一份资料内容的资料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90645a6b-93e3-4121-8054-48deb9684cb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98687, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元数据", "is_correct": true, "explanation": "正确：元数据是描述其他资料的资料，与句子的定义一致。"}, {"text": "图书", "is_correct": false, "explanation": "语义：图书本身就是资料，不是用来说明另一份资料的资料。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，不是描述资料内容的资料。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，放在书面的定义句中不合语域。"}], "explanations": {"元数据": "正确：元数据是描述其他资料的资料，与句子的定义一致。", "图书": "语义：图书本身就是资料，不是用来说明另一份资料的资料。", "手机": "语义：手机是通讯工具，不是描述资料内容的资料。", "玩意儿": "语域：“玩意儿”是口语说法，放在书面的定义句中不合语域。"}, "sentence_index": 0, "correct_answer": "元数据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用元数据统计了销量。", "explanation": "这里应该用〈销售记录〉。元数据是说明其他资料是什么的资料，本身不记录销售情况，统计销量要用销售记录。"}, {"text": "他把元数据装进了箱子。", "explanation": "这里应该用〈文件〉。元数据是说明其他资料的资料，它不是可以装进箱子的实物。"}, {"text": "这份元数据讲了一个感人的故事。", "explanation": "这里应该用〈小说〉。元数据只是描述资料的信息，它本身并不讲故事，不能说它讲了感人的故事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98687, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元数据", "is_correct": true, "explanation": "正确：没有元数据，就很难按照描述找到资料，与句意相合。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光与查找资料没有关系，放在这里句意不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，与查找资料无关，放在这里句意不通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，与查找资料没有关系，放在这里句意不通。"}], "explanations": {"元数据": "正确：没有元数据，就很难按照描述找到资料，与句意相合。", "阳光": "语义：阳光与查找资料没有关系，放在这里句意不通。", "钢琴": "语义：钢琴是乐器，与查找资料无关，放在这里句意不通。", "蛋糕": "语义：蛋糕是食物，与查找资料没有关系，放在这里句意不通。"}, "sentence_index": 6, "correct_answer": "元数据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的元数据很精彩。", "explanation": "这里应该用〈内容〉。元数据是描述数据的数据，不是影片本身的内容，不能说“很精彩”。"}, {"text": "这份元数据是一幅很美的画。", "explanation": "这里应该用〈绘画作品〉。元数据是描述其他资料的资料，它不是一幅可以欣赏的画，不能这样描述它。"}, {"text": "这篇文章的元数据很幽默。", "explanation": "这里应该用〈正文〉。元数据是描述文章的信息，并不是文章本身，不能说它幽默。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98687, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只元数据里写着作者的名字。", "corrected_sentence": "这组元数据里写着作者的名字。", "error_description": "量词错误：“只”用于动物或成对的物件，元数据应用“组”或“条”，应改为“这组元数据”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98687, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些元数据们里写着作者的名字。", "corrected_sentence": "这些元数据里写着作者的名字。", "error_description": "“们”只加在指人的名词或代词后，元数据是抽象名词，不能说“元数据们”，应改为“这些元数据”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
