INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98688, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "描述其他数据的信息的数据。", "primary_collocate": null, "pronunciation": "yuán shù jù", "ipa": "ɥɛn˧˥ ʂu˥˩ tɕy˥˩", "syllable_count": 3, "sentences": [{"text": "元数据就是描述其他数据的数据。", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "表格旁边的元数据写着每一列的意思。", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑里的每个文件都有元数据。", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个数据库的元数据放在另一个表里。", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "元数据记录了数据的来源和格式。", "target_word": "元数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先整理数据，再写元数据。", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道这份数据的元数据在哪儿吗？", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的元数据能让数据更容易找到。", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司正在检查所有数据的元数据。", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生要为这些数据写清楚元数据。", "target_word": "元数据", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "描述其他数据的数据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90645a6b-93e3-4121-8054-48deb9684cb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98688, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元数据", "is_correct": true, "explanation": "正确：元数据就是描述其他数据的数据，与句子的定义一致。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是音乐作品，不是描述其他数据的数据。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，与描述数据的定义毫无关系。"}, {"text": "伙计", "is_correct": false, "explanation": "语域：“伙计”是口语说法，放在书面的定义句中不合语域。"}], "explanations": {"元数据": "正确：元数据就是描述其他数据的数据，与句子的定义一致。", "歌曲": "语义：歌曲是音乐作品，不是描述其他数据的数据。", "汽车": "语义：汽车是交通工具，与描述数据的定义毫无关系。", "伙计": "语域：“伙计”是口语说法，放在书面的定义句中不合语域。"}, "sentence_index": 0, "correct_answer": "元数据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用元数据画了一张柱状图。", "explanation": "这里应该用〈数值〉。画柱状图要用具体的数值，元数据只是描述数据的数据，本身不是可以直接画图的数值。"}, {"text": "元数据正在运行。", "explanation": "这里应该用〈程序〉。元数据是描述数据的数据，它本身不能运行，不能像程序一样执行。"}, {"text": "这份元数据是一首很动人的歌。", "explanation": "这里应该用〈歌曲〉。元数据是描述数据的信息，它不是一首歌，不能说它很动人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元数据", "is_correct": true, "explanation": "正确：“元数据”指描述其他数据的数据，放在“这份数据的……”中语义通顺，符合询问的内容。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是大气状况，不是可以存放位置的数据描述，放在这里句意不通。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“这份数据的早饭”搭配不当，“早饭”不能用作“数据”的修饰对象。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，与数据的描述信息无关，放在这里句意不通。"}], "explanations": {"元数据": "正确：“元数据”指描述其他数据的数据，放在“这份数据的……”中语义通顺，符合询问的内容。", "天气": "语义：天气是大气状况，不是可以存放位置的数据描述，放在这里句意不通。", "早饭": "搭配：“这份数据的早饭”搭配不当，“早饭”不能用作“数据”的修饰对象。", "小说": "语义：小说是文学作品，与数据的描述信息无关，放在这里句意不通。"}, "sentence_index": 6, "correct_answer": "元数据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇论文的元数据有三百页，讲的是历史。", "explanation": "这里应该用〈正文〉。元数据是描述其他资料的资料，它不是论文的正文，不能说它有几百页、讲的是历史。"}, {"text": "这篇论文的元数据写得很感人。", "explanation": "这里应该用〈结尾〉。元数据只是描述论文的信息，不是论文的文字内容，不能说它写得感人。"}, {"text": "这篇论文的元数据里画了一只小猫。", "explanation": "这里应该用〈插图〉。元数据只是描述论文的信息，它本身没有画面，不能说里面画了一只小猫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只元数据描述了照片的拍摄时间。", "corrected_sentence": "这组元数据描述了照片的拍摄时间。", "error_description": "量词错误：“只”用于动物或成对的物件，元数据应用“组”或“条”，应改为“这组元数据”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把照片的元数据们整理好了。", "corrected_sentence": "我们把照片的元数据整理好了。", "error_description": "“们”只加在指人的名词或代词后，元数据是抽象名词，不能说“元数据们”，应改为“元数据”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
