INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98691, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "元语言是用来讲另一种语言的语言。", "primary_collocate": null, "pronunciation": "yuán yǔ yán", "ipa": "ɥɛn˧˥ y˨˩ jɛn˧˥", "syllable_count": 3, "sentences": [{"text": "用汉语讲日语语法时，汉语就是元语言。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "元语言是用来说明另一种语言的语言。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书用英语作元语言来教汉语。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课堂上的元语言是学生能听懂的语言。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲语法时用了很多元语言。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在词典里，解释词义的语言就是元语言。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课先介绍什么是元语言，也就是用来讲解语言的语言。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用中文作元语言来学习法语。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "元语言和对象语言不是同一种语言。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词典用简单的元语言写成。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "元语言学", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "书面", "sense_fingerprint": "用来讲解另一种语言的语言", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8ddae9-ae0a-4af4-8122-16a67952f138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98691, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元语言", "is_correct": true, "explanation": "正确。元语言指用来讲解另一种语言的语言，与“用汉语讲日语语法”一致。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指把一种语言转换成另一种，汉语不能等同于翻译，句子说不通。"}, {"text": "词典", "is_correct": false, "explanation": "语义：“词典”是工具书，不是用来讲解语言的语言，“汉语就是词典”不通。"}, {"text": "语法", "is_correct": false, "explanation": "搭配：“就是”后接的应是同类概念，“语法”是语言的规则，不能与“汉语”等同。"}], "explanations": {"元语言": "正确。元语言指用来讲解另一种语言的语言，与“用汉语讲日语语法”一致。", "翻译": "语义：“翻译”指把一种语言转换成另一种，汉语不能等同于翻译，句子说不通。", "词典": "语义：“词典”是工具书，不是用来讲解语言的语言，“汉语就是词典”不通。", "语法": "搭配：“就是”后接的应是同类概念，“语法”是语言的规则，不能与“汉语”等同。"}, "sentence_index": 0, "correct_answer": "元语言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在超市里用元语言跟店员买东西。", "explanation": "这里应该用〈口语〉。元语言用来讲解另一种语言，不用于日常买卖；跟店员买东西要说口语。"}, {"text": "我从小就说元语言，不需要专门学习。", "explanation": "这里应该用〈母语〉。元语言是用来讲解别的语言的语言，不是一个人从小就会说的语言。"}, {"text": "他在国外住了五年，元语言说得很流利。", "explanation": "这里应该用〈外语〉。元语言用来描述语言，不是用来日常交流的语言；说得流利的应是〈外语〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98691, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元语言", "is_correct": true, "explanation": "正确。“什么是元语言”指介绍用来讲解语言的语言这一概念，与课程内容一致。"}, {"text": "数学", "is_correct": false, "explanation": "语义：这门课讲语言，介绍“数学”与课程内容不符。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：“什么是香蕉”与语言课的内容无关，句子不合理。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“什么是”后接的应是需要解释的概念，“地铁”是具体事物，不作为课堂概念讲解。"}], "explanations": {"元语言": "正确。“什么是元语言”指介绍用来讲解语言的语言这一概念，与课程内容一致。", "数学": "语义：这门课讲语言，介绍“数学”与课程内容不符。", "香蕉": "语义：“什么是香蕉”与语言课的内容无关，句子不合理。", "地铁": "搭配：“什么是”后接的应是需要解释的概念，“地铁”是具体事物，不作为课堂概念讲解。"}, "sentence_index": 6, "correct_answer": "元语言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我写信时总用元语言，语气很正式。", "explanation": "这里应该用〈书面语〉。元语言是用来讲解语言的语言，不是写信时用的正式语体；写信用的应是〈书面语〉。"}, {"text": "聋哑人用元语言交流，手势很清楚。", "explanation": "这里应该用〈手语〉。元语言是用来讲解语言的语言，不是靠手势交流的语言；靠手势交流的应是〈手语〉。"}, {"text": "这个词是从英语借来的，所以它叫元语言。", "explanation": "这里应该用〈外来语〉。元语言是用来讲解语言的语言，不是从别的语言借来的词；借来的词应说〈外来语〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "词典里用来解释词义的语言叫元语言们。", "corrected_sentence": "词典里用来解释词义的语言叫元语言。", "error_description": "词缀错误：“元语言”是抽象名词，不能加复数后缀“们”，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套教材用一本简单的元语言写成。", "corrected_sentence": "这套教材用一种简单的元语言写成。", "error_description": "量词错误：“元语言”是一种语言体系，应用量词“种”，不能用“本”（书籍的量词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
