INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来描述或分析另一种语言的语言。", "primary_collocate": null, "pronunciation": "yuán yǔ yán", "ipa": "ɥɛn˧˥ y˨˩ jɛn˧˥", "syllable_count": 3, "sentences": [{"text": "语言学家用元语言分析句子的结构。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写语法书需要清楚的元语言。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章里的元语言太难懂了。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "元语言可以描述一种语言的规则。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者用统一的元语言来记录方言。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生要先看懂书里的元语言。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的元语言应该简单、准确。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论文用英语作元语言来分析汉语。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语法术语也是一种元语言。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授正在研究元语言的特点。", "target_word": "元语言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "元语言学", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "书面", "sense_fingerprint": "描述、分析另一种语言所用的语言", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8ddae9-ae0a-4af4-8122-16a67952f138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98692, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元语言", "is_correct": true, "explanation": "正确。“用元语言分析句子的结构”中，元语言是用来描述语言规则的语言。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”不能用来分析句子的结构，句子不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“水果”与分析句子的结构毫无关系。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“用……分析”需要的是分析手段，“冰箱”不作为分析工具。"}], "explanations": {"元语言": "正确。“用元语言分析句子的结构”中，元语言是用来描述语言规则的语言。", "乐器": "语义：“乐器”不能用来分析句子的结构，句子不通。", "水果": "语义：“水果”与分析句子的结构毫无关系。", "冰箱": "搭配：“用……分析”需要的是分析手段，“冰箱”不作为分析工具。"}, "sentence_index": 0, "correct_answer": "元语言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话常用元语言，朋友们都听得懂。", "explanation": "这里应该用〈俚语〉。元语言用于描述语言，不是日常说话用的词语；说话常用的非正式词语应说〈俚语〉。"}, {"text": "老人们在村里说元语言，年轻人也听得懂。", "explanation": "这里应该用〈方言〉。元语言用于描述或分析语言，不是村里日常使用的话；村里人说的话应说〈方言〉。"}, {"text": "运动员在赛场上喊元语言来加油。", "explanation": "这里应该用〈口号〉。元语言是用来描述或分析语言的语言，不是用来鼓劲的喊话；赛场上喊的应是〈口号〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元语言", "is_correct": true, "explanation": "正确。“好的元语言”指好的描述性语言，应该简单、准确，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能说“应该简单、准确”，句子不通。"}, {"text": "汤", "is_correct": false, "explanation": "语义：“汤”与“简单、准确”搭配不当，句子不合理。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“简单、准确”用于说明、描述，不用来形容家具。"}], "explanations": {"元语言": "正确。“好的元语言”指好的描述性语言，应该简单、准确，句意通顺。", "天气": "语义：“天气”不能说“应该简单、准确”，句子不通。", "汤": "语义：“汤”与“简单、准确”搭配不当，句子不合理。", "沙发": "搭配：“简单、准确”用于说明、描述，不用来形容家具。"}, "sentence_index": 6, "correct_answer": "元语言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首诗用了很多元语言，读起来很有古意。", "explanation": "这里应该用〈古语〉。元语言是用来描述语言的语言，不是诗中的古代词语；诗里古雅的词语应说〈古语〉。"}, {"text": "他把元语言写进歌里，唱给大家听。", "explanation": "这里应该用〈歌词〉。元语言是用来描述语言的语言，不是可以唱的歌词；写进歌里唱的应是〈歌词〉。"}, {"text": "老人嘴里念着元语言，据说能驱赶邪气。", "explanation": "这里应该用〈咒语〉。元语言是用来描述语言的专业语言，不是用来驱邪的话；念来驱邪的应是〈咒语〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些语法术语组成了一本元语言。", "corrected_sentence": "这些语法术语组成了一种元语言。", "error_description": "量词错误：“元语言”是一种语言体系，应用量词“种”，不能用书籍的量词“本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一种好的元语言们应该简单、准确。", "corrected_sentence": "一种好的元语言应该简单、准确。", "error_description": "词缀错误：“元语言”是抽象名词，不能加复数后缀“们”，应说“一种好的元语言”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
