INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98695, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "全家是一家里所有的人。", "primary_collocate": null, "pronunciation": "quán jiā", "ipa": "tɕʰyɛn˧˥ tɕja˥˥", "syllable_count": 2, "sentences": [{"text": "周末全家去公园玩儿。", "target_word": "全家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天全家一起吃饭。", "target_word": "全家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们全家都爱吃饺子。", "target_word": "全家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年全家去过海边。", "target_word": "全家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，全家都回老家。", "target_word": "全家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全家都在看电视。", "target_word": "全家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天全家要去看爷爷。", "target_word": "全家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们全家住在一个小城里。", "target_word": "全家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全家一起做了很多好吃的菜。", "target_word": "全家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，全家都没出门。", "target_word": "全家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全家福", "label": "复合词"}], "register": "中性", "sense_fingerprint": "一家里所有的人，常作主语，如全家去旅游", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caeccb10-6a79-4d7a-87ac-7a371c930c18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98695, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工厂", "is_correct": false, "explanation": "语义：工厂是机构，不会去公园玩儿，“去”的主语应是人或群体。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“去……玩儿”的主语要求是人或群体，教室不能去公园。"}, {"text": "全家", "is_correct": true, "explanation": "“全家”指一家的所有成员，“周末全家去公园玩儿”指一家人一起去公园。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是物品，不能自己去公园玩儿。"}], "explanations": {"工厂": "语义：工厂是机构，不会去公园玩儿，“去”的主语应是人或群体。", "教室": "搭配：“去……玩儿”的主语要求是人或群体，教室不能去公园。", "全家": "“全家”指一家的所有成员，“周末全家去公园玩儿”指一家人一起去公园。", "玩具": "语义：玩具是物品，不能自己去公园玩儿。"}, "sentence_index": 0, "correct_answer": "全家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全家农民都在地里干活。", "explanation": "这里应该用〈全村〉。农民属于村子，全家只指一家人，要用“全村”。"}, {"text": "全家同学都来参加了运动会。", "explanation": "这里应该用〈全班〉。全家指一家人，同学属于班级，要用“全班”。"}, {"text": "全家人民都关心这件事。", "explanation": "这里应该用〈全国〉。人民指全国的人，全家只指一家人，要用“全国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98695, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "树", "is_correct": false, "explanation": "搭配：“去看……”的主语要能移动的人，树不能去看爷爷。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是无生命的物体，不能去看爷爷。"}, {"text": "全家", "is_correct": true, "explanation": "“全家”指一家的所有成员，“明天全家要去看爷爷”指一家人去探望爷爷。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能去看人，“去看爷爷”需要人作主语。"}], "explanations": {"树": "搭配：“去看……”的主语要能移动的人，树不能去看爷爷。", "房子": "语义：房子是无生命的物体，不能去看爷爷。", "全家": "“全家”指一家的所有成员，“明天全家要去看爷爷”指一家人去探望爷爷。", "手机": "语义：手机不能去看人，“去看爷爷”需要人作主语。"}, "sentence_index": 6, "correct_answer": "全家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全家学生都在上课。", "explanation": "这里应该用〈全校〉。全家指一家人的成员，学生属于学校，全校学生要说“全校”。"}, {"text": "全家工人都放假了。", "explanation": "这里应该用〈全厂〉。全家只指一家的家庭成员，工厂里的工人不是家人，要用“全厂”。"}, {"text": "全家将士都在训练。", "explanation": "这里应该用〈全军〉。全家指一家人，部队的官兵要用“全军”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98695, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个全家都去了公园。", "corrected_sentence": "全家都去了公园。", "error_description": "错误：“一个全家”。“全家”本身表示整个家庭，不能用数量词“一个”修饰，应直接说“全家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98695, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下个月全家们都想去海边。", "corrected_sentence": "下个月全家都想去海边。", "error_description": "错误：“全家们”。“们”只加在指人的名词或代词后面表示复数，“全家”已表示整个家庭，不能再加“们”，应说“全家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
