INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98699, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两全是两件事都能顾到，都做好。", "primary_collocate": null, "pronunciation": "liǎng quán", "ipa": "ljɑŋ˨˩˦ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "工作和家庭很难两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习和玩都想要，怎么能两全？", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有没有一个办法可以两全？", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "忠孝不能两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱和时间常常不能两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找一个两全的办法。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我想不出两全的方法。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她既要上班，又要照顾孩子，很难两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事业和爱情，他希望能两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想快又想好，常常不能两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两件事同时顾到并做好，常说难两全、不能两全", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88de35c8-0eb8-4233-8872-c58f86c79787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98699, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "两全", "is_correct": true, "explanation": "正确答案。两全（liǎng quán）指两方面都顾到、都做好。"}, {"text": "两犬", "is_correct": false, "explanation": "两犬（liǎng quǎn）与两全（liǎng quán）第二个音节声调不同：第三声与第二声，意思是两条狗。"}, {"text": "两圈", "is_correct": false, "explanation": "两圈（liǎng quān）与两全（liǎng quán）第二个音节声调不同：第一声与第二声，意思是两周。"}, {"text": "两元", "is_correct": false, "explanation": "两元（liǎng yuán）与两全（liǎng quán）第二个音节声母不同：y 与 q，意思是两块钱。"}], "explanations": {"两全": "正确答案。两全（liǎng quán）指两方面都顾到、都做好。", "两犬": "两犬（liǎng quǎn）与两全（liǎng quán）第二个音节声调不同：第三声与第二声，意思是两条狗。", "两圈": "两圈（liǎng quān）与两全（liǎng quán）第二个音节声调不同：第一声与第二声，意思是两周。", "两元": "两元（liǎng yuán）与两全（liǎng quán）第二个音节声母不同：y 与 q，意思是两块钱。"}, "sentence_index": null, "correct_answer": "两全"}, "level_3": {"options": [{"text": "两全", "is_correct": true, "explanation": "正确答案。“很难两全”指难以两方面都做好，符合句意。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：驾驶需要车辆等对象，不能用来说工作和家庭的处境。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪指做饭，与工作和家庭的处境无关。"}, {"text": "举行", "is_correct": false, "explanation": "搭配：“举行”用于活动、会议，不能说“举行工作和家庭”。"}], "explanations": {"两全": "正确答案。“很难两全”指难以两方面都做好，符合句意。", "驾驶": "语义：驾驶需要车辆等对象，不能用来说工作和家庭的处境。", "烹饪": "语义：烹饪指做饭，与工作和家庭的处境无关。", "举行": "搭配：“举行”用于活动、会议，不能说“举行工作和家庭”。"}, "sentence_index": 0, "correct_answer": "两全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一套两全的工具，修东西很方便。", "explanation": "这里应该用〈齐全〉。齐全指种类完备，用于工具、物品；两全指两方面都顾全，不能用来形容工具的种类是否完备。"}, {"text": "博物馆里有一件两全的古董，保存得很好。", "explanation": "这里应该用〈完好〉。完好指没有损坏；两全指两方面都顾全，不能用来说古董是否完好无损。"}, {"text": "这两个软件能两全，可以一起用。", "explanation": "这里应该用〈兼容〉。兼容指两者能一起使用、互不妨碍；两全指两方面都做好，不用来说软件之间的配合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98699, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "两全", "is_correct": true, "explanation": "正确答案。两全（liǎng quán）指两方面都顾到、都做好。"}, {"text": "两船", "is_correct": false, "explanation": "两船（liǎng chuán）与两全（liǎng quán）第二个音节声母不同：ch 与 q，意思是两条船。"}, {"text": "两团", "is_correct": false, "explanation": "两团（liǎng tuán）与两全（liǎng quán）第二个音节声母不同：t 与 q，意思是两团东西。"}, {"text": "两钱", "is_correct": false, "explanation": "两钱（liǎng qián）与两全（liǎng quán）第二个音节韵母不同：ian 与 uan，“钱”在这里是重量单位。"}], "explanations": {"两全": "正确答案。两全（liǎng quán）指两方面都顾到、都做好。", "两船": "两船（liǎng chuán）与两全（liǎng quán）第二个音节声母不同：ch 与 q，意思是两条船。", "两团": "两团（liǎng tuán）与两全（liǎng quán）第二个音节声母不同：t 与 q，意思是两团东西。", "两钱": "两钱（liǎng qián）与两全（liǎng quán）第二个音节韵母不同：ian 与 uan，“钱”在这里是重量单位。"}, "sentence_index": null, "correct_answer": "两全"}, "level_3": {"options": [{"text": "两全", "is_correct": true, "explanation": "正确答案。“两全的方法”指能两方面都顾好的办法，符合句意。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳指在水中运动，与这件事的解决办法无关。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：演奏指乐器或乐曲的表演，与这件事的解决办法无关。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞指身体的舞动，与这件事的解决办法无关。"}], "explanations": {"两全": "正确答案。“两全的方法”指能两方面都顾好的办法，符合句意。", "游泳": "语义：游泳指在水中运动，与这件事的解决办法无关。", "演奏": "语义：演奏指乐器或乐曲的表演，与这件事的解决办法无关。", "跳舞": "语义：跳舞指身体的舞动，与这件事的解决办法无关。"}, "sentence_index": 6, "correct_answer": "两全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间里桌子、椅子、床都两全了。", "explanation": "这里应该用〈齐全〉。齐全指东西样样都有；两全指两方面都顾全，不能用来说家具是否齐备。"}, {"text": "他写了一部两全的传记，书里几乎没有缺漏。", "explanation": "这里应该用〈完整〉。完整指没有缺漏；两全指两方面都顾全，不能用来形容传记的内容是否齐全。"}, {"text": "这种插头能两全，大多数电器都能用。", "explanation": "这里应该用〈通用〉。通用指一种东西适用于多种对象；两全指两方面都顾全，不能用来说插头的适用范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98699, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他工作和家庭都很两全。", "corrected_sentence": "他工作和家庭都能两全。", "error_description": "错误形式：“很两全”；正确形式：“能两全”。“两全”是动词，不能直接受程度副词“很”修饰，应说“都能两全”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98699, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经两全了过，那是很难得的经历。", "corrected_sentence": "他曾经两全过，那是很难得的经历。", "error_description": "“两全”后面的“了”和“过”重复标记时态，应只用“过”：应说“曾经两全过”，不能说“曾经两全了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
