INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98700, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两方面都顾全。", "primary_collocate": null, "pronunciation": "liǎng quán", "ipa": "ljɑŋ˨˩˦ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "做生意要对客人好，也要自己赚钱，两全不容易。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想帮朋友又不想骗老师，他很难两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望我们学习和身体两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做，大家都高兴，真能两全吗？", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买便宜的又要质量好，不能两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了很久，还是没有办法两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孝顺父母和出国读书，我难以两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们别吵了，我们想想怎么两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间不够，工作和休息不能两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她既想去旅游，又要照顾妈妈，无法两全。", "target_word": "两全", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两个方面都照顾周全，不偏向一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88de35c8-0eb8-4233-8872-c58f86c79787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98700, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "两全", "is_correct": true, "explanation": "正确答案。两全（liǎng quán）指两方面都顾全、不偏向一边。"}, {"text": "两犬", "is_correct": false, "explanation": "两犬（liǎng quǎn）与两全（liǎng quán）第二个音节声调不同：第三声与第二声，意思是两条狗。"}, {"text": "两圈", "is_correct": false, "explanation": "两圈（liǎng quān）与两全（liǎng quán）第二个音节声调不同：第一声与第二声，意思是两周。"}, {"text": "两元", "is_correct": false, "explanation": "两元（liǎng yuán）与两全（liǎng quán）第二个音节声母不同：y 与 q，意思是两块钱。"}], "explanations": {"两全": "正确答案。两全（liǎng quán）指两方面都顾全、不偏向一边。", "两犬": "两犬（liǎng quǎn）与两全（liǎng quán）第二个音节声调不同：第三声与第二声，意思是两条狗。", "两圈": "两圈（liǎng quān）与两全（liǎng quán）第二个音节声调不同：第一声与第二声，意思是两周。", "两元": "两元（liǎng yuán）与两全（liǎng quán）第二个音节声母不同：y 与 q，意思是两块钱。"}, "sentence_index": null, "correct_answer": "两全"}, "level_3": {"options": [{"text": "两全", "is_correct": true, "explanation": "正确答案。“两全不容易”指两方面都做好很难，符合句意。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”指蒙骗他人，与前句“要对客人好”的要求相反，句意不合。"}, {"text": "偷懒", "is_correct": false, "explanation": "语义：偷懒与前文“要对客人好”“要自己赚钱”的要求相反。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：迟到与做生意、赚钱的要求无关，句意不通。"}], "explanations": {"两全": "正确答案。“两全不容易”指两方面都做好很难，符合句意。", "欺骗": "语义：“欺骗”指蒙骗他人，与前句“要对客人好”的要求相反，句意不合。", "偷懒": "语义：偷懒与前文“要对客人好”“要自己赚钱”的要求相反。", "迟到": "语义：迟到与做生意、赚钱的要求无关，句意不通。"}, "sentence_index": 0, "correct_answer": "两全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一套两全的工具，修东西很方便。", "explanation": "这里应该用〈齐全〉。齐全指种类完备，用于工具、物品；两全指两方面都顾全，不能用来形容工具的种类是否完备。"}, {"text": "博物馆里有一件两全的古董，保存得很好。", "explanation": "这里应该用〈完好〉。完好指没有损坏；两全指两方面都顾全，不能用来说古董是否完好无损。"}, {"text": "这两个软件能两全，可以一起用。", "explanation": "这里应该用〈兼容〉。兼容指两者能一起使用、互不妨碍；两全指两方面都做好，不用来说软件之间的配合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98700, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "两全", "is_correct": true, "explanation": "正确答案。两全（liǎng quán）指两方面都顾全、不偏向一边。"}, {"text": "两船", "is_correct": false, "explanation": "两船（liǎng chuán）与两全（liǎng quán）第二个音节声母不同：ch 与 q，意思是两条船。"}, {"text": "两团", "is_correct": false, "explanation": "两团（liǎng tuán）与两全（liǎng quán）第二个音节声母不同：t 与 q，意思是两团东西。"}, {"text": "两钱", "is_correct": false, "explanation": "两钱（liǎng qián）与两全（liǎng quán）第二个音节韵母不同：ian 与 uan，“钱”在这里是重量单位。"}], "explanations": {"两全": "正确答案。两全（liǎng quán）指两方面都顾全、不偏向一边。", "两船": "两船（liǎng chuán）与两全（liǎng quán）第二个音节声母不同：ch 与 q，意思是两条船。", "两团": "两团（liǎng tuán）与两全（liǎng quán）第二个音节声母不同：t 与 q，意思是两团东西。", "两钱": "两钱（liǎng qián）与两全（liǎng quán）第二个音节韵母不同：ian 与 uan，“钱”在这里是重量单位。"}, "sentence_index": null, "correct_answer": "两全"}, "level_3": {"options": [{"text": "两全", "is_correct": true, "explanation": "正确答案。“难以两全”指难以两方面都顾好，符合句意。"}, {"text": "冲突", "is_correct": false, "explanation": "语义：冲突指双方对立，不能用来说“我”一个人的处境。"}, {"text": "收获", "is_correct": false, "explanation": "语义：收获指获得成果，与“孝顺父母和出国读书”的两难处境不符，句意不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：驾驶与孝顺父母、出国读书的处境无关，句意不通。"}], "explanations": {"两全": "正确答案。“难以两全”指难以两方面都顾好，符合句意。", "冲突": "语义：冲突指双方对立，不能用来说“我”一个人的处境。", "收获": "语义：收获指获得成果，与“孝顺父母和出国读书”的两难处境不符，句意不通。", "驾驶": "语义：驾驶与孝顺父母、出国读书的处境无关，句意不通。"}, "sentence_index": 6, "correct_answer": "两全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房里锅、碗、筷子都两全了。", "explanation": "这里应该用〈齐全〉。齐全指东西样样都有；两全指两方面都顾全，不能用来说用品是否齐备。"}, {"text": "他写了一部两全的传记，书里几乎没有缺漏。", "explanation": "这里应该用〈完整〉。完整指没有缺漏；两全指两方面都顾全，不能用来形容传记的内容是否齐全。"}, {"text": "这种插头能两全，大多数电器都能用。", "explanation": "这里应该用〈通用〉。通用指一种东西适用于多种对象；两全指两方面都顾全，不能用来说插头的适用范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她事业和生活都很两全。", "corrected_sentence": "她事业和生活都能两全。", "error_description": "错误形式：“很两全”；正确形式：“能两全”。“两全”是动词，不能直接受程度副词“很”修饰，应说“都能两全”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于很两全了，大家都很佩服。", "corrected_sentence": "他终于两全了，大家都很佩服。", "error_description": "错误形式：“终于很两全了”；正确形式：“终于两全了”。“两全”是动词，不能直接受程度副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
