INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98701, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公社是很多人住在一起、一起干活、一起分东西的集体。", "primary_collocate": null, "pronunciation": "gōng shè", "ipa": "kʊŋ˥˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这个公社里的人一起种地。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公社里的人一起吃饭，一起干活。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想办一个公社。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公社里的东西大家一起分。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人搬进了这个公社。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公社有三十个人。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公社的人每天一起做饭。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公社里学会了种菜。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公社里的孩子一起上课。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友想住进一个公社。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "很多人共同生活、劳动、分配的集体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caeccb10-6a79-4d7a-87ac-7a371c930c18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98701, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是文化场所，里面的人不会一起种地。"}, {"text": "公社", "is_correct": true, "explanation": "“公社”指很多人住在一起、一起干活的集体，“这个公社里的人一起种地”指这样的集体。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，里面的人不会一起种地。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“种地”通常与农村、农田搭配，“银行里的人一起种地”搭配不当。"}], "explanations": {"图书馆": "语义：图书馆是文化场所，里面的人不会一起种地。", "公社": "“公社”指很多人住在一起、一起干活的集体，“这个公社里的人一起种地”指这样的集体。", "地铁": "语义：地铁是交通工具，里面的人不会一起种地。", "银行": "搭配：“种地”通常与农村、农田搭配，“银行里的人一起种地”搭配不当。"}, "sentence_index": 0, "correct_answer": "公社"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家是一个公社，一共只有三口人。", "explanation": "这里应该用〈家庭〉。公社指很多人一起生活、劳动、分配的集体，三口人的家不能称为公社。"}, {"text": "我每天坐公社上班。", "explanation": "这里应该用〈公交〉。公社是共同生活、劳动的集体，不是交通工具，乘车上班要说“公交”。"}, {"text": "他是一名公社，在机关工作。", "explanation": "这里应该用〈公务员〉。公社指共同生活、劳动的集体，是组织而不是人，说某人的身份要用“公务员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98701, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不是人的集体，不能一起做饭。"}, {"text": "公社", "is_correct": true, "explanation": "“公社”指很多人一起生活、劳动、分配的集体，“公社的人每天一起做饭”指这个集体的成员。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“……的人”要求中心语指人或人的集体，“歌曲”不能这样搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头无法做饭，不能作“做饭”的主语。"}], "explanations": {"天空": "语义：天空不是人的集体，不能一起做饭。", "公社": "“公社”指很多人一起生活、劳动、分配的集体，“公社的人每天一起做饭”指这个集体的成员。", "歌曲": "搭配：“……的人”要求中心语指人或人的集体，“歌曲”不能这样搭配。", "石头": "语义：石头无法做饭，不能作“做饭”的主语。"}, "sentence_index": 6, "correct_answer": "公社"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们村门口的公社很宽，通往县城。", "explanation": "这里应该用〈公路〉。公社指共同生活、劳动的集体，不是道路；通往县城的路要说“公路”。"}, {"text": "这所公社有一千个学生。", "explanation": "这里应该用〈学校〉。公社是共同生活、劳动的集体，招收学生、开设课程的机构要说“学校”。"}, {"text": "我每个月都去这家公社剪头发。", "explanation": "这里应该用〈理发店〉。公社是共同生活、劳动的集体，不是理发的场所，剪头发要去“理发店”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98701, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那张公社里的人一起种地。", "corrected_sentence": "那个公社里的人一起种地。", "error_description": "错误：“那张公社”。“张”用于纸、桌子等平面的东西，“公社”是集体组织，不是平面物，应用量词“个”，说“那个公社”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98701, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个公社们的人每天一起做饭。", "corrected_sentence": "那个公社的人每天一起做饭。", "error_description": "错误：“公社们”。“们”加在指人的名词后表示复数，“公社”是集体名词，本身不加“们”，应说“公社的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
