INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98702, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "过去农村中政社合一的基层集体组织。", "primary_collocate": null, "pronunciation": "gōng shè", "ipa": "kʊŋ˥˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷小时候住在公社里。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时公社管着农村的很多事。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公社的书记来村里开会。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在公社工作过。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去农民都是公社的人。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公社的干部住在镇上。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公社后来改成了乡。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，公社那时候很大。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公社的大喇叭每天早上都响。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时农村的学校也归公社管。", "target_word": "公社", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "过去农村中政社合一的基层组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caeccb10-6a79-4d7a-87ac-7a371c930c18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是物品，不能住在里面。"}, {"text": "公社", "is_correct": true, "explanation": "“公社”指过去农村政社合一的基层组织，“爷爷小时候住在公社里”指他住在这一组织所在的地方。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是能住人的处所。"}, {"text": "电影院", "is_correct": false, "explanation": "搭配：“住在……里”一般用于能居住的地方，电影院不能说住在里面。"}], "explanations": {"冰箱": "语义：冰箱是物品，不能住在里面。", "公社": "“公社”指过去农村政社合一的基层组织，“爷爷小时候住在公社里”指他住在这一组织所在的地方。", "海洋": "语义：海洋不是能住人的处所。", "电影院": "搭配：“住在……里”一般用于能居住的地方，电影院不能说住在里面。"}, "sentence_index": 0, "correct_answer": "公社"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我奶奶是一名公社，每天在村里做饭。", "explanation": "这里应该用〈炊事员〉。公社是政社合一的基层组织，不能指人；说某人的职业要用“炊事员”。"}, {"text": "这个公社很结实，可以坐三个人。", "explanation": "这里应该用〈长凳〉。公社是基层组织，不是家具，说东西结实、能坐人要用“长凳”。"}, {"text": "这家公社有三百张病床。", "explanation": "这里应该用〈医院〉。病床属于医疗机构，公社不是医院，不设病床。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火车", "is_correct": false, "explanation": "语义：火车是交通工具，不能改成乡级行政单位。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是教育机构，不能改成乡。"}, {"text": "公社", "is_correct": true, "explanation": "“公社”指过去农村的基层组织，“公社后来改成了乡”指这一组织的变化。"}, {"text": "公司", "is_correct": false, "explanation": "搭配：“改成乡”的主语应是行政单位，公司不能改成乡。"}], "explanations": {"火车": "语义：火车是交通工具，不能改成乡级行政单位。", "学校": "语义：学校是教育机构，不能改成乡。", "公社": "“公社”指过去农村的基层组织，“公社后来改成了乡”指这一组织的变化。", "公司": "搭配：“改成乡”的主语应是行政单位，公司不能改成乡。"}, "sentence_index": 6, "correct_answer": "公社"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那时我们村的公社很小，只卖些油盐酱醋。", "explanation": "这里应该用〈商店〉。公社是政社合一的基层组织，不是卖东西的店铺；买油盐酱醋要去“商店”。"}, {"text": "这家公社每天演两场戏。", "explanation": "这里应该用〈剧院〉。演戏的场所是剧院，公社是基层组织，不是演出场所。"}, {"text": "我们每天都去这家公社游泳。", "explanation": "这里应该用〈游泳馆〉。公社是基层组织，不是供人游泳的场所，去游泳要说“游泳馆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶年轻时在公社们里工作。", "corrected_sentence": "奶奶年轻时在公社里工作。", "error_description": "错误：“公社们”。“们”只加在指人的名词后面，“公社”是表示处所的组织，不能加“们”，应说“在公社里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸说，那时候公社大很。", "corrected_sentence": "爸爸说，那时候公社很大。", "error_description": "错误形式：“大很”。正确形式：“很大”。程度副词“很”应放在形容词“大”前面，说“公社很大”，不能放在“大”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d613e9-003f-4206-bd1a-26c433c78ebb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98705, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
