INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98705, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "典礼是很多人聚在一起，庆祝大事的隆重活动。", "primary_collocate": null, "pronunciation": "diǎn lǐ", "ipa": "tjɛn˨˩ li˨˩", "syllable_count": 2, "sentences": [{"text": "明天学校有一个典礼。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都去参加这个典礼。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "典礼上，大家都很高兴。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "典礼在大礼堂举行。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场典礼有很多人来。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在典礼上唱了一首歌。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "典礼开始前，大家都坐好了。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个典礼很热闹。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我穿着新衣服去参加典礼。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "典礼结束后，我们一起照相。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场典礼", "label": "量词"}, {"form": "一个典礼", "label": "量词"}, {"form": "毕业典礼", "label": "复合"}, {"form": "开幕典礼", "label": "复合"}, {"form": "结婚典礼", "label": "复合"}], "register": "正式", "sense_fingerprint": "很多人聚在一起庆祝大事的隆重活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0979d30-f37e-4aca-8dc4-51c8b00cb872') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98705, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "典礼", "is_correct": true, "explanation": "典礼 diǎnlǐ：隆重举行的庆祝性仪式，与释义相符。"}, {"text": "店里", "is_correct": false, "explanation": "diàn（第四声）与 diǎn（第三声）声调不同，“店里”指商店的里面，意思不对。"}, {"text": "电力", "is_correct": false, "explanation": "diàn 与 lì 都是第四声，与 diǎnlǐ 的声调不同，“电力”指电能，意思不对。"}, {"text": "电离", "is_correct": false, "explanation": "diàn（第四声）与 lí（第二声）声调不同，“电离”指物质分解成离子，意思不对。"}], "explanations": {"典礼": "典礼 diǎnlǐ：隆重举行的庆祝性仪式，与释义相符。", "店里": "diàn（第四声）与 diǎn（第三声）声调不同，“店里”指商店的里面，意思不对。", "电力": "diàn 与 lì 都是第四声，与 diǎnlǐ 的声调不同，“电力”指电能，意思不对。", "电离": "diàn（第四声）与 lí（第二声）声调不同，“电离”指物质分解成离子，意思不对。"}, "sentence_index": null, "correct_answer": "典礼"}, "level_3": {"options": [{"text": "典礼", "is_correct": true, "explanation": "正确。“典礼”是隆重的庆祝活动，可以用“有一个”来引出，句意通顺。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是一段时间，不是学校可以拥有的活动，“明天学校有一个星期”不通。"}, {"text": "周末", "is_correct": false, "explanation": "语义：“周末”是时间段，学校不会“有”周末这样的活动，句子不通。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“有一个”后接的应是活动或事件，“感冒”是疾病，不能说“学校有一个感冒”。"}], "explanations": {"典礼": "正确。“典礼”是隆重的庆祝活动，可以用“有一个”来引出，句意通顺。", "星期": "语义：“星期”是一段时间，不是学校可以拥有的活动，“明天学校有一个星期”不通。", "周末": "语义：“周末”是时间段，学校不会“有”周末这样的活动，句子不通。", "感冒": "搭配：“有一个”后接的应是活动或事件，“感冒”是疾病，不能说“学校有一个感冒”。"}, "sentence_index": 0, "correct_answer": "典礼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天去医院看病，医生给我做了一个典礼。", "explanation": "这里应该用〈检查〉。典礼是隆重的庆祝仪式，医生给病人做的是检查，不能说典礼。"}, {"text": "同学们穿着睡衣在教室里举行了一场典礼，边吃零食边玩游戏。", "explanation": "这里应该用〈晚会〉。典礼是庄重的仪式，穿睡衣、吃零食、玩游戏的娱乐活动应说晚会，与“庄重”不符。"}, {"text": "我参加了一只典礼。", "explanation": "这里量词用错。典礼应用〈场〉，“只”用于动物或小件物品，不能修饰典礼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98705, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "典礼", "is_correct": true, "explanation": "正确。“典礼开始前”指庆祝活动开始之前，大家坐好符合语境。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“雨”不是可以“开始”并让大家“坐好”等待的活动，句子不通。"}, {"text": "地震", "is_correct": false, "explanation": "语义：“地震”是突发的灾害，人们不会在它“开始前”坐好准备，句意不合常理。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电是瞬间的自然现象，不是可以“开始”并让大家“坐好”等待的活动，句子不通。"}], "explanations": {"典礼": "正确。“典礼开始前”指庆祝活动开始之前，大家坐好符合语境。", "雨": "语义：“雨”不是可以“开始”并让大家“坐好”等待的活动，句子不通。", "地震": "语义：“地震”是突发的灾害，人们不会在它“开始前”坐好准备，句意不合常理。", "闪电": "语义：闪电是瞬间的自然现象，不是可以“开始”并让大家“坐好”等待的活动，句子不通。"}, "sentence_index": 6, "correct_answer": "典礼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司每周开一次典礼。", "explanation": "这里应该用〈会议〉。典礼指庄重的仪式，公司每周例行的工作安排应说会议，典礼不指日常会议。"}, {"text": "我们今晚在酒店吃典礼，菜很丰富。", "explanation": "这里应该用〈晚宴〉。典礼是庄重的仪式，不能被吃，今晚在酒店吃的是饭菜，应说晚宴。"}, {"text": "我们在操场上进行了一场典礼，大家跑来跑去比谁跑得快。", "explanation": "这里应该用〈比赛〉。典礼是庄重的仪式，跑来跑去比谁跑得快属于竞技比赛，不能称典礼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98705, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校将在下周做典礼。", "corrected_sentence": "学校将在下周举行典礼。", "error_description": "“做典礼”搭配错误，应说“举行典礼”。典礼通常与“举行”“主持”搭配，“做”不能带“典礼”作宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98705, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家典礼，然后一起吃饭。", "corrected_sentence": "大家参加典礼，然后一起吃饭。", "error_description": "“典礼”是名词，不能直接当动词用，应说“参加典礼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
