INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98706, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "庄重举行的仪式。", "primary_collocate": null, "pronunciation": "diǎn lǐ", "ipa": "tjɛn˨˩ li˨˩", "syllable_count": 2, "sentences": [{"text": "国家举行了隆重的典礼。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "典礼上，校长讲了话。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个典礼很庄重。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在典礼上拿了奖。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "典礼九点开始。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "典礼现场很安静。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长来参加了典礼。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个典礼每年举行一次。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在典礼上穿着校服。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "典礼结束时，大家一起鼓掌。", "target_word": "典礼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场典礼", "label": "量词"}, {"form": "一个典礼", "label": "量词"}, {"form": "颁奖典礼", "label": "复合"}, {"form": "毕业典礼", "label": "复合"}], "register": "正式", "sense_fingerprint": "庄重地举行的仪式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0979d30-f37e-4aca-8dc4-51c8b00cb872') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98706, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "典礼", "is_correct": true, "explanation": "典礼 diǎnlǐ：庄重举行的仪式，与释义相符。"}, {"text": "店里", "is_correct": false, "explanation": "diàn（第四声）与 diǎn（第三声）声调不同，“店里”指商店的里面，意思不对。"}, {"text": "电力", "is_correct": false, "explanation": "diàn 与 lì 都是第四声，与 diǎnlǐ 的声调不同，“电力”指电能，意思不对。"}, {"text": "电离", "is_correct": false, "explanation": "diàn（第四声）与 lí（第二声）声调不同，“电离”指物质分解成离子，意思不对。"}], "explanations": {"典礼": "典礼 diǎnlǐ：庄重举行的仪式，与释义相符。", "店里": "diàn（第四声）与 diǎn（第三声）声调不同，“店里”指商店的里面，意思不对。", "电力": "diàn 与 lì 都是第四声，与 diǎnlǐ 的声调不同，“电力”指电能，意思不对。", "电离": "diàn（第四声）与 lí（第二声）声调不同，“电离”指物质分解成离子，意思不对。"}, "sentence_index": null, "correct_answer": "典礼"}, "level_3": {"options": [{"text": "典礼", "is_correct": true, "explanation": "正确。“隆重的典礼”指庄重举行的仪式，与“国家举行”相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不能被“举行”，也不能“隆重”，句子不通。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：“游戏”不是可以“隆重”举行的仪式，国家不会举行隆重的游戏。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“举行”后接的是仪式或活动，不能说“举行作业”。"}], "explanations": {"典礼": "正确。“隆重的典礼”指庄重举行的仪式，与“国家举行”相符。", "感冒": "语义：感冒是疾病，不能被“举行”，也不能“隆重”，句子不通。", "游戏": "语义：“游戏”不是可以“隆重”举行的仪式，国家不会举行隆重的游戏。", "作业": "搭配：“举行”后接的是仪式或活动，不能说“举行作业”。"}, "sentence_index": 0, "correct_answer": "典礼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师每天下午给我们上一个典礼。", "explanation": "这里应该用〈课〉。典礼是庄重举行的仪式，老师每天给学生上的是课，不能说典礼。"}, {"text": "同学们穿着拖鞋在操场上举行了一场典礼，一边跳舞一边喝饮料。", "explanation": "这里应该用〈联欢〉。典礼是庄重的仪式，穿拖鞋跳舞喝饮料的联欢活动不能称典礼。"}, {"text": "老师参加了一只典礼。", "explanation": "这里量词用错。典礼应用〈场〉，“只”用于动物或小件物品，不能修饰典礼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "典礼", "is_correct": true, "explanation": "正确。“参加典礼”是常见搭配，“市长来参加了”指市长出席这一仪式。"}, {"text": "公园", "is_correct": false, "explanation": "配价：“参加”要求带活动类宾语，“公园”是地点，不能作为“参加”的对象。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不是可以参加的活动，“参加了感冒”不通。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“雨”不是人可以参加的事件，句子不通。"}], "explanations": {"典礼": "正确。“参加典礼”是常见搭配，“市长来参加了”指市长出席这一仪式。", "公园": "配价：“参加”要求带活动类宾语，“公园”是地点，不能作为“参加”的对象。", "感冒": "语义：“感冒”是疾病，不是可以参加的活动，“参加了感冒”不通。", "雨": "语义：“雨”不是人可以参加的事件，句子不通。"}, "sentence_index": 6, "correct_answer": "典礼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司每周开一次典礼。", "explanation": "这里应该用〈会议〉。典礼指庄重的仪式，公司每周例行的工作安排应说会议，典礼不指日常会议。"}, {"text": "学生们在操场上举行典礼，谁先跑到终点谁赢。", "explanation": "这里应该用〈比赛〉。典礼是庄重的仪式，谁先跑到终点谁赢属于竞技比赛，不能称典礼。"}, {"text": "学校每学期举行一次典礼，家长们和老师单独谈孩子的成绩。", "explanation": "这里应该用〈家长会〉。典礼是庄重的仪式，家长与老师私下谈孩子的成绩属于家长会，不能称典礼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长做了这场典礼。", "corrected_sentence": "校长主持了这场典礼。", "error_description": "“做典礼”搭配错误，应说“主持典礼”。典礼宜与“主持”“举行”等动词搭配，“做”不能带“典礼”作宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天要典礼。", "corrected_sentence": "我们明天要参加典礼。", "error_description": "“典礼”是名词，不能直接当动词用，应说“参加典礼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
