INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98709, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分送是把东西一份一份地送给不同的人。", "primary_collocate": null, "pronunciation": "fēn sòng", "ipa": "fən˥ suŋ˥˩", "syllable_count": 2, "sentences": [{"text": "过节时，他把水果分成几份，分送给邻居。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶做了饺子，分送给左右邻居。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把蛋糕切好，一份一份分送给朋友。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把苹果分送到每个人手里。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王把旅行买的小礼物分送给同事。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把煮好的汤分送给三位老人。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长把书分送给山区的孩子们。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己种的菜分送给朋友。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者把面包分送给街上的人。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人把新米分送给每一户。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分送了", "label": "体标"}, {"form": "分送过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把东西分成几份，一份一份送给不同的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0979d30-f37e-4aca-8dc4-51c8b00cb872') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98709, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分送", "is_correct": true, "explanation": "正确：分送指一份一份送给不同的人，与“分成几份……给邻居”相符。"}, {"text": "收", "is_correct": false, "explanation": "语义：收是收取，与“分成几份后送给邻居”的方向相反。"}, {"text": "藏", "is_correct": false, "explanation": "搭配：藏是隐藏，不能说把分好的水果藏给邻居。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧是焚毁，与送给邻居的意思不符。"}], "explanations": {"分送": "正确：分送指一份一份送给不同的人，与“分成几份……给邻居”相符。", "收": "语义：收是收取，与“分成几份后送给邻居”的方向相反。", "藏": "搭配：藏是隐藏，不能说把分好的水果藏给邻居。", "烧": "语义：烧是焚毁，与送给邻居的意思不符。"}, "sentence_index": 0, "correct_answer": "分送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这份感情分送给了他。", "explanation": "这里应该用〈分享〉。分送用于可递送的实物，感情不能分送，应说“分享”。"}, {"text": "老板把任务分送给每个人。", "explanation": "这里应该用〈分配〉。分送用于把实物送到各人手中，任务、工作要用“分配”。"}, {"text": "他把一个笑话分送给了大家。", "explanation": "这里应该用〈讲〉。分送用于把实物一份一份送给别人，笑话是说出来的，应说“给大家讲了一个笑话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98709, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分送", "is_correct": true, "explanation": "正确：分送指分别送给各人，与“把书分送给山区的孩子们”相符。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是撕裂，与把书送给孩子们的意思不符。"}, {"text": "压", "is_correct": false, "explanation": "搭配：压是按压，不能与“送给孩子们”搭配。"}, {"text": "锁", "is_correct": false, "explanation": "语义：锁是上锁，与送书的意思相反。"}], "explanations": {"分送": "正确：分送指分别送给各人，与“把书分送给山区的孩子们”相符。", "撕": "语义：撕是撕裂，与把书送给孩子们的意思不符。", "压": "搭配：压是按压，不能与“送给孩子们”搭配。", "锁": "语义：锁是上锁，与送书的意思相反。"}, "sentence_index": 6, "correct_answer": "分送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一座山分送给了朋友。", "explanation": "这里应该用〈转让〉。分送只用于可递送的物品，山是不动产，不能分送。"}, {"text": "我把一份合同分送到东京。", "explanation": "这里应该用〈寄〉。分送要分别送到各处，只寄往一个地方时用“寄”。"}, {"text": "他把这一天分送给了朋友。", "explanation": "这里应该用〈分享〉。分送用于把实物分别送出，时间不能分送；“分享”才用于把时间、快乐等抽象内容告诉别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98709, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把包子分成几盘，分送向邻居。", "corrected_sentence": "妈妈把包子分成几盘，分送给邻居。", "error_description": "介词用错：分送时接受者前应用“给”引出，“向”不能这样用，应说“分送给邻居”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98709, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里人把鱼分送分给各家。", "corrected_sentence": "村里人把鱼分送给各家。", "error_description": "“分送”与“分给”意思重复，只用其一；应说“分送给各家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
