INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98710, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分别送给各人或各处。", "primary_collocate": null, "pronunciation": "fēn sòng", "ipa": "fən˥ suŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师把新书分送给每位同学。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把月饼分送到各个部门。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者每天分送早饭到各个小区。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员把包裹分送到不同的楼。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节前，妈妈把礼物分送给亲戚。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把通知分送给各班。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把报纸分送到每家门口。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把水分送到各个工地。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把资料分送给了大家。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆把新书分送到各个分馆。", "target_word": "分送", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分送了", "label": "体标"}, {"form": "分送过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把东西或文件分别送到各个地方或各个部门、各个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0979d30-f37e-4aca-8dc4-51c8b00cb872') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分送", "is_correct": true, "explanation": "正确：分送指分别送给各人，与“把新书……给每位同学”相符。"}, {"text": "收", "is_correct": false, "explanation": "语义：收是收取，与“送给每位同学”的方向相反。"}, {"text": "藏", "is_correct": false, "explanation": "搭配：藏是隐藏，不能说把书藏给同学。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧是焚毁，与把书送给同学的意思不符。"}], "explanations": {"分送": "正确：分送指分别送给各人，与“把新书……给每位同学”相符。", "收": "语义：收是收取，与“送给每位同学”的方向相反。", "藏": "搭配：藏是隐藏，不能说把书藏给同学。", "烧": "语义：烧是焚毁，与把书送给同学的意思不符。"}, "sentence_index": 0, "correct_answer": "分送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这份心事分送给了他。", "explanation": "这里应该用〈分享〉。分送用于可递送的实物，心事不能分送，应说“分享”。"}, {"text": "公司把任务分送给每个部门。", "explanation": "这里应该用〈分配〉。分送用于把实物送到各处，任务、工作要用“分配”。"}, {"text": "他把一首歌分送给了大家。", "explanation": "这里应该用〈唱〉。分送用于把实物分别送到各人或各处，歌是唱出来的，应说“给大家唱了一首歌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分送", "is_correct": true, "explanation": "正确：分送指分别送到各处，与“把报纸送到每家门口”相符。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：撕是撕裂，不能与“送到每家门口”搭配。"}, {"text": "压", "is_correct": false, "explanation": "搭配：压是按压，不能表示把报纸送达门口。"}, {"text": "锁", "is_correct": false, "explanation": "语义：锁是上锁，与送报纸的意思不符。"}], "explanations": {"分送": "正确：分送指分别送到各处，与“把报纸送到每家门口”相符。", "撕": "搭配：撕是撕裂，不能与“送到每家门口”搭配。", "压": "搭配：压是按压，不能表示把报纸送达门口。", "锁": "语义：锁是上锁，与送报纸的意思不符。"}, "sentence_index": 6, "correct_answer": "分送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这栋楼分送给了邻居。", "explanation": "这里应该用〈转让〉。分送用于可递送的物品，房屋不能分送，应说“转让”。"}, {"text": "我把一份合同分送到东京。", "explanation": "这里应该用〈寄〉。分送要分别送到各个地方，只寄往一个地方时用“寄”。"}, {"text": "这场比赛被分送到各个城市。", "explanation": "这里误用了〈分送〉。分送只用于把实物分别送出，比赛是活动，不能分送；比赛的转播应说〈播送〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把节日礼物分送在每个班。", "corrected_sentence": "学校把节日礼物分送给每个班。", "error_description": "介词错误：“分送”的接收对象要用“给”，不能用“在”。应说“把节日礼物分送给每个班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区把节日礼物分送在每户。", "corrected_sentence": "社区把节日礼物分送到每户。", "error_description": "介词错误：“分送”的目的地要用“到”，不能用“在”。应说“把节日礼物分送到每户”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98713, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放任", "is_correct": true, "explanation": "放任：听任别人做下去，不加阻止，与“制止”正相反。"}, {"text": "修理", "is_correct": false, "explanation": "修理指修复器物，与“制止”没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫指清除脏物，与“制止”没有反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "收集指把东西聚拢起来，与“制止”没有反义关系。"}], "correct_answer": "放任", "explanations": {"放任": "放任：听任别人做下去，不加阻止，与“制止”正相反。", "修理": "修理指修复器物，与“制止”没有反义关系。", "打扫": "打扫指清除脏物，与“制止”没有反义关系。", "收集": "收集指把东西聚拢起来，与“制止”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98713, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "纵容", "is_correct": true, "explanation": "纵容：对不良行为不加制止、任其发展，与“制止”正相反。"}, {"text": "庆祝", "is_correct": false, "explanation": "庆祝指以活动表示喜悦，与“制止”没有反义关系。"}, {"text": "欢迎", "is_correct": false, "explanation": "欢迎指热情接待，与“制止”没有反义关系。"}, {"text": "参观", "is_correct": false, "explanation": "参观指到某处观看，与“制止”没有反义关系。"}], "correct_answer": "纵容", "explanations": {"纵容": "纵容：对不良行为不加制止、任其发展，与“制止”正相反。", "庆祝": "庆祝指以活动表示喜悦，与“制止”没有反义关系。", "欢迎": "欢迎指热情接待，与“制止”没有反义关系。", "参观": "参观指到某处观看，与“制止”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98713, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "制止是叫别人别再做下去。", "primary_collocate": null, "pronunciation": "zhì zhǐ", "ipa": "ʈʂɻ̩˥˩ ʈʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈制止弟弟再玩手机。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师制止同学说话。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到他在墙上乱画，我马上制止了。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸大声制止孩子在路上跑。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想制止朋友再喝酒，可是没用。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我劝他，也制止过他，他还是抽烟。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在旁边制止他们吵架。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看到了，就制止他们乱扔垃圾。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到他说脏话，老师立刻制止。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一冲动，要在会上跟人吵起来，同事赶紧制止了他。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制止了", "label": "完成体"}, {"form": "制止过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "出面叫别人不要继续做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1baa88c0-478f-4d07-801d-78f872fad5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98713, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "智齿", "is_correct": false, "explanation": "chǐ（第三声）与 zhǐ（第三声）声母不同（ch 与 zh），意思是智齿（一种牙）。"}, {"text": "制止", "is_correct": true, "explanation": "制止（zhì zhǐ）：叫别人不要再做下去。"}, {"text": "住址", "is_correct": false, "explanation": "第一个音节 zhù（第四声）与 zhì（第四声）韵母不同（u 与 i），意思是住址。"}, {"text": "治理", "is_correct": false, "explanation": "第二个音节 lǐ（第三声）与 zhǐ（第三声）声母不同（l 与 zh），意思是治理、管理。"}], "explanations": {"智齿": "chǐ（第三声）与 zhǐ（第三声）声母不同（ch 与 zh），意思是智齿（一种牙）。", "制止": "制止（zhì zhǐ）：叫别人不要再做下去。", "住址": "第一个音节 zhù（第四声）与 zhì（第四声）韵母不同（u 与 i），意思是住址。", "治理": "第二个音节 lǐ（第三声）与 zhǐ（第三声）声母不同（l 与 zh），意思是治理、管理。"}, "sentence_index": null, "correct_answer": "制止"}, "level_3": {"options": [{"text": "劝", "is_correct": false, "explanation": "语义：“劝”是劝说，“劝弟弟再玩手机”与妈妈阻止他玩的意思相反。"}, {"text": "制止", "is_correct": true, "explanation": "制止：叫弟弟不要再做下去，符合句意。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要物品作宾语，“送弟弟”后不能直接接“再玩手机”这样的动作。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸”是称赞，“夸弟弟再玩手机”与句中妈妈管束的语境不符。"}], "explanations": {"劝": "语义：“劝”是劝说，“劝弟弟再玩手机”与妈妈阻止他玩的意思相反。", "制止": "制止：叫弟弟不要再做下去，符合句意。", "送": "配价：“送”需要物品作宾语，“送弟弟”后不能直接接“再玩手机”这样的动作。", "夸": "语义：“夸”是称赞，“夸弟弟再玩手机”与句中妈妈管束的语境不符。"}, "sentence_index": 0, "correct_answer": "制止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "闹钟制止了他睡懒觉。", "explanation": "这里应该用〈叫醒〉。制止指有权出面的人叫人停止做某事，闹钟不能“制止”人。"}, {"text": "天气预报制止了我们去郊游。", "explanation": "这里应该用〈让……取消〉。制止要有人出面叫人停下，天气预报不能“制止”人，应说“天气预报让我们取消了郊游”。"}, {"text": "司机制止了汽车。", "explanation": "这里应该用〈刹住〉。制止指叫人停止做某事，汽车不能被制止，应说刹住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98713, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "试纸", "is_correct": false, "explanation": "第一个音节 shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是试纸。"}, {"text": "制止", "is_correct": true, "explanation": "制止（zhì zhǐ）：叫别人不要再做下去。"}, {"text": "纸质", "is_correct": false, "explanation": "两个音节的声调都与“制止”不同（zhǐ zhì），意思是纸质。"}, {"text": "质子", "is_correct": false, "explanation": "第二个音节 zǐ（第三声）与 zhǐ（第三声）声母不同（z 与 zh），意思是质子。"}], "explanations": {"试纸": "第一个音节 shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是试纸。", "制止": "制止（zhì zhǐ）：叫别人不要再做下去。", "纸质": "两个音节的声调都与“制止”不同（zhǐ zhì），意思是纸质。", "质子": "第二个音节 zǐ（第三声）与 zhǐ（第三声）声母不同（z 与 zh），意思是质子。"}, "sentence_index": null, "correct_answer": "制止"}, "level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示喜爱赞赏，与句中“吵架”的负面内容冲突。"}, {"text": "制止", "is_correct": true, "explanation": "制止：叫他们不要再吵下去，符合句意。"}, {"text": "安慰", "is_correct": false, "explanation": "搭配：“安慰”的对象是难过或受伤的人，不能用于“他们吵架”这类行为。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”的宾语应是对自己有帮助的人或事，不能接“他们吵架”。"}], "explanations": {"欣赏": "语义：“欣赏”表示喜爱赞赏，与句中“吵架”的负面内容冲突。", "制止": "制止：叫他们不要再吵下去，符合句意。", "安慰": "搭配：“安慰”的对象是难过或受伤的人，不能用于“他们吵架”这类行为。", "感谢": "配价：“感谢”的宾语应是对自己有帮助的人或事，不能接“他们吵架”。"}, "sentence_index": 6, "correct_answer": "制止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师制止了同学的勇气。", "explanation": "这里应该用〈赞美〉。制止用于叫人停止做某事，“勇气”不能被制止。"}, {"text": "他制止了朋友的帮助。", "explanation": "这里应该用〈拒绝〉。制止针对人的行为，“帮助”不能被制止，应说拒绝。"}, {"text": "他很快制止了自己的脸红。", "explanation": "这里应该用〈掩饰〉。制止针对人的行为，脸红是生理反应，不能被叫停，应说掩饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把争吵制止。", "corrected_sentence": "妈妈把争吵制止了。", "error_description": "“把”字句的谓语动词后须带“了”或其他成分才完整，应说“妈妈把争吵制止了”，不能说“妈妈把争吵制止”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于制止了住我的冲动。", "corrected_sentence": "他终于制止住了我的冲动。", "error_description": "结果补语“住”应紧跟动词，“了”放在“住”后，说“制止住了”。错误形式“制止了住”把“了”插在补语前，不符合汉语语序。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
