INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98714, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "强迫使停止行动。", "primary_collocate": null, "pronunciation": "zhì zhǐ", "ipa": "ʈʂɻ̩˥˩ ʈʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察及时制止了打架。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师马上制止了他们的吵闹。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安制止他进入大楼。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府制止了乱收费。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要制止浪费粮食的行为。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察制止了围观的人继续靠近。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路人冲上去制止小偷逃跑。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司制止了员工乱用电脑。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长制止了比赛里的暴力动作。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安大声制止，他才停下来。", "target_word": "制止", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制止了", "label": "完成体"}, {"form": "制止过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "以强制手段使不良行为停止", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1baa88c0-478f-4d07-801d-78f872fad5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98714, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "智齿", "is_correct": false, "explanation": "chǐ（第三声）与 zhǐ（第三声）声母不同（ch 与 zh），意思是智齿（一种牙）。"}, {"text": "制止", "is_correct": true, "explanation": "制止（zhì zhǐ）：强迫使停止行动。"}, {"text": "住址", "is_correct": false, "explanation": "第一个音节 zhù（第四声）与 zhì（第四声）韵母不同（u 与 i），意思是住址。"}, {"text": "治理", "is_correct": false, "explanation": "第二个音节 lǐ（第三声）与 zhǐ（第三声）声母不同（l 与 zh），意思是治理、管理。"}], "explanations": {"智齿": "chǐ（第三声）与 zhǐ（第三声）声母不同（ch 与 zh），意思是智齿（一种牙）。", "制止": "制止（zhì zhǐ）：强迫使停止行动。", "住址": "第一个音节 zhù（第四声）与 zhì（第四声）韵母不同（u 与 i），意思是住址。", "治理": "第二个音节 lǐ（第三声）与 zhǐ（第三声）声母不同（l 与 zh），意思是治理、管理。"}, "sentence_index": null, "correct_answer": "制止"}, "level_3": {"options": [{"text": "参与", "is_correct": false, "explanation": "语义：“参与”是加入某件事。警察参与打架，与“及时”制止的意思相反。"}, {"text": "制止", "is_correct": true, "explanation": "制止：用强制手段叫人停止打架，符合句意。"}, {"text": "躲", "is_correct": false, "explanation": "搭配：“躲”表示躲开人或东西，不能直接以“打架”作宾语。"}, {"text": "奖励", "is_correct": false, "explanation": "配价：“奖励”需要受奖的人，“奖励了打架”不成立。"}], "explanations": {"参与": "语义：“参与”是加入某件事。警察参与打架，与“及时”制止的意思相反。", "制止": "制止：用强制手段叫人停止打架，符合句意。", "躲": "搭配：“躲”表示躲开人或东西，不能直接以“打架”作宾语。", "奖励": "配价：“奖励”需要受奖的人，“奖励了打架”不成立。"}, "sentence_index": 0, "correct_answer": "制止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一场大雨制止了我们去公园。", "explanation": "这里应该用〈阻止〉。制止要用强制手段叫人停止不良行为，大雨不能“制止”人。"}, {"text": "妈妈用药制止了他的咳嗽。", "explanation": "这里应该用〈止住〉。制止针对人的不良行为，咳嗽是身体症状，不能被制止，应说止住咳嗽。"}, {"text": "他因为生病制止了这份工作。", "explanation": "这里应该用〈辞去〉。制止指强制停止不良行为，个人因病离职应说辞去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98714, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "纸质", "is_correct": false, "explanation": "两个音节的声调都与“制止”不同（zhǐ zhì），意思是纸质。"}, {"text": "制止", "is_correct": true, "explanation": "制止（zhì zhǐ）：强迫使停止行动。"}, {"text": "试纸", "is_correct": false, "explanation": "第一个音节 shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是试纸。"}, {"text": "质子", "is_correct": false, "explanation": "第二个音节 zǐ（第三声）与 zhǐ（第三声）声母不同（z 与 zh），意思是质子。"}], "explanations": {"纸质": "两个音节的声调都与“制止”不同（zhǐ zhì），意思是纸质。", "制止": "制止（zhì zhǐ）：强迫使停止行动。", "试纸": "第一个音节 shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是试纸。", "质子": "第二个音节 zǐ（第三声）与 zhǐ（第三声）声母不同（z 与 zh），意思是质子。"}, "sentence_index": null, "correct_answer": "制止"}, "level_3": {"options": [{"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”的宾语是来客，不能接“小偷逃跑”这样的动作。"}, {"text": "制止", "is_correct": true, "explanation": "制止：叫人停止继续做某事，符合句意。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”针对场所或展览，不能用于小偷的逃跑动作。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”是庆贺，路人祝贺小偷逃跑与句意冲突。"}], "explanations": {"欢迎": "配价：“欢迎”的宾语是来客，不能接“小偷逃跑”这样的动作。", "制止": "制止：叫人停止继续做某事，符合句意。", "参观": "搭配：“参观”针对场所或展览，不能用于小偷的逃跑动作。", "祝贺": "语义：“祝贺”是庆贺，路人祝贺小偷逃跑与句意冲突。"}, "sentence_index": 6, "correct_answer": "制止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "守门员用手制止了飞来的足球。", "explanation": "这里应该用〈挡住〉。制止用于叫人停止做某事，足球不能被制止。"}, {"text": "他很快制止了那条发错的消息。", "explanation": "这里应该用〈撤回〉。制止针对人的行为，已经发出的消息应说撤回。"}, {"text": "他拼命制止眼泪，却还是哭了。", "explanation": "这里应该用〈忍住〉。眼泪不是可以叫停的行为，应说忍住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察把打架制止。", "corrected_sentence": "警察把打架制止了。", "error_description": "“把”字句的谓语动词后须带“了”或其他成分才完整，应说“警察把打架制止了”，不能说“警察把打架制止”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "保安终于制止了住那场争吵。", "corrected_sentence": "保安终于制止住了那场争吵。", "error_description": "结果补语“住”应紧跟动词，“了”放在“住”后，说“制止住了”。错误形式“制止了住”把“了”插在补语前，不符合汉语语序。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32ed84d-a66b-4e0f-83e5-19a3b61855aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
