INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98721, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "反弹是东西碰到别的东西，又跳回来。", "primary_collocate": null, "pronunciation": "fǎn tán", "ipa": "fan˨˩ tʰan˧˥", "syllable_count": 2, "sentences": [{"text": "球打在墙上，又反弹回来了。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮球掉在地上，反弹得很高。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力一踢，球碰到门柱反弹了。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小石头打到玻璃上，反弹到了地上。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球碰到篮板后反弹出来了。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨点打在伞上，立刻反弹开了。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乒乓球打到桌子上会反弹。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小球打在铁门上，反弹了好几次。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把球扔向地面，球反弹到他手里。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "橡皮球比铁球更容易反弹。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反弹了", "label": "体标"}, {"form": "反弹过", "label": "体标"}], "register": "中性", "sense_fingerprint": "反弹|物体碰到后弹回来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88de35c8-0eb8-4233-8872-c58f86c79787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98721, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反弹", "is_correct": true, "explanation": "正确。反弹指物体碰到别的东西后弹回，球打在墙上又回来，符合这一义项。"}, {"text": "散开", "is_correct": false, "explanation": "语义：“散开”指分散开来，球撞墙后不会四散，与“又……回来”的方向不合。"}, {"text": "碎裂", "is_correct": false, "explanation": "语义：“碎裂”指破成碎块，球撞墙并不会碎，句意说的是弹回，不是破裂。"}, {"text": "投掷", "is_correct": false, "explanation": "配价：“投掷”需要有人施力，球不能自己投掷，句中没有施力的人，搭配不当。"}], "explanations": {"反弹": "正确。反弹指物体碰到别的东西后弹回，球打在墙上又回来，符合这一义项。", "散开": "语义：“散开”指分散开来，球撞墙后不会四散，与“又……回来”的方向不合。", "碎裂": "语义：“碎裂”指破成碎块，球撞墙并不会碎，句意说的是弹回，不是破裂。", "投掷": "配价：“投掷”需要有人施力，球不能自己投掷，句中没有施力的人，搭配不当。"}, "sentence_index": 0, "correct_answer": "反弹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳从东方反弹起来了。", "explanation": "这里应该用〈升起〉。反弹指物体碰到东西后弹回，太阳从地平线升起不是碰撞后的回弹，应说升起。"}, {"text": "对方发起进攻，我们迅速反弹。", "explanation": "这里应该用〈反击〉。反弹指物体碰到东西后弹回，回击进攻要说反击，不能说反弹。"}, {"text": "这件衣服不合适，我把它反弹给了店家。", "explanation": "这里应该用〈退还〉。反弹指物体碰到东西后弹回，把东西退还给店家要说退还，不能说反弹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98721, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反弹", "is_correct": true, "explanation": "正确。反弹指碰到物体后弹回，乒乓球落到桌上会弹起，符合句意。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体遇热变成液体，乒乓球打到桌子上不会融化。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”指变成冰或停止流动，与乒乓球撞击桌面的情况无关。"}, {"text": "点头", "is_correct": false, "explanation": "配价：“点头”需要有生命的主语，乒乓球没有生命，不能点头。"}], "explanations": {"反弹": "正确。反弹指碰到物体后弹回，乒乓球落到桌上会弹起，符合句意。", "融化": "语义：“融化”指固体遇热变成液体，乒乓球打到桌子上不会融化。", "冻结": "语义：“冻结”指变成冰或停止流动，与乒乓球撞击桌面的情况无关。", "点头": "配价：“点头”需要有生命的主语，乒乓球没有生命，不能点头。"}, "sentence_index": 6, "correct_answer": "反弹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出差三天后反弹回了家乡。", "explanation": "这里应该用〈返回〉。反弹指物体碰到东西后弹回，人从外地回到家乡应说返回。"}, {"text": "我把工资反弹进了银行卡。", "explanation": "这里应该用〈存入〉。反弹指物体碰到东西后弹回，把钱存入账户要说存入，不能说反弹。"}, {"text": "沉船慢慢反弹到了海底。", "explanation": "这里应该用〈下沉〉。反弹要求物体碰撞后弹回，沉船慢慢沉入海底应说下沉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98721, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个篮球从台阶上反弹地特别高。", "corrected_sentence": "这个篮球从台阶上反弹得特别高。", "error_description": "“地”应改为“得”：“反弹”后面的程度补语要用“得”，“地”只用在动词前作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98721, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "排球撞到地面后，又反弹到来了。", "corrected_sentence": "排球撞到地面后，又反弹回来了。", "error_description": "“反弹”后的趋向补语应为“回来”，不能用“到来”：“到来”表示来临，不用于物体弹回。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
