INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98722, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "反弹指价格、股价等下降后又回升。", "primary_collocate": null, "pronunciation": "fǎn tán", "ipa": "fan˨˩ tʰan˧˥", "syllable_count": 2, "sentences": [{"text": "股价跌了三天，今天开始反弹了。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房价下降以后，最近又反弹了。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情结束后，旅游人数快速反弹。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上个月物价下降，这个月又反弹了。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的股票先下跌，后来慢慢反弹了。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济不好的时候，汽车销量反弹得很慢。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只股票上周跌得很厉害，这周终于反弹了。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜价跌得太低，下个月一定会反弹。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥以后体重很容易反弹。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手机的价格下降后，很快又反弹了。", "target_word": "反弹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反弹了", "label": "体标"}, {"form": "反弹过", "label": "体标"}], "register": "中性", "sense_fingerprint": "反弹|下降后又回升", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88de35c8-0eb8-4233-8872-c58f86c79787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反弹", "is_correct": true, "explanation": "正确。反弹指下降后又回升，股价跌了三天后今天回升，符合句意。"}, {"text": "枯竭", "is_correct": false, "explanation": "语义：“枯竭”指资源用尽，用来说股价不合适，与“开始……了”的回升不符。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火焰或灯光等停止发光，不能用来描述股价。"}, {"text": "讲话", "is_correct": false, "explanation": "配价：“讲话”需要有生命的主语，股价不能讲话，主语与动词搭配不上。"}], "explanations": {"反弹": "正确。反弹指下降后又回升，股价跌了三天后今天回升，符合句意。", "枯竭": "语义：“枯竭”指资源用尽，用来说股价不合适，与“开始……了”的回升不符。", "熄灭": "语义：“熄灭”指火焰或灯光等停止发光，不能用来描述股价。", "讲话": "配价：“讲话”需要有生命的主语，股价不能讲话，主语与动词搭配不上。"}, "sentence_index": 0, "correct_answer": "反弹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "阳光下，湖水慢慢反弹了。", "explanation": "这里应该用〈蒸发〉。反弹指先下降后回升，水分变成气体散失要说蒸发，不能说反弹。"}, {"text": "这块冰在阳光下很快反弹了。", "explanation": "这里应该用〈融化〉。反弹指先下降后回升，冰受热变成水要说融化，不能说反弹。"}, {"text": "他的成绩从来没有下降过，这次考试又反弹了。", "explanation": "这里应该用〈提高〉。反弹要先下降再回升，成绩从没下降过，应说提高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反弹", "is_correct": true, "explanation": "正确。反弹指下降后又回升，这只股票上周大跌，这周回升，符合句意。"}, {"text": "扩散", "is_correct": false, "explanation": "语义：“扩散”指向四周散开，多用于疫情、消息，不用于股价回升，与句意不合。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火焰或灯光停止发光，不能用来描述股价回升。"}, {"text": "点头", "is_correct": false, "explanation": "配价：“点头”需要有生命的施事，股票不能点头，主语与动词搭配不上。"}], "explanations": {"反弹": "正确。反弹指下降后又回升，这只股票上周大跌，这周回升，符合句意。", "扩散": "语义：“扩散”指向四周散开，多用于疫情、消息，不用于股价回升，与句意不合。", "熄灭": "语义：“熄灭”指火焰或灯光停止发光，不能用来描述股价回升。", "点头": "配价：“点头”需要有生命的施事，股票不能点头，主语与动词搭配不上。"}, "sentence_index": 6, "correct_answer": "反弹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件毛衣洗完后反弹了一圈。", "explanation": "这里应该用〈收缩〉。反弹指先下降后回升，衣物缩小要说收缩，不能说反弹。"}, {"text": "这艘船在风暴中慢慢反弹了。", "explanation": "这里应该用〈沉没〉。反弹指先下降后回升，船只沉入水底要说沉没，不能说反弹。"}, {"text": "这家店的生意一直很好，从没下滑过，今年又反弹了。", "explanation": "这里应该用〈增长〉。反弹要先下降再回升，生意从没下滑过，应说增长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只股票今天反弹的很快。", "corrected_sentence": "这只股票今天反弹得很快。", "error_description": "“的”应改为“得”：“反弹”后面的程度补语要用“得”，“的”不能用来连接动词和补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "股价上午大跌后，下午又反弹到来了。", "corrected_sentence": "股价上午大跌后，下午又反弹回来了。", "error_description": "“反弹”后的趋向补语应为“回来”，不能用“到来”：“到来”表示来临，不用于股价回升。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98726, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "支持", "is_correct": true, "explanation": "支持与反驳是反义：反驳是否定对方的看法，支持是肯定对方的看法。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行是到外地游览，与反驳没有反义或近义关系。"}, {"text": "整理", "is_correct": false, "explanation": "整理是使东西有条理，与反驳没有反义或近义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌是发声演唱，与反驳在任何义项上都没有反义关系。"}], "correct_answer": "支持", "explanations": {"支持": "支持与反驳是反义：反驳是否定对方的看法，支持是肯定对方的看法。", "旅行": "旅行是到外地游览，与反驳没有反义或近义关系。", "整理": "整理是使东西有条理，与反驳没有反义或近义关系。", "唱歌": "唱歌是发声演唱，与反驳在任何义项上都没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98726, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赞成", "is_correct": true, "explanation": "赞成与反驳是反义：反驳是否定对方的看法，赞成是认可对方的看法。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫是清理卫生，与反驳没有反义或近义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步是快速移动身体的运动，与反驳没有反义或近义关系。"}, {"text": "写作", "is_correct": false, "explanation": "写作是创作文字的活动，与反驳在任何义项上都没有反义关系。"}], "correct_answer": "赞成", "explanations": {"赞成": "赞成与反驳是反义：反驳是否定对方的看法，赞成是认可对方的看法。", "打扫": "打扫是清理卫生，与反驳没有反义或近义关系。", "跑步": "跑步是快速移动身体的运动，与反驳没有反义或近义关系。", "写作": "写作是创作文字的活动，与反驳在任何义项上都没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98726, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用理由否定对方的意见。", "primary_collocate": null, "pronunciation": "fǎn bó", "ipa": "fan˨˩ pwo˧˥", "syllable_count": 2, "sentences": [{"text": "她用事实反驳了对方的意见。", "target_word": "反驳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理反驳了这个计划。", "target_word": "反驳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师在法庭上反驳证人的话。", "target_word": "反驳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想反驳他的看法。", "target_word": "反驳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿出数字来反驳我。", "target_word": "反驳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个意见很难反驳。", "target_word": "反驳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上，小李反驳了老板的想法。", "target_word": "反驳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她反驳得很有道理。", "target_word": "反驳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有理由反驳这个结论。", "target_word": "反驳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都反驳过他的方案。", "target_word": "反驳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反驳了", "label": "体标"}, {"form": "反驳过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用理由或事实否定对方的看法、意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0979d30-f37e-4aca-8dc4-51c8b00cb872') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反驳", "is_correct": true, "explanation": "反驳表示用事实否定对方的意见，与“用事实……对方的意见”相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理针对器物，不能说“修理对方的意见”。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记是记不住，与用事实回应对方意见的动作不合。"}, {"text": "翻修", "is_correct": false, "explanation": "搭配：翻修多用于房屋、设施，不用于意见。"}], "explanations": {"反驳": "反驳表示用事实否定对方的意见，与“用事实……对方的意见”相符。", "修理": "搭配：修理针对器物，不能说“修理对方的意见”。", "忘记": "语义：忘记是记不住，与用事实回应对方意见的动作不合。", "翻修": "搭配：翻修多用于房屋、设施，不用于意见。"}, "sentence_index": 0, "correct_answer": "反驳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我反驳她的歌。", "explanation": "这里应该用〈欣赏〉。反驳针对别人的看法或说法，歌曲不是观点，不能反驳。"}, {"text": "他反驳了那台电脑。", "explanation": "这里应该用〈修理〉。反驳针对别人的意见，电脑不能提出意见，应该说修理。"}, {"text": "他反驳了自己的错误。", "explanation": "这里应该用〈承认〉。反驳针对别人的观点，错误是已经发生的事实，应该承认。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反驳", "is_correct": true, "explanation": "反驳表示用理由否定对方的想法，与“会上，小李……老板的想法”相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理针对器物，不说修理想法。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫是清理卫生，不能用于想法，与句意不合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是演唱，不能施加于想法，与句意不合。"}], "explanations": {"反驳": "反驳表示用理由否定对方的想法，与“会上，小李……老板的想法”相符。", "修理": "搭配：修理针对器物，不说修理想法。", "打扫": "语义：打扫是清理卫生，不能用于想法，与句意不合。", "唱": "语义：唱是演唱，不能施加于想法，与句意不合。"}, "sentence_index": 6, "correct_answer": "反驳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们都反驳他的生日。", "explanation": "这里应该用〈庆祝〉。反驳针对别人的看法或说法，生日是日子，不能反驳。"}, {"text": "他反驳了一碗面条。", "explanation": "这里应该用〈吃〉。反驳针对别人的看法或说法，面条不是观点，不能反驳。"}, {"text": "妈妈反驳了他的遭遇。", "explanation": "这里应该用〈同情〉。遭遇是经历，不是别人说的话，不能反驳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他反驳了过我的看法。", "corrected_sentence": "他反驳过我的看法。", "error_description": "错误在于体标重复。“反驳过”已经带有体标“过”，不能再加“了”，应说“他反驳过我的看法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很反驳我的意见。", "corrected_sentence": "他会反驳我的意见。", "error_description": "错误在于状语用错。“反驳”是动作动词，一般不受程度副词“很”修饰；应改用表示可能的能愿动词“会”，说“他会反驳我的意见”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98729, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自主", "is_correct": true, "explanation": "自主：自己做主，与“受制”（不能自己做主）相对"}, {"text": "游泳", "is_correct": false, "explanation": "游泳：在水中活动身体，与“受制”没有反义关系"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：到外地游览，与“受制”没有反义关系"}, {"text": "讨论", "is_correct": false, "explanation": "讨论：交换意见，与“受制”没有反义关系"}], "correct_answer": "自主", "explanations": {"自主": "自主：自己做主，与“受制”（不能自己做主）相对", "游泳": "游泳：在水中活动身体，与“受制”没有反义关系", "旅行": "旅行：到外地游览，与“受制”没有反义关系", "讨论": "讨论：交换意见，与“受制”没有反义关系"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98729, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自主", "is_correct": true, "explanation": "自主：自己做主，与“受制”（不能自己做主）相对"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉：闭眼休息，与“受制”没有反义关系"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：用声音演唱曲调，与“受制”没有反义关系"}, {"text": "跑步", "is_correct": false, "explanation": "跑步：快速奔跑运动，与“受制”没有反义关系"}], "correct_answer": "自主", "explanations": {"自主": "自主：自己做主，与“受制”（不能自己做主）相对", "睡觉": "睡觉：闭眼休息，与“受制”没有反义关系", "唱歌": "唱歌：用声音演唱曲调，与“受制”没有反义关系", "跑步": "跑步：快速奔跑运动，与“受制”没有反义关系"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98729, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "受制是被别人管着，不能自己做主。", "primary_collocate": null, "pronunciation": "shòu zhì", "ipa": "ʂoʊ̯⁵¹ ʈʂɻ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "公司受制于大股东，很难自己做主。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直受制于父母，不能选自己的工作。", "target_word": "受制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小国受制于大国，说话没有分量。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想一辈子受制于人。", "target_word": "受制", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店受制于总公司，价格不能自己定。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她受制于家里的规矩，不能晚回家。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板受制于银行，什么事都要问他们。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子长大了，不想再受制于父母。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "受制于人的日子，他已经过够了。", "target_word": "受制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队受制于老板，教练不能自己换人。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "受制于", "label": "复合"}, {"form": "受制于人", "label": "复合"}], "register": "书面", "sense_fingerprint": "被别人管着而不能自己做主", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dd17ffc-a76b-42f7-bbad-b8985cc3d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98729, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独立", "is_correct": false, "explanation": "语义：“独立于大股东”表示不受控制，与“很难自己做主”矛盾"}, {"text": "受制", "is_correct": true, "explanation": "受制：被别人管着，不能自己做主，与“很难自己做主”相符"}, {"text": "凌驾", "is_correct": false, "explanation": "语义：“凌驾于”表示高于、压过，与“很难自己做主”矛盾"}, {"text": "反抗", "is_correct": false, "explanation": "语义：“反抗”表示对抗、不服从，与“很难自己做主”矛盾"}], "explanations": {"独立": "语义：“独立于大股东”表示不受控制，与“很难自己做主”矛盾", "受制": "受制：被别人管着，不能自己做主，与“很难自己做主”相符", "凌驾": "语义：“凌驾于”表示高于、压过，与“很难自己做主”矛盾", "反抗": "语义：“反抗”表示对抗、不服从，与“很难自己做主”矛盾"}, "sentence_index": 0, "correct_answer": "受制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于受制了一份好工作。", "explanation": "这里应该用〈得到〉。受制表示被约束，不能直接带宾语，拿到工作要说得到"}, {"text": "他正在受制于假期的快乐。", "explanation": "这里应该用〈享受〉。受制表示被约束，不表示享用，享受快乐要说享受"}, {"text": "多读书受制于开阔视野。", "explanation": "这里应该用〈有助于〉。受制表示被管住、不能自主，读书对开阔视野有益要说有助于"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98729, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "超然", "is_correct": false, "explanation": "语义：“超然于”表示置身事外，与“什么事都要问他们”矛盾"}, {"text": "游离", "is_correct": false, "explanation": "语义：“游离于”表示脱离、不接触，与“什么事都要问他们”矛盾"}, {"text": "受制", "is_correct": true, "explanation": "受制：被别人管着，不能自己做主，与“什么事都要问他们”相符"}, {"text": "独立", "is_correct": false, "explanation": "语义：“独立于银行”表示不受约束，与“什么事都要问他们”矛盾"}], "explanations": {"超然": "语义：“超然于”表示置身事外，与“什么事都要问他们”矛盾", "游离": "语义：“游离于”表示脱离、不接触，与“什么事都要问他们”矛盾", "受制": "受制：被别人管着，不能自己做主，与“什么事都要问他们”相符", "独立": "语义：“独立于银行”表示不受约束，与“什么事都要问他们”矛盾"}, "sentence_index": 6, "correct_answer": "受制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他全心受制于研究工作。", "explanation": "这里应该用〈献身〉。受制表示被动受约束，不表示自愿投入，全心投入研究要说献身于"}, {"text": "这份礼物受制于善意。", "explanation": "这里应该用〈出于〉。受制表示被约束，不表示出自某种动机，礼物出于善意要说出于"}, {"text": "她受制了这次冠军。", "explanation": "这里应该用〈夺得〉。受制表示被约束，不能直接带宾语，取得冠军要说夺得"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
