INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98730, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "被别人控制或限制。", "primary_collocate": null, "pronunciation": "shòu zhì", "ipa": "ʂoʊ̯⁵¹ ʈʂɻ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "这个项目受制于资金，进展很慢。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛受制于天气，可能要推迟。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂生产受制于原材料的价格。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农业发展受制于水，北方尤其明显。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的计划受制于时间，只能少做一点。", "target_word": "受制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公司受制于大公司的技术。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市发展受制于交通。", "target_word": "受制", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "受制于场地，这次活动人数不能太多。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的经济受制于外国市场。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作受制于很多规定。", "target_word": "受制", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "受制于", "label": "复合"}], "register": "书面", "sense_fingerprint": "被人或条件控制、限制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dd17ffc-a76b-42f7-bbad-b8985cc3d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98730, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得益", "is_correct": false, "explanation": "语义：“得益于资金”表示受益，与“进展很慢”矛盾"}, {"text": "受制", "is_correct": true, "explanation": "受制：被条件限制，与“资金”及“进展很慢”相符"}, {"text": "受益", "is_correct": false, "explanation": "语义：“受益于资金”表示得到好处，与“进展很慢”矛盾"}, {"text": "出于", "is_correct": false, "explanation": "搭配：“出于”后接动机或缘由，不能接“资金”这样的物质条件"}], "explanations": {"得益": "语义：“得益于资金”表示受益，与“进展很慢”矛盾", "受制": "受制：被条件限制，与“资金”及“进展很慢”相符", "受益": "语义：“受益于资金”表示得到好处，与“进展很慢”矛盾", "出于": "搭配：“出于”后接动机或缘由，不能接“资金”这样的物质条件"}, "sentence_index": 0, "correct_answer": "受制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书受制于我。", "explanation": "这里应该用〈属于〉。受制表示被限制或控制，不表示物品归某人所有"}, {"text": "这个错误受制于粗心。", "explanation": "这里应该用〈源于〉。受制表示被约束，不表示发生原因，错误由粗心引起要说源于"}, {"text": "多吃蔬菜受制于健康。", "explanation": "这里应该用〈有助于〉。受制表示被限制，不表示对健康有益，多吃蔬菜对健康有益要说有助于"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "献身", "is_correct": false, "explanation": "搭配：“献身于”指人全心投入某事业，主语须是人，不能说“城市发展献身于交通”"}, {"text": "受制", "is_correct": true, "explanation": "受制：被条件限制，与“城市发展”和“交通”相符"}, {"text": "效忠", "is_correct": false, "explanation": "搭配：“效忠”多指人对国家或组织的忠诚，不用于“城市发展”"}, {"text": "俯首", "is_correct": false, "explanation": "语义：“俯首”指人低头顺从，主语须是人，不能用于“城市发展”"}], "explanations": {"献身": "搭配：“献身于”指人全心投入某事业，主语须是人，不能说“城市发展献身于交通”", "受制": "受制：被条件限制，与“城市发展”和“交通”相符", "效忠": "搭配：“效忠”多指人对国家或组织的忠诚，不用于“城市发展”", "俯首": "语义：“俯首”指人低头顺从，主语须是人，不能用于“城市发展”"}, "sentence_index": 6, "correct_answer": "受制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个节日受制于古代。", "explanation": "这里应该用〈起源于〉。受制表示被限制，不表示事物发源于某个时代"}, {"text": "学校受制于市中心。", "explanation": "这里应该用〈位于〉。受制表示被限制，不表示处在某个位置"}, {"text": "这条规定受制于所有员工。", "explanation": "这里应该用〈适用于〉。受制表示被管住，规定对某群体生效要说适用于"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
