INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98733, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "另类是和大家不太一样的那一种。", "primary_collocate": null, "pronunciation": "lìng lèi", "ipa": "liŋ⁵¹ leɪ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "在我们班，他算是另类。", "target_word": "另类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的想法在公司里算另类。", "target_word": "另类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都穿西装，只有他是另类。", "target_word": "另类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这群人里，她一直是个另类。", "target_word": "另类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人觉得他是另类，其实他很普通。", "target_word": "另类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在老一辈眼里，玩摇滚的人都是另类。", "target_word": "另类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就是个另类。", "target_word": "另类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把不一样的人都看成另类。", "target_word": "另类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕当另类，总是说出自己的想法。", "target_word": "另类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有一个另类，他从来不用手机。", "target_word": "另类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "另类人", "label": "复合"}, {"form": "另類", "label": "繁体"}], "register": "口语", "sense_fingerprint": "和大家不太一样的那一种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0951d8-de99-4fb1-907c-73c4f740a35d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98733, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "另类", "is_correct": true, "explanation": "正确：“另类”指和大家不太一样的那一种人，可以说“他算是另类”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能指人，“算是”后应接人或人的类别。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能指一个人，与“在我们班”的语境不合。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“他算是树”的说法不成立，“树”与人的身份不搭配。"}], "explanations": {"另类": "正确：“另类”指和大家不太一样的那一种人，可以说“他算是另类”。", "桌子": "语义：“桌子”是家具，不能指人，“算是”后应接人或人的类别。", "天气": "语义：天气不能指一个人，与“在我们班”的语境不合。", "树": "搭配：“他算是树”的说法不成立，“树”与人的身份不搭配。"}, "sentence_index": 0, "correct_answer": "另类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请把这份文件另类保存。", "explanation": "这里应该用〈另存〉。“另类”指和大家不一样，不能表示“另外保存”；文件另存要用“另存”。"}, {"text": "我们班来了一只另类。", "explanation": "这里应该用〈个〉。“另类”指人时用“个”，“只”多用于动物。"}, {"text": "另类，我还有个问题。", "explanation": "这里应该用〈另外〉。“另外”表示补充，“另类”不能作连接语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98733, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "另类", "is_correct": true, "explanation": "正确：“她从小就是个另类”指她从小就与大家不一样。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是人，不能用“是个……”来指她的身份。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，与“从小就是个”的描述不合。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象是动物，不能用“从小就是个……”来说她的身份。"}], "explanations": {"另类": "正确：“她从小就是个另类”指她从小就与大家不一样。", "水果": "语义：水果不是人，不能用“是个……”来指她的身份。", "石头": "语义：石头不是人，与“从小就是个”的描述不合。", "大象": "语义：大象是动物，不能用“从小就是个……”来说她的身份。"}, "sentence_index": 6, "correct_answer": "另类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请另类通知大家。", "explanation": "这里应该用〈另行〉。“另类”指和大家不一样，不能表示“单独、另外”；另行通知要用“另行”。"}, {"text": "新来的老师是一只另类。", "explanation": "这里应该用〈个〉。“另类”指人时用“个”，“只”多用于动物，不能用于指人的“另类”。"}, {"text": "我们另类请了一位老师。", "explanation": "这里应该用〈另请〉。“另类”指和大家不一样，不能表示“另外请人”；另请某人要用“另请”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98733, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我们班里的一只另类。", "corrected_sentence": "他是我们班里的一个另类。", "error_description": "量词错误：“另类”指人时应用量词“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98733, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是班里的一条另类。", "corrected_sentence": "她是班里的一个另类。", "error_description": "量词错误：“另类”指人时应用量词“个”，不能用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
