INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98737, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（办法、计划等）行得通，能够做到。", "primary_collocate": null, "pronunciation": "kě xíng", "ipa": "kʰɤ˨˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个办法很可行。", "target_word": "可行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的计划听起来很可行。", "target_word": "可行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得这样做不太可行。", "target_word": "可行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说这个方案完全可行。", "target_word": "可行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想出了一个可行的办法。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看看这个想法是否可行。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划在现实中并不可行。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理认为这个做法可行。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样安排时间，对大家都可行。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说的方法听上去可行，我们试试吧。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可行", "label": "否定形式"}, {"form": "可行性", "label": "复合"}], "register": "中性", "sense_fingerprint": "做法、办法行得通，能够做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8ddae9-ae0a-4af4-8122-16a67952f138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98737, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可行", "is_correct": true, "explanation": "正确：可行指做法能够实行，与“很”搭配，符合句意。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：嘹亮形容声音，不能用来形容办法。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：办法没有情感，不会高兴，“高兴”的主体须是有情感的人。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：办法没有年龄，“年轻”不能修饰办法。"}], "explanations": {"可行": "正确：可行指做法能够实行，与“很”搭配，符合句意。", "嘹亮": "搭配：嘹亮形容声音，不能用来形容办法。", "高兴": "语义：办法没有情感，不会高兴，“高兴”的主体须是有情感的人。", "年轻": "语义：办法没有年龄，“年轻”不能修饰办法。"}, "sentence_index": 0, "correct_answer": "可行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔收入很可行。", "explanation": "这里应该用〈可观〉。收入、数量大要说可观，可行指做法行得通，不能形容收入。"}, {"text": "这只小狗很可行。", "explanation": "这里应该用〈可爱〉。形容小狗的样子要说可爱，可行只用于做法、方案。"}, {"text": "这个人很可行。", "explanation": "这里应该用〈可靠〉。形容人值得信任要说可靠，可行不能用来形容人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可行", "is_correct": true, "explanation": "正确：“并不可行”指计划行不通，与“在现实中”的语境相符。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：清脆形容声音，不能用来形容计划。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：计划没有感情，不会感到幸福。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：温柔形容人的性格，计划不能温柔。"}], "explanations": {"可行": "正确：“并不可行”指计划行不通，与“在现实中”的语境相符。", "清脆": "搭配：清脆形容声音，不能用来形容计划。", "幸福": "语义：计划没有感情，不会感到幸福。", "温柔": "语义：温柔形容人的性格，计划不能温柔。"}, "sentence_index": 6, "correct_answer": "可行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的遭遇很可行。", "explanation": "这里应该用〈可怜〉。形容遭遇令人同情要说可怜，可行不能形容遭遇。"}, {"text": "这道菜很可行。", "explanation": "这里应该用〈可口〉。形容食物好吃要说可口，可行指做法行得通。"}, {"text": "他的样子很可行。", "explanation": "这里应该用〈可笑〉。形容样子滑稽要说可笑，可行不能形容人的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个办法的可行很高。", "corrected_sentence": "这个办法的可行性很高。", "error_description": "漏掉“性”：“可行”是形容词，表示可行的程度要用名词“可行性”，应为“可行性很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个想法在现实中并不可行性。", "corrected_sentence": "这个想法在现实中并不可行。", "error_description": "词性错误：“可行性”是名词，不能直接受“不”修饰作谓语，应用形容词“可行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
