INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98738, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "行得通；可以实行。", "primary_collocate": null, "pronunciation": "kě xíng", "ipa": "kʰɤ˨˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个方案在技术上是可行的。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在研究新办法是否可行。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说这条路线可行。", "target_word": "可行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个方案对学生来说不可行。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要一个简单可行的计划。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出的建议既省钱又可行。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法听起来好，但做起来不可行。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过讨论，大家觉得这个办法可行。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的方法最可行，我们就用它。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份计划太大，一年内不可行。", "target_word": "可行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可行", "label": "否定形式"}, {"form": "可行性", "label": "复合"}], "register": "中性", "sense_fingerprint": "计划、方案可以实行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8ddae9-ae0a-4af4-8122-16a67952f138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可行", "is_correct": true, "explanation": "正确：“是可行的”说明方案在技术上行得通，符合句意。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：方案不能是幽默的，句意不通。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：方案没有感情，不能悲伤。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：宽敞形容空间，不能用来形容方案。"}], "explanations": {"可行": "正确：“是可行的”说明方案在技术上行得通，符合句意。", "幽默": "语义：方案不能是幽默的，句意不通。", "悲伤": "语义：方案没有感情，不能悲伤。", "宽敞": "搭配：宽敞形容空间，不能用来形容方案。"}, "sentence_index": 0, "correct_answer": "可行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个游戏的画面很可行。", "explanation": "这里应该用〈精美〉。形容画面好看要说精美，可行指做法、方案能实行，不能形容画面。"}, {"text": "这次考试的分数很可行。", "explanation": "这里应该用〈高〉。形容分数多要说高，可行指做法、方案能实行，不能形容分数。"}, {"text": "这把椅子对学生来说很可行。", "explanation": "这里应该用〈实用〉。形容椅子好用要说实用，可行指做法、方案行得通，不能形容实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可行", "is_correct": true, "explanation": "正确：“做起来不可行”指做起来行不通，与前句“听起来好”形成转折，符合句意。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：响亮形容声音或名声，不能用来形容做起来的事情。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：做事情没有情感，不会害羞。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：做法没有年龄，“年轻”不能修饰做起来的事情。"}], "explanations": {"可行": "正确：“做起来不可行”指做起来行不通，与前句“听起来好”形成转折，符合句意。", "响亮": "搭配：响亮形容声音或名声，不能用来形容做起来的事情。", "害羞": "语义：做事情没有情感，不会害羞。", "年轻": "语义：做法没有年龄，“年轻”不能修饰做起来的事情。"}, "sentence_index": 6, "correct_answer": "可行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画很可行。", "explanation": "这里应该用〈美丽〉。形容画好看要说美丽，可行不能用来形容画。"}, {"text": "他的贡献很可行。", "explanation": "这里应该用〈伟大〉。形容贡献之大要说伟大，可行指做法能实行。"}, {"text": "这首歌很可行。", "explanation": "这里应该用〈好听〉。形容歌曲动听要说好听，可行指做法、方案能实行，不能形容歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们需要一个很可行办法。", "corrected_sentence": "我们需要一个很可行的办法。", "error_description": "漏掉“的”：“很可行”修饰名词“办法”时要加“的”，应为“很可行的办法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方案现在把可行了。", "corrected_sentence": "这个方案现在可行了。", "error_description": "“把”用错：“可行”是形容词，不能用于“把”字句，应直接说“这个方案现在可行了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
