INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98762, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "医学的一个分支，研究以手术为主要手段治疗疾病。", "primary_collocate": null, "pronunciation": "wài kē xué", "ipa": "uai̯⁵¹ kʰɤ⁵⁵ ɕɥɛ³⁵", "syllable_count": 3, "sentences": [{"text": "外科学是医学的一个分支，主要靠手术治病。", "target_word": "外科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授研究外科学，常带学生进手术室。", "target_word": "外科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在外科学中，手术是最重要的治疗方法。", "target_word": "外科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与内科学不同，外科学主要用手术治疗疾病。", "target_word": "外科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他选了外科学，以后每天都要做手术。", "target_word": "外科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外科学发展很快，新的手术方法越来越多。", "target_word": "外科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用外科学的知识给病人做了手术。", "target_word": "外科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代外科学用手术救活了很多重病人。", "target_word": "外科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想学外科学，因为她喜欢做手术救人。", "target_word": "外科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医学院开了外科学这门课，学生都要学手术。", "target_word": "外科学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外科學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "医学分支，以手术为主要手段治疗疾病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64d38e22-74eb-4da9-84a8-607619094d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外科学", "is_correct": true, "explanation": "“外科学”是医学分支，与“主要靠手术治病”相符。"}, {"text": "内科学", "is_correct": false, "explanation": "语义：内科以药物治疗为主，与“主要靠手术治病”矛盾。"}, {"text": "药学", "is_correct": false, "explanation": "语义：药学研究药物，不以手术为主，与后半句矛盾。"}, {"text": "手术", "is_correct": false, "explanation": "搭配：“手术”是治疗方法，不能说“是医学的一个分支”。"}], "explanations": {"外科学": "“外科学”是医学分支，与“主要靠手术治病”相符。", "内科学": "语义：内科以药物治疗为主，与“主要靠手术治病”矛盾。", "药学": "语义：药学研究药物，不以手术为主，与后半句矛盾。", "手术": "搭配：“手术”是治疗方法，不能说“是医学的一个分支”。"}, "sentence_index": 0, "correct_answer": "外科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生用外科学给病人开药，效果很好。", "explanation": "“外科学”是学科，不是药物；开药应说〈药物治疗〉。"}, {"text": "他在治疗外科学，每天都去医院。", "explanation": "“外科学”是学科，不能作为被治疗的对象；治疗的对象应是〈疾病〉。"}, {"text": "他下班后去外科学看病。", "explanation": "“外科学”是学科，不是科室；去医院看病应说〈外科〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外科学", "is_correct": true, "explanation": "“外科学”是学科，与“做了手术”相符。"}, {"text": "体育", "is_correct": false, "explanation": "语义：体育的知识与“做手术”无关，句意不通。"}, {"text": "园艺", "is_correct": false, "explanation": "语义：园艺知识用于种植，不能用于做手术。"}, {"text": "手术刀", "is_correct": false, "explanation": "搭配：“的知识”要接学问，“手术刀”是器械，不能作为知识的修饰语。"}], "explanations": {"外科学": "“外科学”是学科，与“做了手术”相符。", "体育": "语义：体育的知识与“做手术”无关，句意不通。", "园艺": "语义：园艺知识用于种植，不能用于做手术。", "手术刀": "搭配：“的知识”要接学问，“手术刀”是器械，不能作为知识的修饰语。"}, "sentence_index": 6, "correct_answer": "外科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐姐是一位外科学，常在手术室里工作。", "explanation": "“外科学”是学科名称，不指人；此处应说〈外科医生〉。"}, {"text": "医生每天给病人做外科学，很辛苦。", "explanation": "“外科学”是学科，不能用“做”，应说〈做手术〉。"}, {"text": "这位学生用外科学缝合了伤口。", "explanation": "“外科学”是知识，不是工具；缝合要用针线或手术器械。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "外科学是一只很难的课，学生要学很多手术。", "corrected_sentence": "外科学是一门很难的课，学生要学很多手术。", "error_description": "错误：「一只很难的课」，课程的量词不能用“只”。正确：「一门很难的课」，学科、课程用量词“门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是学外科学学生，每天都去手术室。", "corrected_sentence": "她是学外科学的学生，每天都去手术室。", "error_description": "“学外科学”修饰“学生”时要加“的”，应说“学外科学的学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
