INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98765, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "多少有些是说有一点点，不是很多。", "primary_collocate": null, "pronunciation": "duō shǎo yǒu xiē", "ipa": "tuɔ˥ ʂaʊ˨˩˦ joʊ˨˩˦ ɕjɛ˥", "syllable_count": 4, "sentences": [{"text": "今天我多少有些累。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得多少有些快。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个问题多少有些好奇。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里多少有些冷。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜多少有些咸。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对朋友多少有些生气。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以前，我多少有些担心。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服多少有些小。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天多少有些不高兴。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在这里，我多少有些不习惯。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "副词：程度很轻，只有一点点，不是很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b273a4-be21-462a-a87c-17dfbdecb405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98765, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多少有些", "is_correct": true, "explanation": "正确。表示程度轻，可以直接修饰“累”。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常与否定词连用，如“根本不累”，不能直接修饰“累”。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示催促尽快行动，不能用来描述“累”的程度。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”表示叮嘱，多用于“千万别累”这类祈使句，不能描述“我”的状态。"}], "explanations": {"多少有些": "正确。表示程度轻，可以直接修饰“累”。", "根本": "搭配：“根本”通常与否定词连用，如“根本不累”，不能直接修饰“累”。", "赶紧": "语义：“赶紧”表示催促尽快行动，不能用来描述“累”的程度。", "千万": "语义：“千万”表示叮嘱，多用于“千万别累”这类祈使句，不能描述“我”的状态。"}, "sentence_index": 0, "correct_answer": "多少有些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "房间里多少有些冷极了。", "explanation": "这里应该用〈确实〉。“多少有些”程度轻，不能与“冷极了”同用。"}, {"text": "房间里多少有些冷得不得了。", "explanation": "这里应该用〈确实〉。“多少有些”程度轻，与“冷得不得了”的强烈程度相矛盾。"}, {"text": "我们多少有些买了两本书。", "explanation": "这里应该用〈确实〉。“多少有些”只表示程度轻，不能修饰已经完成的“买了两本书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多少有些", "is_correct": true, "explanation": "正确。表示程度轻，可以与“担心”搭配。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示几个人共同做某事，不表示程度，不能修饰“担心”。"}, {"text": "拼命", "is_correct": false, "explanation": "语义：“拼命”表示用尽全力，不能修饰“担心”。"}, {"text": "最好", "is_correct": false, "explanation": "搭配：“最好”多用于提建议，如“最好别担心”，不能直接描述“我”的心理状态。"}], "explanations": {"多少有些": "正确。表示程度轻，可以与“担心”搭配。", "一起": "语义：“一起”表示几个人共同做某事，不表示程度，不能修饰“担心”。", "拼命": "语义：“拼命”表示用尽全力，不能修饰“担心”。", "最好": "搭配：“最好”多用于提建议，如“最好别担心”，不能直接描述“我”的心理状态。"}, "sentence_index": 6, "correct_answer": "多少有些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "住在这里，我多少有些完全不习惯。", "explanation": "这里应该用〈非常〉。“多少有些”程度轻，与“完全”这类表示全部的词矛盾。"}, {"text": "住在这里，我多少有些热得不得了。", "explanation": "这里应该用〈非常〉。“多少有些”程度轻，与“热得不得了”的强烈程度相矛盾。"}, {"text": "住在这里，我多少有些找到了房子。", "explanation": "这里应该用〈确实〉。“多少有些”只表示程度轻，不能修饰已经完成的“找到了房子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天多少有些很累，不想出去。", "corrected_sentence": "我今天多少有些累，不想出去。", "error_description": "“多少有些”本身已表示程度轻，后面不能再加“很”，应说“多少有些累”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件衣服不多少有些大，我不太喜欢。", "corrected_sentence": "这件衣服多少有些大，我不太喜欢。", "error_description": "“多少有些”前面不能加“不”。表示有一点儿大，应说“这件衣服多少有些大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
