INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98766, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "或多或少有一点。", "primary_collocate": null, "pronunciation": "duō shǎo yǒu xiē", "ipa": "tuɔ˥ ʂaʊ˨˩˦ joʊ˨˩˦ ɕjɛ˥", "syllable_count": 4, "sentences": [{"text": "他多少有些紧张。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，我多少有些意外。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事跟他多少有些关系。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她多少有些不放心。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法多少有些作用。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我多少有些误会。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气不好，大家多少有些失望。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方我多少有些印象。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话多少有些道理。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子第一天上学，多少有些害怕。", "target_word": "多少有些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "副词：表示某种情绪、看法或关系或多或少存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b273a4-be21-462a-a87c-17dfbdecb405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多少有些", "is_correct": true, "explanation": "正确。表示程度轻，可以直接修饰“紧张”。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常与否定词连用，如“根本不紧张”，不能直接修饰“紧张”。"}, {"text": "赶快", "is_correct": false, "explanation": "语义：“赶快”表示催促尽快行动，不能用来描述“紧张”的程度。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”表示叮嘱或强调，多用于“千万别紧张”这类祈使句，不能描述他的状态。"}], "explanations": {"多少有些": "正确。表示程度轻，可以直接修饰“紧张”。", "根本": "搭配：“根本”通常与否定词连用，如“根本不紧张”，不能直接修饰“紧张”。", "赶快": "语义：“赶快”表示催促尽快行动，不能用来描述“紧张”的程度。", "千万": "语义：“千万”表示叮嘱或强调，多用于“千万别紧张”这类祈使句，不能描述他的状态。"}, "sentence_index": 0, "correct_answer": "多少有些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他多少有些愤怒极了。", "explanation": "这里应该用〈非常〉。“多少有些”表示程度轻，不能与“极了”这种程度很高的词同用。"}, {"text": "他多少有些比我高得多。", "explanation": "这里应该用〈确实〉。“多少有些”程度轻，与“比我高得多”表示差距很大的程度相矛盾。"}, {"text": "他多少有些考了一百分。", "explanation": "这里应该用〈确实〉。“多少有些”只表示程度轻，不能修饰已经确定的结果“考了一百分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多少有些", "is_correct": true, "explanation": "正确。表示程度轻，可以与“失望”搭配。"}, {"text": "拼命", "is_correct": false, "explanation": "语义：“拼命”表示使出全力，不能修饰“失望”这种心理状态。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”表示随意或不加限制，不能用来修饰“失望”。"}, {"text": "最好", "is_correct": false, "explanation": "搭配：“最好”多用于提建议，如“最好别失望”，不能直接描述大家的心情。"}], "explanations": {"多少有些": "正确。表示程度轻，可以与“失望”搭配。", "拼命": "语义：“拼命”表示使出全力，不能修饰“失望”这种心理状态。", "随便": "语义：“随便”表示随意或不加限制，不能用来修饰“失望”。", "最好": "搭配：“最好”多用于提建议，如“最好别失望”，不能直接描述大家的心情。"}, "sentence_index": 6, "correct_answer": "多少有些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子第一天上学，多少有些吃完了三碗饭。", "explanation": "这里应该用〈确实〉。“多少有些”只表示程度轻，不能修饰已经完成的“吃完了三碗饭”。"}, {"text": "孩子第一天上学，多少有些哭得很厉害。", "explanation": "这里应该用〈确实〉。“多少有些”程度轻，与“哭得很厉害”的强烈程度相矛盾。"}, {"text": "孩子第一天上学，多少有些害怕极了。", "explanation": "这里应该用〈十分〉。“多少有些”程度轻，与“害怕极了”的强烈程度相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这件事多少有些很担心。", "corrected_sentence": "他对这件事多少有些担心。", "error_description": "“多少有些”本身已表示程度轻，后面不能再加“很”，应说“多少有些担心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
