INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98770, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能在多种系统或设备上使用的。", "primary_collocate": null, "pronunciation": "duō píng tái", "ipa": "two˥ pʰiŋ˧˥ tʰai˧˥", "syllable_count": 3, "sentences": [{"text": "这是一个多平台软件。", "target_word": "多平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢多平台的游戏。", "target_word": "多平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多平台应用手机电脑都能用。", "target_word": "多平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司做了一款多平台游戏。", "target_word": "多平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多平台软件很方便。", "target_word": "多平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在找一个多平台的笔记软件。", "target_word": "多平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多平台工具是免费的。", "target_word": "多平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多平台的好处是换设备也能用。", "target_word": "多平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的网站是多平台的。", "target_word": "多平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款多平台软件很受欢迎。", "target_word": "多平台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "软件、游戏等能在多种系统或设备上使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0979d30-f37e-4aca-8dc4-51c8b00cb872') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多平台", "is_correct": true, "explanation": "多平台指软件、应用能在多种系统或设备上使用，修饰“软件”正合句意。"}, {"text": "深红", "is_correct": false, "explanation": "搭配：深红是颜色词，不用来修饰“软件”。"}, {"text": "高大", "is_correct": false, "explanation": "语义：高大形容体积或身材，软件没有高矮大小之分，与句意不合。"}, {"text": "年迈", "is_correct": false, "explanation": "语义：年迈形容人年纪大，不能用来修饰软件。"}], "explanations": {"多平台": "多平台指软件、应用能在多种系统或设备上使用，修饰“软件”正合句意。", "深红": "搭配：深红是颜色词，不用来修饰“软件”。", "高大": "语义：高大形容体积或身材，软件没有高矮大小之分，与句意不合。", "年迈": "语义：年迈形容人年纪大，不能用来修饰软件。"}, "sentence_index": 0, "correct_answer": "多平台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把剪刀是多平台的。", "explanation": "这里应该用〈多功能〉。多平台指同一软件或应用能在多种系统或设备上使用，剪刀没有系统或设备之分。"}, {"text": "社会正在走向多平台。", "explanation": "这里应该用〈多元〉。多平台只用于软件或应用，不能用来描述社会的多样性。"}, {"text": "这块蛋糕的口味是多平台的。", "explanation": "这里应该用〈多样〉。多平台只用于能在多种系统或设备上使用的软件或应用，口味不能用它描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多平台", "is_correct": true, "explanation": "多平台指软件、应用能在多种系统或设备上使用，修饰“工具”正合句意。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：年轻用于人或生物，不能用来形容工具。"}, {"text": "湿润", "is_correct": false, "explanation": "搭配：湿润形容物体或环境的含水状态，不说“湿润工具”。"}, {"text": "清瘦", "is_correct": false, "explanation": "体貌：清瘦描述人的体型，不能用于工具。"}], "explanations": {"多平台": "多平台指软件、应用能在多种系统或设备上使用，修饰“工具”正合句意。", "年轻": "语义：年轻用于人或生物，不能用来形容工具。", "湿润": "搭配：湿润形容物体或环境的含水状态，不说“湿润工具”。", "清瘦": "体貌：清瘦描述人的体型，不能用于工具。"}, "sentence_index": 6, "correct_answer": "多平台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的题目是多平台的。", "explanation": "这里应该用〈多种〉。多平台只用于能在多种系统或设备上使用的软件或应用，考试题目不能用它描述。"}, {"text": "这家饭店的菜是多平台的。", "explanation": "这里应该用〈多样〉。多平台只用于能在多种系统或设备上使用的软件或应用，饭菜不能用它描述。"}, {"text": "这张桌子是多平台的。", "explanation": "这里应该用〈结实〉。多平台只用于能在多种系统或设备上使用的软件或应用，桌子的牢固程度不能用它描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个工具很方便，它多平台的。", "corrected_sentence": "这个工具很方便，它是多平台的。", "error_description": "错误在于漏掉“是”。“多平台”作谓语时需要系动词“是”，应说“它是多平台的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想买一个多平台地应用。", "corrected_sentence": "我想买一个多平台的应用。", "error_description": "错误在于结构助词用错。修饰名词的形容词要用“的”，“地”用于修饰动词，应说“多平台的应用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
