INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98773, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大难是很大很可怕的坏事。", "primary_collocate": null, "pronunciation": "dà nàn", "ipa": "ta˥˩ nan˥˩", "syllable_count": 2, "sentences": [{"text": "他在地震中逃过了一次大难。", "target_word": "大难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大难让全城的人都很难过。", "target_word": "大难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大难过后，大家一起重建家园。", "target_word": "大难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，他一生经历过两次大难。", "target_word": "大难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大难来了，我们要互相帮助。", "target_word": "大难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那年的大难，我到现在还记得。", "target_word": "大难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在那场大难中活了下来，真是太幸运了。", "target_word": "大难", "complexity_tier": "T3", "furigana": "tā zài nà chǎng dànàn zhōng huó le xiàlái, zhēn shì tài xìngyùn le.", "sentence_source": "generated"}, {"text": "村里遇到大难，大家都来帮忙。", "target_word": "大难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大难起于一场大火。", "target_word": "大难", "complexity_tier": "T3", "furigana": "zhè chǎng dànàn qǐ yú yì chǎng dà huǒ.", "sentence_source": "generated"}, {"text": "面对大难，他一点也不怕。", "target_word": "大难", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "大难：很大很可怕的坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4e257c-d76d-447e-870c-0909fbaadfdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98773, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大难", "is_correct": true, "explanation": "正确：“大难”指很大很可怕的灾祸，与“在地震中逃过了一次”相合。"}, {"text": "小事", "is_correct": false, "explanation": "语义：“逃过”的对象应是危险的灾祸，“小事”不是需要逃避的险境。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“逃过”不能与“午饭”搭配，午饭不是险境。"}, {"text": "节日", "is_correct": false, "explanation": "语义：在地震中逃过的不能是节日这样的欢庆日子。"}], "explanations": {"大难": "正确：“大难”指很大很可怕的灾祸，与“在地震中逃过了一次”相合。", "小事": "语义：“逃过”的对象应是危险的灾祸，“小事”不是需要逃避的险境。", "午饭": "搭配：“逃过”不能与“午饭”搭配，午饭不是险境。", "节日": "语义：在地震中逃过的不能是节日这样的欢庆日子。"}, "sentence_index": 0, "correct_answer": "大难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于解开了那道数学大难。", "explanation": "这里应该用〈难题〉。大难指很大很可怕的灾祸，数学题只是学习上的难题，不能说〈大难〉。"}, {"text": "新校区启用是学校的一场大难。", "explanation": "这里应该用〈大事〉。大难指很大很可怕的灾祸，新校区启用是好事，不能说〈大难〉。"}, {"text": "他送了我一份大难。", "explanation": "这里应该用〈大礼〉。大难是灾祸，不能当作礼物送人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大难", "is_correct": true, "explanation": "正确：“大难”指很大很可怕的灾祸，与“活了下来，真是太幸运了”相合。"}, {"text": "晚会", "is_correct": false, "explanation": "语义：晚会是欢乐的聚会，不是人能“活下来”的险境。"}, {"text": "宴会", "is_correct": false, "explanation": "语义：宴会不是有生命危险的场合，与“活了下来”不相合。"}, {"text": "婚礼", "is_correct": false, "explanation": "搭配：“活下来”不能与“婚礼”搭配，婚礼不会危及生命。"}], "explanations": {"大难": "正确：“大难”指很大很可怕的灾祸，与“活了下来，真是太幸运了”相合。", "晚会": "语义：晚会是欢乐的聚会，不是人能“活下来”的险境。", "宴会": "语义：宴会不是有生命危险的场合，与“活了下来”不相合。", "婚礼": "搭配：“活下来”不能与“婚礼”搭配，婚礼不会危及生命。"}, "sentence_index": 6, "correct_answer": "大难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春节是中国最重要的大难。", "explanation": "这里应该用〈节日〉。大难指很大很可怕的灾祸，春节是喜庆的节日，不能说〈大难〉。"}, {"text": "这件大难让全家人都笑了。", "explanation": "这里应该用〈喜事〉。让人高兴的是喜事，大难是很可怕的坏事，不会让人笑。"}, {"text": "他的书包里装满了大难。", "explanation": "语义：这里把大难当成了可以装进书包的具体东西，但大难是抽象的灾祸，不能这样装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那场地震之后，村子经历了一个大难。", "corrected_sentence": "那场地震之后，村子经历了一场大难。", "error_description": "量词错误：“大难”应该用量词“场”，不能用“个”，正确说法是“一场大难”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于大难中走了出来。", "corrected_sentence": "他终于从大难中走了出来。", "error_description": "介词错误：表示从困境中走出要用「从…中」，「大难中」前缺少介词「从」，正确说法是「从大难中走了出来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
