INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98779, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天上是在天空里。", "primary_collocate": null, "pronunciation": "tiān shàng", "ipa": "tʰiɛn˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "天上有很多白云。", "target_word": "天上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天上的星星很亮。", "target_word": "天上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天天上一朵云也没有。", "target_word": "天上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天上飞着一只小鸟。", "target_word": "天上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们抬头看天上的月亮。", "target_word": "天上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上下雨了，我们回家吧。", "target_word": "天上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上有一架飞机飞过去。", "target_word": "天上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里天上挂着一轮明月。", "target_word": "天上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上的太阳很大。", "target_word": "天上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他看着天上的云，想起了家。", "target_word": "天上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "在天空里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69273c12-942b-4785-8ed5-3d4f334825ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98779, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天上", "is_correct": true, "explanation": "正确：“天上”指天空中，白云在天上。"}, {"text": "地下", "is_correct": false, "explanation": "语义：地下没有白云，句意不通。"}, {"text": "碗里", "is_correct": false, "explanation": "搭配：白云不会在碗里，“白云”与“碗里”不搭配。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底没有白云，与常识冲突。"}], "explanations": {"天上": "正确：“天上”指天空中，白云在天上。", "地下": "语义：地下没有白云，句意不通。", "碗里": "搭配：白云不会在碗里，“白云”与“碗里”不搭配。", "海底": "语义：海底没有白云，与常识冲突。"}, "sentence_index": 0, "correct_answer": "天上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把桌子放在天上。", "explanation": "“天上”指天空中，桌子不能放在天空中，这里应该用〈桌子上〉。"}, {"text": "鱼儿在天上游。", "explanation": "“天上”指天空中，鱼不能在天空中游，这里应该用〈水里〉。"}, {"text": "我的房子建在天上。", "explanation": "“天上”指天空中，房子不能建在天空中，这里应该用〈地上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98779, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天上", "is_correct": true, "explanation": "正确：“天上”指天空中，飞机在天上飞过去。"}, {"text": "水里", "is_correct": false, "explanation": "语义：水里不会有飞机飞过去，句意不通。"}, {"text": "床底下", "is_correct": false, "explanation": "搭配：“飞过去”的地点要求是空中，“床底下”不搭配。"}, {"text": "抽屉里", "is_correct": false, "explanation": "语义：抽屉里装不下飞机，句意不通。"}], "explanations": {"天上": "正确：“天上”指天空中，飞机在天上飞过去。", "水里": "语义：水里不会有飞机飞过去，句意不通。", "床底下": "搭配：“飞过去”的地点要求是空中，“床底下”不搭配。", "抽屉里": "语义：抽屉里装不下飞机，句意不通。"}, "sentence_index": 6, "correct_answer": "天上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的书架摆在天上。", "explanation": "“天上”指天空中，书架不能摆在天空中，这里应该用〈地上〉。"}, {"text": "这盆花种在天上。", "explanation": "“天上”指天空中，花不能种在天空中，这里应该用〈地里〉。"}, {"text": "椅子放在天上。", "explanation": "“天上”指天空中，椅子不能放在天空中，这里应该用〈地上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天上在鸽子飞。", "corrected_sentence": "鸽子在天上飞。", "error_description": "错误：语序不对，「在天上」被拆开，主语「鸽子」放在了「在」后面。正确：应为「主语＋在天上＋动词」，说「鸽子在天上飞」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只鸟在天上的飞。", "corrected_sentence": "一只鸟在天上飞。", "error_description": "错误：“天上”后面多了“的”。正确：动词前的地点状语“在天上”后面不加“的”，应说“一只鸟在天上飞”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
