INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98780, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天空中。", "primary_collocate": null, "pronunciation": "tiān shàng", "ipa": "tʰiɛn˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "天上飞来了一群鸟。", "target_word": "天上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上没有星星。", "target_word": "天上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你看，天上有一道彩虹。", "target_word": "天上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天上的云走得很慢。", "target_word": "天上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "晚上天上全是星星。", "target_word": "天上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天上有风筝，也有鸟。", "target_word": "天上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明指着天上说：“那是月亮。”", "target_word": "天上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上挂着一个红太阳。", "target_word": "天上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雪以前，天上总是灰的。", "target_word": "天上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上的飞机越飞越远。", "target_word": "天上", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "天空中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69273c12-942b-4785-8ed5-3d4f334825ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天上", "is_correct": true, "explanation": "正确：“天上”指天空中，鸟可以从天上飞来。"}, {"text": "地下", "is_correct": false, "explanation": "语义：地下没有飞来的鸟群，句意不通。"}, {"text": "碗里", "is_correct": false, "explanation": "搭配：“飞来”的地点应为空中，“碗里”不搭配。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底不会有鸟群飞来，与常识冲突。"}], "explanations": {"天上": "正确：“天上”指天空中，鸟可以从天上飞来。", "地下": "语义：地下没有飞来的鸟群，句意不通。", "碗里": "搭配：“飞来”的地点应为空中，“碗里”不搭配。", "海底": "语义：海底不会有鸟群飞来，与常识冲突。"}, "sentence_index": 0, "correct_answer": "天上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把行李放在天上。", "explanation": "“天上”指天空中，行李不能放在天空中，这里应该用〈床上〉。"}, {"text": "这条小鱼在天上游。", "explanation": "“天上”指天空中，鱼不能在天空中游，这里应该用〈水里〉。"}, {"text": "他把车停在天上。", "explanation": "“天上”指天空中，车不能停在天空中，这里应该用〈路边〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天上", "is_correct": true, "explanation": "正确：“天上”指天空中，小明指着天上说月亮。"}, {"text": "书包里", "is_correct": false, "explanation": "语义：书包里不会有月亮，指着书包里说“那是月亮”句意不通。"}, {"text": "抽屉里", "is_correct": false, "explanation": "语义：抽屉里看不见月亮，句意不通。"}, {"text": "床底下", "is_correct": false, "explanation": "搭配：“指着……说”要求地点可见，“床底下”看不见月亮，不搭配。"}], "explanations": {"天上": "正确：“天上”指天空中，小明指着天上说月亮。", "书包里": "语义：书包里不会有月亮，指着书包里说“那是月亮”句意不通。", "抽屉里": "语义：抽屉里看不见月亮，句意不通。", "床底下": "搭配：“指着……说”要求地点可见，“床底下”看不见月亮，不搭配。"}, "sentence_index": 6, "correct_answer": "天上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆花种在天上。", "explanation": "“天上”指天空中，花不能种在天空中，这里应该用〈地里〉。"}, {"text": "他的书堆在天上。", "explanation": "“天上”指天空中，书不能堆在天空中，这里应该用〈桌上〉。"}, {"text": "我的眼镜戴在天上。", "explanation": "“天上”指天空中，眼镜不能戴在天空中，这里应该用〈脸上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小鸟在天上的飞。", "corrected_sentence": "小鸟在天上飞。", "error_description": "错误：“天上”后多加了“的”。正确：应说“在天上飞”，动词前的方位状语后面不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看见天上上的飞机了。", "corrected_sentence": "我看见天上的飞机了。", "error_description": "错误：“天上”后多加了一个“上”，方位词重复。正确：应说“天上的飞机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
