INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98787, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好强是什么事都想比别人做得好。", "primary_collocate": null, "pronunciation": "hào qiáng", "ipa": "xaʊ̯˥˩ tɕʰjaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "她从小就很好强。", "target_word": "好强", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他好强，考试一定要拿第一。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐是个好强的人。", "target_word": "好强", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为好强，他不愿意让别人帮忙。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈年轻时特别好强，工作很拼命。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太好强了，输了比赛一晚上没睡。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟很好强，什么都要和我比。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好强的小明每天都最早到学校。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她好强，做什么事都不想输给别人。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都说他很好强。", "target_word": "好强", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "性格上凡事都想比别人好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8ddae9-ae0a-4af4-8122-16a67952f138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好强", "is_correct": true, "explanation": "正确。好强指凡事都想比别人做得好，与“从小就很”搭配，描述她的性格。"}, {"text": "年迈", "is_correct": false, "explanation": "语义：“年迈”指年纪很大，与“从小就”矛盾，孩子不可能年迈。"}, {"text": "苍老", "is_correct": false, "explanation": "体貌：“苍老”形容外貌衰老，与一个从小就的孩子不合。"}, {"text": "古老", "is_correct": false, "explanation": "搭配：“古老”多修饰事物，如古老的城市，不说“很古老的人”。"}], "explanations": {"好强": "正确。好强指凡事都想比别人做得好，与“从小就很”搭配，描述她的性格。", "年迈": "语义：“年迈”指年纪很大，与“从小就”矛盾，孩子不可能年迈。", "苍老": "体貌：“苍老”形容外貌衰老，与一个从小就的孩子不合。", "古老": "搭配：“古老”多修饰事物，如古老的城市，不说“很古老的人”。"}, "sentence_index": 0, "correct_answer": "好强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身体很好强，一口气能扛起一百斤米。", "explanation": "这里应该用〈强壮〉。好强形容性格上凡事想比别人好，不用来说身体结实；身体结实应说〈强壮〉。"}, {"text": "他对新事物很好强，总想弄明白其中的道理。", "explanation": "这里应该用〈好奇〉。好强指争强好胜，不指对新事物感兴趣；对新事物感兴趣应说〈好奇〉。"}, {"text": "他的眼睛很好强，看东西又亮又有神。", "explanation": "这里应该用〈明亮〉。好强指性格争胜，不指眼睛亮；形容眼睛有神应说〈明亮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好强", "is_correct": true, "explanation": "正确。好强指凡事想比别人好，与“什么都要和我比”的态度一致。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与“什么都要和我比”的好胜态度相反，句子会自相矛盾。"}, {"text": "温顺", "is_correct": false, "explanation": "语义：“温顺”指性情柔和、不争，与“什么都要和我比”矛盾。"}, {"text": "谦恭", "is_correct": false, "explanation": "语义：“谦恭”指谦虚恭敬、礼让别人，与“什么都要和我比”的争胜态度矛盾。"}], "explanations": {"好强": "正确。好强指凡事想比别人好，与“什么都要和我比”的态度一致。", "懒惰": "语义：“懒惰”与“什么都要和我比”的好胜态度相反，句子会自相矛盾。", "温顺": "语义：“温顺”指性情柔和、不争，与“什么都要和我比”矛盾。", "谦恭": "语义：“谦恭”指谦虚恭敬、礼让别人，与“什么都要和我比”的争胜态度矛盾。"}, "sentence_index": 6, "correct_answer": "好强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他身材很好强，走起路来很有气派。", "explanation": "这里应该用〈高大〉。好强指性格上要强好胜，不用来形容身材；形容身材应说〈高大〉。"}, {"text": "他心地很好强，常常帮助陌生人。", "explanation": "这里应该用〈善良〉。好强指争强好胜，不说明心地好坏；形容心地应说〈善良〉。"}, {"text": "他的酒量很好强，两斤白酒下肚也不醉。", "explanation": "这里应该用〈大〉。好强指争胜心强，不指酒量大小；形容酒量应说“酒量很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被好强，不愿意让别人帮忙。", "corrected_sentence": "他很好强，不愿意让别人帮忙。", "error_description": "错误：「被」不能直接修饰形容词「好强」，程度应使用副词「很」。只需把「被」改为「很」，即为「他很好强」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是个好强得孩子，学习很拼命。", "corrected_sentence": "他是个好强的孩子，学习很拼命。", "error_description": "助词错误：形容词修饰名词时用「的」，「好强得孩子」中的「得」应为「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
