INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98788, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "要强；事事想超过别人。", "primary_collocate": null, "pronunciation": "hào qiáng", "ipa": "xaʊ̯˥˩ tɕʰjaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "奶奶一辈子好强，从不向人低头。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他性格好强，什么事都不肯落在别人后面。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好强的她又一次拿了第一名。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别这么好强，累了就休息一下。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个好强的孩子，学什么都要最好。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李好强，总想比同事做得多。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥好强，打球输了就不高兴。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她这么好强，一定会成功。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很好强，公司的事都要最好。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好强的人往往给自己很大压力。", "target_word": "好强", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "要强，事事想超过别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8ddae9-ae0a-4af4-8122-16a67952f138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好强", "is_correct": true, "explanation": "正确。好强即要强，事事想超过别人，与“从不向人低头”的性格一致。"}, {"text": "懦弱", "is_correct": false, "explanation": "语义：“懦弱”指胆小软弱，与“从不向人低头”矛盾。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指不熟悉，不用来形容一个人的性格，句子不通。"}, {"text": "偏僻", "is_correct": false, "explanation": "搭配：“偏僻”多修饰地方，如偏僻的山村，不说“很偏僻的人”。"}], "explanations": {"好强": "正确。好强即要强，事事想超过别人，与“从不向人低头”的性格一致。", "懦弱": "语义：“懦弱”指胆小软弱，与“从不向人低头”矛盾。", "陌生": "语义：“陌生”指不熟悉，不用来形容一个人的性格，句子不通。", "偏僻": "搭配：“偏僻”多修饰地方，如偏僻的山村，不说“很偏僻的人”。"}, "sentence_index": 0, "correct_answer": "好强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的手很好强，拿起针线来又快又稳。", "explanation": "这里应该用〈灵巧〉。好强指争胜心强，不指手的灵活；形容手巧应说〈灵巧〉。"}, {"text": "他的字写得很好强，一笔一画都很有力。", "explanation": "这里应该用〈有力〉。好强指性格争胜，不用来形容字迹；形容字写得有力应说〈有力〉。"}, {"text": "他的脑子很好强，见过一遍的字就能记住。", "explanation": "这里应该用〈好使〉。好强指争胜心强，不指记忆力；形容脑子灵、记性好应说“脑子很好使”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好强", "is_correct": true, "explanation": "正确。好强指争强好胜，所以输了球会不高兴，与句意一致。"}, {"text": "大度", "is_correct": false, "explanation": "语义：“大度”指宽容、不计较，与“输了就不高兴”矛盾。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”指镇定、不急躁，与输球后不高兴的情绪不合。"}, {"text": "淡泊", "is_correct": false, "explanation": "语域：“淡泊”偏书面，指不追求名利，与口语句子中输球后的情绪描写不合。"}], "explanations": {"好强": "正确。好强指争强好胜，所以输了球会不高兴，与句意一致。", "大度": "语义：“大度”指宽容、不计较，与“输了就不高兴”矛盾。", "冷静": "语义：“冷静”指镇定、不急躁，与输球后不高兴的情绪不合。", "淡泊": "语域：“淡泊”偏书面，指不追求名利，与口语句子中输球后的情绪描写不合。"}, "sentence_index": 6, "correct_answer": "好强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他个子很好强，说话却很有力量。", "explanation": "这里应该用〈矮小〉。好强指性格要强，不用来形容个子；形容个子不高应说〈矮小〉。"}, {"text": "他身体很好强，很少生病。", "explanation": "这里应该用〈健康〉。好强指争胜心强，不指身体状况；形容身体好、少生病应说〈健康〉。"}, {"text": "她的嗓子很好强，一开口全场都能听见。", "explanation": "这里应该用〈洪亮〉。好强指争胜心强，不指声音大小；形容嗓音大应说〈洪亮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他比我很好强，不肯认输。", "corrected_sentence": "他比我更好强，不肯认输。", "error_description": "错误：比较句「比……」中不能使用程度副词「很」，应改为「更」，说「比我更好强」。只需把「很」改为「更」即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个好强得同学总是考第一。", "corrected_sentence": "那个好强的同学总是考第一。", "error_description": "助词错误：形容词修饰名词时用「的」，「好强得同学」中的「得」应为「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760ccf3f-fce7-4d65-a4d6-8894981c248c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
