INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98792, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学术上观点相近的人所形成的派别。", "primary_collocate": null, "pronunciation": "xué pài", "ipa": "ɕɥe³⁵ pʰaɪ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "这两个学派的观点很不一样。", "target_word": "学派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是哪个学派的学者？", "target_word": "学派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儒家是中国很有名的学派。", "target_word": "学派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们介绍了几个学派。", "target_word": "学派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学派的人都喜欢讨论哲学。", "target_word": "学派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个学派争论了很多年。", "target_word": "学派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想建立自己的学派。", "target_word": "学派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西方有很多不同的学派。", "target_word": "学派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学派在法国很有名。", "target_word": "学派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个学派不太了解。", "target_word": "学派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "哲学学派", "label": "复合"}, {"form": "學派", "label": "繁体"}], "register": "书面", "sense_fingerprint": "学术上观点相近的人形成的派别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0951d8-de99-4fb1-907c-73c4f740a35d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学派", "is_correct": true, "explanation": "正确：“学派”指学术上观点相近的人形成的派别，可以说“两个学派的观点”。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产场所，不持有学术观点，与“观点很不一样”不合。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店是服务场所，不会有学术观点，句子语义说不通。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物没有观点，不能说“观点很不一样”。"}], "explanations": {"学派": "正确：“学派”指学术上观点相近的人形成的派别，可以说“两个学派的观点”。", "工厂": "语义：工厂是生产场所，不持有学术观点，与“观点很不一样”不合。", "饭店": "语义：饭店是服务场所，不会有学术观点，句子语义说不通。", "植物": "语义：植物没有观点，不能说“观点很不一样”。"}, "sentence_index": 0, "correct_answer": "学派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个乐队的风格属于摇滚学派。", "explanation": "这里应该用〈流派〉。“学派”多指学术、思想上的派别；说音乐风格一般用“流派”，“摇滚学派”不这样说。"}, {"text": "我的学派都很努力。", "explanation": "这里应该用〈学生〉。“学派”指派别，不指人，不能做“努力”的主语。"}, {"text": "这所大学里有两位学派。", "explanation": "这里应该用〈个〉。“学派”不用“位”计量（“位”用于人），应说“一个学派”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学派", "is_correct": true, "explanation": "正确：“建立学派”是固定说法，指创立自己的学术派别。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：午饭是吃的、做的，不能用“建立”来说。"}, {"text": "头发", "is_correct": false, "explanation": "体貌：头发是长出来的，不说“建立”，与外貌的说法不搭配。"}, {"text": "谣言", "is_correct": false, "explanation": "搭配：谣言是编造或散布的，不说“建立”，此处搭配不成立。"}], "explanations": {"学派": "正确：“建立学派”是固定说法，指创立自己的学术派别。", "午饭": "搭配：午饭是吃的、做的，不能用“建立”来说。", "头发": "体貌：头发是长出来的，不说“建立”，与外貌的说法不搭配。", "谣言": "搭配：谣言是编造或散布的，不说“建立”，此处搭配不成立。"}, "sentence_index": 6, "correct_answer": "学派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他要在家里举办一个学派。", "explanation": "这里应该用〈派对〉。“学派”指学术上的派别，不能举办；家里的聚会要说“派对”。"}, {"text": "他的学派很高。", "explanation": "这里应该用〈学历〉。“学派”是派别，不能用来说“高”。"}, {"text": "学派很贵。", "explanation": "这里应该用〈学费〉。“学派”是派别，没有价钱，不能说“很贵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位学派形成于十九世纪。", "corrected_sentence": "这个学派形成于十九世纪。", "error_description": "量词错误：“学派”应用量词“个”，“位”只用于人，此处应说“这个学派”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些学派们都很有名。", "corrected_sentence": "这些学派都很有名。", "error_description": "词缀错误：“学派”是群体名词，“们”只用于人，不能加在“学派”后面，应说“这些学派”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
