INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98793, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "家法是一个家里的老规矩，也指家里长辈用来管孩子的办法。", "primary_collocate": null, "pronunciation": "jiā fǎ", "ipa": "tɕja˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们家的家法是吃饭前先洗手。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，家法不能随便改。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的家法很严，晚上不能玩手机。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照家法，孩子要先叫人再吃饭。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把家法写在纸上，贴在门口。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有一条家法：说话要诚实。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子做错事，爸爸就用家法管他。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个家里，家法比什么都重要。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我最怕奶奶的家法。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就懂家法，从不晚归。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条家法", "label": "量词"}, {"form": "一套家法", "label": "量词"}], "register": "中性", "sense_fingerprint": "一个家里的老规矩，或长辈管教孩子的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b273a4-be21-462a-a87c-17dfbdecb405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98793, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家法", "is_correct": true, "explanation": "正确：家法指家里的老规矩，“吃饭前先洗手”正是这类规矩。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具是摆在家里的器物，不是规矩，与句中的做法不符。"}, {"text": "家谱", "is_correct": false, "explanation": "语义：家谱记录家族世系，不是行为规矩，无法说成“吃饭前先洗手”。"}, {"text": "家境", "is_correct": false, "explanation": "搭配：“家境”指家庭的经济状况，不能用来说明要遵守什么做法。"}], "explanations": {"家法": "正确：家法指家里的老规矩，“吃饭前先洗手”正是这类规矩。", "家具": "语义：家具是摆在家里的器物，不是规矩，与句中的做法不符。", "家谱": "语义：家谱记录家族世系，不是行为规矩，无法说成“吃饭前先洗手”。", "家境": "搭配：“家境”指家庭的经济状况，不能用来说明要遵守什么做法。"}, "sentence_index": 0, "correct_answer": "家法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府刚颁布了一条新家法，要求全市居民遵守。", "explanation": "这里应该用〈法规〉。法规指国家或政府颁布的规定；家法只指一家之内的规矩，不能由政府颁布。"}, {"text": "这个复习家法很实用，考试前我都用。", "explanation": "这里应该用〈方法〉。方法指做事的步骤，可用于复习；家法专指家里的规矩或长辈管教子孙的办法，不能指复习步骤。"}, {"text": "妈妈做的家法很好吃，全家都爱吃。", "explanation": "这里应该用〈家常菜〉。家常菜指家里日常做的饭菜；家法指家里的规矩或长辈管教子孙的办法，不能指饭菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98793, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家法", "is_correct": true, "explanation": "正确：“用……管他”中的工具应是管教的办法，家法正是长辈管教子孙的办法。"}, {"text": "家电", "is_correct": false, "explanation": "语义：家电是电器，不是管教孩子的办法，“用家电管他”说不通。"}, {"text": "家常", "is_correct": false, "explanation": "搭配：“家常”指日常琐事，不能作“用……管他”的工具。"}, {"text": "家书", "is_correct": false, "explanation": "语义：家书是写给家人的信，不能用来管教孩子。"}], "explanations": {"家法": "正确：“用……管他”中的工具应是管教的办法，家法正是长辈管教子孙的办法。", "家电": "语义：家电是电器，不是管教孩子的办法，“用家电管他”说不通。", "家常": "搭配：“家常”指日常琐事，不能作“用……管他”的工具。", "家书": "语义：家书是写给家人的信，不能用来管教孩子。"}, "sentence_index": 6, "correct_answer": "家法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部家法是国家制定的，大家都要遵守。", "explanation": "这里应该用〈法律〉。法律由国家制定、适用于全体公民；家法只在一家之内有效，不能指国家制定的规定。"}, {"text": "我们用这种家法打扫房间。", "explanation": "这里应该用〈方式〉。方式指做事的办法，可用于打扫；家法专指家里的规矩或管教办法，不能指打扫的方式。"}, {"text": "他把全部家法都卖了，只留下一张床。", "explanation": "这里应该用〈家当〉。家当指家里的财物，可以卖掉；家法指家里的规矩或管教办法，不能拿来卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把家法是爷爷定下的，全家都要遵守。", "corrected_sentence": "这条家法是爷爷定下的，全家都要遵守。", "error_description": "量词错误：“家法”是抽象的规矩，应说“这条家法”，不能用“把”（“把”用于有柄的器具）。正确形式是“这条家法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥哥小时候过挨家法，到现在还记得。", "corrected_sentence": "我哥哥小时候挨过家法，到现在还记得。", "error_description": "“过”的位置错误：动词后带“过”时，“过”应紧跟动词，说“挨过家法”，不能颠倒成“过挨家法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98794, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98794, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "家族或家庭中的规矩，也指长辈惩罚子孙的办法。", "primary_collocate": null, "pronunciation": "jiā fǎ", "ipa": "tɕja˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "古时候，孩子犯了错，要受家法。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不听话，父亲就请出了家法。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个大家族的家法有很多条。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按家法，不孝的子孙不能进家门。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥偷了钱，被爷爷按家法罚跪。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说家法不严，家就乱了。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个家族的家法传了一百多年。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犯了大错，只好接受家法。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家法再严，也要讲道理。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷小时候挨过家法，现在还记得。", "target_word": "家法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条家法", "label": "量词"}, {"form": "一套家法", "label": "量词"}], "register": "中性", "sense_fingerprint": "家族的规矩，以及长辈惩罚子孙的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b273a4-be21-462a-a87c-17dfbdecb405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家法", "is_correct": true, "explanation": "正确：“受家法”指接受长辈按家规的惩罚，与句意相符。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具是器物，不是惩罚的办法，“要受家具”说不通。"}, {"text": "家谱", "is_correct": false, "explanation": "语义：家谱记录世系，不是惩罚孩子的办法，无法与“受”搭配成句。"}, {"text": "家境", "is_correct": false, "explanation": "搭配：“家境”是经济状况，“受”后不能接这类表示状况的词。"}], "explanations": {"家法": "正确：“受家法”指接受长辈按家规的惩罚，与句意相符。", "家具": "语义：家具是器物，不是惩罚的办法，“要受家具”说不通。", "家谱": "语义：家谱记录世系，不是惩罚孩子的办法，无法与“受”搭配成句。", "家境": "搭配：“家境”是经济状况，“受”后不能接这类表示状况的词。"}, "sentence_index": 0, "correct_answer": "家法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国务院颁布了一条新家法，要求全民遵守。", "explanation": "这里应该用〈法规〉。法规是国家颁布的规定；家法只指一家一族之内的规矩，不能由国务院颁布。"}, {"text": "这个学习家法很有效，我每天都用。", "explanation": "这里应该用〈方法〉。方法可指学习的步骤；家法专指家族规矩或长辈惩罚子孙的办法，不能泛指学习方法。"}, {"text": "他每天都干家法，洗衣做饭，很辛苦。", "explanation": "这里应该用〈家务〉。家务指家里日常的杂事；家法指家族的规矩或长辈惩罚子孙的办法，不能说“干家法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家法", "is_correct": true, "explanation": "正确：家法是家族的规矩，可以世代相传，“传了一百多年”与之相符。"}, {"text": "家电", "is_correct": false, "explanation": "语义：家电是电器，不是规矩，不能说“传了一百多年”。"}, {"text": "家禽", "is_correct": false, "explanation": "语义：家禽是饲养的禽类，不指规矩，句意不通。"}, {"text": "家务", "is_correct": false, "explanation": "语义：家务指日常杂事，不是可以传承的规矩，与“传了一百多年”不搭。"}], "explanations": {"家法": "正确：家法是家族的规矩，可以世代相传，“传了一百多年”与之相符。", "家电": "语义：家电是电器，不是规矩，不能说“传了一百多年”。", "家禽": "语义：家禽是饲养的禽类，不指规矩，句意不通。", "家务": "语义：家务指日常杂事，不是可以传承的规矩，与“传了一百多年”不搭。"}, "sentence_index": 6, "correct_answer": "家法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部家法是全国人大通过的，全国都要遵守。", "explanation": "这里应该用〈法律〉。法律由国家立法机关通过，适用于全国；家法只在一家一族之内有效。"}, {"text": "我们用这种家法开会，效率很高。", "explanation": "这里应该用〈方式〉。方式指做事的办法，可以用于开会；家法专指家族规矩或管教子孙的办法，不能指开会的方式。"}, {"text": "他把家里的家法都当掉了，换了点钱。", "explanation": "这里应该用〈家当〉。家当指家里的财物，可以当掉、卖掉；家法指家族的规矩或管教子孙的办法，不能拿去当掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个家族传下了一张家法，代代遵守。", "corrected_sentence": "这个家族传下了一套家法，代代遵守。", "error_description": "量词错误：成套的家规应说“一套家法”，不能用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爸爸年轻时过挨家法，现在想起来还害怕。", "corrected_sentence": "我爸爸年轻时挨过家法，现在想起来还害怕。", "error_description": "“过”的位置错误：“过”应紧跟动词，说“挨过家法”，不能说“过挨家法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
