INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98795, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "实际情况是事情真正的样子。", "primary_collocate": null, "pronunciation": "shí jì qíng kuàng", "ipa": "ʂɨ˧˥ tɕi˥˩ tɕʰiŋ˧˥ kʰuaŋ˥˩", "syllable_count": 4, "sentences": [{"text": "别人怎么说都行，实际情况谁也不清楚。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他很忙，实际情况是在家睡觉。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看起来很容易，实际情况却很难。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实际情况比新闻说的好多了。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你告诉我实际情况，我不会生气。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要根据实际情况来安排时间。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈问起考试，他才说了实际情况。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的实际情况，你来了就知道。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕大家担心，没说实际情况。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片很漂亮，实际情况完全不同。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情真正的样子，常与别人的说法或表面看起来的样子相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0979d30-f37e-4aca-8dc4-51c8b00cb872') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98795, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实际情况", "is_correct": true, "explanation": "正确：实际情况指事情真正的样子，与“别人怎么说都行，谁也不清楚”相符。"}, {"text": "梦境", "is_correct": false, "explanation": "语义：梦境是睡梦中的景象，与“谁也不清楚”的真实情况无关。"}, {"text": "神话", "is_correct": false, "explanation": "语义：神话是传说故事，不是别人说法之外需要弄清楚的真相。"}, {"text": "谎言", "is_correct": false, "explanation": "语义：谎言与真实相反，句子强调的是真实的样子，与之不符。"}], "explanations": {"实际情况": "正确：实际情况指事情真正的样子，与“别人怎么说都行，谁也不清楚”相符。", "梦境": "语义：梦境是睡梦中的景象，与“谁也不清楚”的真实情况无关。", "神话": "语义：神话是传说故事，不是别人说法之外需要弄清楚的真相。", "谎言": "语义：谎言与真实相反，句子强调的是真实的样子，与之不符。"}, "sentence_index": 0, "correct_answer": "实际情况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有一个伟大的实际情况。", "explanation": "这里应该用〈梦想〉。梦想是尚未实现的愿望，实际情况是已经存在的真实状况，不能说“伟大的实际情况”。"}, {"text": "大家都期待这个实际情况的到来。", "explanation": "这里应该用〈愿望〉。期待的是尚未发生的事，实际情况已经存在，不用来表示期待。"}, {"text": "我把这个实际情况装进了盒子里。", "explanation": "这里应该用〈礼物〉。实际情况是抽象的状况，不是可以装进盒子的实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98795, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实际情况", "is_correct": true, "explanation": "正确：实际情况指事情真正的样子，与“他才说了”的语境相符。"}, {"text": "童话", "is_correct": false, "explanation": "语义：童话是虚构的故事，不是考试的真实情况。"}, {"text": "想象", "is_correct": false, "explanation": "搭配：想象是心中的设想，不能说“说了想象”。"}, {"text": "传说", "is_correct": false, "explanation": "语义：传说是流传的故事，与真实说明不符。"}], "explanations": {"实际情况": "正确：实际情况指事情真正的样子，与“他才说了”的语境相符。", "童话": "语义：童话是虚构的故事，不是考试的真实情况。", "想象": "搭配：想象是心中的设想，不能说“说了想象”。", "传说": "语义：传说是流传的故事，与真实说明不符。"}, "sentence_index": 6, "correct_answer": "实际情况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的实际情况很好听。", "explanation": "这里应该用〈旋律〉。实际情况是事物的真实状态，不用来形容作品好不好听。"}, {"text": "这个方案的实际情况很大胆。", "explanation": "这里应该用〈设想〉。大胆形容想法，实际情况是客观状况，不能说大胆。"}, {"text": "他的实际情况很高大。", "explanation": "这里应该用〈身材〉。“高大”形容人的身材或事物的规模，实际情况指真实存在的状况，不能用来形容人的体型。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直没有说出这只实际情况。", "corrected_sentence": "他一直没有说出这种实际情况。", "error_description": "量词搭配错误。“情况”不用“只”，应说“这种实际情况”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张实际情况很难懂。", "corrected_sentence": "这种实际情况很难懂。", "error_description": "量词搭配错误。“情况”不用“张”，应说“这种实际情况”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
