INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物真实存在的状况。", "primary_collocate": null, "pronunciation": "shí jì qíng kuàng", "ipa": "ʂɨ˧˥ tɕi˥˩ tɕʰiŋ˧˥ kʰuaŋ˥˩", "syllable_count": 4, "sentences": [{"text": "我们要先了解实际情况，再做决定。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实际情况和你想的不一样。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师去学生家，看看实际情况。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里写得很好，可实际情况不是这样。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说一说工厂的实际情况。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要根据病人的实际情况开药。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划不符合实际情况。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没去过那里，不知道实际情况。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理亲自来看了实际情况。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者到现场，了解了当地的实际情况。", "target_word": "实际情况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物或某个地方、某个人现在真实存在的状况，需要去了解或根据它做决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0979d30-f37e-4aca-8dc4-51c8b00cb872') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实际情况", "is_correct": true, "explanation": "正确：实际情况指真实存在的状况，与“了解……再做决定”相符。"}, {"text": "童话", "is_correct": false, "explanation": "语义：童话是虚构的故事，不能作为做决定前要了解的真实状况。"}, {"text": "想象", "is_correct": false, "explanation": "搭配：想象是心中的构思，不能与“了解”搭配作为决定的依据。"}, {"text": "梦境", "is_correct": false, "explanation": "语义：梦境是睡梦中的景象，与做决定所需的现实依据不符。"}], "explanations": {"实际情况": "正确：实际情况指真实存在的状况，与“了解……再做决定”相符。", "童话": "语义：童话是虚构的故事，不能作为做决定前要了解的真实状况。", "想象": "搭配：想象是心中的构思，不能与“了解”搭配作为决定的依据。", "梦境": "语义：梦境是睡梦中的景象，与做决定所需的现实依据不符。"}, "sentence_index": 0, "correct_answer": "实际情况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只是表面的实际情况，不是真的。", "explanation": "这里应该用〈假象〉。实际情况指真实存在的状况，不能指表面的样子。"}, {"text": "别听信实际情况，要自己去看。", "explanation": "这里应该用〈传言〉。听信指相信别人的说法，实际情况是客观状况，不能被听信。"}, {"text": "他的实际情况很帅气。", "explanation": "这里应该用〈外表〉。“帅气”形容外貌，实际情况指真实存在的状况，不指外表的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实际情况", "is_correct": true, "explanation": "正确：实际情况指真实状况，与“计划不符合实际情况”相符。"}, {"text": "神话", "is_correct": false, "explanation": "语义：神话是古代的传说，与“符合现实”的意思不符。"}, {"text": "谎言", "is_correct": false, "explanation": "语义：谎言是假话，与“符合真实情况”的意思相反。"}, {"text": "童谣", "is_correct": false, "explanation": "语义：童谣是儿歌，不能用来衡量计划是否符合现实。"}], "explanations": {"实际情况": "正确：实际情况指真实状况，与“计划不符合实际情况”相符。", "神话": "语义：神话是古代的传说，与“符合现实”的意思不符。", "谎言": "语义：谎言是假话，与“符合真实情况”的意思相反。", "童谣": "语义：童谣是儿歌，不能用来衡量计划是否符合现实。"}, "sentence_index": 6, "correct_answer": "实际情况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他脑子里的实际情况很丰富。", "explanation": "这里应该用〈想象〉。实际情况指现实中真实存在的状况，不指脑子里构想的画面。"}, {"text": "我昨晚做了一个奇怪的实际情况。", "explanation": "这里应该用〈梦〉。实际情况是现实中的状况，不是睡眠中出现的景象。"}, {"text": "我同意他的观点，因为他的实际情况很有道理。", "explanation": "这里应该用〈说法〉。“很有道理”形容说法、建议等，实际情况指客观状况，不能讲道理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要先实际情况核实清楚，再做决定。", "corrected_sentence": "我们要先把实际情况核实清楚，再做决定。", "error_description": "把字句漏了“把”。“实际情况”前要用“把”引出，应说“我们要先把实际情况核实清楚”，不能说“我们要先实际情况核实清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只实际情况很少见，大家都很惊讶。", "corrected_sentence": "这种实际情况很少见，大家都很惊讶。", "error_description": "量词搭配错误。“情况”不用“只”，应说“这种实际情况”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
