INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98797, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "小小是非常小的样子。", "primary_collocate": null, "pronunciation": "xiǎo xiǎo", "ipa": "ɕjɑʊ̯²¹⁴ ɕjɑʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "树下有一只小小的蚂蚁，正在搬东西。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗小小的种子，会长成一棵大树。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在山上，只有一个小小的木屋，但很温暖。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的灯光，在黑夜里亮着。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的船在大海里，看起来像一片叶子。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的脚小小的，穿不了妈妈的鞋。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的一块糖，一口就吃完了。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一个小小的闹钟，滴答滴答地响。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蓝天下，有一个小小的点，那是一架飞机。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把小小的虫子放在手心里看。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小小的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "形容样子非常小，带有小巧可爱的意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64d38e22-74eb-4da9-84a8-607619094d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小小", "is_correct": true, "explanation": "“小小”形容蚂蚁很小，与句意相符。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不能用来形容蚂蚁。"}, {"text": "冰冷", "is_correct": false, "explanation": "搭配：“冰冷”形容温度，不能用来形容蚂蚁。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：“辽阔”形容土地、天空等广大，不能用来形容蚂蚁。"}], "explanations": {"小小": "“小小”形容蚂蚁很小，与句意相符。", "宽敞": "搭配：“宽敞”形容空间，不能用来形容蚂蚁。", "冰冷": "搭配：“冰冷”形容温度，不能用来形容蚂蚁。", "辽阔": "搭配：“辽阔”形容土地、天空等广大，不能用来形容蚂蚁。"}, "sentence_index": 0, "correct_answer": "小小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这头大象长得小小的，比房子还高。", "explanation": "这里应该用〈高大〉。“小小”形容非常小，与“比房子还高”矛盾。"}, {"text": "这条河小小的，宽得看不到对岸。", "explanation": "这里应该用〈宽阔〉。“小小”形容非常小，与“看不到对岸”矛盾。"}, {"text": "这座山小小的，我们爬了三天才到山顶。", "explanation": "这里应该用〈高大〉。“小小”形容非常小，与“爬了三天”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小小", "is_correct": true, "explanation": "“小小”形容糖很小，与“一口就吃完”相符。"}, {"text": "巨大", "is_correct": false, "explanation": "语义：糖如果“巨大”，就不可能一口吃完，与句意矛盾。"}, {"text": "庞大", "is_correct": false, "explanation": "语义：“庞大”说体积极大，与“一口就吃完”矛盾。"}, {"text": "沉甸甸", "is_correct": false, "explanation": "语义：“沉甸甸”形容重量大，与“一口就吃完”不符。"}], "explanations": {"小小": "“小小”形容糖很小，与“一口就吃完”相符。", "巨大": "语义：糖如果“巨大”，就不可能一口吃完，与句意矛盾。", "庞大": "语义：“庞大”说体积极大，与“一口就吃完”矛盾。", "沉甸甸": "语义：“沉甸甸”形容重量大，与“一口就吃完”不符。"}, "sentence_index": 6, "correct_answer": "小小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条鲸鱼小小的，比一条船还长。", "explanation": "这里应该用〈巨大〉。“小小”形容非常小，与“比一条船还长”矛盾。"}, {"text": "这只猫小小地跑过了草地。", "explanation": "“小小”不能作副词修饰动作；应说〈轻轻地〉或〈小心地〉。"}, {"text": "这个操场小小的，能站下一万人。", "explanation": "这里应该用〈宽大〉。“小小”形容非常小，与“能站下一万人”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗台上有一盏很小小的台灯，很温暖。", "corrected_sentence": "窗台上有一盏小小的台灯，很温暖。", "error_description": "“小小”已表示“很小”，前面不能再加“很”。应说“小小的台灯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在地上发现了一个小小得脚印。", "corrected_sentence": "她在地上发现了一个小小的脚印。", "error_description": "“小小”作定语要用“的”，不能用“得”。应说“小小的脚印”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
