INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98798, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很小的；不大的。", "primary_collocate": null, "pronunciation": "xiǎo xiǎo", "ipa": "ɕjɑʊ̯²¹⁴ ɕjɑʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "这是一间小小的房子，只能住两个人。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的一只鸟，飞得却很高。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从口袋里拿出一个小小的盒子。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的杯子里，只能放一点点水。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的手小小的，很可爱。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外有一只小小的猫，正看着我。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小小的盒子里，放着我的生日礼物。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一朵小小的花，是白色的。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的一个包，怎么能放下这么多书？", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把小小的照片放进了钱包里。", "target_word": "小小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小小的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "形容东西体积很小、不大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64d38e22-74eb-4da9-84a8-607619094d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小小", "is_correct": true, "explanation": "“小小”形容面积很小，与“只能住两个人”相符。"}, {"text": "宽敞", "is_correct": false, "explanation": "语义：“宽敞”说面积大，与“只能住两个人”矛盾。"}, {"text": "巨大", "is_correct": false, "explanation": "语义：“巨大”说面积很大，与“只能住两个人”矛盾。"}, {"text": "胖胖", "is_correct": false, "explanation": "体貌：“胖胖”形容人或动物的体型，房子不能这样形容。"}], "explanations": {"小小": "“小小”形容面积很小，与“只能住两个人”相符。", "宽敞": "语义：“宽敞”说面积大，与“只能住两个人”矛盾。", "巨大": "语义：“巨大”说面积很大，与“只能住两个人”矛盾。", "胖胖": "体貌：“胖胖”形容人或动物的体型，房子不能这样形容。"}, "sentence_index": 0, "correct_answer": "小小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种小小的颜色很好看。", "explanation": "“小小”只能形容大小，不能形容颜色；颜色的深浅应说〈浅〉或〈淡〉。"}, {"text": "这辆车的小小速度很惊人。", "explanation": "“小小”只能形容体积，不能形容速度；速度慢应说〈慢〉。"}, {"text": "这台机器的小小质量很好。", "explanation": "“小小”只说大小，不能评价质量；质量好应说〈优良〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小小", "is_correct": true, "explanation": "“小小”形容盒子体积小，与整句相符。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”形容人的情绪，不能形容盒子。"}, {"text": "空空", "is_correct": false, "explanation": "语义：“空空”指里面没有东西，与“放着我的生日礼物”矛盾。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”形容声音，盒子不能用来形容吵闹。"}], "explanations": {"小小": "“小小”形容盒子体积小，与整句相符。", "悲伤": "语义：“悲伤”形容人的情绪，不能形容盒子。", "空空": "语义：“空空”指里面没有东西，与“放着我的生日礼物”矛盾。", "吵闹": "语义：“吵闹”形容声音，盒子不能用来形容吵闹。"}, "sentence_index": 6, "correct_answer": "小小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的小小味道很好。", "explanation": "“小小”只能形容大小，不能形容味道；味道鲜美应说〈鲜美〉。"}, {"text": "他说话的小小声音很好听。", "explanation": "“小小”形容体积大小，不能修饰声音的高低；声音不大应说〈轻〉或〈小〉。"}, {"text": "这只猫的小小性格很温和。", "explanation": "“小小”只能形容体积，不能修饰性格；此处应去掉“小小”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个杯子小小得，只能放一点水。", "corrected_sentence": "这个杯子小小的，只能放一点水。", "error_description": "“小小”作谓语描写大小时，后面要用“的”（杯子小小的），不能用“得”；应改为“小小的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把小小钥匙放进了口袋里。", "corrected_sentence": "他把小小的钥匙放进了口袋里。", "error_description": "“小小”作定语时要加“的”，应说“小小的钥匙”；漏掉“的”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98801, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "钝", "is_correct": true, "explanation": "正确：钝指不锋利，与“尖锐”（末端锋利）相对，为反义。"}, {"text": "柔软", "is_correct": false, "explanation": "与“尖锐”无反义关系：柔软指质地松软，与尖端形态无关。"}, {"text": "平滑", "is_correct": false, "explanation": "与“尖锐”无反义关系：平滑指表面平整，不描述末端形态。"}, {"text": "潮湿", "is_correct": false, "explanation": "与“尖锐”无反义关系：潮湿指含水分多，与尖端形态无关。"}], "correct_answer": "钝", "explanations": {"钝": "正确：钝指不锋利，与“尖锐”（末端锋利）相对，为反义。", "柔软": "与“尖锐”无反义关系：柔软指质地松软，与尖端形态无关。", "平滑": "与“尖锐”无反义关系：平滑指表面平整，不描述末端形态。", "潮湿": "与“尖锐”无反义关系：潮湿指含水分多，与尖端形态无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98801, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "钝", "is_correct": true, "explanation": "正确：钝指不锋利，与“尖锐”（末端锋利）相对，为反义。"}, {"text": "粗糙", "is_correct": false, "explanation": "与“尖锐”无反义关系：粗糙指表面不平滑，与尖端形态无关。"}, {"text": "宽阔", "is_correct": false, "explanation": "与“尖锐”无反义关系：宽阔指面积大，与尖端无关。"}, {"text": "厚重", "is_correct": false, "explanation": "与“尖锐”无反义关系：厚重指厚而重，不描述末端形态。"}], "correct_answer": "钝", "explanations": {"钝": "正确：钝指不锋利，与“尖锐”（末端锋利）相对，为反义。", "粗糙": "与“尖锐”无反义关系：粗糙指表面不平滑，与尖端形态无关。", "宽阔": "与“尖锐”无反义关系：宽阔指面积大，与尖端无关。", "厚重": "与“尖锐”无反义关系：厚重指厚而重，不描述末端形态。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98801, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "尖锐是很尖很利，一碰就会扎人。", "primary_collocate": null, "pronunciation": "jiān ruì", "ipa": "tɕjɛn˥ ɻweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这根针很尖锐，别用手碰。", "target_word": "尖锐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一块尖锐的石头。", "target_word": "尖锐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，这把剪刀的头很尖锐。", "target_word": "尖锐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仙人掌的刺又细又尖锐。", "target_word": "尖锐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不能玩太尖锐的东西。", "target_word": "尖锐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼骨头很尖锐，吃的时候要小心。", "target_word": "尖锐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀的刀尖非常尖锐。", "target_word": "尖锐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子角太尖锐，我们贴上了软垫。", "target_word": "尖锐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用尖锐的树枝在地上画画。", "target_word": "尖锐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎的爪子又长又尖锐。", "target_word": "尖锐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "东西很尖很利，一碰就会扎人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b273a4-be21-462a-a87c-17dfbdecb405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98801, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尖锐", "is_correct": true, "explanation": "正确：“这根针”末端又细又利，“别用手碰”的提醒与之相符。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：针很轻，不能说“沉重”，句意不通。"}, {"text": "宽大", "is_correct": false, "explanation": "体貌：针细长，不能形容为“宽大”。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：针是硬的，不能说“柔软”，与“别用手碰”的提醒矛盾。"}], "explanations": {"尖锐": "正确：“这根针”末端又细又利，“别用手碰”的提醒与之相符。", "沉重": "语义：针很轻，不能说“沉重”，句意不通。", "宽大": "体貌：针细长，不能形容为“宽大”。", "柔软": "语义：针是硬的，不能说“柔软”，与“别用手碰”的提醒矛盾。"}, "sentence_index": 0, "correct_answer": "尖锐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这床棉被很尖锐，盖起来很暖和。", "explanation": "这里应该用〈柔软〉。棉被质地松软，没有尖端；尖锐用于末端又细又利的物体，与棉被不相符。"}, {"text": "这块布很尖锐，做成衣服很厚实。", "explanation": "这里应该用〈厚实〉。厚实指质地厚而结实，适用于布料；尖锐指末端又尖又利、会扎人，不能用来形容布料。"}, {"text": "这块石头很尖锐，摸起来很舒服。", "explanation": "这里应该用〈光滑〉。光滑指表面平整不扎手；尖锐指末端锋利、会扎手，与“摸起来很舒服”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尖锐", "is_correct": true, "explanation": "正确：“刀尖非常尖锐”描述刀尖末端锋利，与句意相符。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列有序，不能用来形容刀尖。"}, {"text": "温润", "is_correct": false, "explanation": "搭配：“温润”多用于玉石或性情，不能形容刀尖。"}, {"text": "巨大", "is_correct": false, "explanation": "体貌：刀尖是细小部分，不能形容为“巨大”。"}], "explanations": {"尖锐": "正确：“刀尖非常尖锐”描述刀尖末端锋利，与句意相符。", "整齐": "搭配：“整齐”形容排列有序，不能用来形容刀尖。", "温润": "搭配：“温润”多用于玉石或性情，不能形容刀尖。", "巨大": "体貌：刀尖是细小部分，不能形容为“巨大”。"}, "sentence_index": 6, "correct_answer": "尖锐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这颗石子很尖锐，不会扎手。", "explanation": "这里应该用〈圆润〉。圆润指末端圆滑、不伤手；尖锐指末端锋利、会扎手，与“不会扎手”矛盾。"}, {"text": "这把木刀很尖锐，不会伤人。", "explanation": "这里应该用〈钝〉。钝指不锋利，与“不会伤人”相符；尖锐指锋利，与句意矛盾。"}, {"text": "这根橡皮管很尖锐，弯折也不会断。", "explanation": "这里应该用〈柔韧〉。柔韧指软而有韧性，能够弯折；尖锐指硬而锋利，不能用来形容可以弯折的软管。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把剪刀很尖锐地，小心点。", "corrected_sentence": "这把剪刀很尖锐，小心点。", "error_description": "助词误用：“尖锐”在这里作谓语，后面不能加“地”（“地”用在状语后修饰动词），应说“很尖锐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把刀的刀尖很太尖锐了，别让孩子碰。", "corrected_sentence": "这把刀的刀尖太尖锐了，别让孩子碰。", "error_description": "程度词重复：“很”与“太”不能同时修饰“尖锐”，应只用“太”，说“太尖锐了”，不能说“很太尖锐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
