INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98804, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示在同类事物中特别突出的一个。", "primary_collocate": null, "pronunciation": "yóu qí shì", "ipa": "jou˧˥ tɕʰi˧˥ ʂʐ̩˥˩", "syllable_count": 3, "sentences": [{"text": "我喜欢水果，尤其是苹果。", "target_word": "尤其是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢运动，尤其是踢足球。", "target_word": "尤其是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里夏天很热，尤其是七月。", "target_word": "尤其是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都爱吃甜的，尤其是巧克力。", "target_word": "尤其是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢北京的秋天，尤其是十月。", "target_word": "尤其是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都很努力，尤其是小王。", "target_word": "尤其是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会说好几种语言，尤其是法语说得很好。", "target_word": "尤其是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节时车票很难买，尤其是回家的火车票。", "target_word": "尤其是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱看书，尤其是历史书。", "target_word": "尤其是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国菜我都爱吃，尤其是四川菜。", "target_word": "尤其是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尤其", "label": "省略形式"}], "register": "中性", "sense_fingerprint": "尤其是|同类中特别突出的一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88de35c8-0eb8-4233-8872-c58f86c79787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98804, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尤其是", "is_correct": true, "explanation": "正确答案。“尤其是”引出同类中特别突出的一个，符合句意。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：偏偏表示出乎意料或与预期相反，与“喜欢水果”的并列句意不合。"}, {"text": "却", "is_correct": false, "explanation": "搭配：“却”要接动词或形容词，不能直接接名词“苹果”。"}, {"text": "竟然", "is_correct": false, "explanation": "搭配：“竟然”要接谓语，不能直接接名词“苹果”。"}], "explanations": {"尤其是": "正确答案。“尤其是”引出同类中特别突出的一个，符合句意。", "偏偏": "语义：偏偏表示出乎意料或与预期相反，与“喜欢水果”的并列句意不合。", "却": "搭配：“却”要接动词或形容词，不能直接接名词“苹果”。", "竟然": "搭配：“竟然”要接谓语，不能直接接名词“苹果”。"}, "sentence_index": 0, "correct_answer": "尤其是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们都爱吃甜的，尤其是蔬菜。", "explanation": "蔬菜不属于“甜的”这一类，“尤其是”只能在同类中突出一个成员，这里应在甜食中选一种来突出。"}, {"text": "孩子们都爱吃甜的，尤其是大人。", "explanation": "大人不属于“孩子们”这一类，尤其是只能在同类中突出一个成员，这里范围用错了。"}, {"text": "孩子们都爱吃甜的，尤其是咸菜。", "explanation": "咸菜不是甜的，不属于“甜的”这一类，“尤其是”只能在同类中突出一个成员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尤其是", "is_correct": true, "explanation": "正确答案。“尤其是法语说得很好”突出多种语言中特别好的一种，符合句意。"}, {"text": "更", "is_correct": false, "explanation": "搭配：“更”要修饰形容词或动词，不能直接接名词“法语”。"}, {"text": "也", "is_correct": false, "explanation": "搭配：“也”要放在谓语前，不能直接接名词“法语”。"}, {"text": "乃", "is_correct": false, "explanation": "语域：“乃”是书面语，口语中不说“乃法语说得很好”。"}], "explanations": {"尤其是": "正确答案。“尤其是法语说得很好”突出多种语言中特别好的一种，符合句意。", "更": "搭配：“更”要修饰形容词或动词，不能直接接名词“法语”。", "也": "搭配：“也”要放在谓语前，不能直接接名词“法语”。", "乃": "语域：“乃”是书面语，口语中不说“乃法语说得很好”。"}, "sentence_index": 6, "correct_answer": "尤其是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中国菜我都爱吃，尤其是北京的冬天。", "explanation": "“北京的冬天”不属于“中国菜”这一类，“尤其是”只能在同类中突出一个成员，这里范围用错了。"}, {"text": "中国菜我都爱吃，尤其是美国汉堡。", "explanation": "美国汉堡不属于中国菜，“尤其是”只能在同类中突出一个成员，这里范围用错了。"}, {"text": "中国菜我都爱吃，尤其是可乐。", "explanation": "可乐是饮料，不是中国菜，“尤其是”只能在同类中突出一个成员，这里范围用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都爱看电影，尤其的动画片。", "corrected_sentence": "大家都爱看电影，尤其是动画片。", "error_description": "“尤其是”是固定搭配，“是”不能换成“的”：应说“尤其是动画片”，不能说“尤其的动画片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喜欢喝茶，尤其有绿茶。", "corrected_sentence": "我喜欢喝茶，尤其是绿茶。", "error_description": "错误形式：“尤其有绿茶”；正确形式：“尤其是绿茶”。突出同类中的一个成员要用“尤其是”，不能把“是”换成“有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
