INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98805, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工作队是一群人，一起到某个地方去做一件事。", "primary_collocate": null, "pronunciation": "gōng zuò duì", "ipa": "kʊŋ˥ tswɔ˥˩ tweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "工作队明天去山里。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一支工作队来到我们村子。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作队的人住在老乡家里。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支工作队有十个人。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作队帮村民修了一条路。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是工作队的队长。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作队走过很多地方。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们跟着工作队去了河边。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作队带着药来到山上。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作队今天早上从城里出发。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "工作队员", "label": "复合"}, {"form": "工作隊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：一起去外地做事的一群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b273a4-be21-462a-a87c-17dfbdecb405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98805, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作队", "is_correct": true, "explanation": "工作队是一群人，可以“明天去山里”做事。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：办公室是地方，不会自己去山里。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是建筑，不能去山里。"}, {"text": "苍生", "is_correct": false, "explanation": "语域：“苍生”是文言词，不用于这样的口语叙述。"}], "explanations": {"工作队": "工作队是一群人，可以“明天去山里”做事。", "办公室": "语义：办公室是地方，不会自己去山里。", "图书馆": "语义：图书馆是建筑，不能去山里。", "苍生": "语域：“苍生”是文言词，不用于这样的口语叙述。"}, "sentence_index": 0, "correct_answer": "工作队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的工作队昨天赢得了冠军。", "explanation": "这里应该用〈球队〉。工作队是为完成某项任务临时组成的集体，不参加体育比赛。"}, {"text": "这个工作队一直待在办公室里，从来不出门。", "explanation": "这里应该用〈部门〉。工作队指一群人一起到某个地方去做事，一直待在办公室里不外出的是固定部门，不是工作队。"}, {"text": "工作队在树上叫了一个早上。", "explanation": "这里应该用〈小鸟〉。工作队是一群去做事的人，不会在树上叫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98805, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作队", "is_correct": true, "explanation": "工作队是去各地做事的一群人，可以“走过很多地方”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能自己走过地方。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是房间，不会走路。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是东西，不能自己走过地方。"}], "explanations": {"工作队": "工作队是去各地做事的一群人，可以“走过很多地方”。", "冰箱": "语义：冰箱不能自己走过地方。", "教室": "语义：教室是房间，不会走路。", "书包": "语义：书包是东西，不能自己走过地方。"}, "sentence_index": 6, "correct_answer": "工作队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工作队的人都是中学生，每天在教室里上课。", "explanation": "这里应该用〈学校〉。工作队指一群人一起到某个地方去做事，在教室里上课的学生属于学校，不是工作队。"}, {"text": "这个工作队营业到晚上十点。", "explanation": "这里应该用〈商店〉。营业用于商店等经营场所，工作队不做买卖。"}, {"text": "工作队每十分钟发一班。", "explanation": "这里应该用〈公交车〉。发班指车次，工作队没有班次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只工作队昨天到了村子。", "corrected_sentence": "一支工作队昨天到了村子。", "error_description": "量词错误：工作队应用量词“支”，“只”用于动物等，不能用于工作队。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条工作队都是年轻人。", "corrected_sentence": "这支工作队都是年轻人。", "error_description": "量词错误：工作队应用量词“支”，“条”用于细长的东西，不能用于工作队。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
