INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98806, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为完成某项任务临时组织起来的集体。", "primary_collocate": null, "pronunciation": "gōng zuò duì", "ipa": "kʊŋ˥ tswɔ˥˩ tweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "公司为这个项目成立了工作队。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作队是临时的。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校临时组织了一支工作队。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支工作队只做三个月的事。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王加入了工作队。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作队每个星期开一次会。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了修桥，市里成立了工作队。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想参加这个工作队。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作队由医生和老师组成。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新工作队下个月开始工作。", "target_word": "工作队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "工作队员", "label": "复合"}, {"form": "工作隊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：为某项任务临时组成的集体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b273a4-be21-462a-a87c-17dfbdecb405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作队", "is_correct": true, "explanation": "为某项任务成立的临时集体，可以“成立”。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不能被成立。"}, {"text": "纪录", "is_correct": false, "explanation": "搭配：“成立”用于组织机构，应说“创造纪录”。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不是组织，不能被成立。"}], "explanations": {"工作队": "为某项任务成立的临时集体，可以“成立”。", "花园": "语义：花园是场所，不能被成立。", "纪录": "搭配：“成立”用于组织机构，应说“创造纪录”。", "饭菜": "语义：饭菜不是组织，不能被成立。"}, "sentence_index": 0, "correct_answer": "工作队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个工作队成立于一九八五年，现在有三千名员工。", "explanation": "这里应该用〈公司〉。工作队是为某项任务临时组成的，不会长期存在、有几千名员工。"}, {"text": "这个工作队已经存在了三百年，从来没有解散过。", "explanation": "这里应该用〈家族〉。工作队是为某项任务临时组成的，任务完成就解散，不会存在几百年。"}, {"text": "工作队昨晚在礼堂演奏了交响乐。", "explanation": "这里应该用〈乐团〉。工作队不演奏乐器，演奏交响乐要用乐团。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作队", "is_correct": true, "explanation": "为修桥而成立的临时集体，符合“成立了”的搭配。"}, {"text": "衙门", "is_correct": false, "explanation": "语域：“衙门”是旧时官署，不用于现代机构。"}, {"text": "冠军", "is_correct": false, "explanation": "搭配：“成立”不搭配“冠军”，应说“夺得冠军”。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不能被成立。"}], "explanations": {"工作队": "为修桥而成立的临时集体，符合“成立了”的搭配。", "衙门": "语域：“衙门”是旧时官署，不用于现代机构。", "冠军": "搭配：“成立”不搭配“冠军”，应说“夺得冠军”。", "小猫": "语义：小猫是动物，不能被成立。"}, "sentence_index": 6, "correct_answer": "工作队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工作队每年九月开学。", "explanation": "这里应该用〈学校〉。工作队是临时组织，不会每年定期开学。"}, {"text": "工作队去桂林玩了三天。", "explanation": "这里应该用〈旅游团〉。工作队是为完成任务组成的，不用来指旅行游玩。"}, {"text": "工作队是一种饮料，喝起来很甜。", "explanation": "这里应该用〈饮料〉。工作队指为完成某项任务临时组织起来的集体，不是饮品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
